SellOffer::SellOffer(const AuItem& item)
{
	m_InstallSecs = 0;
	m_Item = item.Clone();
	m_Price = 0;
	m_Workers = 0;

	const DgData& gd = g_Au.LockDataForRead();
	gd.EmpireName(item.EmpireOfOrigin(), m_EmpireOfOrigin);
	g_Au.UnlockData();
}

SellOffer::SellOffer(const AuItem& item, quint32 countNeeded, quint16 installSecs, quint16 workers)
{
	m_InstallSecs = installSecs;
	m_Item = item.Clone();
	m_Item->SetCount(countNeeded);
	m_Price = 0;
	m_Workers = workers;

	const DgData& gd = g_Au.LockDataForRead();
	gd.EmpireName(item.EmpireOfOrigin(), m_EmpireOfOrigin);
	g_Au.UnlockData();
}

