class AuFireBay
{
public:
	quint16	fireBay;
	AuPoint fireEmitLoc;
	quint32 fireUnits;
	const DaAtom* fireAtTarget;
	AuPoint fireAtSysLoc;

	inline AuFireBay()
	{
		fireBay = 0;
		fireUnits = 0;
		fireAtTarget = 0;
	}
};

