AuBdRender::AuBdRender() : m_CmdEmpty(),
	m_FireEmpty(),
	m_NavEmpty(),
	m_SensorEmpty(),
	m_ShieldEmpty(),
	m_SurgeryEmpty(),
	m_TransEmpty()
{
	for(int as=0; as<AS_MaxSources; as++)
		m_AudioShip[as] = 0;

	m_AmbientR = 0;
	m_AmbientG = 0;
	m_AmbientB = 0;
	m_CursorSiteOnly = false;

	for(int dmg=0; dmg<9; dmg++)
		m_DamageTex[dmg] = 0;

	m_DoorExt = 0;		// 0=no change, 1=opened, 2=closed
	m_DoorInt1 = 0;		// 0=no change, 1=opened, 2=closed
	m_DoorInt2 = 0;		// 0=no change, 1=opened, 2=closed
	m_DoorLift1 = 0;	// 0=no change, 1=opened, 2=closed
	m_DoorLift2 = 0;	// 0=no change, 1=opened, 2=closed

	for(int eff=EFF_None; eff<EFF_Count; eff++)
		m_EffectCur[eff] = 0;

	m_EffectFrame = 0;
	m_EffectRandFrame = 0;

	for(int eff=EFF_None; eff<EFF_Count+6; eff++)
		for(int frame=0; frame<6; frame++)
			m_EffectTex[eff][frame] = 0;

	m_EmpireFlagDecals = -1;
	m_EmpireNameDecals = -1;
	m_FlagEmpire = 0;
	m_FogDensity = 0;
	m_FogR = 0;
	m_FogG = 0;
	m_FogB = 0;

	for(int iSDEffect=0; iSDEffect<MAX_SHIELD_HIT_EFFECTS; iSDEffect++)
		m_fShieldDuration[iSDEffect] = 0;	// 0 which turns off all hit effects
	for(int iSEffect=0; iSEffect<MAX_SHIELD_HIT_EFFECTS*4; iSEffect++)
		m_fShieldEffect[iSEffect] = 1;		// 1 because we can't divide by zero in fragment shader

	m_fShieldTexOffset = 0;
	m_HColor = QColor(AuGLLight::ColorSodiumVapor());
	m_HCosInnerCone = -1;
	m_HCosOuterCone = -1;
	m_HDir = AuPoint(0,1,0);
	m_HkL = .005f;
	m_HkQ = 1.f/(float)(d_StreetLight * d_StreetLight);
	m_HullEffectAppl = 0;
	m_InsideVisible = false;
	m_IsAboard = false;
	m_IsDark = true;
	m_LandingSystem = 0;
	m_LaunchSystem = 0;
	m_LensBeaconAngle = 0;
	m_LifeSupportStatus = -1;
	m_LifeSupportStatusTex = 0;
	m_LightOmniTex = 0;
	m_LightSpotTex = 0;
	m_StrobesLit = 0;
	m_SunsBlocked = false;
	m_TractorBeam = 0;
	m_VAOsCreated = false;
	m_WorldMaps = -1;
	m_WorldMapTex = 0;

	beaconPartId = 0;
	decalPartId = 0;
	hullPartId = 0;
	streetLightPartId = 0;
	strobePartId = 0;
	customFence = false;
}

AuBdRender::~AuBdRender()
{
	if(m_TractorBeam)
		delete m_TractorBeam;
	if(m_LandingSystem)
		delete m_LandingSystem;
	if(m_LaunchSystem)
		delete m_LaunchSystem;
}

