void AuBdRender::CreateTextures(const AuId& id, AuGLEffects& re)
{
	if(m_LifeSupportStatusTex)
		return;	// We already did this.

	m_LifeSupportStatusTex = re.CreateTextureFromBitmap(id.GetID(), "LSI", ":data/LifeSupportStatusIndicators.png");

	m_WorldMapTex = re.CreateTextureFromBitmap(STATIC_TEXTURE_ID, "WormholeSpace", ":data/WormholeSpace.png", GL_LINEAR, GL_LINEAR,
			true);

	// Load hull surface damage textures.
	for(int dmg=0; dmg<9; dmg++)
		m_DamageTex[dmg] =
			AuTextureLibItem::EffectTexture(re, (AuTextureLibItem::EFFECT_INDEX)(AuTextureLibItem::EI_Damage1+dmg));

	// Load all frames of the effect textures.
	for(int eff=0; eff<EFF_Count; eff++)
		for(int frame=0; frame<6; frame++)
			m_EffectTex[eff][frame] = AuTextureLibItem::EffectTexture(re, (SURFACE_EFFECT)eff, frame);

	// Maneuver drives in low power mode.
	m_EffectTex[EFF_Count][0] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_ManeuverDriveLow1);
	m_EffectTex[EFF_Count][1] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_ManeuverDriveLow2);
	m_EffectTex[EFF_Count][2] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_ManeuverDriveLow3);
	m_EffectTex[EFF_Count][3] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_ManeuverDriveLow4);
	m_EffectTex[EFF_Count][4] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_ManeuverDriveLow5);
	m_EffectTex[EFF_Count][5] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_ManeuverDriveLow6);

	// Transporter pads in low power mode.
	m_EffectTex[EFF_Count+1][0] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_TransporterLow1);
	m_EffectTex[EFF_Count+1][1] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_TransporterLow2);
	m_EffectTex[EFF_Count+1][2] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_TransporterLow3);
	m_EffectTex[EFF_Count+1][3] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_TransporterLow4);
	m_EffectTex[EFF_Count+1][4] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_TransporterLow5);
	m_EffectTex[EFF_Count+1][5] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_TransporterLow6);

	// FTL hull in warp.
	m_EffectTex[EFF_Count+2][0] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWarp1);
	m_EffectTex[EFF_Count+2][1] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWarp2);
	m_EffectTex[EFF_Count+2][2] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWarp3);
	m_EffectTex[EFF_Count+2][3] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWarp4);
	m_EffectTex[EFF_Count+2][4] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWarp5);
	m_EffectTex[EFF_Count+2][5] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWarp6);

	// FTL drives in low power mode.
	m_EffectTex[EFF_Count+3][0] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_FTLDriveLow1);
	m_EffectTex[EFF_Count+3][1] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_FTLDriveLow2);
	m_EffectTex[EFF_Count+3][2] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_FTLDriveLow3);
	m_EffectTex[EFF_Count+3][3] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_FTLDriveLow4);
	m_EffectTex[EFF_Count+3][4] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_FTLDriveLow5);
	m_EffectTex[EFF_Count+3][5] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_FTLDriveLow6);

	// FTL hull in negative wormhole.
	m_EffectTex[EFF_Count+4][0] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeg1);
	m_EffectTex[EFF_Count+4][1] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeg2);
	m_EffectTex[EFF_Count+4][2] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeg3);
	m_EffectTex[EFF_Count+4][3] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeg4);
	m_EffectTex[EFF_Count+4][4] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeg5);
	m_EffectTex[EFF_Count+4][5] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeg6);

	// FTL hull in neutral wormhole.
	m_EffectTex[EFF_Count+5][0] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeu1);
	m_EffectTex[EFF_Count+5][1] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeu2);
	m_EffectTex[EFF_Count+5][2] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeu3);
	m_EffectTex[EFF_Count+5][3] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeu4);
	m_EffectTex[EFF_Count+5][4] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeu5);
	m_EffectTex[EFF_Count+5][5] = AuTextureLibItem::EffectTexture(re, AuTextureLibItem::EI_HullWormNeu6);
}

void AuBdRender::CreatePartTextures(const AuScParts& parts, AuGLEffects& re)
{
	// Textures needed by parts.
	for(AuScParts::const_iterator pi = parts.cbegin(); pi != parts.cend(); pi++)
	{
		if((*pi)->IsOmitted())
			continue;
		if((*pi)->IsLight())
			continue;
		if(!(*pi)->IsVisibleInFinalModel())
			continue;

		if((*pi)->IsDecal() && (*pi)->HasOwnTexture())
		{
			// Own Decal VAOs.
			// This is also where flag decals get created. The empire flag is often not ready yet so we'll wait for
			// animate to fix the aspect ratio of the vao.
			// Load/select the private texture.
			GLuint texId = (*pi)->OwnTexture(re);
			if(!texId)
				continue;
			m_OwnTextures.insert(pi.key(), texId);
		}
		else if((*pi)->HasOwnTexture())
		{
			// Own VAOs.
			// Load/select the private texture.
			GLuint texId = (*pi)->OwnTexture(re);
			if(!texId)
				continue;
			m_OwnTextures.insert(pi.key(), texId);
		}
	}

	// Custom fence designs need to remember their texture palette.
	if(customFence)
	{
		AuTexturePalette tex;
		const DgData& sdd = g_Au.LockBdDesignsForRead();
		for(QHash<quint32, AuSegmentArray>::const_iterator fi = fenceSegs.cbegin(); fi != fenceSegs.cend(); fi++)
		{
			if(fi.key() <= AuScFence::STYLE_Count)
				continue;	// Not a custom fence.
			AuBdDesignHash::const_iterator di = sdd.m_BdDesigns->find(fi.key());
			if(di != sdd.m_BdDesigns->cend())
			{
				COMMODITYID hullModule = (*di).second.HullModule();
				(*di).second.ShaderTexturePalette(hullModule, re, tex);
				m_FenceCustomTex.insert(fi.key(), tex);
			}
		}
		g_Au.UnlockBdDesigns();
	}
}

void AuBdRender::DeleteGL()
{
	m_LifeSupportStatusTex = 0;
	m_WorldMapTex = 0;

	if(m_BoardsVAO.VAO())
		m_BoardsVAO.DeleteGL();

	if(m_CursorVAO.VAO())
		m_CursorVAO.DeleteGL();
	if(m_CursorCoverageVAO.VAO())
		m_CursorCoverageVAO.DeleteGL();

	m_FenceCustomTex.clear();
	for(QHash<quint32, AuScVAO>::iterator vi = m_FenceCustomOpaqueVAO.begin(); vi != m_FenceCustomOpaqueVAO.end(); vi++)
		if((*vi).VAO())
			(*vi).DeleteGL();
	for(QHash<quint32, AuScVAO>::iterator vi = m_FenceCustomTransparentVAO.begin(); vi != m_FenceCustomTransparentVAO.end(); vi++)
		if((*vi).VAO())
			(*vi).DeleteGL();

	if(m_FenceStyleOpaqueVAO.VAO())
		m_FenceStyleOpaqueVAO.DeleteGL();
	if(m_FenceStyleTransparentVAO.VAO())
		m_FenceStyleTransparentVAO.DeleteGL();

	if(m_WeaponVAO.VAO())
		m_WeaponVAO.DeleteGL();

	for(QHash<quint16, AuScVAO>::iterator vi = m_OpaqueVAOs.begin(); vi != m_OpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_OpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_TransparentVAOs.begin(); vi != m_TransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_TransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_IntRoomOpaqueVAOs.begin(); vi != m_IntRoomOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_IntRoomOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_IntRoomTransparentVAOs.begin(); vi != m_IntRoomTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_IntRoomTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_RoomOpaqueVAOs.begin(); vi != m_RoomOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_RoomOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_RoomTransparentVAOs.begin(); vi != m_RoomTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_RoomTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_OwnOpaqueVAOs.begin(); vi != m_OwnOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_OwnOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_OwnTransparentVAOs.begin(); vi != m_OwnTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_OwnTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_DecalOpaqueVAOs.begin(); vi != m_DecalOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_DecalOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_DecalTransparentVAOs.begin(); vi != m_DecalTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_DecalTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LiftOpaqueVAOs.begin(); vi != m_LiftOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LiftOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LiftTransparentVAOs.begin(); vi != m_LiftTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LiftTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_OwnDecalOpaqueVAOs.begin(); vi != m_OwnDecalOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_OwnDecalOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_OwnDecalTransparentVAOs.begin(); vi != m_OwnDecalTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_OwnDecalTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_WindowTranslucentVAOs.begin(); vi != m_WindowTranslucentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_WindowTranslucentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_WindowTransparentVAOs.begin(); vi != m_WindowTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_WindowTransparentVAOs.clear();

	for(QHash<quint32, AuScVAO>::iterator vi = m_DoorOpaqueVAOs.begin(); vi != m_DoorOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_DoorOpaqueVAOs.clear();

	for(QHash<quint32, AuScVAO>::iterator vi = m_DoorTransparentVAOs.begin(); vi != m_DoorTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_DoorTransparentVAOs.clear();

	for(QHash<quint32, AuScVAO>::iterator vi = m_IntDoorOpaqueVAOs.begin(); vi != m_IntDoorOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_IntDoorOpaqueVAOs.clear();

	for(QHash<quint32, AuScVAO>::iterator vi = m_IntDoorTransparentVAOs.begin(); vi != m_IntDoorTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_IntDoorTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_TurBaseOpaqueVAOs.begin(); vi != m_TurBaseOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_TurBaseOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_TurBaseTransparentVAOs.begin(); vi != m_TurBaseTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_TurBaseTransparentVAOs.clear();

	for(QHash<quint32, AuScVAO>::iterator vi = m_TurGunOpaqueVAOs.begin(); vi != m_TurGunOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_TurGunOpaqueVAOs.clear();

	for(QHash<quint32, AuScVAO>::iterator vi = m_TurGunTransparentVAOs.begin(); vi != m_TurGunTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_TurGunTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensBeaconOpaqueVAOs.begin(); vi != m_LensBeaconOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LensBeaconOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensBeaconTransparentVAOs.begin(); vi != m_LensBeaconTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LensBeaconTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensHeadlightOpaqueVAOs.begin(); vi != m_LensHeadlightOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LensHeadlightOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensHeadlightTransparentVAOs.begin(); vi != m_LensHeadlightTransparentVAOs.end();
			vi++)
		(*vi).DeleteGL();
	m_LensHeadlightTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensNavOpaqueVAOs.begin(); vi != m_LensNavOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LensNavOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensNavTransparentVAOs.begin(); vi != m_LensNavTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LensNavTransparentVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensStrobeOpaqueVAOs.begin(); vi != m_LensStrobeOpaqueVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LensStrobeOpaqueVAOs.clear();

	for(QHash<quint16, AuScVAO>::iterator vi = m_LensStrobeTransparentVAOs.begin(); vi != m_LensStrobeTransparentVAOs.end(); vi++)
		(*vi).DeleteGL();
	m_LensStrobeTransparentVAOs.clear();

	m_VAOsCreated = false;
}

void AuBdRender::Animate(const AuId& id, const AuElapsedTimer& lastAnim, bool inDesignEnvironment, float illumination,
		BUILDING_STRUCTURE structure, bool lightsWorking)
{
	// Illumination is -1 when lighting not calculated and when I am behind the viewer.
	if(illumination >= 0)
		m_IsDark = DaAtom::IsDark(illumination);	// Get setting needed for nav lights and street lights.

	// Render shield bubble.
	if(m_shieldTime.isValid())
		m_fShieldTexOffset += m_shieldTime.elapsed()*(.005f);
	else
		m_shieldTime.start();

	if(m_TractorBeam)
		m_TractorBeam->Update();

	quint32 offset = id.GetID();
	if(!m_LensStrobeGlows.empty() && lastAnim.IsNewPeriod(d_MSecPerSec, offset))
		m_StrobesLit = 5;	// Light strobe lenses for a brief number of frames.
	else if(m_StrobesLit)
		m_StrobesLit--;		// Decay lit state of strobes.

	if(!m_LensBeaconGlows.empty())
		m_LensBeaconAngle = lastAnim.SecCycle(offset) * (PI*2);

	if(inDesignEnvironment)
	{
		// Animate often in design environment so they can be observed.
		if(lastAnim.ElapsedSecTicks())
			AnimateFacadeWindowLights(structure, illumination, lightsWorking);
	}
	else
	{
		// Animate slowly in game environment.
		if(lastAnim.IsNewPeriod(d_MSecPerMin, offset))
			AnimateFacadeWindowLights(structure, illumination, lightsWorking);
	}
}

void AuBdRender::AnimateFacadeWindowLights(BUILDING_STRUCTURE structure, float illumination, bool lightsWorking)
{
	if(m_WindowLightStates.empty())
		return;

	// Illumination is -1 when lighting not calculated and when I am behind the viewer.
	if(illumination < 0)
		return;

	// Update lit states of dummy facade windows.
	if(m_WindowLightStates.empty() &&
			m_LensNavTransparentVAOs.empty() &&
			m_LensDimLightGlows.empty() &&
			m_LensHeadlightGlows.empty() &&
			m_LensNavOpaqueVAOs.empty() &&
			m_LensNavGlows.empty() &&
			structure != BD_StreetLight)	// Street light needs to know if it is dark.
		return;

	if(!lightsWorking)
	{
		// Turn all facade window lights off.
		m_WindowLightStates.SetInteriorLight(INTLIGHT_Dark);
		return;
	}

	// Check for any lights on at all.
	if(m_WindowLightStates.AnyLightOn())
	{
		// At least one light is on.
		if(m_IsDark)
		{
			// Turn on lights.
			// Animate lighting on some of the windows each time. This makes them change over time.
			int anim = g_Au.Dice().Roll(1, (m_WindowLightStates.size()+1)/2 + 2, -2);	// Number to animate this cycle.
			if(anim < 0)
				anim = 0;
			while(anim--)
			{
				int idx = g_Au.Dice().Roll(1, m_WindowLightStates.size(), -1);	// Index of light to change state.
				int lidx = 0;	// Index of current light.
				for(AuRoomLightStateHash::iterator wi = m_WindowLightStates.begin(); wi != m_WindowLightStates.end();
						wi++, lidx++)
				{
					if(lidx < idx)
						continue;	// Skip until we reach the desired index.
					// Determine lighting state of the window.
					INTERIOR_LIGHT light;
					quint32 roll = g_Au.Dice().Roll(1,100);
					if(roll <= 60)
						light = INTLIGHT_Bright;			// Bright 60% of the time.
					else if(roll <= 75)
						light = INTLIGHT_Dim;				// Dim 15% of the time.
					else
						light = INTLIGHT_Dark;				// Dark 25% of the time.
					*wi = light;
					break;	// We only do one index per iteration of the anim loop.
				}
			}
		}
		else if(illumination >= .5f)
		{
			// Turn all facade window lights off.
			m_WindowLightStates.SetInteriorLight(INTLIGHT_Dark);
		}
		else
		{
			// Turn off lights.
			// Turn off lighting on many of the windows each time. This makes them go off faster than they come on.
			int anim = g_Au.Dice().Roll(1, m_WindowLightStates.size());	// Number to animate this cycle.
			while(anim--)
			{
				int idx = g_Au.Dice().Roll(1, m_WindowLightStates.size(), -1);	// Index of light to change state.
				int lidx = 0;	// Index of current light.
				for(AuRoomLightStateHash::iterator wi = m_WindowLightStates.begin(); wi != m_WindowLightStates.end();
						wi++, lidx++)
				{
					if(lidx < idx)
						continue;	// Skip until we reach the desired index.
					*wi = INTLIGHT_Dark;
					break;	// We only do one index per iteration of the anim loop.
				}
			}
		}
	}
	else
	{
		// No lights are on.
		if(m_IsDark)
		{
			// Turn on lights.
			// Animate lighting on all of the windows, to give them an initial light state. May have just come into view.
			for(AuRoomLightStateHash::iterator wi = m_WindowLightStates.begin(); wi != m_WindowLightStates.end(); wi++)
			{
				// Determine lighting state of the window.
				INTERIOR_LIGHT light;
				quint32 roll = g_Au.Dice().Roll(1,100);
				if(roll <= 60)
					light = INTLIGHT_Bright;			// Bright 60% of the time.
				else if(roll <= 75)
					light = INTLIGHT_Dim;				// Dim 15% of the time.
				else
					light = INTLIGHT_Dark;				// Dark 25% of the time.
				*wi = light;
			}
		}
	}
}

void AuBdRender::PrepareForRendering(const AuScParts& parts, const QSet<quint32>& bdDesigns,
		QColor themeColors[AuScFace::THEME_Count])
{
	for(AuScParts::const_iterator pi = parts.cbegin(); pi != parts.cend(); pi++)
	{
		if((*pi)->IsOmitted())
			continue;
		if((*pi)->IsLight())
		{
			m_HColor = (*pi)->LightColor();
			m_HCosInnerCone = (*pi)->LightCosInnerCone();
			m_HCosOuterCone = (*pi)->LightCosOuterCone();
			m_HDir = (*pi)->LightDir();
			m_HkL = (*pi)->LightkL();
			m_HkQ = (*pi)->LightkQ();
			m_HPos = (*pi)->LightLoc();
			continue;
		}
		if(!(*pi)->IsVisibleInFinalModel())
			continue;

		if((*pi)->IsDoor())
		{
			// Door VAOs are built in a later block of this function. This one simply builds door rendering information.
			for(AuScParts::const_iterator ti = parts.cbegin(); ti != parts.cend(); ti++)
			{
				if((*ti)->IsOmitted())
					continue;
				if(!(*ti)->IsRoomVoid())
					continue;
				if((*ti)->AssociatedPartId() != pi.key() || (*ti)->AssociatedPartState() != AuScDoor::Open)
					continue;
				// Found a room void associated with the open state of the door.
				m_DoorRooms.insert(pi.key(), (*ti)->GroupName());
				break;
			}
		}
		else if((*pi)->IsFence())
		{
			// We will accumulate the fence data so we can adjust the fence to the terrain and eliminate redunant posts.
			// There are several styles of fences; let's group them by style.
			quint32 fenceStyle = (AuScFence::STYLE)(*pi)->FenceStyle();
			if(fenceStyle == AuScFence::Custom)
			{
				if(bdDesigns.contains((*pi)->FenceDesignId()))
				{
					customFence = true;
					fenceStyle = (*pi)->FenceDesignId();
				}
				else
					fenceStyle = AuScFence::STYLE_Count;	// Show 'under construction' model.
			}

			QHash<quint32, AuSegmentArray>::iterator si = fenceSegs.find(fenceStyle);
			if(si == fenceSegs.end())
				si = fenceSegs.insert(fenceStyle, AuSegmentArray());
			(*pi)->FenceSegments(*si);
		}
		else if((*pi)->Type() == AuScPart::Part_LightLens)
		{
			// Light
			(*pi)->RenderTriangles(streetLightOpaqueTris, streetLightTransparentTris, themeColors);
			m_LensHeadlightGlows.insert(pi.key(), AuLensGlow((*pi)->LightLoc(), (*pi)->LightColor()));
			m_LensDimLightGlows.insert(pi.key(), AuLensGlow((*pi)->LightLoc(), AuGLLight::ColorTorch()));
			streetLightPartId = pi.key();
		}
		else if((*pi)->Type() == AuScPart::Part_NavLightLens)
		{
			// Nav lights cannot be combined into a single VAO because they glow in different colors.
			m_LensNavGlows.insert(pi.key(), AuLensGlow((*pi)->LightLoc(), (*pi)->LightColor()));
			AuScTriRenderList opaqueTris, transparentTris;
			(*pi)->RenderTriangles(opaqueTris, transparentTris, themeColors);
			if(!opaqueTris.empty())
				navOpaqueTris.insert(pi.key(), opaqueTris);
			if(!transparentTris.empty())
				navTransparentTris.insert(pi.key(), transparentTris);
		}
		else if((*pi)->Type() == AuScPart::Part_RotatingBeaconLens)
		{
			// Rotating beacon.
			(*pi)->RenderTriangles(beaconOpaqueTris, beaconTransparentTris, themeColors);
			m_LensBeaconGlows.insert(pi.key(), AuLensGlow((*pi)->LightLoc(), (*pi)->LightColor()));
			m_LensBeaconAxes.insert(pi.key(), (*pi)->LightRotationAxis());
			beaconPartId = pi.key();
		}
		else if((*pi)->Type() == AuScPart::Part_StrobeLens)
		{
			// Strobe light.
			(*pi)->RenderTriangles(strobeOpaqueTris, strobeTransparentTris, themeColors);
			m_LensStrobeGlows.insert(pi.key(), AuLensGlow((*pi)->LightLoc(), (*pi)->LightColor()));
			strobePartId = pi.key();
		}
		else if((*pi)->IsWindow())
		{
			// Window VAOs are lit by rooms so they cannot be combined.
			if((*pi)->HasGroupName() && (*pi)->GroupName() != AuScPart::GroupNameHull())
				m_WindowRooms.insert(pi.key(), (*pi)->GroupName());
			else
				m_WindowRooms.insert(pi.key(), QString("%1%2").arg((*pi)->PartName()).arg(pi.key()));
			AuScTriRenderList translucentTris, transparentTris;
			(*pi)->RenderTriangles(translucentTris, transparentTris, themeColors);
			if(!translucentTris.empty())
				windowTranslucentTris.insert(pi.key(), translucentTris);
			if(!transparentTris.empty())
				windowTransparentTris.insert(pi.key(), transparentTris);
		}
		else if((*pi)->IsDecal() && (*pi)->HasOwnTexture())
		{
			// Own Decal VAOs.
			// Load/select the private texture.
			if((*pi)->Type() == AuScPart::Part_EmpireFlag)
				continue;	// The empire flag is often not ready yet so we'll wait for animate to fix the aspect ratio of the vao.
			AuScTriRenderList opaqueTris, transparentTris;
			(*pi)->RenderTriangles(opaqueTris, transparentTris, themeColors);
			if(!opaqueTris.empty())
				decalOwnOpaqueTris.insert(pi.key(), opaqueTris);
			if(!transparentTris.empty())
				decalOwnTransparentTris.insert(pi.key(), transparentTris);
		}
		else if((*pi)->HasOwnTexture())
		{
			// Own VAOs.
			AuScTriRenderList opaqueTris, transparentTris;
			(*pi)->RenderTriangles(opaqueTris, transparentTris, themeColors);
			if(!opaqueTris.empty())
				ownOpaqueTris.insert(pi.key(), opaqueTris);
			if(!transparentTris.empty())
				ownTransparentTris.insert(pi.key(), transparentTris);
		}
		else if((*pi)->IsDecal())
		{
			// Decal VAOs.
			(*pi)->RenderTriangles(decalOpaqueTris, decalTransparentTris, themeColors);
			decalPartId = pi.key();
		}
		else if((*pi)->IsTurboLiftMesh())
		{
			// Turbo lift VAOs.
			m_RoomNames.insert(pi.key(), (*pi)->GroupName());
			AuScTriRenderList opaqueTris, transparentTris;
			(*pi)->RenderTriangles(opaqueTris, transparentTris, themeColors);

			// Remove the stop matrix from the faces. They will be repositioned later, using the matrix for their
			// current stop.
			const AuMatrix4x4& stopM = (*pi)->StopMatrixAt((*pi)->AtStop());
			opaqueTris.Transform(stopM.Inverse());
			transparentTris.Transform(stopM.Inverse());
			if(!opaqueTris.empty())
				liftOpaqueTris.insert(pi.key(), opaqueTris);
			if(!transparentTris.empty())
				liftTransparentTris.insert(pi.key(), transparentTris);
		}
		else if((*pi)->IsRoomMesh())
		{
			// Room mesh.
			m_RoomNames.insert(pi.key(), (*pi)->GroupName());
			AuScTriRenderList opaqueTris, transparentTris;
			(*pi)->RenderTriangles(opaqueTris, transparentTris, themeColors);

			// Collect faces from generic meshes associated with them, so they are lit the same as the room.
			for(AuScParts::const_iterator mi = parts.cbegin(); mi != parts.cend(); mi++)
			{
				if((*mi)->IsOmitted())
					continue;
				if((*mi)->Type() != AuScPart::Part_Mesh)
					continue;
				if((*mi)->GroupName() != (*pi)->GroupName())
					continue;
				(*mi)->RenderTriangles(opaqueTris, transparentTris, themeColors);
			}

			if((*pi)->InteriorIsSunlit())
			{
				m_SunlitRooms.insert((*pi)->GroupName());
				if(!opaqueTris.empty())
					sunnyroomOpaqueTris.insert(pi.key(), opaqueTris);
				if(!transparentTris.empty())
					sunnyroomTransparentTris.insert(pi.key(), transparentTris);
			}
			else
			{
				if(!opaqueTris.empty())
					roomOpaqueTris.insert(pi.key(), opaqueTris);
				if(!transparentTris.empty())
					roomTransparentTris.insert(pi.key(), transparentTris);
			}
		}
		else
		{
			// Routine VAOs.
			hullPartId = pi.key();
			(*pi)->RenderTriangles(hullOpaqueTris, hullTransparentTris, themeColors);
		}
	}

	// Configure dummy light states for fake facade windows.
	for(QHash<quint16, QString>::const_iterator wi = m_WindowRooms.cbegin(); wi != m_WindowRooms.cend(); wi++)
	{
		// Look for a room with that name.
		bool foundRoom = false;
		for(QHash<quint16, QString>::const_iterator ri = m_RoomNames.cbegin(); ri != m_RoomNames.cend(); ri++)
			if(*ri == *wi)
			{
				foundRoom = true;
				break;
			}

		// If no room corresponds to the window name, it is a fake facade window that needs a light state.
		if(!foundRoom)
		{
			// Determine lighting state of the window.
			// Choose a random light setting in a distribution similar to the animator.
			INTERIOR_LIGHT light;
			quint32 roll = g_Au.Dice().Roll(1,100);
			if(roll <= 60)
				light = INTLIGHT_Bright;		// Bright 60% of the time.
			else if(roll <= 75)
				light = INTLIGHT_Dim;			// Dim 15% of the time.
			else
				light = INTLIGHT_Dark;			// Dark 25% of the time.
			m_WindowLightStates.insert(*wi, light);
		}
	}
}

void AuBdRender::PrepareForRenderingFrame(const AuScParts& parts, COMMODITYID hullMaterial, int percentComplete)
{
	// Make a unit length board.
	AuPointArray profile;
	switch(hullMaterial)
	{
	case CID_Wood:
		// 6" logs
		{
			double r = .083*3;						// Radius of the log.
			profile.MakeCircle(AuPoint(0,0), AuPoint(r,0), 7);
		}
		break;
	case CID_Lumber:
		// 2"x6" boards
		{
			double w2 = .083;						// 1/2 width of the board.
			double h2 = .083*3;						// 1/2 height of the board.
			profile.append(AuPoint(-w2, -h2));
			profile.append(AuPoint(-w2, h2));
			profile.append(AuPoint(w2, h2));
			profile.append(AuPoint(w2, -h2));
		}
		break;
	case CID_Stone:
		// 6"x6" beams
		{
			double w2 = .083*3;						// 1/2 width of the beam.
			double h2 = .083*3;						// 1/2 height of the beam.
			profile.append(AuPoint(-w2, -h2));
			profile.append(AuPoint(-w2, h2));
			profile.append(AuPoint(w2, h2));
			profile.append(AuPoint(w2, -h2));
		}
		break;
	case CID_Metal:
	case CID_Magmium:
	case CID_Vulcium:
	case CID_Adamantine:
		// 4" flange x 6" web I-beams
		{
			double f2 = .083*2;						// 1/2 width of the flange.
			double h2 = .083*3;						// 1/2 height of the web.
			double ft = .083 * .28;					// Thickness of the flange.
			double wt2 = (.083 * .23)/2;			// 1/2 thickness of the web.
			double h2f = h2 - ft;					// Height to bottom face of flange.
			profile.append(AuPoint(-f2, -h2));		// Bottom left corner.
			profile.append(AuPoint(-f2, -h2f));
			profile.append(AuPoint(-wt2, -h2f));
			profile.append(AuPoint(-wt2, h2f));
			profile.append(AuPoint(-f2, h2f));
			profile.append(AuPoint(-f2, h2));		// Top left corner.
			profile.append(AuPoint(f2, h2));		// Top right corner.
			profile.append(AuPoint(f2, h2f));
			profile.append(AuPoint(wt2, h2f));
			profile.append(AuPoint(wt2, -h2f));
			profile.append(AuPoint(f2, -h2f));
			profile.append(AuPoint(f2, -h2));		// Bottom right corner.
		}
		break;
	default:
		// Triangle beams?
		{
			double w2 = .083*2;						// 1/2 width of the beam.
			double h2 = .083*3;						// 1/2 height of the beam.
			profile.append(AuPoint(-w2, -h2));
			profile.append(AuPoint(0, h2));
			profile.append(AuPoint(w2, -h2));
		}
		break;
	}
	if(profile.size() > 1)
		profile.append(profile.first());
	AuScFaceList bfu;
	bfu.MakeExtrusion(profile, AuPoint(0,0,1), AuMatrix4x4(), 2, true);
	bfu.FlattenVertexNormals();
	AuScSelectInfo psel;
	bfu.FaceIds(psel.m_Faces);
	bfu.TextureUnwrap(psel, SCTEXI_Material, 1, AuScFaceList::UNWRAP_Edges, DEG2RADf*60, true, 0, AuMatrix4x4());
	//qDebug() << "profile" << profile.size() << "bfu faces" << bfu.size();

	AuSegmentArray edges;
	parts.BuildingConstructionSegments(edges);

	//qDebug() << "edges" << edges.size();
	int edgesComplete = edges.size() * percentComplete / 100;	// Limit edge boards based on percent complete. This is
																// why BuildingConstructionSegments sorts them, lowest
																// Z first.
	if(!edgesComplete)
		edgesComplete = 1;
	AuScFaceList faces;
	for(AuSegmentArray::const_iterator ei = edges.cbegin(); ei != edges.cend() && edgesComplete--; ei++)
	{
		// Make a board.
		AuPoint segvec((*ei).m_fLoc2 - (*ei).m_fLoc1);

		AuScFaceList bf(bfu);

		AuMatrix4x4 boardM;
		boardM.Translate((*ei).m_fLoc1);
		if(IsFuzzyZero(segvec.y) && IsFuzzyZero(segvec.z))
		{
			if(segvec.x < 0)
				boardM.Rotate(AuPoint(0,-PI/2,PI/2));
			else
				boardM.Rotate(AuPoint(0,PI/2,PI/2));
		}
		else
			boardM *= AuPoint(0,0,1).GetAlignmentTransform(segvec);
		boardM.Scale(1,1,segvec.Length());
		bf.Transform(boardM);
		faces.AddFaces(bf);
	}
	faces.FlattenVertexNormals();
	faces.ApplyHullFTLEffect(parts.HullEffectSize(), false);	// Set texture coords for damage overlay.
	//AuScSelectInfo psel;
	//faces.FaceIds(psel.m_Faces);
	//faces.TextureUnwrap(psel, 0, 10, AuScFaceList::UNWRAP_ByFace, DEG2RAD, true, 0, AuMatrix4x4());
	//qDebug() << "boards faces" << faces.size();

	QColor themeColors[AuScFace::THEME_Count];	// not used by boards.
	AuScTriRenderList boardsTransparentTris;	// not used
	faces.RenderTriangles(boardsOpaqueTris, boardsTransparentTris, themeColors);
}

void AuBdRender::CreateVAOs(AuOpenGLFunctions& GLf)
{
	if(!boardsOpaqueTris.empty())
		m_BoardsVAO.Create(GLf, boardsOpaqueTris, GL_STATIC_DRAW);

	// Nav lights cannot be combined into a single VAO because they glow in different colors.
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = navOpaqueTris.cbegin(); ti != navOpaqueTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensNavOpaqueVAOs.insert(ti.key(), vao);
	}
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = navTransparentTris.cbegin(); ti != navTransparentTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensNavTransparentVAOs.insert(ti.key(), vao);
	}

	// Window VAOs are lit by rooms so they cannot be combined.
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = windowTranslucentTris.cbegin(); ti != windowTranslucentTris.cend();
			ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_WindowTranslucentVAOs.insert(ti.key(), vao);
	}
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = windowTransparentTris.cbegin(); ti != windowTransparentTris.cend();
			ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_WindowTransparentVAOs.insert(ti.key(), vao);
	}

	// Own Decal VAOs.
	// This is also where flag decals get created. The empire flag is often not ready yet so we'll wait for
	// animate to fix the aspect ratio of the vao.
	// Load/select the private texture.
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = decalOwnOpaqueTris.cbegin(); ti != decalOwnOpaqueTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_OwnDecalOpaqueVAOs.insert(ti.key(), vao);
	}
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = decalOwnTransparentTris.cbegin();
			ti != decalOwnTransparentTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_OwnDecalTransparentVAOs.insert(ti.key(), vao);
	}

	// Own VAOs.
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = ownOpaqueTris.cbegin(); ti != ownOpaqueTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_OwnOpaqueVAOs.insert(ti.key(), vao);
	}
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = ownTransparentTris.cbegin(); ti != ownTransparentTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_OwnTransparentVAOs.insert(ti.key(), vao);
	}

	// Turbo lift VAOs.
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = liftOpaqueTris.cbegin(); ti != liftOpaqueTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LiftOpaqueVAOs.insert(ti.key(), vao);
	}
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = liftTransparentTris.cbegin(); ti != liftTransparentTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LiftTransparentVAOs.insert(ti.key(), vao);
	}

	// Room meshes.
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = roomOpaqueTris.cbegin(); ti != roomOpaqueTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_IntRoomOpaqueVAOs.insert(ti.key(), vao);
	}
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = roomTransparentTris.cbegin(); ti != roomTransparentTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_IntRoomTransparentVAOs.insert(ti.key(), vao);
	}

	// Sunlit room meshes.
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = sunnyroomOpaqueTris.cbegin(); ti != sunnyroomOpaqueTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_RoomOpaqueVAOs.insert(ti.key(), vao);
	}
	for(QHash<quint16, AuScTriRenderList>::const_iterator ti = sunnyroomTransparentTris.cbegin();
			ti != sunnyroomTransparentTris.cend(); ti++)
	{
		AuScVAO vao;
		vao.Create(GLf, *ti, GL_STATIC_DRAW);
		if(vao.VAO())
			m_RoomTransparentVAOs.insert(ti.key(), vao);
	}

	// Create one VAO for the beacon lenses.
	if(!beaconOpaqueTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, beaconOpaqueTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensBeaconOpaqueVAOs.insert(beaconPartId, vao);
	}
	if(!beaconTransparentTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, beaconTransparentTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensBeaconTransparentVAOs.insert(beaconPartId, vao);
	}

	// Create one VAO for decals that do not have their own texture.
	if(!decalOpaqueTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, decalOpaqueTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_DecalOpaqueVAOs.insert(decalPartId, vao);
	}
	if(!decalTransparentTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, decalTransparentTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_DecalTransparentVAOs.insert(decalPartId, vao);
	}

	// Create one VAO for the street light lenses.
	if(!streetLightOpaqueTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, streetLightOpaqueTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensHeadlightOpaqueVAOs.insert(streetLightPartId, vao);
	}
	if(!streetLightTransparentTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, streetLightTransparentTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensHeadlightTransparentVAOs.insert(streetLightPartId, vao);
	}

	// Create one VAO for the hull.
	if(!hullOpaqueTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, hullOpaqueTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_OpaqueVAOs.insert(hullPartId, vao);
	}
	if(!hullTransparentTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, hullTransparentTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_TransparentVAOs.insert(hullPartId, vao);
	}

	// Create one VAO for the strobe lenses.
	if(!strobeOpaqueTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, strobeOpaqueTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensStrobeOpaqueVAOs.insert(strobePartId, vao);
	}
	if(!strobeTransparentTris.empty())
	{
		AuScVAO vao;
		vao.Create(GLf, strobeTransparentTris, GL_STATIC_DRAW);
		if(vao.VAO())
			m_LensStrobeTransparentVAOs.insert(strobePartId, vao);
	}

	m_VAOsCreated = true;
}

void AuBdRender::CopyVAOs(const AuBdRender& c)
{
	// Data from PrepareForRendering
	m_HColor = c.m_HColor;
	m_HCosInnerCone = c.m_HCosInnerCone;
	m_HCosOuterCone = c.m_HCosOuterCone;
	m_HDir = c.m_HDir;
	m_HkL = c.m_HkL;
	m_HkQ = c.m_HkQ;
	m_HPos = c.m_HPos;
	m_DoorRooms = c.m_DoorRooms;
	fenceSegs = c.fenceSegs;
	m_LensDimLightGlows = c.m_LensDimLightGlows;
	m_LensHeadlightGlows = c.m_LensHeadlightGlows;
	m_LensNavGlows = c.m_LensNavGlows;
	m_LensBeaconAxes = c.m_LensBeaconAxes;
	m_LensBeaconGlows = c.m_LensBeaconGlows;
	m_LensStrobeGlows = c.m_LensStrobeGlows;
	m_WindowRooms = c.m_WindowRooms;
	m_RoomNames = c.m_RoomNames;
	m_WindowLightStates = c.m_WindowLightStates;

	// Data from CreateVAOs
	m_BoardsVAO = c.m_BoardsVAO;
	m_LensNavOpaqueVAOs = c.m_LensNavOpaqueVAOs;
	m_LensNavTransparentVAOs = c.m_LensNavTransparentVAOs;
	m_WindowTranslucentVAOs = c.m_WindowTranslucentVAOs;
	m_WindowTransparentVAOs = c.m_WindowTransparentVAOs;
	m_OwnDecalOpaqueVAOs = c.m_OwnDecalOpaqueVAOs;
	m_OwnDecalTransparentVAOs = c.m_OwnDecalTransparentVAOs;
	m_OwnOpaqueVAOs = c.m_OwnOpaqueVAOs;
	m_OwnTransparentVAOs = c.m_OwnTransparentVAOs;
	m_LiftOpaqueVAOs = c.m_LiftOpaqueVAOs;
	m_LiftTransparentVAOs = c.m_LiftTransparentVAOs;
	m_IntRoomOpaqueVAOs = c.m_IntRoomOpaqueVAOs;
	m_IntRoomTransparentVAOs = c.m_IntRoomTransparentVAOs;
	m_RoomOpaqueVAOs = c.m_RoomOpaqueVAOs;
	m_RoomTransparentVAOs = c.m_RoomTransparentVAOs;
	m_LensBeaconOpaqueVAOs = c.m_LensBeaconOpaqueVAOs;
	m_LensBeaconTransparentVAOs = c.m_LensBeaconTransparentVAOs;
	m_DecalOpaqueVAOs = c.m_DecalOpaqueVAOs;
	m_DecalTransparentVAOs = c.m_DecalTransparentVAOs;
	m_LensHeadlightOpaqueVAOs = c.m_LensHeadlightOpaqueVAOs;
	m_LensHeadlightTransparentVAOs = c.m_LensHeadlightTransparentVAOs;
	m_OpaqueVAOs = c.m_OpaqueVAOs;
	m_TransparentVAOs = c.m_TransparentVAOs;
	m_LensStrobeOpaqueVAOs = c.m_LensStrobeOpaqueVAOs;
	m_LensStrobeTransparentVAOs = c.m_LensStrobeTransparentVAOs;
	m_VAOsCreated = c.m_VAOsCreated;
}

