	m_ReportPopDeaths = 0;
	m_ReportPopIndigenousArr = 0;
	m_ReportPopIndigenousDep = 0;
	m_ReportPopSeafarersArr = 0;
	m_ReportPopSeafarersDep = 0;
	m_ReportPopTravellersArr = 0;
	m_ReportPopTravellersDep = 0;
	m_ReportPopWanderersArr = 0;
	m_ReportPopWanderersDep = 0;
	m_Residents = 0;
	m_ResidentEcoRole = ECO_Omnivore;
	m_StoreCommodity = CID_Invalid;
	m_Workers = 0;
	m_pConstruct = 0;
	m_ShieldCap = 0;
	m_ShieldScram = 0;
	m_TargetLocValid = false;
	m_Ticked = false;
	m_Tocked = false;
	m_HasAir = false;
	m_IndustryId = IID_None;
