	m_ReportPopSeafarersDep = rhs.m_ReportPopSeafarersDep;
	m_ReportPopTravellersArr = rhs.m_ReportPopTravellersArr;
	m_ReportPopTravellersDep = rhs.m_ReportPopTravellersDep;
	m_ReportPopWanderersArr = rhs.m_ReportPopWanderersArr;
	m_ReportPopWanderersDep = rhs.m_ReportPopWanderersDep;
	m_Residents = rhs.m_Residents;
	m_ResidentEcoRole = rhs.m_ResidentEcoRole;
	m_ResidentsEmployed = rhs.m_ResidentsEmployed;
	m_ResidentSpecies = rhs.m_ResidentSpecies;
	m_RocksOnSite = rhs.m_RocksOnSite;
	m_Workers = rhs.m_Workers;
	m_tmCitizenChange = rhs.m_tmCitizenChange;
	m_tmReport = rhs.m_tmReport;
	m_tmResidentChange = rhs.m_tmResidentChange;
	rhs.m_BdLock.unlock();

	rhs.m_ModDbLock.lockForRead();
	m_tmModDb = rhs.m_tmModDb;
	rhs.m_ModDbLock.unlock();

	rhs.m_TradeConnectionsLock.lockForRead();
	m_TradeConnections = rhs.m_TradeConnections;
	m_TradeConnectionsChg = rhs.m_TradeConnectionsChg;
	m_Airport = rhs.m_Airport;
	m_Wharf = rhs.m_Wharf;
	rhs.m_TradeConnectionsLock.unlock();

	rhs.m_VesselLock.lockForRead();
	m_CapacitorLevel = rhs.m_CapacitorLevel;
	rhs.m_VesselLock.unlock();

