	rhs.m_CargoLock.lockForRead();
	for(AuItemHash::const_iterator ii = rhs.m_Cargo.begin(); ii != rhs.m_Cargo.end(); ii++)
		m_Cargo.insert(pair<COMMODITYID, AuItem*>((*ii).first, (*ii).second->Clone()));
