bool DaBd::AnyHullDoorOpenInRoom(const QString& roomName) const
{
	m_DesignLock.lockForRead();
	for(QHash<quint16, QString>::const_iterator dri = m_HullDoorRooms.cbegin(); dri != m_HullDoorRooms.cend(); dri++)
	{
		if(*dri != roomName)
			continue;	// Door is not in the same room.
		AuDoorStateHash::const_iterator dsi = m_DoorStates.find(dri.key());
		if(dsi == m_DoorStates.cend())
			continue;
		if(!(*dsi).IsOpen())
			continue;
		if(!(*dsi).IsHullDoor())
			continue;
		m_DesignLock.unlock();
		return true;
	}
	m_DesignLock.unlock();
	return false;
}

