const AuBdDesign* DaBd::LockDesign() const
{
	// Fences and walls do not have an associated design.
	//DHH custom fence if(IndustryId() == IID_Fence)
		//DHH custom fence return 0;

	// Get my parent design environment, if any. I could be a preview of a design in progress.
	DaDesigner* pardes = (DaDesigner*)FindParentDesignerInEnv();	// Cast away constness.
	if(pardes)
		return dynamic_cast<const AuBdDesign*>(pardes->LockDesignForRead());	// I am a preview in a design studio.

	// I am not a preview in a design studio.
	const DgData& sdd = g_Au.LockBdDesignsForRead();
	AuBdDesignHash::const_iterator di = sdd.m_BdDesigns->find(m_Design.DesignId());
	if(di == sdd.m_BdDesigns->cend())
		return 0;
	return &(*di).second;
}

void DaBd::UnlockDesign() const
{
	//DHH custom fence if(IndustryId() == IID_Fence)
		//DHH custom fence return;

	// Get my parent design environment, if any. I could be a preview of a design in progress.
	DaDesigner* pardes = (DaDesigner*)FindParentDesignerInEnv();	// Cast away constness.
	if(pardes)
	{
		pardes->UnlockDesign();								// I am a preview in a design studio.
		return;
	}

	// I am not a preview in a design studio.
	g_Au.UnlockBdDesigns();
}

