{
	m_DesignLock.lockForRead();
	bool v = m_Design.HasWeaponBay();
	m_DesignLock.unlock();
	return v;
}

bool DaBd::HasWorkingSurgeryUnit() const
{
	m_DesignLock.lockForRead();
	QList<quint16> surgs = m_Design.SurgeryUnitIds();
	m_DesignLock.unlock();

	for(QList<quint16>::const_iterator sui = surgs.cbegin(); sui != surgs.cend(); sui++)
	{
		if(SystemModule(SYS_SurgeryUnit, *sui) == CID_SurgeryMedicalModule)
		{
			// Found a surgery unit. Is it working?
			if(GetPowerConsumption(SYS_SurgeryUnit, *sui))
				return true;	// The surgery unit is working.
		}
	}
	return false;
}

AuPoint DaBd::HelmLocation() const
{
	AuPoint helmLoc;
	const AuBdDesign* scd = LockDesign();
	if(scd)
		helmLoc = scd->HelmLocation();
	UnlockDesign();
	return helmLoc;
}

int DaBd::RemoteDoorIndex(bool forVehicle, const AuPoint& loc) const
{
	m_DesignLock.lockForRead();
	quint16 doorId = m_Design.ClosestRemoteDoor(forVehicle, loc, m_DoorStates);
	m_DesignLock.unlock();
	return doorId;
}

int DaBd::RemoteDoorIndex(bool forVehicle, const AuPoint& loc, quint16 roomId) const
{
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	quint16 doorId = scd->ClosestRemoteDoorInRoom(forVehicle, loc, roomId, m_DoorStates);
	UnlockDesign();
	m_DesignLock.unlock();
	return doorId;
}

bool DaBd::HullDoorLocked(unsigned int doorIndex) const
{
	m_DesignLock.lockForRead();
	bool is = m_DoorStates.IsDoorLocked(doorIndex) && m_DoorStates.IsHullDoor(doorIndex);
	m_DesignLock.unlock();
	return is;
}

void DaBd::Insert(QSqlDatabase& db) const
{
	if(IsDead())
		return;

	AuAtomPos pos(Pos());
	AuPoint vLoc = pos.Translation();
	AuPoint vRot = pos.Rotation();

    // Store city capitol population for the city report.
    int cityPop = 0;
    if(IndustryId() == IID_Capitol || IndustryId() == IID_BaseHeadquarters)
    {
        AuCityReport report;
        if(ReportLast(report))
            cityPop = report.m_PopOrig;
    }

	QString flds;
	QString vals;
	if(IndustryId() == IID_SpacecraftFactory)
	{
		flds = ",scFactory";
		vals = ",?";
	}
	else if(IndustryId() == IID_Broker)
	{
		flds = ",broker";
		vals = ",?";
	}
	else if(IndustryId() == IID_Fence)
	{
		flds = ",fence";
		vals = ",?";
	}

	QSqlQuery qa(QString(), db);
	QString sq;
	sq = QString("INSERT INTO a_Bd (id,idp,locX,locY,locZ,rotX,rotY,rotZ, timeCreate,timeModified,timeTock,timeDeath, "
			"name,allegiance,arenaTeam,conditions,damageHistory, "
			"capacitor,capitol,cityName,citizenDNA,resSpec,cargo,cargo4,damage,banka,industry,qual,mfgproc,systems,shield,games,"
			"baySetting, designId,designRpt,airPressures,doorStates,landingSystems,launchers,lifts,log, "
			"roomLights,transporters,turretPos,reportHist,reportTime,cityPop,platform %1) "
			"VALUES (?,?,?,?,?,?,?,?, ?,?,?,?, "
			"?,?,?,?,?, "
			"?,?,?,?,?,?,?,?,?,?,?,?,?,?,?, "
			"?, ?,?,?,?,?,?,?,?, "
			"?,?,?,?,?,?,? %2);")
		.arg(flds)
		.arg(vals);
	qa.prepare(sq);
	qa.addBindValue(Id().GetID());
	qa.addBindValue(pos.ParentId().GetID());
	qa.addBindValue(FuzzyClamp(vLoc.x));
	qa.addBindValue(FuzzyClamp(vLoc.y));
	qa.addBindValue(FuzzyClamp(vLoc.z));
	qa.addBindValue(FuzzyClamp(vRot.x));
	qa.addBindValue(FuzzyClamp(vRot.y));
	qa.addBindValue(FuzzyClamp(vRot.z));
	qa.addBindValue(CreatedTime().UTC());
	qa.addBindValue(ModifyTime().UTC());
	qa.addBindValue(TockTime().UTC());
	qa.addBindValue(DeathTime().UTC());

	// DaUnit values.
	qa.addBindValue(AssignedName());
	qa.addBindValue(Allegiance());
	qa.addBindValue(ArenaTeam());
	{
		// Conditions
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << LockConditions();
		UnlockConditions();

		// Construction process is a temporary condition.
		const DeConstructionProcess* cproc = LockConstructionProcessForRead();
		if(cproc)
		{
			out << (quint8)1;
			*cproc >> out;
		}
		else
		{
			out << (quint8)0;
		}
		UnlockConstructionProcess();
		qa.addBindValue(ba);
	}
	{
		// Unit Damage History
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		const AuUnitDamageHash& ud = LockUnitDamage();
		out << (quint32)ud.size();
		for(AuUnitDamageHash::const_iterator di = ud.begin(); di != ud.end(); di++)
		{
			out << (*di).first;
			out << (*di).second;
		}
		UnlockUnitDamage();
		qa.addBindValue(ba);
	}

	// DaBd values.
	qa.addBindValue(FuzzyClamp(m_CapacitorLevel));
	qa.addBindValue(m_CapitolId.GetID());
	qa.addBindValue(m_CityName);
	{
		// Citizen DNA and population.
		QByteArray ba;
		qa.addBindValue(ba);	// Clear old citizenDNA field.

		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_7);
		m_BdLock.lockForRead();
		out << (quint8)m_ResidentEcoRole;
		out << m_ResidentSpecies;
		out << m_Residents;
		out << (quint16)m_TransientPopulation.size();
		for(QMap<AuSpecies, quint32>::const_iterator ti = m_TransientPopulation.cbegin(); ti != m_TransientPopulation.cend(); ti++)
		{
			out << ti.key();
			out << *ti;
		}
		out << m_Workers;
		m_BdLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Cargo
		QByteArray ba;
		qa.addBindValue(ba);	// Add old version empty.

		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_7);
		out << (quint8)0;	// version
		m_CargoLock.lockForRead();
		m_Cargo >> out;
		m_Tools >> out;
		out << m_Patents;
		out << m_LivestockSpecies;
		out << m_StoreCommodity;
		m_CargoLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Damage
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_DamageLock.lockForRead();
		m_Damage >> out;
		out << m_tmDamageChange;	// We depend on the damage change time to delay the recovery of ships in stasis.
		m_DamageLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Bank
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_Bank;
		qa.addBindValue(ba);
	}
	qa.addBindValue(m_IndustryId);
	qa.addBindValue(m_QMade);

	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_MfgProcLock.lockForRead();
		m_MfgProc >> out;
		m_MfgProcLock.unlock();
		qa.addBindValue(ba);
	}

	{
		// Systems
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_SystemsLock.lockForRead();
		m_ssaShipSystems >> out;
		m_SystemsLock.unlock();
		qa.addBindValue(ba);
	}

	// Shields
	qa.addBindValue(FuzzyClamp(m_ShieldCap));

	{
		// Games
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_GamesLock.lockForRead();
		out << (quint16)m_Games.size();
		for(unordered_map<quint16, AuGame*>::const_iterator gi = m_Games.begin(); gi != m_Games.end(); gi++)
		{
			out << (*gi).first;
			out << (*gi).second->Type();
			out << *(*gi).second;
		}
		m_GamesLock.unlock();
		qa.addBindValue(ba);
	}

	{
		// Bay settings
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);

		m_BayLock.lockForRead();
		out << (quint32)m_BaySetting.size();
		for(unordered_map<quint16, AuBaySetting>::const_iterator bi = m_BaySetting.begin(); bi != m_BaySetting.end(); bi++)
		{
			out << (*bi).first;
			out << (*bi).second;
		}
		m_BayLock.unlock();

		m_TurretLock.lockForRead();
		out << (quint32)m_Turrets.size();
		for(unordered_map<quint16, AuOrdnance>::const_iterator ti = m_Turrets.begin(); ti != m_Turrets.end(); ti++)
		{
			out << (*ti).first;
			out << (*ti).second;
		}
		m_TurretLock.unlock();

		m_BayLock.lockForRead();
		out << (quint32)m_BayFired.size();
		for(unordered_map<quint16, AuBayFired>::const_iterator bi = m_BayFired.cbegin(); bi != m_BayFired.cend(); bi++)
		{
			out << (*bi).first;
			out << (*bi).second;
		}
		m_BayLock.unlock();

		qa.addBindValue(ba);
	}

	// DaBd values.
	qa.addBindValue(DesignId());

	{
		// Design report
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_Design;
		out << (quint8)2;	// version
		out << m_FounderId;
		out << m_FounderName;

		// Surveyed rocks.
		m_BdLock.lockForRead();
		out << (quint16)m_RocksOnSite.size();
		for(QHash<COMMODITYID, quint32>::const_iterator ri = m_RocksOnSite.cbegin(); ri != m_RocksOnSite.cend(); ri++)
		{
			out << (quint16)ri.key();
			out << *ri;
		}
		m_BdLock.unlock();

		qa.addBindValue(ba);
	}
	{
		// Air Pressures and Alert Condition
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_AirPressures;
		qa.addBindValue(ba);
	}
	{
		// Door states
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_DoorStates;
		qa.addBindValue(ba);
	}
	{
		// Landing systems
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_LandingSystemStates;
		qa.addBindValue(ba);
	}
	{
		// Launchers
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_LauncherStates;
		qa.addBindValue(ba);
	}
	{
		// Lifts
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_Lifts;
		qa.addBindValue(ba);
	}
	{
		// Log
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_EventLogLock.lock();
		out << *m_EventLog;
		m_EventLogLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Room lights
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_RoomLightStates;
		qa.addBindValue(ba);
	}
	{
		// Transporters
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_TRoomStates;
		qa.addBindValue(ba);
	}
	{
		// Turret positions
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_TurretPosLock.lockForRead();
		out << m_TurretPos;
		m_TurretPosLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// City report history
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_BdLock.lockForRead();
		m_ReportHistory >> out;
		out << m_ReportPopBirths;
		out << m_ReportPopIndigenousArr;
		out << m_ReportPopTravellersArr;
		out << m_ReportPopIndigenousDep;
		out << m_ReportPopTravellersDep;
		out << m_ReportPopDeaths;
		out << (quint32)0;
		out << m_ReportPopSeafarersArr;
		out << m_ReportPopSeafarersDep;
		out << m_ReportPopWanderersArr;
		out << m_ReportPopWanderersDep;
		m_BdLock.unlock();
		qa.addBindValue(ba);
	}
	qa.addBindValue(m_tmReport.UTC());
	qa.addBindValue(cityPop);
	qa.addBindValue(m_PlatformId.GetID());

	if(IndustryId() == IID_SpacecraftFactory)
	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_SpacecraftFactoryLock.lockForRead();
		out << m_CompanyMaxQ;
		out << m_CompanyOk;
		out << m_DefaultDesign;
		out << m_DesignQueue;
		out << m_MakeMinQ;
		out << m_MakingShip;
		m_SpacecraftFactoryLock.unlock();
		qa.addBindValue(ba);
	}
	else if(IndustryId() == IID_Broker)
	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_0);
		m_CargoLock.lockForRead();
		out << m_Shipments;
		out << m_TradeAgreements;
		m_CargoLock.unlock();
		qa.addBindValue(ba);
	}
	else if(IndustryId() == IID_Fence)
	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_0);
		m_FenceLock.lockForRead();
		out << m_FenceSegs;
		out << m_FenceStyle;				// AuScFence::STYLE
		m_FenceLock.unlock();
		qa.addBindValue(ba);
	}

	if(!qa.exec())
		qWarning() << "error: DaBd::Insert." << Id() << qa.lastError() << sq;
}

void DaBd::Update(QSqlDatabase& db) const
{
	if(IsDead())
		return;

    // Store city capitol population for the city report.
    int cityPop = 0;
    if(IndustryId() == IID_Capitol || IndustryId() == IID_BaseHeadquarters)
    {
        AuCityReport report;
        if(ReportLast(report))
            cityPop = report.m_PopOrig;
    }

	AuAtomPos pos(Pos());
	AuPoint vLoc = pos.Translation();
	AuPoint vRot = pos.Rotation();

	QString flds;
	if(IndustryId() == IID_SpacecraftFactory)
		flds = ", scFactory=?";
	else if(IndustryId() == IID_Broker)
		flds = ", broker=?";
	else if(IndustryId() == IID_Fence)
		flds = ", fence=?";

	QString sq;
	sq = QString("UPDATE a_Bd SET idp=?, locX=?, locY=?, locZ=?, rotX=?, rotY=?, rotZ=?, timeModified=?, timeTock=?, "
			"timeDeath=?, "
			"name=?, allegiance=?, arenaTeam=?, conditions=?, damageHistory=?, "
			"capacitor=?, capitol=?, cityName=?, citizenDNA=?, resSpec=?, cargo=?, cargo4=?, damage=?, banka=?, industry=?, "
			"qual=?, mfgproc=?, "
			"systems=?, shield=?, games=?, baySetting=?, designId=?, designRpt=?, airPressures=?, doorStates=?, landingSystems=?, "
			"launchers=?, lifts=?, log=?, roomLights=?, transporters=?, turretPos=?, reportHist=?, reportTime=?, cityPop=?, "
			"platform=? %2 "
			"WHERE id=%1;")
		.arg(Id().GetID())
		.arg(flds);
	QSqlQuery qa(QString(), db);
	qa.prepare(sq);
	qa.addBindValue(pos.ParentId().GetID());
	qa.addBindValue(FuzzyClamp(vLoc.x));
	qa.addBindValue(FuzzyClamp(vLoc.y));
	qa.addBindValue(FuzzyClamp(vLoc.z));
	qa.addBindValue(FuzzyClamp(vRot.x));
	qa.addBindValue(FuzzyClamp(vRot.y));
	qa.addBindValue(FuzzyClamp(vRot.z));
	qa.addBindValue(ModifyTime().UTC());
	qa.addBindValue(TockTime().UTC());
	qa.addBindValue(DeathTime().UTC());

	// DaUnit values.
	qa.addBindValue(AssignedName());
	qa.addBindValue(Allegiance());
	qa.addBindValue(ArenaTeam());
	{
		// Conditions
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << LockConditions();
		UnlockConditions();

		// Construction process is a temporary condition.
		const DeConstructionProcess* cproc = LockConstructionProcessForRead();
		if(cproc)
		{
			out << (quint8)1;
			*cproc >> out;
		}
		else
		{
			out << (quint8)0;
		}
		UnlockConstructionProcess();
		qa.addBindValue(ba);
	}
	{
		// Unit Damage History
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		const AuUnitDamageHash& ud = LockUnitDamage();
		out << (quint32)ud.size();
		for(AuUnitDamageHash::const_iterator di = ud.begin(); di != ud.end(); di++)
		{
			out << (*di).first;
			out << (*di).second;
		}
		UnlockUnitDamage();
		qa.addBindValue(ba);
	}

	// DaBd values.
	qa.addBindValue(FuzzyClamp(m_CapacitorLevel));
	qa.addBindValue(m_CapitolId.GetID());
	qa.addBindValue(m_CityName);
	{
		// Citizen DNA and population.
		QByteArray ba;
		qa.addBindValue(ba);	// Clear old citizenDNA field.

		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_7);
		m_BdLock.lockForRead();
		out << (quint8)m_ResidentEcoRole;
		out << m_ResidentSpecies;
		out << m_Residents;
		out << (quint16)m_TransientPopulation.size();
		for(QMap<AuSpecies, quint32>::const_iterator ti = m_TransientPopulation.cbegin(); ti != m_TransientPopulation.cend(); ti++)
		{
			out << ti.key();
			out << *ti;
		}
		out << m_Workers;
		m_BdLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Cargo
		QByteArray ba;
		qa.addBindValue(ba);	// Add old version empty.

		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_7);
		out << (quint8)0;	// version
		m_CargoLock.lockForRead();
		m_Cargo >> out;
		m_Tools >> out;
		out << m_Patents;
		out << m_LivestockSpecies;
		out << m_StoreCommodity;
		m_CargoLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Damage
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_DamageLock.lockForRead();
		m_Damage >> out;
		out << m_tmDamageChange;	// We depend on the damage change time to delay the recovery of ships in stasis.
		m_DamageLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Bank
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_Bank;
		qa.addBindValue(ba);
	}
	qa.addBindValue(m_IndustryId);
	qa.addBindValue(m_QMade);

	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_MfgProcLock.lockForRead();
		m_MfgProc >> out;
		m_MfgProcLock.unlock();
		qa.addBindValue(ba);
	}

	{
		// Systems
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_SystemsLock.lockForRead();
		m_ssaShipSystems >> out;
		m_SystemsLock.unlock();
		qa.addBindValue(ba);
	}

	// Shields
	qa.addBindValue(FuzzyClamp(m_ShieldCap));

	{
		// Games
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_GamesLock.lockForRead();
		out << (quint16)m_Games.size();
		for(unordered_map<quint16, AuGame*>::const_iterator gi = m_Games.begin(); gi != m_Games.end(); gi++)
		{
			out << (*gi).first;
			out << (*gi).second->Type();
			out << *(*gi).second;
		}
		m_GamesLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Bay settings
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);

		m_BayLock.lockForRead();
		out << (quint32)m_BaySetting.size();
		for(unordered_map<quint16, AuBaySetting>::const_iterator bi = m_BaySetting.begin(); bi != m_BaySetting.end(); bi++)
		{
			out << (*bi).first;
			out << (*bi).second;
		}
		m_BayLock.unlock();

		m_TurretLock.lockForRead();
		out << (quint32)m_Turrets.size();
		for(unordered_map<quint16, AuOrdnance>::const_iterator ti = m_Turrets.begin(); ti != m_Turrets.end(); ti++)
		{
			out << (*ti).first;
			out << (*ti).second;
		}
		m_TurretLock.unlock();

		m_BayLock.lockForRead();
		out << (quint32)m_BayFired.size();
		for(unordered_map<quint16, AuBayFired>::const_iterator bi = m_BayFired.cbegin(); bi != m_BayFired.cend(); bi++)
		{
			out << (*bi).first;
			out << (*bi).second;
		}
		m_BayLock.unlock();

		qa.addBindValue(ba);
	}

	qa.addBindValue(DesignId());

	{
		// Design report
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_Design;
		out << (quint8)2;	// version
		out << m_FounderId;
		out << m_FounderName;

		// Surveyed rocks.
		m_BdLock.lockForRead();
		out << (quint16)m_RocksOnSite.size();
		for(QHash<COMMODITYID, quint32>::const_iterator ri = m_RocksOnSite.cbegin(); ri != m_RocksOnSite.cend(); ri++)
		{
			out << (quint16)ri.key();
			out << *ri;
		}
		m_BdLock.unlock();

		qa.addBindValue(ba);
	}
	{
		// Air Pressures and Alert Condition
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_AirPressures;
		qa.addBindValue(ba);
	}
	{
		// Door states
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_DoorStates;
		qa.addBindValue(ba);
	}
	{
		// Landing systems
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_LandingSystemStates;
		qa.addBindValue(ba);
	}
	{
		// Launchers
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_LauncherStates;
		qa.addBindValue(ba);
	}
	{
		// Lifts
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_Lifts;
		qa.addBindValue(ba);
	}
	{
		// Log
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_EventLogLock.lock();
		out << *m_EventLog;
		m_EventLogLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// Room lights
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_RoomLightStates;
		qa.addBindValue(ba);
	}
	{
		// Transporters
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		out << m_TRoomStates;
		qa.addBindValue(ba);
	}
	{
		// Turret positions
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_TurretPosLock.lockForRead();
		out << m_TurretPos;
		m_TurretPosLock.unlock();
		qa.addBindValue(ba);
	}
	{
		// City report history
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_BdLock.lockForRead();
		m_ReportHistory >> out;
		out << m_ReportPopBirths;
		out << m_ReportPopIndigenousArr;
		out << m_ReportPopTravellersArr;
		out << m_ReportPopIndigenousDep;
		out << m_ReportPopTravellersDep;
		out << m_ReportPopDeaths;
		out << (quint32)0;
		out << m_ReportPopSeafarersArr;
		out << m_ReportPopSeafarersDep;
		out << m_ReportPopWanderersArr;
		out << m_ReportPopWanderersDep;
		m_BdLock.unlock();
		qa.addBindValue(ba);
	}
	qa.addBindValue(m_tmReport.UTC());
	qa.addBindValue(cityPop);
	qa.addBindValue(m_PlatformId.GetID());

	if(IndustryId() == IID_SpacecraftFactory)
	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_4_1);
		m_SpacecraftFactoryLock.lockForRead();
		out << m_CompanyMaxQ;
		out << m_CompanyOk;
		out << m_DefaultDesign;
		out << m_DesignQueue;
		out << m_MakeMinQ;
		out << m_MakingShip;
		m_SpacecraftFactoryLock.unlock();
		qa.addBindValue(ba);
	}
	else if(IndustryId() == IID_Broker)
	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_0);
		m_CargoLock.lockForRead();
		out << m_Shipments;
		out << m_TradeAgreements;
		m_CargoLock.unlock();
		qa.addBindValue(ba);
	}
	else if(IndustryId() == IID_Fence)
	{
		QByteArray ba;
		QDataStream out(&ba, QIODevice::WriteOnly);
		out.setVersion(QDataStream::Qt_5_0);
		m_FenceLock.lockForRead();
		out << m_FenceSegs;
		out << m_FenceStyle;				// AuScFence::STYLE
		m_FenceLock.unlock();
		qa.addBindValue(ba);
	}

	if(!qa.exec())
		qWarning() << "error: DaBd::Update" << Id() << Name() << sq << qa.lastError();
}

//static
DaBd* DaBd::LoadSubatoms(AuEther& ether, QSqlDatabase& db, const AuId& parentId, const AuId& idToLoad)
{
	QString sq;
	sq = QString("SELECT id,locX,locY,locZ,rotX,rotY,rotZ,timeCreate,timeModified,timeTock,timeDeath, "
			"name,allegiance,arenaTeam,conditions,damageHistory, "
			"capacitor,capitol,cityName,citizenDNA,resSpec,cargo,cargo4,damage,bank,banka,industry,qual,mfgproc,systems,shield,"
			"games,baySetting, designRpt,airPressures,doorStates,landingSystems,launchers,lifts,log, "
			"roomLights,transporters,turretPos,reportHist,reportTime,platform,scFactory,broker,fence "
			"FROM a_Bd WHERE ");
	if(!idToLoad.IsNull())
		sq += " id=" + QVariant(idToLoad.GetID()).toString();
	else
		sq += " idp=" + QVariant(parentId.GetID()).toString();
	sq += ";";
	QSqlQuery qa(QString(), db);
	qa.prepare(sq);
	qa.exec();
	while(qa.next())
	{
		DaBd *pnu = new DaBd;
		if(pnu)
		{
			// DaAtom values.
			int qv=0;	// query value index
			quint32 id = qa.value(qv++).toUInt();
			pnu->SetId(AuId(id));
			double locx = qa.value(qv++).toDouble();
			double locy = qa.value(qv++).toDouble();
			double locz = qa.value(qv++).toDouble();
			double rx = qa.value(qv++).toDouble();
			double ry = qa.value(qv++).toDouble();
			double rz = qa.value(qv++).toDouble();
			AuAtomPos pos(parentId, locx,locy,locz, rx,ry,rz);
			pnu->SetPosAndOrient(pos);

			QDateTime tmCreated = qa.value(qv++).toDateTime();
			QDateTime tmModify = qa.value(qv++).toDateTime();
			QDateTime tmTocked = qa.value(qv++).toDateTime();
			QDateTime tmDeath = qa.value(qv++).toDateTime();
			tmCreated.setTimeSpec(Qt::UTC);
			tmModify.setTimeSpec(Qt::UTC);
			tmTocked.setTimeSpec(Qt::UTC);
			tmDeath.setTimeSpec(Qt::UTC);
			QDateTime now(QDateTime::currentDateTime());
			now.setTimeSpec(Qt::UTC);
			if(tmCreated > now)
				tmCreated = now;
			if(tmModify > now)
				tmModify = now;
			if(tmTocked > now)
				tmTocked = now;
			pnu->SetCreatedTime(tmCreated);
			pnu->SetModifyTime(tmModify);
			pnu->SetTockTime(tmTocked);
			pnu->SetDeathTime(tmDeath);

			// DaUnit values.
			pnu->SetName(qa.value(qv++).toString());
			pnu->SetAllegiance(qa.value(qv++).toUInt());
			pnu->SetArenaTeam(qa.value(qv++).toUInt());
			int qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Conditions
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->LockConditionsForWrite();
				pnu->UnlockConditions();

				quint8 underConstruction;
				in >> underConstruction;
				if(underConstruction)
				{
					pnu->m_pConstruct = new DeConstructionProcess;
					*pnu->m_pConstruct << in;
				}
				else
					pnu->m_pConstruct = 0;
			}
			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Unit Damage History
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				quint32 c;
				AuUnitDamageHash& ud = pnu->LockUnitDamageForWrite();
				in >> c;
				while(c--)
				{
					AuId i;
					AuUnitDamage d;

					in >> i;
					in >> d;

					ud.insert(pair<AuId, AuUnitDamage>(i, d));
				}
				pnu->UnlockUnitDamage();
			}

			// DaBd values.
			pnu->m_CapacitorLevel = qa.value(qv++).toDouble();
			pnu->m_CapitolId = AuId(qa.value(qv++).toUInt());
			pnu->m_CityName = qa.value(qv++).toString();

			// Citizen DNA and population.
			QByteArray ba3 = qa.value(qv++).toByteArray();
			QByteArray ba4 = qa.value(qv++).toByteArray();
			if(!ba3.isEmpty())
			{
				// Old citizenDNA field has contents so it must be valid.
				QDataStream in(ba3);
				in.setVersion(QDataStream::Qt_4_1);
				DhDNA dna3;
				in >> dna3;
				pnu->m_ResidentEcoRole = dna3.EcoRole();
				pnu->m_ResidentSpecies = dna3.Species();
				in >> pnu->m_Residents;

				QMap<DhDNA, quint32> oldRes;
				in >> oldRes;
				for(QMap<DhDNA, quint32>::const_iterator ri = oldRes.cbegin(); ri != oldRes.cend(); ri++)
					pnu->m_TransientPopulation.insert(ri.key().Species(), *ri);
				in >> pnu->m_Workers;
			}
			else
			{
				QDataStream in(ba4);
				in.setVersion(QDataStream::Qt_5_7);
				quint8 ui8;
				in >> ui8;
				pnu->m_ResidentEcoRole = (ECOROLE)ui8;
				in >> pnu->m_ResidentSpecies;
				in >> pnu->m_Residents;

				quint16 trans;
				in >> trans;
				while(trans--)
				{
					AuSpecies species;
					in >> species;
					quint32 pop;
					in >> pop;
					pnu->m_TransientPopulation.insert(species, pop);
				}
				in >> pnu->m_Workers;
			}

			// Cargo
			ba3 = qa.value(qv++).toByteArray();
			ba4 = qa.value(qv++).toByteArray();
			if(!ba3.isEmpty())
			{
				// Old field has data so it must be valid.
				QDataStream in(ba3);
				in.setVersion(QDataStream::Qt_4_1);
				AuItemHash fuel;
				fuel << in;	// Fuel used to be stored separately.
				pnu->m_Cargo << in;
				pnu->m_Cargo.AddItems(fuel);
				pnu->m_Tools << in;
				in >> pnu->m_Patents;
				DhDNA dna3;
				in >> dna3;
				pnu->m_LivestockSpecies = dna3.Species();
				in >> pnu->m_StoreCommodity;
			}
			else if(!ba4.isEmpty())
			{
				QDataStream in(ba4);
				in.setVersion(QDataStream::Qt_5_7);
				quint8 ver;
				in >> ver;
				pnu->m_Cargo << in;
				pnu->m_Tools << in;
				in >> pnu->m_Patents;
				in >> pnu->m_LivestockSpecies;
				in >> pnu->m_StoreCommodity;
			}

			QByteArray ba = qa.value(qv++).toByteArray();
			if(!ba.isEmpty())
			{
				// Damage
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				pnu->m_Damage << in;
				in >> pnu->m_tmDamageChange;	// We depend on the damage change time to delay the recovery of ships in stasis.
				if(pnu->m_tmDamageChange.IsNull())
					pnu->m_tmDamageChange.Set();
			}

			// Bank changed from a double in 'bank' to a blob in 'banka'.
			double bank = qa.value(qv++).toDouble();
			ba = qa.value(qv++).toByteArray();
			if(!ba.isEmpty())
			{
				// Bank activity
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_Bank;
			}
			else
			{
				// No bank activity blob so use the old bank account balance.
				pnu->m_Bank = AuBank(bank);
			}

			pnu->m_IndustryId = (INDUSTRYID)qa.value(qv++).toUInt();
			pnu->m_QMade = qa.value(qv++).toUInt();
			if(!pnu->m_QMade)
				pnu->m_QMade = 1;

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				pnu->m_MfgProc << in;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Ship Systems
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				pnu->m_ssaShipSystems << in;
			}

			pnu->m_ShieldCap = qa.value(qv++).toDouble();

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Games
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);

				// Active games at tables.
				quint16 gameCount;
				in >> gameCount;
				//qDebug() << "DaBd::LoadSubatoms" << pnu->Id() << pnu->Name() << "games" << gameCount;

				quint8 gameType;
				quint16 whichTable;
				AuGame* game;
				for(; gameCount; gameCount--)
				{
					in >> whichTable;
					in >> gameType;
					game = AuGame::CreateGame(gameType);
					if(game)
					{
						// The game object was created.
						in >> *game;
						pnu->m_Games.insert(pair<quint16, AuGame*>(whichTable, game));
					}
					else
					{
						qWarning() << "error: Bd" << pnu->Id() << pnu->Name() << "Game table" << whichTable
							<< "loaded unknown game type" << gameType;
						break;
					}
				}
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Weapon bay settings
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);

				pnu->m_BaySetting.clear();
				quint32 n;
				in >> n;
				//qDebug() << "DaBd::LoadSubatoms" << pnu->Id() << pnu->Name() << "bay settings" << n;
				while(n--)
				{
					quint16 key;
					AuBaySetting val;
					in >> key;
					in >> val;
					pnu->m_BaySetting.insert(pair<quint16, AuBaySetting>(key, val));
				}

				pnu->m_Turrets.clear();
				in >> n;
				//qDebug() << "DaBd::LoadSubatoms" << pnu->Id() << pnu->Name() << "turret settings" << n;
				while(n--)
				{
					quint16 key;
					AuOrdnance val;
					in >> key;
					in >> val;
					pnu->m_Turrets.insert(pair<quint16, AuOrdnance>(key, val));
				}

				pnu->m_BayFired.clear();
				in >> n;
				//qDebug() << "DaBd::LoadSubatoms" << pnu->Id() << pnu->Name() << "bay settings" << n;
				while(n--)
				{
					quint16 key;
					AuBayFired val;
					in >> key;
					in >> val;
					pnu->m_BayFired.insert(pair<quint16, AuBayFired>(key, val));
				}
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Design report
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_Design;
				quint8 ver;
				in >> ver;
				if(ver >= 1)
				{
					in >> pnu->m_FounderId;
					in >> pnu->m_FounderName;
				}

				if(ver >= 2)
				{
					// Surveyed rocks.
					quint16 rcount;
					in >> rcount;
					while(rcount--)
					{
						quint16 cid;
						quint32 cidcount;
						in >> cid;
						in >> cidcount;
						pnu->m_RocksOnSite.insert((COMMODITYID)cid, cidcount);
					}
				}
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Air Pressures
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_AirPressures;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Door states
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_DoorStates;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Landing Systems
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_LandingSystemStates;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Launchers
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_LauncherStates;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Lifts
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_Lifts;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> *pnu->m_EventLog;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Room lights
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_RoomLightStates;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Transporters
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_TRoomStates;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				// Turret positions
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_TurretPos;
			}

			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				pnu->m_ReportHistory << in;
				in >> pnu->m_ReportPopBirths;
				in >> pnu->m_ReportPopIndigenousArr;
				in >> pnu->m_ReportPopTravellersArr;
				in >> pnu->m_ReportPopIndigenousDep;
				in >> pnu->m_ReportPopTravellersDep;
				in >> pnu->m_ReportPopDeaths;
				quint32 usedToBePowerConsumed;
				in >> usedToBePowerConsumed;
				in >> pnu->m_ReportPopSeafarersArr;
				in >> pnu->m_ReportPopSeafarersDep;
				in >> pnu->m_ReportPopWanderersArr;
				in >> pnu->m_ReportPopWanderersDep;
				if(!pnu->m_ReportHistory.IsEmpty())
				{
					pnu->m_Morale = pnu->m_ReportHistory.Last().Morale();
					pnu->m_HasAir = pnu->m_ReportHistory.Last().m_AirSupply > 0;
				}
			}

			QDateTime trpt = qa.value(qv++).toDateTime();
			trpt.setTimeSpec(Qt::UTC);
			if(trpt > now)
				trpt = now;
			pnu->m_tmReport = trpt;

			AuId platform = AuId(qa.value(qv++).toUInt());
			pnu->SetPlatformId(platform);

			// Spacecraft Factory
			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_4_1);
				in >> pnu->m_CompanyMaxQ;
				in >> pnu->m_CompanyOk;
				in >> pnu->m_DefaultDesign;
				in >> pnu->m_DesignQueue;
				in >> pnu->m_MakeMinQ;
				in >> pnu->m_MakingShip;
			}

			// Broker
			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_5_0);
				in >> pnu->m_Shipments;
				in >> pnu->m_TradeAgreements;
			}

			// Fence or Wall
			qvi = qv++;
			if(!qa.value(qvi).isNull())
			{
				QByteArray ba = qa.value(qvi).toByteArray();
				QDataStream in(ba);
				in.setVersion(QDataStream::Qt_5_0);
				in >> pnu->m_FenceSegs;
				in >> pnu->m_FenceStyle;
			}

			if(pnu->IndustryId() == IID_Fence && pnu->m_FenceSegs.empty())
			{
				qDebug() << "DaBd::LoadSubatoms" << *pnu << "discarded no fence segs";
				delete pnu;
				pnu = 0;
				continue;
			}

			pnu->ReconcileSystems();
			pnu->ConnectSignals();
			ether.AddAtom(pnu);
			pnu->SetNormal();	// New atom is ready for normal thread processing. This must be done before loading subatoms.

			// Load subatoms of the nu atom AFTER adding it to its pnu parent.
			DaAnimal::LoadSubatoms(ether, db, pnu->Id());
			DaSc::LoadSubatoms(ether, db, pnu->Id());
			DaVehicle::LoadSubatoms(ether, db, pnu->Id());
			DaItem::LoadSubatoms(ether, db, pnu->Id());
			DaPerson::LoadSubatoms(ether, db, pnu->Id());
			DaNpc::LoadSubatoms(ether, db, pnu->Id());

			if(g_Au.IsSceneWorker())
			{
				// Insure the local application has a copy of my design loaded.
				// This is a soft request, only loading the design if it's not already loaded.
				pnu->DesignGeometryNeeded();
			}
		}
		if(!idToLoad.IsNull())
			return pnu;
	}
	return 0;
}

bool DaBd::InsideRoom(const AuPoint& loc, quint16& roomId) const
{
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	roomId = scd->RoomVoidContainingLocLive(loc, .1, m_DoorStates, m_Lifts);
	UnlockDesign();
	m_DesignLock.unlock();
	return roomId;
}

quint16 DaBd::InsideRoomType(const AuPoint& loc, ROOMTYPE& roomType, QString& roomName) const
{
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	quint16 roomId = scd->RoomVoidContainingLocLive(loc, .1, m_DoorStates, m_Lifts);
	HOLD_ACCESS a;
	if(roomId)
	{
		a = scd->RoomVoidHoldAccess(roomId);
		roomName = scd->RoomVoidName(roomId);
	}
	else
	{
		if(m_Design.HasEnvironmentVoid())
			roomId = scd->EnvironmentVoidContainingLocLive(loc, m_DoorStates, m_Lifts);
		if(roomId)
		{
			roomName = tr("Environment Void");
			a = HOLD_Inaccessible;
		}
		else
		{
			if(scd->Structure() == BD_AerialPlatform ||
					scd->Structure() == BD_GroundPlatform ||
					scd->Structure() == BD_SeaPlatform)
				roomId = scd->InBuildZone(loc);
			if(roomId)
			{
				roomName = tr("Build Zone");
				a = HOLD_Inaccessible;
			}
			else
			{
				a = HOLD_Inaccessible;
				if(scd->IsInsideHull(loc, m_DoorStates, m_Lifts))
				{
					roomName = AuScPart::GroupNameHull();
					roomType = ROOM_Hull;
				}
				else
					roomName = "";
			}
		}
	}
	UnlockDesign();
	m_DesignLock.unlock();
	if(roomId)
	{
		// Assign a room type based on hold access.
		switch(a)
		{
		case HOLD_Inaccessible:
		case HOLD_Count:
			roomType = ROOM_Corridor;
			break;
		case HOLD_Armory:
			roomType = ROOM_Barracks;
			break;
		case HOLD_Bar:
			roomType = ROOM_Lounge;
			break;
		case HOLD_Feeder:
			roomType = ROOM_Brig;
			break;
		case HOLD_FuelCoupling:
			roomType = ROOM_EngineRoom;
			break;
		case HOLD_VehicleBay:
			roomType = ROOM_VehicleBay;
			break;
		case HOLD_Hold:
			roomType = ROOM_Hold;
			break;
		case HOLD_Pantry:
			roomType = ROOM_Galley;
			break;
		case HOLD_Pharmacy:
			roomType = ROOM_SickBay;
			break;
		case HOLD_Wardrobe:
			roomType = ROOM_Stateroom;
			break;
		}
	}
	return roomId;
}

bool DaBd::InsideRoomType(const AuPoint& loc, bool getRoomUp, quint16& roomId, ROOMTYPE& roomType, double& htAbvFloor,
		QString& roomName, AuPoint& gravityN) const
{
	roomId = InsideRoomType(loc, roomType, roomName);
	if(!roomId)
		return false;

	gravityN = GravityNormal();
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	if(scd)
	{
		// 'roomId' could be a build zone, when transporting to a platform. In that case, the platform returned a target location
		// that was on the deck. Consequently, the default return of 0 for RoomVoidHeightAboveFloor from a build zone is ok.
		htAbvFloor = scd->RoomVoidHeightAboveFloor(roomId, loc, getRoomUp, gravityN, m_Lifts);	// Height above room void floor.
	}
	else
		htAbvFloor = 0;
	UnlockDesign();
	m_DesignLock.unlock();
	return true;
}

void DaBd::WindowSurfaceGlow(const QString& windowName, float& glowR, float& glowG, float& glowB) const
{
	if(IsDestroyed() || !m_AV)
	{
		glowR = 0;
		glowG = 0;
		glowB = 0;
		return;
	}

	INTERIOR_LIGHT interiorLight;
	m_RoomLightLock.lockForRead();
	AuRoomLightStateHash::const_iterator li = m_RoomLightStates.find(windowName);
	if(li != m_RoomLightStates.cend())
		interiorLight = (INTERIOR_LIGHT)*li;
	else
	{
		AuRoomLightStateHash::const_iterator wi = m_AV->m_WindowLightStates.find(windowName);
		if(wi != m_AV->m_WindowLightStates.cend())
			interiorLight = (INTERIOR_LIGHT)*wi;
		else
			interiorLight = INTLIGHT_Dark;
	}
	m_RoomLightLock.unlock();

	if(DbIndustry::IsCandleLit(IndustryId()))
	{
		if(HasPower())
		{
			if(interiorLight == INTLIGHT_Bright)
			{
				// Bright interior lighting.
				const QColor& c = AuGLLight::ColorTungsten100W();
				glowR = AuGLLight::AmbientLitInterior()*c.redF();
				glowG = AuGLLight::AmbientLitInterior()*c.greenF();
				glowB = AuGLLight::AmbientLitInterior()*c.blueF();
			}
			else if(interiorLight == INTLIGHT_Dim)
			{
				// Dim interior lighting.
				const QColor& c = AuGLLight::ColorTungsten40W();
				glowR = AuGLLight::AmbientLitInteriorDim()*c.redF();
				glowG = AuGLLight::AmbientLitInteriorDim()*c.greenF();
				glowB = AuGLLight::AmbientLitInteriorDim()*c.blueF();
			}
			else
			{
				// No interior lighting means no window glow.
				glowR = 0;
				glowG = 0;
				glowB = 0;
				return;
			}
		}
		else
		{
			// No power for interior lighting.
			if(interiorLight == INTLIGHT_Bright)
			{
				// Bright interior lighting.
				const QColor& c = AuGLLight::ColorTorch();
				glowR = AuGLLight::AmbientLitInteriorDim()*c.redF();
				glowG = AuGLLight::AmbientLitInteriorDim()*c.greenF();
				glowB = AuGLLight::AmbientLitInteriorDim()*c.blueF();
			}
			else if(interiorLight == INTLIGHT_Dim)
			{
				// Dim interior lighting.
				const QColor& c = AuGLLight::ColorCandle();
				glowR = AuGLLight::AmbientLitInteriorDim()/2*c.redF();
				glowG = AuGLLight::AmbientLitInteriorDim()/2*c.greenF();
				glowB = AuGLLight::AmbientLitInteriorDim()/2*c.blueF();
			}
			else
			{
				// No interior lighting means no window glow.
				glowR = 0;
				glowG = 0;
				glowB = 0;
				return;
			}
		}
	}
	else
	{
		if(HasPower())
		{
			if(interiorLight == INTLIGHT_Bright)
			{
				// Bright interior lighting.
				const QColor& c = AuGLLight::ColorFluorescentTubeDaylight();
				glowR = AuGLLight::AmbientLitInterior()*c.redF();
				glowG = AuGLLight::AmbientLitInterior()*c.greenF();
				glowB = AuGLLight::AmbientLitInterior()*c.blueF();
			}
			else if(interiorLight == INTLIGHT_Dim)
			{
				// Dim interior lighting.
				const QColor& c = AuGLLight::ColorFluorescentTubeCoolWhite();
				glowR = AuGLLight::AmbientLitInteriorDim()*c.redF();
				glowG = AuGLLight::AmbientLitInteriorDim()*c.greenF();
				glowB = AuGLLight::AmbientLitInteriorDim()*c.blueF();
			}
			else
			{
				// No interior lighting means no window glow.
				glowR = 0;
				glowG = 0;
				glowB = 0;
				return;
			}
		}
		else
		{
			// No interior lighting means no window glow.
			glowR = 0;
			glowG = 0;
			glowB = 0;
			return;
		}
	}

	// Shift colors to red when there is no air or power in a harsh environment.
	if(!IsAirBreathable() && (!m_HasAir || !HasPower()))
	{
		glowG *= .05f;
		glowB *= .05f;
	}

	if(glowR < 0.f)
		glowR = 0.f;
	else if(glowR > 1.f)
		glowR = 1.f;

	if(glowG < 0.f)
		glowG = 0.f;
	else if(glowG > 1.f)
		glowG = 1.f;

	if(glowB < 0.f)
		glowB = 0.f;
	else if(glowB > 1.f)
		glowB = 1.f;
}

void DaBd::InteriorAmbientLight(const QString& roomName, float& ambientR, float& ambientG, float& ambientB, bool& sunsBlocked) const
{
	// Calculate ambient lighting from interior lights, if any.
	if(DbIndustry::IsCandleLit(IndustryId()))
	{
		INTERIOR_LIGHT interiorLight = InteriorLight(roomName);
		if(HasPower())
		{
			if(interiorLight == INTLIGHT_Bright)
			{
				// Bright interior lighting.
				const QColor& c = AuGLLight::ColorTungsten100W();
				ambientR = AuGLLight::AmbientLitInterior()*c.redF();
				ambientG = AuGLLight::AmbientLitInterior()*c.greenF();
				ambientB = AuGLLight::AmbientLitInterior()*c.blueF();
			}
			else if(interiorLight == INTLIGHT_Dim)
			{
				// Dim interior lighting.
				const QColor& c = AuGLLight::ColorTungsten40W();
				ambientR = AuGLLight::AmbientLitInteriorDim()*c.redF();
				ambientG = AuGLLight::AmbientLitInteriorDim()*c.greenF();
				ambientB = AuGLLight::AmbientLitInteriorDim()*c.blueF();
			}
			else
			{
				// Very little interior lighting, not quite black.
				ambientR = AuGLLight::AmbientDarkInterior();
				ambientG = AuGLLight::AmbientDarkInterior();
				ambientB = AuGLLight::AmbientDarkInterior();
			}
		}
		else
		{
			// No power for interior lighting.
			if(interiorLight == INTLIGHT_Bright)
			{
				// Bright interior lighting.
				const QColor& c = AuGLLight::ColorTorch();
				ambientR = AuGLLight::AmbientLitInteriorDim()*c.redF();
				ambientG = AuGLLight::AmbientLitInteriorDim()*c.greenF();
				ambientB = AuGLLight::AmbientLitInteriorDim()*c.blueF();
			}
			else if(interiorLight == INTLIGHT_Dim)
			{
				// Dim interior lighting.
				const QColor& c = AuGLLight::ColorCandle();
				ambientR = AuGLLight::AmbientLitInteriorDim()/2*c.redF();
				ambientG = AuGLLight::AmbientLitInteriorDim()/2*c.greenF();
				ambientB = AuGLLight::AmbientLitInteriorDim()/2*c.blueF();
			}
			else
			{
				// Very little interior lighting, not quite black.
				ambientR = AuGLLight::AmbientDarkness();
				ambientG = AuGLLight::AmbientDarkness();
				ambientB = AuGLLight::AmbientDarkness();
			}
		}
	}
	else
	{
		if(HasPower())
		{
			INTERIOR_LIGHT interiorLight = InteriorLight(roomName);
			if(interiorLight == INTLIGHT_Bright)
			{
				// Bright interior lighting.
				const QColor& c = AuGLLight::ColorFluorescentTubeDaylight();
				ambientR = AuGLLight::AmbientLitInterior()*c.redF();
				ambientG = AuGLLight::AmbientLitInterior()*c.greenF();
				ambientB = AuGLLight::AmbientLitInterior()*c.blueF();
			}
			else if(interiorLight == INTLIGHT_Dim)
			{
				// Dim interior lighting.
				const QColor& c = AuGLLight::ColorFluorescentTubeCoolWhite();
				ambientR = AuGLLight::AmbientLitInteriorDim()*c.redF();
				ambientG = AuGLLight::AmbientLitInteriorDim()*c.greenF();
				ambientB = AuGLLight::AmbientLitInteriorDim()*c.blueF();
			}
			else
			{
				// Very little interior lighting, not quite black.
				ambientR = AuGLLight::AmbientDarkInterior();
				ambientG = AuGLLight::AmbientDarkInterior();
				ambientB = AuGLLight::AmbientDarkInterior();
			}
		}
		else
		{
			// No power for interior lighting.
			ambientR = AuGLLight::AmbientDarkness();
			ambientG = AuGLLight::AmbientDarkness();
			ambientB = AuGLLight::AmbientDarkness();
		}
	}

	sunsBlocked = m_AV && !m_AV->m_SunlitRooms.contains(roomName);
	if(!sunsBlocked)
	{
		// Add ambient light level of external environment.
		float extAmbR;
		float extAmbG;
		float extAmbB;
		float fogDen, fogR, fogG, fogB;
		bool eSunsBlocked;
		SceneRenderParameters(0, extAmbR, extAmbG, extAmbB, fogDen, fogR, fogG, fogB, false, eSunsBlocked);
		ambientR += extAmbR*.85f;
		ambientG += extAmbG*.85f;
		ambientB += extAmbB*.85f;
		if(eSunsBlocked)
			sunsBlocked = true;
	}

	// Clamp RGB values.
	if(ambientR < 0.f)
		ambientR = 0.f;
	else if(ambientR > 1.f)
		ambientR = 1.f;

	if(ambientG < 0.f)
		ambientG = 0.f;
	else if(ambientG > 1.f)
		ambientG = 1.f;

	if(ambientB < 0.f)
		ambientB = 0.f;
	else if(ambientB > 1.f)
		ambientB = 1.f;
}

INTERIOR_LIGHT DaBd::InteriorLight(const QString& roomName) const
{
	INTERIOR_LIGHT v;
	m_RoomLightLock.lockForRead();
	AuRoomLightStateHash::const_iterator li = m_RoomLightStates.find(roomName);
	if(li != m_RoomLightStates.cend())
		v = (INTERIOR_LIGHT)*li;
	else
		v = INTLIGHT_Dark;
	m_RoomLightLock.unlock();
	return v;
}

bool DaBd::InteriorLightToggle(INTERIOR_LIGHT state)
{
	bool anySet = false;
	m_RoomLightLock.lockForWrite();
	for(AuRoomLightStateHash::iterator li = m_RoomLightStates.begin(); li != m_RoomLightStates.end(); li++)
		if(*li != state)
		{
			*li = state;
			anySet = true;
		}
	if(anySet)
		m_RoomLightChg.Set();
	m_RoomLightLock.unlock();
	return anySet;
}

bool DaBd::InteriorLightToggle(const QString& roomName, INTERIOR_LIGHT state)
{
	bool anySet = false;
	m_RoomLightLock.lockForWrite();
	AuRoomLightStateHash::iterator li = m_RoomLightStates.find(roomName);
	if(li != m_RoomLightStates.end() && *li != state)
	{
		*li = state;
		anySet = true;
	}
	if(anySet)
		m_RoomLightChg.Set();
	m_RoomLightLock.unlock();
	return anySet;
}

