bool DaBd::IsDoorOnWall(unsigned int doorIndex) const
{
	Q_UNUSED(doorIndex);
	// In practice, this is used to decide if a doorway has an associated ladder. AuBdReport::EntranceLocation returns ladders as
	// 'holes', so we'll say all doors are on the wall, without ladders.
	return true;
}

bool DaBd::IsDoorOpen(unsigned int doorIndex) const
{
	m_DesignLock.lockForRead();
	bool is = m_DoorStates.IsDoorOpen(doorIndex);
	m_DesignLock.unlock();
	return is;
}

bool DaBd::IsHoleOnWall(unsigned int holeIndex) const
{
	// In practice, this is used to decide if a hole has an associated ladder. AuBdReport::EntranceLocation returns ladders as
	// 'holes' with a non zero index. Holes with a zero index are ladderless openings in the hull, equivalent to a hole on a wall
	// in the old designs.
	return holeIndex == 0;
}

bool DaBd::IsHullDoor(int doorIndex) const
{
	m_DesignLock.lockForRead();
	bool is = m_DoorStates.IsHullDoor(doorIndex);
	m_DesignLock.unlock();
	return is;
}

// returns 0=no, 1=in hull, 2=on hull, 3=under hull hatch
int DaBd::IsInOrOnHull(const AuPoint& loc) const
{
	bool v;
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	if(scd)
		v = scd->IsInsideHull(loc, m_DoorStates, m_Lifts);
	else
		v = false;
	UnlockDesign();
	m_DesignLock.unlock();
	return v;
}

bool DaBd::IsInScene(const DaPerson* sceneAtom, const AuPoint& cameraEnvLoc) const
{
	Q_UNUSED(cameraEnvLoc);
	bool isInScene = sceneAtom->IsNearPlanet() &&
		FindParentWorldNotSatelliteInEnv() == sceneAtom->FindParentWorldNotSatelliteInEnv();
	return isInScene;
}

bool DaBd::IsInsideAirBreathable() const
{
	// Check air pressure in all rooms. Any breathable air and the answer is yes.
	// NOTE: The 15%-85% pressure range matches the atmosphere density requirement in DaWorld::HasBreathableAtmosphere.
	bool anyAir = false;
	m_AirLock.lockForRead();
	for(AuAirPressureHash::const_iterator ai = m_AirPressures.cbegin(); ai != m_AirPressures.cend(); ai++)
		if(*ai >= 30 && *ai <= 170)
		{
			anyAir = true;
			break;
		}
	m_AirLock.unlock();
	return anyAir;
}

bool DaBd::IsObstacle(const DaAtom* toWho) const
{
	if(IsInAtmosphere() != toWho->IsInAtmosphere())
		return false;
	const DaMissile* missile = dynamic_cast<const DaMissile*>(toWho);	// Includes bombs.
	if(missile)
	{
		if(IsDestroyed() || missile->IsArmedBy(Id()))
			return false;	// I am not an obstacle to my own munitions or when destroyed.
	}
	return true;	// Buildings are obstacles to movement.
}

bool DaBd::IsPathBlocked(const AuPoint& oloc, const AuPoint& nloc, AuPoint& hitLoc, AuPoint& hitNormal, const DaAtom* toWho)
{
	if(!IsDesignDataCacheValid())
	{
		hitLoc = oloc;
		hitNormal = AuPoint(0,0,0);								// Do not bounce.
		return true;											// No movement allowed until the design is valid.
	}

	const DaPerson* person = dynamic_cast<const DaPerson*>(toWho);
	if(person)
	{
		// Entity is not blocked by spacecraft hull.
		if(person->AgentEntity())
			return false;
	}
	else if(IsDestroyed())
	{
		if(dynamic_cast<const DaMissile*>(toWho))
			return false;	// Missiles do not hit destroyed buildings or they act as impenetrable shields.
	}

	if(IndustryId() == IID_Fence)
	{
		AuPoint myLoc = AuPoint(0,0);
		if(myLoc.DistToSegment(oloc, nloc) > RoughRadius())
			return false;
	}

	// The rough test passed, we need to get more detailed.
	QHash<quint32, AuSegmentArray> fenceSegs;
	if(!IsUnderConstruction())
	{
		// Fences and walls are not obstructions while under construction.
		const DaWorldLL* world = FindParentWorldInEnv();
		if(world)
		{
			FenceSegments(fenceSegs);
			if(!fenceSegs.empty())
			{
				bool hitMe = false;
				AuPoint woloc = Transform() * oloc;	// In the space of the world.
				AuPoint wnloc = Transform() * nloc;	// In the space of the world.
				AuPoint wn;
				bool onPlatform = OnPlatform();
				for(QHash<quint32, AuSegmentArray>::iterator fi = fenceSegs.begin(); fi != fenceSegs.end(); fi++)
				{
					AuScFaceList upost;		// post barrier faces
					AuScFaceList usect;		// section barrier faces
					AuScFaceList vsect;		// visible section faces
					quint32 fenceStyle = fi.key();
					if(fenceStyle == AuScFence::Custom)
					{
						// Preview of current fence design in the designer.
						const AuBdDesign* scd = LockDesign();
						if(scd)
						{
							scd->BarrierFaces(upost, AuScPart::GroupNameFencePost());
							scd->BarrierFaces(usect, AuScPart::GroupNameFenceSection());
							scd->VisibleFaces(vsect, AuScPart::GroupNameFenceSection());
						}
						UnlockDesign();
					}
					else if(fenceStyle < AuScFence::Custom)
					{
						// Built in fence design.
						// Get post and section barrier faces from built in fence styles.
						AuScFence::FencePostBarrierFaces((AuScFence::STYLE)fenceStyle, upost);
						bool testPanel;
						switch((AuScFence::STYLE)fenceStyle)
						{
						case AuScFence::Posts:
						case AuScFence::PostsT:
							testPanel = false;								// Posts only, no panel.
							break;
						case AuScFence::SplitRail:
						case AuScFence::Wire:
						case AuScFence::WireT:
							{
								const DaCreature* crea = dynamic_cast<const DaCreature*>(toWho);
								if(crea)
									testPanel = crea->MaxHitPoints() > 100;	// Wire fences block creatures with more than 100hp.
								else if(dynamic_cast<const DaItem*>(toWho))
									testPanel = false;						// Items pass through wire and split rail fences.
								else
									testPanel = true;
							}
							break;
						case AuScFence::Range:
						case AuScFence::RangeT:
							{
								const DaCreature* crea = dynamic_cast<const DaCreature*>(toWho);
								if(crea)
									testPanel = crea->MaxHitPoints() > 10;	// Range fences block creatures with more than 10hp.
								else
									testPanel = true;						// Nothing else passes through range fences.
							}
							break;
						case AuScFence::ChainLink:
						case AuScFence::ChainLinkRazorWire:
						case AuScFence::SandBagWall:
						case AuScFence::BrickWall:
						case AuScFence::StoneWall:
						case AuScFence::WoodYard:
							testPanel = true;								// These fences block everything.
							break;
						case AuScFence::Custom:
						case AuScFence::STYLE_Count:
							testPanel = false;	// wut?
							break;
						}
						if(testPanel)
						{
							AuScFence::FenceSectionBarrierFaces((AuScFence::STYLE)fenceStyle, usect);
							AuScFence::FenceSectionFaces((AuScFence::STYLE)fenceStyle, vsect);
						}
					}
					else
					{
						// Custom fence design.
						const DgData& sdd = g_Au.LockBdDesignsForRead();
						AuBdDesignHash::const_iterator di = sdd.m_BdDesigns->find(fi.key());
						if(di != sdd.m_BdDesigns->cend())
						{
							(*di).second.BarrierFaces(upost, AuScPart::GroupNameFencePost());
							(*di).second.BarrierFaces(usect, AuScPart::GroupNameFenceSection());
							(*di).second.VisibleFaces(vsect, AuScPart::GroupNameFenceSection());
						}
						g_Au.UnlockBdDesigns();
					}
					if(upost.empty() && usect.empty())
						continue;	// No barriers.

					AuPointArray posts;					// Locations where we have already tested a post.
					for(AuSegmentArray::iterator si = (*fi).begin(); si != (*fi).end(); si++)
					{
						// On a platform at at fence building, fence segments are already conformant to terrain.
						if(!onPlatform && IndustryId() != IID_Fence)
						{
							AuGlobeLL postll1;
							if(world->LLOfLoc(postll1, (*si).m_fLoc1))
								(*si).m_fLoc1 = world->GetSurfaceLocation(postll1);	// Adjust the post location to the terrain.
							AuGlobeLL postll2;
							if(world->LLOfLoc(postll2, (*si).m_fLoc2))
								(*si).m_fLoc2 = world->GetSurfaceLocation(postll2);	// Adjust the post location to the terrain.
						}

						AuPoint vUp1 = -world->GravityDir((*si).m_fLoc1);		// Up vector at post 1.
						AuPoint vUp2 = -world->GravityDir((*si).m_fLoc2);		// Up vector at post 2.

						// Test posts.
						if(!upost.empty())
						{
							AuPoint segVec((*si).m_fLoc2 - (*si).m_fLoc1);
							segVec.Unit();
							if(!posts.contains((*si).m_fLoc1))
							{
								posts.append((*si).m_fLoc1);
								AuPoint vFacing(vUp1.Cross(segVec));
								vFacing.Unit();
								AuPoint vX = vFacing.Cross(vUp1);
								vX.Unit();
								AuMatrix4x4 postM((*si).m_fLoc1, vX, vFacing);
								AuScFaceList post(upost);						// Get faces so we can transform them.
								post.Transform(postM);							// Transform the faces to the post location.

								// Test for collision with the post.
								if(post.Sight(woloc, wnloc, wn))
									hitMe = true;
							}
							if(!posts.contains((*si).m_fLoc2))
							{
								posts.append((*si).m_fLoc2);
								AuPoint vFacing(vUp2.Cross(segVec));
								vFacing.Unit();
								AuPoint vX = vFacing.Cross(vUp2);
								vX.Unit();
								AuMatrix4x4 postM((*si).m_fLoc2, vX, vFacing);
								AuScFaceList post(upost);						// Get faces so we can transform them.
								post.Transform(postM);							// Transform the faces to the post location.

								// Test for collision with the post.
								if(post.Sight(woloc, wnloc, wn))
									hitMe = true;
							}
						}

						// Test section.
						if(!usect.empty())
						{
							AuScFaceList sect(usect);
							sect.FenceConform(*si, vUp1, vUp2, vsect.Max().x);

							// Test for collision with the section.
							if(sect.Sight(woloc, wnloc, wn))
								hitMe = true;
						}
					}
				}
				if(hitMe)
				{
					// Calculate resulting hit location and hit normal in my space.
					hitLoc = Transform().UnProject(wnloc);
					hitNormal = Transform().UnProjectVector(wn);
					hitNormal.Unit();
					return true;
				}
			}
		}
	}
	if(IndustryId() == IID_Fence)
		return false;

	if(ShieldsBlockWeapons() && !ShieldContains(oloc))
	{
		// The atom is moving outside my shield bubble.
		AuPoint isect1, isect2;
		AuSphere s(ShieldBubbleCenter(), ShieldBubbleRadius());
		int isect = s.Intersect(oloc, nloc, isect1, isect2);
		if(isect > 0)
		{
			// The path intersects my shield bubble.
			// If our relative speed is too fast, bounce them.
			DaAtom* cp = CommonParent(toWho, 0);
			if(cp && cp != this)
			{
				AuMatrix4x4 tme;
				AuMatrix4x4 twho;
				if(GetTransformRelativeToParent(tme, cp) && toWho->GetTransformRelativeToParent(twho, cp))
				{
					AuPoint vwho(twho.ProjectVector(toWho->Vector()));	// toWho's vector relative to the common parent.
					vwho = tme.UnProjectVector(vwho);					// toWho's vector relative to me.
					if(vwho.Length() > ShieldCollisionSpeed())
					{
						// toWho is moving more than the shield collision speed, relative to me.
						hitLoc = isect1;
						hitNormal = isect1;
						hitNormal.Unit();
						return true;
					}
				}
			}
		}
	}

	// Creatures and items may open automatic doors along the path.
	if(toWho && toWho->OpensAutomaticDoors())
	{
		QSet<quint16> opened;
		m_DesignLock.lockForWrite();
		if(m_DoorStates.OpenAutomaticDoors(oloc, nloc, FeetPerMeter()*2, opened))
		{
			m_DoorChg.Set();
			for(QSet<quint16>::const_iterator oi = opened.cbegin(); oi != opened.cend(); oi++)
				m_DoorOpenTimes.insert(*oi, AuTime::Now());
			SetModified();
		}
		m_DesignLock.unlock();
	}

	bool is;
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	if(scd)
		is = scd->IsPathBlocked(oloc, nloc, hitLoc, hitNormal, m_DoorStates, m_Lifts);
	else
		is = false;
	UnlockDesign();
	m_DesignLock.unlock();
	return is;
}

bool DaBd::IsTransporterSystemActive(int troomIndex) const
{
	m_TRoomLock.lockForRead();
	AuTransporterSystemStateHash::const_iterator ti = m_TRoomStates.find(troomIndex);
	bool v = ti != m_TRoomStates.cend() && *ti == TRANSPORTER_Active;
	m_TRoomLock.unlock();
	return v;
}

bool DaBd::IsTransporterSystemOn(int troomIndex) const
{
	m_TRoomLock.lockForRead();
	AuTransporterSystemStateHash::const_iterator ti = m_TRoomStates.find(troomIndex);
	bool v = ti != m_TRoomStates.cend() && (*ti == TRANSPORTER_On || *ti == TRANSPORTER_Active);
	m_TRoomLock.unlock();
	return v;
}

void DaBd::JamDoorClosed(unsigned int doorIndex)
{
	m_DesignLock.lockForWrite();
	if(m_DoorStates.JamDoorClosed(doorIndex))
	{
		m_DoorChg.Set();
		m_DoorOpenTimes.remove(doorIndex);
		SetModified();
	}
	m_DesignLock.unlock();
}

void DaBd::JamDoorOpen(unsigned int doorIndex)
{
	m_DesignLock.lockForWrite();
	if(m_DoorStates.JamDoorOpen(doorIndex))
	{
		m_DoorChg.Set();
		m_DoorOpenTimes.insert(doorIndex, AuTime::Now());
		SetModified();
	}
	m_DesignLock.unlock();
}

double DaBd::Width() const
{
	AuPoint min,max;
	if(IndustryId() == IID_Fence)
	{
		// Get extents of fence segments.
		FenceExtents(min, max);
	}
	else
	{
		m_DesignLock.lockForRead();
		m_Design.Extents(min, max);
		m_DesignLock.unlock();
	}
	return max.x - min.x;
}

double DaBd::Length() const
{
	AuPoint min,max;
	if(IndustryId() == IID_Fence)
	{
		// Get extents of fence segments.
		FenceExtents(min, max);
	}
	else
	{
		m_DesignLock.lockForRead();
		m_Design.Extents(min, max);
		m_DesignLock.unlock();
	}
	return max.y - min.y;
}

double DaBd::Height() const
{
	AuPoint min,max;
	if(IndustryId() == IID_Fence)
	{
		// Get extents of fence segments.
		FenceExtents(min, max);
	}
	else
	{
		m_DesignLock.lockForRead();
		m_Design.Extents(min, max);
		m_DesignLock.unlock();
	}
	return max.z - min.z;
}

void DaBd::ListOccupiedTroopStations(QSet<quint16>& troopStations, const AuId& exceptTroop) const
{
	DaAtomList subs;
	ListNormalSubatoms(subs);
	for(DaAtomList::const_iterator it = subs.cbegin(); it != subs.cend(); it++)
	{
		DaCitizen* troop = dynamic_cast<DaCitizen*>(*it);
		if(!troop || !troop->IsNpcTroop())
			continue;
		if(troop->Is(exceptTroop))
			continue;
		if(troop->EmpireId() != EmpireId())
			continue;
		quint16 stationId = troop->StationId();
		if(!stationId)
			continue;
		if(!troop->IsPostPose())
			continue;
		troopStations.insert(stationId);
	}
}

void DaBd::ListSystems(QList<AuSystemInfo>& systems) const
{
	const AuShipSystemArray& ssa = LockSystems();

	m_DesignLock.lockForRead();
	for(AuShipSystemArray::const_iterator ssi = ssa.constBegin(); ssi != ssa.constEnd(); ssi++)
		if((*ssi).GetSystemType() != SYS_CommandAndControl &&
				(*ssi).GetSystemType() != SYS_VehicleLaunch &&
				(*ssi).GetSystemType() != SYS_VehicleLanding)
			systems.append(AuSystemInfo(*ssi, m_Design));
	m_DesignLock.unlock();

	UnlockSystems();
}

