void DaBd::TurnTransporterSystemOff(int troomIndex)
{
	m_TRoomLock.lockForWrite();
	AuTransporterSystemStateHash::iterator ti = m_TRoomStates.find(troomIndex);
	if(ti != m_TRoomStates.end())
	{
		*ti = TRANSPORTER_Off;
		m_TRoomChg.Set();
		SetModified();
	}
	m_TRoomLock.unlock();
}

void DaBd::TurnTransporterSystemOn(int troomIndex)
{
	m_TRoomLock.lockForWrite();
	AuTransporterSystemStateHash::iterator ti = m_TRoomStates.find(troomIndex);
	if(ti != m_TRoomStates.end())
	{
		*ti = TRANSPORTER_On;
		m_TRoomChg.Set();
		SetModified();
	}
	m_TRoomLock.unlock();
}

