bool DaBd::WeaponBayCanFire(quint16 which) const
{
	m_DesignLock.lockForRead();

	if(m_Design.WeaponBays().isEmpty())
	{
		m_DesignLock.unlock();
		return false;				// Ship design has no weapon bays. This can happen on ships with a FC station but no bays.
	}
	else if(!m_Design.WeaponBays().contains(which))
	{
		qDebug() << "DaBd::WeaponBayCanFire" << Id() << Name() << "bad which" << which << "total bays"
			<< m_Design.WeaponBays().count() << "firstWhich" << m_Design.WeaponBays().begin().key();
		m_DesignLock.unlock();
		return false;				// Bad 'which' value.
	}

	m_DesignLock.unlock();

	if(IsBayFiring(which))
		return false;				// Bay is still in its firing sequence.

	return true;
}

AuPoint DaBd::WeaponBayEmitLoc(quint16 whichBay, const AuPoint& gunnerLoc) const
{
	Q_UNUSED(gunnerLoc);
	AuPoint emitLoc;
	const AuBdDesign* scd = LockDesign();
	if(scd)
		emitLoc = scd->WeaponEmitLocation(whichBay);
	UnlockDesign();
	return emitLoc;
}

void DaBd::WeaponBayIds(QList<quint16>& bayIds) const
{
	m_DesignLock.lockForRead();
	bayIds = m_Design.WeaponBays().keys();
	m_DesignLock.unlock();
}

quint16 DaBd::WeaponBayNextId(quint16 which) const
{
	QList<quint16> bayIds;
	WeaponBayIds(bayIds);

	int curi = bayIds.indexOf(which) + 1;	// If not found, find return -1.

	if(curi >= bayIds.size())
		curi = 0;

	return bayIds[curi];
}

quint16 DaBd::WeaponBayPreviousId(quint16 which) const
{
	QList<quint16> bayIds;
	WeaponBayIds(bayIds);

	int curi = bayIds.indexOf(which) - 1;	// If not found, find return -1.

	if(curi < 0)
		curi = bayIds.size() - 1;

	return bayIds[curi];
}

int DaBd::WeaponBays() const
{
	m_DesignLock.lockForRead();
	int v = m_Design.WeaponBays().size();
	m_DesignLock.unlock();
	return v;
}

void DaBd::WeaponBaysWithModule(QList<quint16>& bayIds, COMMODITYID bayModule) const
{
	m_DesignLock.lockForRead();
	for(AuScReportSysVolHash::const_iterator bi = m_Design.WeaponBays().cbegin(); bi != m_Design.WeaponBays().cend(); bi++)
		if((*bi).Module() == bayModule)
			bayIds.append(bi.key());
	m_DesignLock.unlock();
}

AuPoint DaBd::WeaponLockLocation(const AuPoint& shipSysLoc, COMMODITYID harvesterModule) const
{
	Q_UNUSED(shipSysLoc);
	Q_UNUSED(harvesterModule);
	return EnvTransform().Project(TargetLocation());
}

QString DaBd::WorstDamagedSystem() const
{
	if(!IsInsideAirBreathable())
		return QObject::tr("Air Pressure");

	// Get a list of the damaged equipment systems.
	AuDamage dmg;
	DamageReportPercent(dmg, 6);

	// Determine most damaged system, based on percentage of damage.
	quint32 mostDmg = 0;
	AuSysId mostDmgId = dmg.MostDamagedSystem(mostDmg);
	return mostDmgId.ScName();
}

unsigned int DaBd::WorstSystemDamage() const
{
	if(!IsInsideAirBreathable())
		return 100;

	// Get a list of the damaged equipment systems.
	AuDamage dmg;
	DamageReportPercent(dmg, 6);

	// Determine most damaged system, based on percentage of damage.
	quint32 mostDmg = 0;
	dmg.MostDamagedSystem(mostDmg);
	return mostDmg;
}

void DaBd::DesignGeometryNeeded()
{
	if(InDesignEnvironment())
		return;
	quint32 designId = DesignId();
	if(!designId)
		return;	// Fence?

	const DgData& sdd = g_Au.LockBdDesignsForRead();
	if(!sdd.BdDesignIsLoaded(designId))
		g_Au.BdDesignNeeded(designId);
	g_Au.UnlockBdDesigns();
}

bool DaBd::HasTransporter() const
{
	m_DesignLock.lockForRead();
	bool v = m_Design.HasTransporter();
	m_DesignLock.unlock();
	return v;
}

bool DaBd::TestPowerSystem()
{
	if(CapacitorLevel() > 0)
	{
		// Capacitor has power so systems are functioning.
		bool systemsLocked = true;
		m_SystemsLock.lockForRead();
		for(AuShipSystemArray::const_iterator si = m_ssaShipSystems.cbegin(); si != m_ssaShipSystems.cend(); si++)
		{
			if((*si).GetOverclocking() && (*si).GetConnectedConsumer() >= 0)
			{
				// Found a system supply that is overclocked and in use.
				// There is a 1% chance that this will cause a problem.
				if(g_Au.Dice().Roll(1, 100) == 100)
				{
					// Damage Ship System due to overclocking.
					AuSysId sysId((*si).SysId());
					COMMODITYID sysModule = CID_Invalid;	// No module damage to buildings, only hit points.
					int hitsDamage = (*si).GetHealthCurrent() / 10;	// 10% damage
					if(!hitsDamage)
						hitsDamage = 1;
					m_SystemsLock.unlock();
					systemsLocked = false;

					m_DamageLock.lockForWrite();
					m_Damage.AddDamage(sysId, sysModule, hitsDamage);
					quint32 dmg = m_Damage.HitsDamage();
					m_DamageLock.unlock();
					if(dmg >= DesignHitsTotal())
					{
						DamageAndDestroy(tr("Overclocking caused critical %1 failure.").arg(sysId.BdName()));
						return true;
					}
					else
						DamageStateChanged();
					break;
				}
			}
		}
		if(systemsLocked)
			m_SystemsLock.unlock();
	}
	return false;
}

