QColor DaBd::LightColor() const
{
	if(HasPower() && m_AV)
		return m_AV->m_HColor;
	else
		return AuGLLight::ColorTorch();
}

float DaBd::LightkQ() const
{
	if(!m_AV)
		return 1;
	if(!HasPower())
	{
		// Powerless we get 1/2 nominal street light attenuation, unless that is more than the light was configured for.
		float atten = d_StreetLight/2;
		float kQ = 1.f/(atten * atten);	// 1/2 nominal street light attenuation
		if(kQ < m_AV->m_HkQ)
			return kQ;	// Return reduced light attenuation.
	}
	return m_AV->m_HkQ;	// Return configured light attenuation.
}

float DaBd::LightAttenuationDistance() const
{
	if(!m_AV)
		return 1;
	if(!HasPower())
	{
		// Powerless we get 1/2 nominal street light attenuation, unless that is more than the light was configured for.
		float atten = d_StreetLight/2;
		float kQ = 1/(atten * atten);	// 1/2 nominal street light attenuation
		if(kQ < m_AV->m_HkQ)
			return atten;	// Return reduced light attenuation.
	}
	return sqrtf(1/m_AV->m_HkQ);	// Return configured light attenuation.
}

bool DaBd::IsStreetLightOn() const
{
	return m_AV && m_AV->m_IsDark && !IsUnderConstruction() && Structure() == BD_StreetLight;
}

void DaBd::GetRenderLightsRecursive(const DaPerson& person, const AuMatrix4x4& model, QList<AuGLSun>& suns,
		QList<AuGLLight>& lights) const
{
	if(IsStreetLightOn())
	{
		// My light is on.
		AuGLLight::ROLE lightRole = person.FindParentCapsuleInEnv() == this ? AuGLLight::SceneSpacecraft : AuGLLight::Spacecraft;
		AuPoint lpos = model.Project(m_AV->m_HPos);
		if(m_AV->m_HCosInnerCone > -1 || m_AV->m_HCosOuterCone > -1)
		{
			AuPoint ldir = model.ProjectVector(m_AV->m_HDir);
			lights.append(AuGLLight(Id(), lightRole, m_AV->m_HkL, LightkQ(), LightColor(), lpos, m_AV->m_HCosOuterCone, m_AV->m_HCosInnerCone, ldir));
		}
		else
			lights.append(AuGLLight(Id(), lightRole, m_AV->m_HkL, LightkQ(), LightColor(), lpos));
	}

	// Make lights for subordinate atoms, particularly the scene atom and potentially subordinate vessels that he might be aboard.
	DaCapsule::GetRenderLightsRecursive(person, model, suns, lights);
}

bool DaBd::InChainOfCommand(const DaAtom* atom) const
{
	if(InChainOfCommand(atom->Id(), atom->EmpireId()))
		return true;
	return atom->HasAgentPower();	// Admins are in the chain-of-command of all ships.
}

bool DaBd::InChainOfCommand(const AuId& personId, quint32 personEmpire) const
{
	if(InDesignEnvironment())
		return true;
	// Buildings in the arena are in the chain of command of everyone on their team.
	quint32 bldEmpire = EmpireId();
	if(InArena())
		return bldEmpire == personEmpire;

	if(!bldEmpire)
	{
		// This building has no empire id.
		// Free avatars can only do anything with buildings that have no empire.
		const DaWorldLL* llworld = FindParentWorldInEnv();
		if(!llworld)
			return true;
		quint32 claimEmpire = llworld->ClaimedByEmpire();
		if(claimEmpire && claimEmpire != personEmpire)
			return false;				// World is claimed by a different empire.
		return true;	// World is not claimed and building has no empire.
	}
	else
	{
		// The building has an empire id. Person must be in the same empire to be in the chain-of-command, even if they are the
		// founder of the city.
		if(personEmpire != bldEmpire)
			return false;										// Wrong empire.
	}

	AuId cityId(CapitolId());
	const DgData& gd = g_Au.LockDataForRead();
	if(!cityId.IsNull() && gd.EmpireCityFounder(bldEmpire, cityId) == personId)
	{
		// Person is the founder/owner of my city and they are in my empire.
		g_Au.UnlockData();
		return true;
	}
	else if(gd.IsEmpireGovernor(personEmpire, personId))
	{
		// The person is a governing official of their empire.
		if(!cityId.IsNull())
		{
			// Get list of current places starting with my city up to the universe.
			AuIdList placeChain;
			placeChain.append(cityId);
			ChainOfPlaces(placeChain);
			if(gd.IsEmpirePlaceInDomain(personEmpire, placeChain, personId))
			{
				g_Au.UnlockData();
				return true;
			}
		}
		else
		{
			// I am not part of any city.
			const DaWorldLL* llworld = FindParentWorldInEnv();
			if(llworld)
			{
				// Test my world to see if the person is in its chain of command.
				g_Au.UnlockData();
				return llworld->InChainOfCommand(personId);
			}
		}
	}
	g_Au.UnlockData();

	// The person is not in the building's chain-of-command if we made it this far.
	return false;
}

bool DaBd::IsSmoldering() const
{
	// Ships in the design studio do not smolder.
	if(InDesignEnvironment())
		return false;

	unsigned int maxHits = DesignHitsStructural();
	unsigned int dmgHits = HitsDamageStructural();
	return dmgHits > maxHits/2;
}

