void DaBd::ManufactureFetch(quint16 panelIndex)
{
	if(IsUnderConstruction())
		return;
	DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return;

	bool didIt = false;
	DeManufacturingProcessArray& mpa = LockManufacturingProcessesForWrite();
	if(panelIndex < mpa.size())
	{
		DeManufacturingProcess& mp = mpa.FindProcess(panelIndex);
		didIt = ManufactureFetchMaterials(llworld, mp);
		if(didIt)
			m_tmMfgProcChange.Set();
	}
	UnlockManufacturingProcesses();
	if(didIt)
		SetModified();
}

void DaBd::ManufactureFetchMPID(quint16 mpid)
{
	if(IsUnderConstruction())
		return;
	DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return;

	bool didIt = false;
	DeManufacturingProcessArray& mpa = LockManufacturingProcessesForWrite();
	DeManufacturingProcessArray::iterator mpi = mpa.FindMPID(mpid);
	if(mpi != mpa.end())
	{
		didIt = ManufactureFetchMaterials(llworld, *mpi);
		if(didIt)
			m_tmMfgProcChange.Set();
	}
	UnlockManufacturingProcesses();
	if(didIt)
		SetModified();
}

bool DaBd::ManufactureFetchMaterials(DaWorldLL* llworld, DeManufacturingProcess& mp)
{
	//redundant if(IsUnderConstruction())
		//redundant return false;
	bool didIt = SelectProcess(mp);					// Spacecraft factory.
	// Fetch from natural environment and ringworld supplies power.
	AuPoint myloc(Location());
	quint8 elecSubQ, waterSubQ;
	bool isUndersea = SeaDepth() > FeetPerMeter();	// +/- 1 is the margin for sea surface construction, i.e. drilling rigs.
	bool inEnclosure = IsInsideEnclosure();			// The only enclosure that can contain a building is a biodome or platform.
	if(llworld->FetchManufacturingMaterials(mp, myloc, IsDark(), IndustryId(), isUndersea, inEnclosure, elecSubQ, waterSubQ))
		didIt = true;

	double totalMoney = AccountBalance();
	if(totalMoney > 0)
	{
		double moneyTaken = mp.SupplyMoney(totalMoney);
		if(moneyTaken)
		{
			if(mp.IsRnD())
			{
				DebitAccount(moneyTaken, AuBank::Civ_DebitRnD);
				CreditAccount(moneyTaken, AuBank::Civ_CreditSalary);
			}
			else
			{
				DebitAccount(moneyTaken, AuBank::Civ_DebitMfg);
			}
			didIt = true;
		}
	}

	// Update our tally of local vehicles periodically.
	TallyCommunityVehicles();

	// Fetch from my own supplies.
	quint32 power = CapacitorLevel();	// Fetch materials will reduce the amount of 'power' if it consumes any.
	if(power > 2)
		power -= 2;						// Don't take the last two unit of power.
	else
		power = 0;
	quint32 origPower = power;
	m_CargoLock.lockForWrite();
	if(mp.FetchVehicles(m_Vehicles))
		didIt = true;
	// Substitution of electricity for sunlight never consumes any of the power, because sunlight is not consumed by any process.
	if(mp.FetchMaterials(m_Cargo, m_Tools, m_Patents, elecSubQ, waterSubQ, power))
		didIt = true;
	m_CargoLock.unlock();
	if(power < origPower)
	{
		quint32 powerUsed = origPower - power;
		if(powerUsed)
			DischargeCapacitor(powerUsed);
	}

	// Import from connected buildings.
	quint32 labor;
	AuSpecies species;
	bool isSentient;
	if(mp.DNAIsOutput())
	{
		labor = ImportComponents(mp.IsRnD(), mp.Components(), mp.MinimumQSet(), waterSubQ, true, species, isSentient);
		if(!species.IsNull())
			mp.SetSpecies(species, isSentient);
	}
	else
		labor = ImportComponents(mp.IsRnD(), mp.Components(), mp.MinimumQSet(), waterSubQ, false, species, isSentient);
	if(labor)
	{
		mp.IncreaseLabor(labor);
		didIt = true;
	}
	return didIt;
}

void DaBd::ManufactureGo(quint16 panelIndex, DaPerson* byWho)
{
	if(IsUnderConstruction())
		return;
	DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return;
	bool didIt = false;
	DeManufacturingProcessArray& mpa = LockManufacturingProcessesForWrite();
	if(panelIndex < mpa.size())
	{
		DeManufacturingProcess& mp = mpa.FindProcess(panelIndex);
		if(!mp.IsRunning())
		{
			ManufactureFetchMaterials(llworld, mp);
			MakeOne(llworld, byWho, mp);
			m_tmMfgProcChange.Set();
			didIt = true;
		}
	}
	UnlockManufacturingProcesses();
	if(didIt)
	{
		SetModified();
		byWho->Stats().BuildingManufacture(IndustryId(), llworld);
		byWho->IncreaseSkill(AuSkill::Manufacture, 1);
	}
}

void DaBd::ManufactureGoMPID(quint16 mpid, DaPerson* byWho)
{
	if(IsUnderConstruction())
		return;
	DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return;
	quint16 curWorkers = Workers();
	bool didIt = false;
	DeManufacturingProcessArray& mpa = LockManufacturingProcessesForWrite();
	DeManufacturingProcessArray::iterator mpi = mpa.FindMPID(mpid);
	if(mpi != mpa.end())
	{
		if(!(*mpi).IsRunning())
		{
			quint32 shopWorkers = 1;	// The player. One person can run disabled production lines this way too.
			if((*mpi).ShopsEnabled() > 1)
			{
				// The production line requires more than one worker. The person counts as one worker.
				// Insure there are enough other workers present to run the process.
				for(DeManufacturingProcessArray::iterator pii = mpa.begin(); pii != mpa.end(); pii++)
				{
					quint32 shops = (*pii).ShopsEnabled();
					if((*pii).ManufacturingProcessId() == mpid)
					{
						shopWorkers += curWorkers;
						break;
					}
					if(curWorkers > shops)
						curWorkers -= shops;
					else
					{
						curWorkers = 0;
						break;
					}
				}
			}
			(*mpi).SetWorkersPresent(shopWorkers);
			ManufactureFetchMaterials(llworld, *mpi);
			MakeOne(llworld, byWho, *mpi);
			m_tmMfgProcChange.Set();
			didIt = true;
		}
	}
	UnlockManufacturingProcesses();
	if(didIt)
	{
		SetModified();
		byWho->Stats().BuildingManufacture(IndustryId(), llworld);
		byWho->IncreaseSkill(AuSkill::Manufacture, 1);
	}
}

void DaBd::ManufactureLowerMPID(quint16 mpid)
{
	DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return;
	bool didIt = false;
	DeManufacturingProcessArray& mpa = LockManufacturingProcessesForWrite();
	int pidx = mpa.MPIDIndex(mpid);
	if(pidx >= 0 && pidx < (int)mpa.size()-1)
	{
		mpa.MoveProcess(pidx, pidx+1);
		m_tmMfgProcChange.Set();
		didIt = true;
	}
	UnlockManufacturingProcesses();
	if(didIt)
		SetModified();
}

