void DaBd::TravellerMovedIn(const AuSpecies& species)
{
	m_BdLock.lockForWrite();
	if(!m_Residents)
	{
		if(m_ResidentSpecies != species)
		{
			// Make an event log entry for this.
			QString citizenName = species.NameOrDesc();
			QString msg = tr("Travelling %1 inhabited a vacant %2.").arg(citizenName).arg(Name());
			LogEvent(AuEventLogEntry::CitizenDNAChange, msg);

			// First citizen changes the species.
			m_ResidentSpecies = species;
		}
	}
	if(m_Residents < 0xffff)
	{
		m_Residents++;
		m_ReportPopTravellersArr++;
		m_tmCitizenChange.Set();
	}
	m_BdLock.unlock();
	SetModified();
}

void DaBd::TravellerMovedIn(const DaCreature* creature, const QString& sourceName)
{
	SpreadDisease(creature, sourceName);	// The arriving creature may have something to share.
	AuSpecies species = creature->Species();
	if(!species.IsNull())
		TravellerMovedIn(species);	// Add to the population of this building, possibly establish worker DNA.
}

void DaBd::IndigenousCitizenMovedIn(const AuSpecies& species)
{
	m_BdLock.lockForWrite();
	if(!m_Residents)
	{
		if(m_ResidentSpecies != species)
		{
			// Make an event log entry for this.
			QString citizenName = species.NameOrDesc();
			QString msg = tr("Indigenous %1 inhabited a vacant %2.").arg(citizenName).arg(Name());
			LogEvent(AuEventLogEntry::CitizenDNAChange, msg);

			// First citizen changes the species.
			m_ResidentSpecies = species;
		}
	}
	if(m_Residents < 0xffff)
	{
		m_Residents++;
		m_ReportPopIndigenousArr++;
		m_tmCitizenChange.Set();
	}
	m_BdLock.unlock();
	SetModified();
}

void DaBd::SeafarerMovedIn(const AuSpecies& species)
{
	m_BdLock.lockForWrite();
	if(!m_Residents)
	{
		if(m_ResidentSpecies != species)
		{
			// Make an event log entry for this.
			QString citizenName = species.NameOrDesc();
			QString msg = tr("Seafaring %1 inhabited a vacant %2.").arg(citizenName).arg(Name());
			LogEvent(AuEventLogEntry::CitizenDNAChange, msg);

			// First citizen changes the species.
			m_ResidentSpecies = species;
		}
	}
	if(m_Residents < 0xffff)
	{
		m_Residents++;
		m_ReportPopSeafarersArr++;
		m_tmCitizenChange.Set();
	}
	m_BdLock.unlock();
	SetModified();
}

void DaBd::WandererMovedIn(const AuSpecies& species)
{
	m_BdLock.lockForWrite();
	if(!m_Residents)
	{
		if(m_ResidentSpecies != species)
		{
			// Make an event log entry for this.
			QString citizenName = species.NameOrDesc();
			QString msg = tr("Wandering %1 inhabited a vacant %2.").arg(citizenName).arg(Name());
			LogEvent(AuEventLogEntry::CitizenDNAChange, msg);

			// First citizen changes the species.
			m_ResidentSpecies = species;
		}
	}
	if(m_Residents < 0xffff)
	{
		m_Residents++;
		m_ReportPopWanderersArr++;
		m_tmCitizenChange.Set();
	}
	m_BdLock.unlock();
	SetModified();
}

void DaBd::EmployConstructionWorker()
{
	quint16 curWorkers = Workers();
	if(IsConstructionWorkerEnabled())
	{
		// Construction worker is enabled.
		if(curWorkers)
			return;	// I already have a construction worker.
		// I need a construction worker.
		DaWorldLL* llworld = FindParentWorldInEnv();
		if(!llworld)
			return;	// wut?
		// Get a worker.
		AuIdList suppliers;
		llworld->CitizenSuppliers(EmpireId(), suppliers);
		for(AuIdList::const_iterator si = suppliers.cbegin(); si != suppliers.cend(); si++)
		{
			if(!HasTradeConnection(*si))
				continue;
			DaBd* bdSup = dynamic_cast<DaBd*>(llworld->FindSubatomId(*si));
			if(bdSup && bdSup->EmployResident(Id()))
			{
				// I got a worker from the supplier. It now knows it is employed at this bd.
				m_BdLock.lockForWrite();
				m_Workers++;
				m_tmCitizenChange.Set();
				m_BdLock.unlock();
				SetModified(NOTIFY_Scene);
				return;	// Only get one per employment round.
			}
			else
				llworld->CitizenNotAvailable(*si);
		}

		// Ask the world to take a citizen from a non essential job.
		m_TradeConnectionsLock.lockForRead();
		bool tookCitizen = llworld->CitizenTakeNonessential(Id(), m_TradeConnections);
		m_TradeConnectionsLock.unlock();
		if(tookCitizen)
		{
			// I got a worker from some other building. It now knows it is employed at this bd.
			m_BdLock.lockForWrite();
			m_Workers++;
			m_tmCitizenChange.Set();
			m_BdLock.unlock();
			SetModified(NOTIFY_Scene);
			return;	// Only get one per employment round.
		}

		// If I get here I did not find a civilian construction worker. Military buildings can use troops.
		if(!IsMilitary())
			return;

		// I can build using a troop. Get one.
		suppliers.clear();
		llworld->TroopSuppliers(EmpireId(), suppliers);
		for(AuIdList::const_iterator si = suppliers.cbegin(); si != suppliers.cend(); si++)
		{
			if(!HasTradeConnection(*si))
				continue;
			DaBd* bdSup = dynamic_cast<DaBd*>(llworld->FindIdRecursive(*si));
			if(bdSup && bdSup->EmployResident(Id()))
			{
				// I got a troop from the supplier. It now knows it is employed at this bd.
				m_BdLock.lockForWrite();
				m_Workers++;
				m_tmCitizenChange.Set();
				m_BdLock.unlock();
				SetModified(NOTIFY_Scene);
				return;	// Only get one per employment round.
			}
			else
				llworld->TroopNotAvailable(*si);
		}

		// Ask the world to take a troop from a non essential job.
		m_TradeConnectionsLock.lockForRead();
		bool tookTroop = llworld->TroopTakeNonessential(Id(), m_TradeConnections);
		m_TradeConnectionsLock.unlock();
		if(tookTroop)
		{
			// I got a troop from some other building. It now knows it is employed at this bd.
			m_BdLock.lockForWrite();
			m_Workers++;
			m_tmCitizenChange.Set();
			m_BdLock.unlock();
			SetModified(NOTIFY_Scene);
			return;	// Only get one per employment round.
		}
	}
	else
	{
		// Construction worker is disabled.
		if(!curWorkers)
			return;	// I have no construction worker.
		// I do not need any workers.
		DaWorldLL* llworld = FindParentWorldInEnv();
		if(!llworld)
			return;	// wut?
		// Release my unneeded construction workers.
		m_BdLock.lockForWrite();
		m_Workers = 0;
		m_tmCitizenChange.Set();
		m_BdLock.unlock();
		SetModified(NOTIFY_Scene);
		llworld->WorkersReleased(Id(), curWorkers);
	}
}

// Employs residents of other buildings to work jobs available in this building.
void DaBd::EmployWorkers()
{
	quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, manufacturingJobsEnabled, serviceJobs, stores, lounges, proJobs;
	IndustryInfoJobs(homesLarge, homesMedium, homesSmall, manufacturingJobs, manufacturingJobsEnabled, serviceJobs, stores, lounges,
			proJobs);
	if(manufacturingJobsEnabled == 0 && proJobs == 0 && serviceJobs == 0)
		return;	// This building does not create any jobs.

	int jobs = serviceJobs;
	if(DbIndustry::DoesManufacture(IndustryId()))
		jobs += manufacturingJobsEnabled;	// Count only manufacturing jobs that are enabled.
	else
		jobs += proJobs;			// Professional workers cannot be disabled.

	quint16 curWorkers = Workers();
	if(curWorkers == jobs)
		return;	// All jobs are filled.

	// I need workers or I have too many.
	DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return;	// wut?
	if(IsMilitary())
	{
		if(curWorkers < jobs)
		{
			// I need more troops. Get one.
			AuIdList suppliers;
			llworld->TroopSuppliers(EmpireId(), suppliers);
			for(AuIdList::const_iterator si = suppliers.cbegin(); si != suppliers.cend(); si++)
			{
				if(!HasTradeConnection(*si))
					continue;
				DaBd* bdSup = dynamic_cast<DaBd*>(llworld->FindIdRecursive(*si));
				if(bdSup && bdSup->EmployResident(Id()))
				{
					// I got a troop from the supplier. It now knows it is employed at this bd.
					m_BdLock.lockForWrite();
					m_Workers++;
					m_tmCitizenChange.Set();
					m_BdLock.unlock();
					SetModified(NOTIFY_Scene);
					return;	// Only get one per employment round.
				}
				else
					llworld->TroopNotAvailable(*si);
			}

			if(IsEssential(llworld->HasBreathableAtmosphere()))
			{
				// Ask the world to take a troop from a non essential job.
				m_TradeConnectionsLock.lockForRead();
				bool tookTroop = llworld->TroopTakeNonessential(Id(), m_TradeConnections);
				m_TradeConnectionsLock.unlock();
				if(tookTroop)
				{
					// I got a troop from some other building. It now knows it is employed at this bd.
					m_BdLock.lockForWrite();
					m_Workers++;
					m_tmCitizenChange.Set();
					m_BdLock.unlock();
					SetModified(NOTIFY_Scene);
					return;	// Only get one per employment round.
				}
			}
		}
		else if(curWorkers > jobs)
		{
			// I have too many troops. Let the extras go.
			quint16 release = curWorkers - jobs;
			m_BdLock.lockForWrite();
			m_Workers -= release;
			m_tmCitizenChange.Set();
			m_BdLock.unlock();
			SetModified(NOTIFY_Scene);
			llworld->WorkersReleased(Id(), release);
		}
	}
	else
	{
		if(curWorkers < jobs)
		{
			// I need more workers. Get one.
			AuIdList suppliers;
			llworld->CitizenSuppliers(EmpireId(), suppliers);
			for(AuIdList::const_iterator si = suppliers.cbegin(); si != suppliers.cend(); si++)
			{
				if(!HasTradeConnection(*si))
					continue;
				DaBd* bdSup = dynamic_cast<DaBd*>(llworld->FindIdRecursive(*si));
				if(bdSup && bdSup->EmployResident(Id()))
				{
					// I got a worker from the supplier. It now knows it is employed at this bd.
					m_BdLock.lockForWrite();
					m_Workers++;
					m_tmCitizenChange.Set();
					m_BdLock.unlock();
					SetModified(NOTIFY_Scene);
					return;	// Only get one per employment round.
				}
				else
					llworld->CitizenNotAvailable(*si);
			}

			if(IsEssential(llworld->HasBreathableAtmosphere()))
			{
				// Ask the world to take a citizen from a non essential job.
				m_TradeConnectionsLock.lockForRead();
				bool tookCitizen = llworld->CitizenTakeNonessential(Id(), m_TradeConnections);
				m_TradeConnectionsLock.unlock();
				if(tookCitizen)
				{
					// I got a worker from some other building. It now knows it is employed at this bd.
					m_BdLock.lockForWrite();
					m_Workers++;
					m_tmCitizenChange.Set();
					m_BdLock.unlock();
					SetModified(NOTIFY_Scene);
					return;	// Only get one per employment round.
				}
			}
		}
		else if(curWorkers > jobs)
		{
			// I have too many workers. Let the extras go.
			quint16 release = curWorkers - jobs;
			m_BdLock.lockForWrite();
			m_Workers -= release;
			m_tmCitizenChange.Set();
			m_BdLock.unlock();
			SetModified(NOTIFY_Scene);
			llworld->WorkersReleased(Id(), release);
		}
	}
}

void DaBd::UnemployWorkers()
{
	// This function helps to eliminate a snafu when manufacturing and all workers get assigned to the same building. That is not
	// a factor for military buildings because they do not manufacture anything.
	if(IsMilitary())
		return;
	quint16 curWorkers = Workers();
	if(!curWorkers)
		return;

	// It is possible one of my workers will decide to quit.
	int quitPercent = Morale() < 0 ? 20 : 10;		// People quit or get fired more often when morale is low.
	int roll = g_Au.Dice().Roll(1,100);
	if(roll > quitPercent)
		return;

	// Someone decided to quit.
	int unemployed = 0;
	m_BdLock.lockForWrite();
	if(m_Workers)
	{
		unemployed = (int)m_Workers * roll / 100;	// Take roll% of the workers. It can be higher when morale is low. Max 10%.
		if(!unemployed)
			unemployed = 1;							// Let at least one employee go.
		m_Workers -= unemployed;
		curWorkers = m_Workers;
	}
	m_tmCitizenChange.Set();
	m_BdLock.unlock();
	SetModified(NOTIFY_Scene);

	DaWorldLL* llworld = FindParentWorldInEnv();
	if(llworld)
		llworld->WorkersReleased(Id(), 1);
	//qDebug() << "DaBd::UnemployWorkers" << *this << "on" << *llworld << "morale" << Morale() << unemployed << "workers quit"
		//<< curWorkers << "remain";
}

bool DaBd::EmployResident(const AuId& atBdId)
{
	if(!ResidentsUnemployed())
		return false;	// No unemployed residents.
	m_BdLock.lockForWrite();
	QHash<AuId, quint16>::iterator ei = m_ResidentsEmployed.find(atBdId);
	if(ei != m_ResidentsEmployed.end())
		(*ei)++;
	else
		m_ResidentsEmployed.insert(atBdId, 1);
	m_tmCitizenChange.Set();
	m_BdLock.unlock();
	SetModified(NOTIFY_Scene);
	//qDebug() << "DaBd::EmployResident" << Id() << Name() << "a resident was employed at" << atBdId;
	return true;
}

bool DaBd::UnemployResidents(const AuId& atBdId, quint16& numToRelease)
{
	bool anyUnemployed = false;
	m_BdLock.lockForWrite();
	QHash<AuId, quint16>::iterator ei = m_ResidentsEmployed.find(atBdId);
	if(ei != m_ResidentsEmployed.end())
	{
		// Some of my residents work at the building.
		if(numToRelease == 0xffff)
		{
			// Erase all because the building went away.
			ei = m_ResidentsEmployed.erase(ei);
			anyUnemployed = true;
		}
		else if(numToRelease < *ei)
		{
			*ei -= numToRelease;
			numToRelease = 0;
			anyUnemployed = true;
		}
		else if(numToRelease == *ei)
		{
			ei = m_ResidentsEmployed.erase(ei);
			numToRelease = 0;
			anyUnemployed = true;
		}
		else
		{
			// Number to release is more than I have. They must have employees at another building too.
			numToRelease -= *ei;
			ei = m_ResidentsEmployed.erase(ei);
			anyUnemployed = true;
		}
	}
	if(anyUnemployed)
		m_tmCitizenChange.Set();
	m_BdLock.unlock();
	if(anyUnemployed)
	{
		SetModified(NOTIFY_Scene);
		/*
		if(numToRelease == 0xffff)
			qDebug() << "DaBd::UnemployResident" << Id() << Name() << "all residents of" << atBdId
				<< "were unemployed" << CityName();
		else if(numToRelease == 0)
			qDebug() << "DaBd::UnemployResident" << Id() << Name() << "a resident was unemployed by" << atBdId
				<< "no more are scheduled for termination" << CityName();
		else
			qDebug() << "DaBd::UnemployResident" << Id() << Name() << "a resident was unemployed by" << atBdId
				<< "it still has" << numToRelease << "left to pink slip" << CityName();
				*/
	}
	return anyUnemployed;
}

bool DaBd::HasTradeConnection(const AuId& toBdId) const
{
	m_TradeConnectionsLock.lockForRead();
	bool hasConnection = m_TradeConnections.contains(toBdId);
	m_TradeConnectionsLock.unlock();
	return hasConnection;
}

bool DaBd::HasTradeConnectionByGround(const AuId& toBdId) const
{
	if(Is(toBdId))
		return true;	// I am connected by ground to myself.
	m_TradeConnectionsLock.lockForRead();
	QHash<AuId, int>::const_iterator ci = m_TradeConnections.find(toBdId);
	bool hasConnection = ci != m_TradeConnections.cend() && (*ci & CON_Road);
	m_TradeConnectionsLock.unlock();
	return hasConnection;
}

bool DaBd::HasAnyTradeConnection() const
{
	m_TradeConnectionsLock.lockForRead();
	bool hasConnection = !m_TradeConnections.empty();
	m_TradeConnectionsLock.unlock();
	return hasConnection;
}

bool DaBd::IsEssential(bool hasBreathableAtmo) const
{
	// Construction jobs are essential so they get done promptly for the player.
	if(IsUnderConstruction())
		return true;

	INDUSTRYID iid = IndustryId();
	if(!hasBreathableAtmo)
	{
		// Unhospitable world.
		if(DbIndustry::IsPowerPlant(iid))
			return true;				// Power production is essential in harsh environments.
	}

	if(iid == IID_Farm || iid == IID_Orchard)
	{
		// Farms and orchards make food.
		quint32 ccap = CargoCapacityVolume();
		if(ccap)
		{
			quint32 cvol = CargoTotalVolume();
			if(cvol <= ccap/10)
				return true;			// Less than 10% of my storage is filled. Let's call that essential.
		}
	}
	else if(iid == IID_Refinery)
	{
		// Refineries can make air. It is often essential to someone, possibly off world.
		quint32 ccap = CargoCapacityVolume();
		if(ccap)
		{
			// I can store more than ten units of air.
			quint32 cvol = CargoRawCount(CID_Air, 0);
			if(cvol <= ccap/10)
			{
				// Less than 10% of my storage is filled with air.
				bool makingAir = false;
				m_MfgProcLock.lockForRead();
				for(DeManufacturingProcessArray::const_iterator mpi = m_MfgProc.cbegin(); mpi != m_MfgProc.cend(); mpi++)
					if((*mpi).ShopsEnabled() && (*mpi).CommodityId() == CID_Air)
					{
						makingAir = true;	// I am making air.
						break;
					}
				m_MfgProcLock.unlock();
				if(makingAir)
					return true;	// I need to be making air.
			}
		}
	}
	return false;
}

quint32 DaBd::Population() const
{
	return Residents() + TransientPopulation();
}

void DaBd::ImportMinutePower(DaSolarSystem* system)
{
	// Import power to fill capacitor, if any.
	quint32 ccap = CapacitorMax();
	if(!ccap)
		return;
	quint32 cap = (quint32)ceilf(CapacitorLevel());
	if(cap >= ccap)
		return;
	quint32 need = ccap - cap;
	if(need > 60)
		need = 60;						// Import max per minute.
	COMMODITYID importCID = CID_Electricity;
	AuIdList suppliers;
	system->CommoditySuppliers(importCID, EmpireId(), suppliers);
	if(suppliers.empty())
		return;

	// Found one or more suppliers that can export electricity to me.
	for(AuIdList::const_iterator si = suppliers.cbegin(); si != suppliers.cend(); si++)
	{
		if(Is(*si))
			continue;	// Do not import stored stuff from myself.
		// Electricity can only be imported via ground.
		if(!HasTradeConnectionByGround(*si))
			continue;
		DaAtom* bdSup = system->FindIdRecursive(*si);
		if(!bdSup)
			continue;
		quint32 power = bdSup->StoredPowerLevel();
		if(power > need + 2)
		{
			// Take units of power to fill my own capacitor. I need power to run lights.
			// Shield generator fills capacitor to augment shield power.
			// If I am a power plant, this bit of imported power may be enough to get my lights on so workers will get to work.
			bdSup->DischargeStoredPower(need);
			bdSup->SetModified();

			// Add one unit of power to my capacitor storage.
			m_VesselLock.lockForWrite();
			m_CapacitorLevel += need;
			if(m_CapacitorLevel > ccap)
				m_CapacitorLevel = ccap;
			m_VesselLock.unlock();
			SetModified();
			break;						// That is enough power to import for one round.
		}
		else if(!power)
			system->CommodityNotAvailable(importCID, *si);	// So people stop checking them.
	}
}

void DaBd::ImportShieldPower()
{
	if(IndustryId() != IID_BaseShield)
		return;
	// Import power to fill shield capacitor, if any.
	quint32 ccap = ShieldUnitsWorking();
	if(!ccap)
		return;
	quint32 cap = (quint32)ceilf(ShieldCapacitor());
	if(cap >= ccap)
		return;
	DaSolarSystem* system = dynamic_cast<DaSolarSystem*>(FindEnvironmentAtom());
	if(!system)
		return;
	COMMODITYID importCID = CID_Electricity;
	AuIdList suppliers;
	system->CommoditySuppliers(importCID, EmpireId(), suppliers);
	if(suppliers.empty())
		return;

	// It takes 10 min to charge my shield capacitor, at most. This function gets called once every 10 seconds.
	quint32 need = ccap - cap;
	quint32 chargeAmount = ccap / 60;	// Capacitor units per 10 second interval.
	if(chargeAmount < 10)
		chargeAmount = 10;				// Minimum one unit per second.
	if(need > chargeAmount)
		need = chargeAmount;			// Limit charge amount so it takes 10 min to charge, at most.

	// Found one or more suppliers that can export electricity to me.
	for(AuIdList::const_iterator si = suppliers.cbegin(); si != suppliers.cend(); si++)
	{
		if(Is(*si))
			continue;	// Do not import stored stuff from myself.
		// Electricity can only be imported via ground.
		if(!HasTradeConnectionByGround(*si))
			continue;
		DaAtom* bdSup = system->FindIdRecursive(*si);
		if(!bdSup)
			continue;
		quint32 power = bdSup->StoredPowerLevel();
		if(power > 2)
		{
			// Take units of power to charge my shield capacitor, leaving at least 2 units in their capacitor.
			quint32 take = power - 2;
			if(take > need)
			{
				take = need;
				need = 0;
			}
			else
				need -= take;
			bdSup->DischargeStoredPower(take);
			bdSup->SetModified();

			// Add power to my shield capacitor.
			ShieldCharge(take);
			SetModified();
			if(!need)
				break;			// Shield capacitor is full.
		}
		else if(!power)
			system->CommodityNotAvailable(importCID, *si);	// So people stop checking them.
	}
}

void DaBd::ImportStorage()
{
	const DaWorldLL* planet = FindParentWorldInEnv();
	if(!planet)
		return;	// wut?
	DaSolarSystem* system = dynamic_cast<DaSolarSystem*>(planet->FindEnvironmentAtom());
	if(!system)
		return;
	COMMODITYID importCID;
	quint32 need = 0;	// Amount of importCID to import this cycle.
	quint32 stock = 0;	// Non-zero number says total amount of importCID that is desired to be in stock.
	bool advertise = false;	// True to advertise my cargo to the solar system as a supplier.
	switch(IndustryId())
	{
	case IID_Capitol:
		// Capitol stockpiles supplies in harsh environments.
		if(planet->HasBreathableAtmosphere())
			return;
		{
			quint32 ccap = CargoCapacityVolume();
			if(!ccap)
				return;
			// Maintain a stock of one day's supply of air for the entire colony.
			quint32 population = LastReportedPopulation();
			quint32 airwanted = population * 4 + 10;
			if(airwanted > ccap)
				airwanted = ccap;
			quint32 air = CargoRawCount(CID_Air, 0);
			if(air < airwanted)
			{
				need = airwanted - air;
				importCID = CID_Air;
				advertise = true;
			}
			else
			{
				// Import a stock of food and medical supplies for the entire colony in harsh environment.
				QList<COMMODITYID> cidsAvailable;
				m_TradeConnectionsLock.lockForRead();
				system->CommodityGrocerySupplies(cidsAvailable, m_TradeConnections);
				m_TradeConnectionsLock.unlock();
				if(cidsAvailable.empty())
					return;
				int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
				importCID = cidsAvailable[index];
				stock = population * 2 + 10;
				advertise = true;
			}
		}
		break;
	case IID_BaseHeadquarters:
	case IID_BaseBarracks:
		{
			quint32 ccap = CargoCapacityVolume();
			if(!ccap)
				return;
			quint32 population = LastReportedPopulation();
			if(!planet->HasBreathableAtmosphere())
			{
				// Maintain a stock of one day's supply of air for the entire base in harsh environment.
				quint32 airwanted = population * 4 + 10;
				if(airwanted > ccap)
					airwanted = ccap;
				quint32 air = CargoRawCount(CID_Air, 0);
				if(air < airwanted)
				{
					need = airwanted - air;
					importCID = CID_Air;
					advertise = true;
					break;
				}
			}

			// Import a stock of food and medical supplies for the entire base.
			// Also imports basic construction materials for building repairs.
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityHQSupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			if(DbCommodity::IsFood(importCID))
				stock = population * 3 + 10;
			else if(DbCommodity::IsConstructionMaterial(importCID))
				need = 50;
			else
				stock = population * 2 + 10;
			advertise = true;
		}
		break;
	case IID_AirportTerminal:
		{
			// Import air in harsh environments.
			if(!planet->HasBreathableAtmosphere())
			{
				quint32 ccap = CargoCapacityVolume();
				if(!ccap)
					return;
				// Maintain a stock of two day's supply of air for the entire colony in harsh environment.
				quint32 population = LastReportedPopulation();
				quint32 airwanted = population * 8 + 100;
				if(airwanted > ccap)
					airwanted = ccap;
				quint32 air = CargoRawCount(CID_Air, 0);
				if(air < airwanted)
				{
					need = airwanted - air;
					importCID = CID_Air;
					advertise = true;
					break;
				}
			}

			// Import fuel.
			QList<COMMODITYID> cidsWanted;
			cidsWanted.append(CID_Hydrogen);
			cidsWanted.append(CID_Gasoline);
			cidsWanted.append(CID_VacSuit);
			cidsWanted.append(CID_VacSuitHelmet);
			int index = g_Au.Dice().Roll(1,cidsWanted.size(),-1);
			importCID = cidsWanted[index];
			if(DbCommodity::IsEnvironmentSuit(importCID) ||
					DbCommodity::IsEnvironmentHelmet(importCID))
			{
				quint32 population = LastReportedPopulation();
				stock = population + 10;
			}
			else if(importCID == CID_Hydrogen)
				need = 1000;
			else
				need = 50;
			advertise = true;
		}
		break;
	case IID_BaseAirTerminal:
		{
			// Import air in harsh environments.
			if(!planet->HasBreathableAtmosphere())
			{
				quint32 ccap = CargoCapacityVolume();
				if(!ccap)
					return;
				// Maintain a stock of two day's supply of air for the entire colony in harsh environment.
				quint32 population = LastReportedPopulation();
				quint32 airwanted = population * 8 + 100;
				if(airwanted > ccap)
					airwanted = ccap;
				quint32 air = CargoRawCount(CID_Air, 0);
				if(air < airwanted)
				{
					need = airwanted - air;
					importCID = CID_Air;
					advertise = true;
					break;
				}
			}

			// Import fuel and ammo for space vehicles.
			// Also imports basic construction materials for building repairs.
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityAirBaseSupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			if(DbCommodity::IsEnvironmentSuit(importCID) ||
					DbCommodity::IsEnvironmentHelmet(importCID))
			{
				quint32 population = LastReportedPopulation();
				stock = population * 2 + 10;
			}
			else if(importCID == CID_Hydrogen)
				need = 1000;
			else
				need = 50;
			advertise = true;
		}
		break;
	case IID_BaseDock:
		{
			// Import fuel and ammo for water vehicles.
			// Also imports basic construction materials for building repairs.
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityDockSupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			need = 50;
			advertise = true;
		}
		break;
	case IID_BaseMotorPool:
		{
			// Import fuel and ammo for ground vehicles.
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityMotorPoolSupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			need = 50;
			advertise = true;
		}
		break;
	case IID_BaseWeapon:
		{
			// Import ammo for my gun(s).
			quint32 cannons = 0;
			quint32 launchers = 0;
			quint32 projectors = 0;
			m_DesignLock.lockForRead();
			for(AuScReportSysVolHash::const_iterator bi = m_Design.WeaponBays().cbegin(); bi != m_Design.WeaponBays().cend(); bi++)
			{
				COMMODITYID bayCID = SystemModule(SYS_Weapon, bi.key());
				switch(bayCID)
				{
				default:
					continue;
				case CID_BallisticWeaponBayModule:
					cannons += AuBdDesign::BayWeaponCannons((*bi).VolumeCuFt());
					break;
				case CID_EnergyWeaponBayModule:
					// Import lenses only if this weapon bay needs them.
					{
						const AuItem* ammoInBay = LockBayWeaponAmmunition(bi.key());
						quint32 lensCount = ammoInBay ? ammoInBay->Count() : 0;
						UnlockBayWeaponAmmunition();
						quint32 bayProj = AuBdDesign::BayWeaponProjectors((*bi).VolumeCuFt());	// Each projector needs a lens.
						if(lensCount < bayProj)
							projectors += bayProj;	// Our stack of lenses is not big enough for the weapon, import a stack.
					}
					break;
				case CID_WeaponLauncherBayModule:
					launchers += AuBdDesign::BayWeaponLaunchers((*bi).VolumeCuFt());
					break;
				}
			}
			m_DesignLock.unlock();

			// Make a list of every possible ammo I can shoot.
			QList<COMMODITYID> ammoCIDs;
			if(cannons)
			{
				ammoCIDs.append(CID_HeavyArmsAmmoPiRa);
				ammoCIDs.append(CID_HeavyArmsAmmoPiAc);
				ammoCIDs.append(CID_HeavyArmsAmmoPiBl);
				ammoCIDs.append(CID_HeavyArmsAmmoPi);
			}
			if(launchers)
			{
				ammoCIDs.append(CID_LargeRocketBuDi);
				ammoCIDs.append(CID_LargeRocketBlBu);
				ammoCIDs.append(CID_LargeMissileSlPo);
				ammoCIDs.append(CID_LargeMissileBlBu);
				ammoCIDs.append(CID_LargeRocketBl);
				ammoCIDs.append(CID_LargeMissileBl);
			}
			if(projectors)
			{
				ammoCIDs.append(CID_CompressorBeam);
				ammoCIDs.append(CID_DisintegratorRay);
				ammoCIDs.append(CID_ProtonBeam);
				ammoCIDs.append(CID_StasisBeam);
				ammoCIDs.append(CID_DisruptorBeam);
				ammoCIDs.append(CID_ErgRay);
				ammoCIDs.append(CID_HeatRay);
				ammoCIDs.append(CID_FreezeRay);
				ammoCIDs.append(CID_NeutronBeam);
				ammoCIDs.append(CID_ElectronBeam);
			}

			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityFindSupplies(cidsAvailable, ammoCIDs, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			if(DbCommodity::IsFiredFromHeavyWeapon(importCID))
				stock = cannons * 12 * 2;	// Bay fires every 5 sec. Get enough to fire for a full minute, until we get more ammo.
			else if(DbCommodity::IsEnergyWeapon(importCID))
				stock = projectors;
			else// if(DbCommodity::IsMissile(importCID) || DbCommodity::IsRocket(importCID))
				stock = launchers * 12 * 2;	// Bay fires every 5 sec. Get enough to fire for a full minute, until we get more ammo.
			advertise = false;	// Don't let others take my ammo.
		}
		break;
	case IID_BaseGuardTower:
		{
			// Import ammo for my gun(s).
			quint32 cannons = 0;
			quint32 launchers = 0;
			quint32 projectors = 0;
			m_DesignLock.lockForRead();
			for(AuScReportTurretHash::const_iterator si = m_Design.Turrets().cbegin(); si != m_Design.Turrets().cend(); si++)
			{
				COMMODITYID turretCID = SystemModule(SYS_Turret, si.key());
				switch(turretCID)
				{
				default:
					continue;
				case CID_BallisticWeaponTurretModule:
					cannons += 1;//AuBdDesign::TurretWeaponCannons((*si).VolumeCuFt());
					break;
				case CID_EnergyWeaponTurretModule:
					// Import a lens only if this turret needs one.
					if(!TurretRoundsCount(si.key()))
					{
						// Try loading the turret from our stores. If it fails, we need to import a lens.
						if(!ReloadTurret(si.key()))
							projectors += 1;//AuBdDesign::TurretWeaponProjectors((*si).VolumeCuFt());
					}
					break;
				case CID_WeaponLauncherTurretModule:
					launchers += 1;//AuBdDesign::TurretWeaponLaunchers((*si).VolumeCuFt());
					break;
				}
			}
			m_DesignLock.unlock();

			// Make a list of every possible ammo I can shoot.
			QList<COMMODITYID> ammoCIDs;
			if(cannons)
			{
				ammoCIDs.append(CID_HeavyArmsAmmoPiRa);
				ammoCIDs.append(CID_HeavyArmsAmmoPiAc);
				ammoCIDs.append(CID_HeavyArmsAmmoPiBl);
				ammoCIDs.append(CID_HeavyArmsAmmoPi);
			}
			if(launchers)
			{
				ammoCIDs.append(CID_SmallMissileBl);
				ammoCIDs.append(CID_SmallMissileBlBu);
				ammoCIDs.append(CID_SmallMissileCrFr);
				ammoCIDs.append(CID_SmallRocketBl);
				ammoCIDs.append(CID_SmallRocketBlBu);
				ammoCIDs.append(CID_SmallRocketSlPi);
			}
			if(projectors)
			{
				ammoCIDs.append(CID_CompressorBeam);
				ammoCIDs.append(CID_DisintegratorRay);
				ammoCIDs.append(CID_ProtonBeam);
				ammoCIDs.append(CID_StasisBeam);
				ammoCIDs.append(CID_DisruptorBeam);
				ammoCIDs.append(CID_ErgRay);
				ammoCIDs.append(CID_HeatRay);
				ammoCIDs.append(CID_FreezeRay);
				ammoCIDs.append(CID_NeutronBeam);
				ammoCIDs.append(CID_ElectronBeam);
			}

			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityFindSupplies(cidsAvailable, ammoCIDs, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			if(DbCommodity::IsFiredFromHeavyWeapon(importCID))
				stock = cannons * 20;	// Turret fires every 3 sec. Get enough to fire for a full minute, until we get more ammo.
			else if(DbCommodity::IsEnergyWeapon(importCID))
				stock = projectors;
			else// if(DbCommodity::IsMissile(importCID) || DbCommodity::IsRocket(importCID))
				stock = launchers * 20;	// Turret fires every 3 sec. Get enough to fire for a full minute, until we get more ammo.
			advertise = false;	// Don't let others take my ammo.
		}
		break;
	case IID_Warehouse:
		// Warehouse requires an office so lets make sure it has a worker.
		if(!Workers())
			return;
		importCID = StoreCommodity();
		need = 1000;
		advertise = true;
		break;
	case IID_StorageTank:
		// Storage tank does not require an office so we cannot require a worker.
		importCID = StoreCommodity();
		need = 1000;
		advertise = true;
		break;
	case IID_Shed:
		// Shed does not require an office so we cannot require a worker.
		{
			// Things that might be found in a shed.
			COMMODITYID shedCIDs[] =
			{
				// Tools
				CID_Clamp,
				CID_FittingWrench,
				CID_GlueGun,
				CID_Hammer,
				CID_Knife,
				CID_MagmiumKnife,
				CID_Microscope,
				CID_NanopathCalibrator,
				CID_OScope,
				CID_Pliers,
				CID_ScrewDriver,
				CID_SewingNeedle,
				CID_Shovel,
				CID_SolderIron,
				CID_Tongs,
				CID_TorqueWrench,
				CID_VulciumKnife,
				CID_Wrench,
				// Spare Parts
				CID_Air,
				CID_AntifluxParticles,
				CID_Computer,
				CID_CryoHeatSink,
				CID_ElectronicPart,
				CID_Gigacell,
				CID_GravCoupling,
				CID_HeavyWeapon,
				CID_IoTube,
				CID_LargeRocketMotor,
				CID_Lumenite,
				CID_Magmium,
				CID_MagmiumHeatSink,
				CID_MechanicalPart,
				CID_Metal,
				CID_Myrasplicer,
				CID_Plastic,
				CID_TesloidDissipator,
				CID_Textiles,
				CID_Vulcium,
				CID_VulciumHeatSink,
				// Construction Materials
				CID_Adamantine,
				CID_Computer,
				CID_CrudeOil,
				CID_ElectronicPart,
				CID_Flag,
				CID_GravCoupling,
				CID_Lumber,
				CID_Magmium,
				CID_MechanicalPart,
				CID_Metal,
				CID_Plastic,
				CID_Stone,
				CID_Textiles,
				CID_Vulcium,
				CID_Wood,
				// Flower pots
				CID_FlowerPotLarge,
				CID_FlowerPotSmall,
				// Fuel
				CID_Gasoline,
				CID_NaturalGas,
				// Lamps
				CID_Candle,
				CID_Torch,
				CID_Lantern,
				// Picture Frames
				CID_PictureFrame120x68,
				CID_PictureFrame22x28,
				CID_PictureFrame60x34,
			};
			int shedCIDCount = sizeof(shedCIDs)/sizeof(COMMODITYID);
			int index = g_Au.Dice().Roll(1,shedCIDCount,-1);
			importCID = shedCIDs[index];
			need = 1;	// This insures a diverse selection of things.
		}
		break;
	case IID_RetailStore:
		// Store requires a worker to import except in harsh environment.
		if(!Workers() && planet->HasBreathableAtmosphere())
			return;
		{
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityRetailSupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			stock = 10 * Stores();
			advertise = true;
		}
		break;
	case IID_Cantina:
		// Store requires a worker to import except in harsh environment.
		if(!Workers() && planet->HasBreathableAtmosphere())
			return;
		{
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityCantinaSupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			stock = 5 * Lounges();	// This insures a diverse selection of things.
			advertise = true;
		}
		break;
	case IID_Grocery:
		// Store requires a worker to import except in harsh environment.
		if(!Workers() && planet->HasBreathableAtmosphere())
			return;
		{
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityGrocerySupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			stock = 10 * Stores();	// This insures a diverse selection of things.
			advertise = true;
		}
		break;
	case IID_CoalPowerPlant:
	case IID_GasolinePowerPlant:
	case IID_HydrogenPowerPlant:
	case IID_NaturalGasPowerPlant:
	case IID_NuclearPowerPlant:
		// Most power plants store fuel on site.
		// Import requires a worker except in harsh environment.
		if(!Workers() && planet->HasBreathableAtmosphere())
			return;
		importCID = Fuel();
		need = 100 * Generators();
		break;
	case IID_Hospital:
		// Hospital requires a worker to import except in harsh environment.
		if(!Workers() && planet->HasBreathableAtmosphere())
			return;
		{
			QList<COMMODITYID> cidsAvailable;
			m_TradeConnectionsLock.lockForRead();
			system->CommodityHospitalSupplies(cidsAvailable, m_TradeConnections);
			m_TradeConnectionsLock.unlock();
			if(cidsAvailable.empty())
				return;
			int index = g_Au.Dice().Roll(1,cidsAvailable.size(),-1);
			importCID = cidsAvailable[index];
			need = 1;	// Import very slowly.
		}
		break;
	default:
		return;
	}
	if((!need && !stock) || importCID == CID_Invalid)
		return;

	if(stock)
	{
		quint32 amt = CargoRawCount(importCID, 0);
		if(amt >= stock)
			return;			// Already have enough in stock.
		need = stock - amt;	// Calculate the amount needed to reach the stock level.
	}

	AuIdList suppliers;
	system->CommoditySuppliers(importCID, EmpireId(), suppliers);
	if(suppliers.empty())
		return;

	// Found one or more suppliers that can export the commodity to me.
	bool gotSome = false;
	for(AuIdList::const_iterator si = suppliers.cbegin(); si != suppliers.cend(); si++)
	{
		// Commodities can be imported via ground, sea, air and space.
		if(Is(*si))
			continue;	// Do not import stored stuff from myself.
		if(!HasTradeConnection(*si))
			continue;
		DaAtom* bdSup = system->FindIdRecursive(*si);
		if(!bdSup)
			continue;
		const AuItemHash* supply = bdSup->LockCommoditiesForRead();
		AuItemHash::const_iterator bi = supply->FindBest(importCID);
		if(bi != supply->cend())
		{
			// Take up to 10% of what he has, to get what I need.
			quint32 take = (*bi).second->Count()/10;
			if(take)
			{
				if(take >= need)
				{
					take = need;
					need = 0;
				}
				else
					need -= take;
				AuItem* item = (*bi).second->Clone();	// Use a clone due to locking.
				bdSup->UnlockCommoditiesForRead();
				item->SetCount(take);
				if(AddCommodity(*item))
				{
					AuItemHash* supply = bdSup->LockCommoditiesForWrite();
					supply->TakeItem(*item);
					bdSup->UnlockCommoditiesForWrite(true);
					gotSome = true;
				}
				delete item;
			}
			else
				bdSup->UnlockCommoditiesForRead();
		}
		else
		{
			system->CommodityNotAvailable(importCID, *si);	// So people stop checking them.
			bdSup->UnlockCommoditiesForRead();
		}
		if(!need)
			break;	// I am full.
	}
	if(advertise && gotSome)
	{
		// Advertise my goods in the system commodity exchange so they can be imported.
		quint32 empireId = EmpireId();
		m_CargoLock.lockForRead();
		for(AuItemHash::const_iterator ci = m_Cargo.cbegin(); ci != m_Cargo.cend(); ci++)
			system->CommodityAvailable((*ci).first, Id(), empireId);
		m_CargoLock.unlock();
	}
}

quint32 DaBd::StoredPowerLevel() const
{
	return CapacitorLevel();
}

void DaBd::DischargeStoredPower(quint32 units)
{
	DischargeCapacitor(units);
}

const AuItemHash* DaBd::LockCommoditiesForRead()
{
	return &LockCargoForRead();
}

AuItemHash* DaBd::LockCommoditiesForWrite()
{
	return &LockCargoForWrite();
}

bool DaBd::RemoveCommodityNoLock(const AuItem& take, quint32 howMany)
{
	return RemoveCargoNoLock(take, howMany);
}

void DaBd::UnlockCommoditiesForRead()
{
	UnlockCargo();
}

void DaBd::UnlockCommoditiesForWrite(bool anyChange)
{
	if(anyChange)
		m_tmCargoChange.Set();
	UnlockCargo();
	if(anyChange)
		SetModified();
}

bool DaBd::ContainsEnemyUnit(quint32 empireId) const
{
	bool foundEnemy = false;
	DaAtomList subs;
	ListNormalSubatoms(subs);
	for(DaAtomList::const_iterator ai = subs.cbegin(); ai != subs.cend(); ai++)
	{
		const DaUnit* unit = dynamic_cast<const DaUnit*>(*ai);
		if(!unit)
			continue;
		if(unit->EmpireId() == 0)
			continue;		// Ignore empire 0 units, mainly to ignore wild animals.
		if(PoliticalStance(unit->EmpireId(), empireId) != POL_Enemy)
			continue;
		foundEnemy = true;	// Enemy unit found in this building.
		break;
	}
	return foundEnemy;
}

void DaBd::CreateRoadMap(const DaWorldLL& world, AuRoadMap& roadMap) const
{
	AuPoint siteCen(SiteCenter());
	siteCen = Transform().Project(siteCen.x, siteCen.y, 0);	// In the space of my world.
	AuGlobeLLF ll;
	if(!world.LLOfLoc(ll, siteCen))
		return;
	AuPoint boxRad = SiteHullBoxRadius();
	double siteRad = boxRad.Length_2D();
	double msl = AltitudeMSL();
	//qDebug() << "DaBd::CreateRoadMap" << Id() << Name() << "at" << ll << msl << "siteRad" << siteRad;
	roadMap.AddRoad(world, AuRoadSegment(AuRoadSegment::Bd, ll, msl, ll, msl, siteRad*2, Id()));
}

// Location returned is relative to my parent atom.
AuPoint DaBd::RandomSpawnLoc() const
{
	AuPoint spawnLoc;
	if(IndustryId() == IID_Fence)
	{
		//DHH Fence
		return Location();
	}

	bool inBuilding = false;
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	if(!scd)
	{
		UnlockDesign();
		m_DesignLock.unlock();
		qDebug() << "error: DaBd::RandomSpawnLoc" << Id() << Name() << "no design" << DesignId();
		return Location();
	}
	quint16 roomId = scd->RandomRoomVoidLocation(spawnLoc, PERSONNEL_Everyone, m_DoorStates, m_Lifts);
	if(roomId)
		inBuilding = true;										// Found a void location inside the building.
	else
		roomId = scd->RandomSiteLocation(spawnLoc, m_DoorStates);	// Look for an unobstructed location on the site.
	UnlockDesign();
	m_DesignLock.unlock();
	if(!roomId)
	{
		// Calculate random location outside the site extents.
		AuPoint siteRad(SiteHullBoxRadius());					// Site radius needed when we find no random location.
		double degrees = g_Au.Dice().Roll(1,361,-181);			// -180 to 180 degrees
		spawnLoc = SiteCenter() + siteRad.RotateZ(degrees * DEG2RAD);
	}
	spawnLoc = Transform().Project(spawnLoc);					// Transform spawn loc into the space of my parent world.
	if(!inBuilding)
	{
		// Elevate the point to the terrain when it is not inside the building.
		const DaWorldLL* world = FindParentWorldInEnv();
		if(world)
		{
			AuGlobeLLF ll;
			if(world->LLOfLoc(ll, spawnLoc))
				spawnLoc = world->GetSurfaceLocation(ll);
		}
	}
	return spawnLoc;
}

void DaBd::PaintOnSurfaceMap(const DaWorldLL& world, QPainter& p, unsigned int width, unsigned int height) const
{
	if(IndustryId() == IID_Fence)
		return;
	// My location on the map.
	float x = (GlobeLL().Longitude() + PIf) * width / (PIf*2.f);
	float y = ((PIf/2.f) - GlobeLL().Latitude()) * height / PIf;

	// Get extents of my design.
	AuPoint min,max;
	m_DesignLock.lockForRead();
	m_Design.Extents(min, max);
	m_DesignLock.unlock();
	float unitsPerPixel = world.NorthSouthDistance() / height;
	float sizeX = (max.x - min.x);
	float sizeY = (max.y - min.y);
	float pixels;
	if(sizeX > sizeY)
		pixels = sizeX / unitsPerPixel;
	else
		pixels = sizeY / unitsPerPixel;
	if(pixels <= 1)
	{
		// Draw a dot.
		p.setPen(QPen(MapColor(), 0.f));
		p.drawPoint(x,y);
	}
	else
	{
		// Draw a box.
		min /= unitsPerPixel;
		max /= unitsPerPixel;
		QRectF rc(x + min.x, y + min.y, max.x - min.x, max.y - min.y);
		p.fillRect(rc, MapColor());
	}
}

QColor DaBd::MapColor() const
{
	return DbIndustry::MapColor(IndustryId());
}

void DaBd::RenderOnSurfaceTexture(AuGLEffects& re, float radiansPerFootX, float radiansPerFootY) const
{
	if(IndustryId() == IID_Fence)
		return;
	const DaWorldLL* world = FindParentWorldInEnv();
	if(!world)
		return;
	if(world->Hydrographics() && !world->IsGasGiant() && AltitudeMSL() < 0)
		return;										// Undersea cities cannot be seen on the surface texture.
	if(DbIndustry::CanBeEnclosure(IndustryId()))
		return;										// Enclosures are so big this often looks strange so don't draw it.
	//qDebug() << "DaBd::RenderOnSurfaceTexture" << Id() << Name();
	// Get extents of my design.
	AuPoint min,max;
	m_DesignLock.lockForRead();
	m_Design.Extents(min, max);
	m_DesignLock.unlock();
	double margin = 2*FeetPerMeter();
	min -= AuPoint(margin, margin);
	max += AuPoint(margin, margin);

	// Locations relative to the world.
	AuPoint cll = Transform().Project(min.x, min.y, 0);
	AuPoint cul = Transform().Project(min.x, max.y, 0);
	AuPoint cur = Transform().Project(max.x, max.y, 0);
	AuPoint clr = Transform().Project(max.x, min.y, 0);
	AuGlobeLLF lll;
	if(!world->LLOfLoc(lll, cll))
		lll = GlobeLL();
	AuGlobeLLF lul;
	if(!world->LLOfLoc(lul, cul))
		lul = GlobeLL();
	AuGlobeLLF lur;
	if(!world->LLOfLoc(lur, cur))
		lur = GlobeLL();
	AuGlobeLLF llr;
	if(!world->LLOfLoc(llr, clr))
		llr = GlobeLL();
	//qDebug() << "DaBd::RenderOnSurfaceTexture" << Id() << Name() << "corners" << lll << lul << lur << llr;

	// Locations relative to the map.
	radiansPerFootX = 1;
	radiansPerFootY = 1;
	AuPoint vll = AuPoint(lll.Longitude() / PIf * radiansPerFootX, lll.Latitude() / (PIf/2.f) * radiansPerFootY);
	AuPoint vul = AuPoint(lul.Longitude() / PIf * radiansPerFootX, lul.Latitude() / (PIf/2.f) * radiansPerFootY);
	AuPoint vur = AuPoint(lur.Longitude() / PIf * radiansPerFootX, lur.Latitude() / (PIf/2.f) * radiansPerFootY);
	AuPoint vlr = AuPoint(llr.Longitude() / PIf * radiansPerFootX, llr.Latitude() / (PIf/2.f) * radiansPerFootY);
	AuPointArray verts;
	if(vur.SideOfLine_2D(vll, vul) < 0)
	{
		// Triangle is clockwise. It did not wrap around the globe.
		verts.append(vll);	// tri 1
		verts.append(vul);
		verts.append(vur);
	}
	else
	{
		// Triangle is counter-clockwise. It wrapped around the globe.
		//DHH Split triangle across 180 E/W line. If you do this here, do it in AuGeoRoadDirt too.
	}

	if(vll.SideOfLine_2D(vur, vlr) < 0)
	{
		// Triangle is clockwise. It did not wrap around the globe.
		verts.append(vur);	// tri 2
		verts.append(vlr);
		verts.append(vll);
	}
	else
	{
		// Triangle is counter-clockwise. It wrapped around the globe.
		//DHH Split triangle across 180 E/W line. If you do this here, do it in AuGeoRoadDirt too.
	}

	// The alpha value is a glow factor. The lower the alpha, the brighter the glow. The closer it approaches 1, the less glow.
	re.GLSL().LineShader().SetColor(0, 0, 0, .99f);

	// Make a VAO of the vertex locations.
	AuGLVAO rvao;
	rvao.CreateForLines(re, verts, false, GL_STREAM_DRAW);
	if(rvao.VAO())
	{
		// Display the VAO once and clean it up.
		re.glDisable(GL_DEPTH_TEST);
		re.glDisable(GL_CULL_FACE);
		rvao.SelectGL();
		rvao.DrawGL(GL_TRIANGLES);
		rvao.DeselectGL();
		rvao.DeleteGL();
		re.glEnable(GL_CULL_FACE);
		re.glEnable(GL_DEPTH_TEST);
	}
}

bool DaBd::IsVisibleNearWorld() const
{
	return true;
}

// Returns the point at the center of my site.
AuPoint DaBd::SiteCenter() const
{
	AuPoint smin, smax;
	if(IndustryId() == IID_Fence)
	{
		FenceExtents(smin, smax);
	}
	else
	{
		m_DesignLock.lockForRead();
		smax = m_Design.SiteMax();
		smin = m_Design.SiteMin();
		m_DesignLock.unlock();
	}
	return (smin + smax)/2;
}

AuPoint DaBd::SiteBoxRadius() const
{
	AuPoint smin, smax;
	if(IndustryId() == IID_Fence)
	{
		FenceExtents(smin, smax);
	}
	else
	{
		m_DesignLock.lockForRead();
		smax = m_Design.SiteMax();
		smin = m_Design.SiteMin();
		m_DesignLock.unlock();
	}
	if(smin == smax)
		return AuPoint(1,1,0);
	return (smax - smin)/2;
}

AuPoint DaBd::SiteHullBoxRadius() const
{
	AuPoint smin, smax;
	if(IndustryId() == IID_Fence)
	{
		FenceExtents(smin, smax);
	}
	else
	{
		m_DesignLock.lockForRead();
		smax = m_Design.SiteMax();
		smin = m_Design.SiteMin();
		// Include hull maxima that may exceed the site max. This is allowed for aerial platforms, sea platforms, and street lights.
		smax = smax.Max(m_Design.HullMax());
		smin = smin.Min(m_Design.HullMin());
		m_DesignLock.unlock();
	}
	if(smin == smax)
		return AuPoint(1,1,0);
	return (smax - smin)/2;
}

bool DaBd::ReportHistory(AuCityReportHistory& report) const
{
	if(IndustryId() != IID_Capitol && IndustryId() != IID_BaseHeadquarters)
		return false;
	m_BdLock.lockForRead();
	report = m_ReportHistory;
	m_BdLock.unlock();
	return true;
}

bool DaBd::ReportLast(AuCityReport& report) const
{
	if(IndustryId() != IID_Capitol && IndustryId() != IID_BaseHeadquarters)
		return false;
	m_BdLock.lockForRead();
	if(m_ReportHistory.IsEmpty())
	{
		m_BdLock.unlock();
		return false;
	}
	report = m_ReportHistory.Last();
	m_BdLock.unlock();
	return true;
}

bool DaBd::ReportNextToLast(AuCityReport& report) const
{
	if(IndustryId() != IID_Capitol && IndustryId() != IID_BaseHeadquarters)
		return false;
	m_BdLock.lockForRead();
	if(m_ReportHistory.Count() < 2)
	{
		m_BdLock.unlock();
		return false;
	}
	report = m_ReportHistory.NextToLast();
	m_BdLock.unlock();
	return true;
}

void DaBd::MailLastReport(const AuId& toId) const
{
	if(InArena() || InDesignPreview())
		return;

	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	const DaSolarSystem* system = world->FindParentSolarSystem();
	if(!system)
		return;
	const DaGalaxy* galaxy = system->FindParentGalaxy();
	if(!galaxy)
		return;

	m_BdLock.lockForRead();
	if(m_ReportHistory.IsEmpty())
	{
		m_BdLock.unlock();
		return;
	}

	const AuCityReport& report = m_ReportHistory.Last();

	AuMailMsg::MSGTYPE messageType = (AuMailMsg::MSGTYPE)report.m_MessageType;

	QString reportTitle(report.Title());

	QString reportText;
	if(m_ReportHistory.Count() == 1)
		reportText = report.ReportHtml(report, true);
	else
		reportText = report.ReportHtml(m_ReportHistory.NextToLast(), true);

	m_BdLock.unlock();

	const DgData& gd = g_Au.LockDataForRead();
	unsigned int idPlayer = gd.PlayerId();	// The local server must be "logged in" as someone to send mail.
	unsigned int confirmNum = gd.ConfirmationNumber();
	g_Au.UnlockData();

	AuPoint galaxyLoc;
	system->GetLocationRelativeToParent(galaxyLoc, galaxy);

	g_Au.SendMail(idPlayer, confirmNum, Id(), CityOrBuildingName(), toId, messageType, reportTitle, reportText, system->Id(),
			system->Name(), world->Id(), world->Name(), galaxy->Galaxy(), galaxyLoc);
}

// Returns true if I have no trade connections to anywhere else.
bool DaBd::IsIsolated() const
{
	m_TradeConnectionsLock.lockForRead();
	bool isIsolated = m_TradeConnections.empty() || (m_TradeConnections.size() == 1 && Is(m_TradeConnections.cbegin().key()));
	m_TradeConnectionsLock.unlock();
	return isIsolated;
}

quint32 DaBd::LastReportedBuildingLevels() const
{
	quint32 buildings;
	m_BdLock.lockForRead();
	if(!m_ReportHistory.IsEmpty())
		buildings = m_ReportHistory.Last().m_Industries.TotalLevels();
	else
		buildings = 0;
	m_BdLock.unlock();
	return buildings;
}

quint32 DaBd::LastReportedHomes() const
{
	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return 0;
	quint32 homes = 0;
	if(IsMilitary())
	{
		// Local facilities.
		DaAtomList base;
		world->FindBdBase(base);
		for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
		{
			DaBd* bd = (DaBd*)*bi;
			if(bd->IndustryId() == IID_BaseAcademy || bd->IndustryId() == IID_BaseMarineBarracks)
				continue;
			quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
			bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
			homes += homesLarge + homesMedium + homesSmall;
		}
	}
	else
	{
		// Local facilities.
		AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
		m_TradeConnectionsLock.lockForRead();
		for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
		{
			if(!(*ci & CON_Road))
				continue;				// Only care about airport repair shop connected by road.
			const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
			if(!bd)
				continue;				// Don't care about cities.
			if(!bd->InCommunityCity(myCapitolId))
				continue;
			if(bd->IndustryId() == IID_School || bd->IndustryId() == IID_PoliceAcademy)
				continue;
			quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
			bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
			homes += homesLarge + homesMedium + homesSmall;
		}
		m_TradeConnectionsLock.unlock();
	}
	return homes;
}

quint32 DaBd::LastReportedPopulation() const
{
	quint32 population;
	m_BdLock.lockForRead();
	if(!m_ReportHistory.IsEmpty())
		population = m_ReportHistory.Last().m_PopOrig;
	else
		population = 0;
	m_BdLock.unlock();
	return population;
}

void DaBd::ReportCurrent(AuCityReport& report, bool resetBankActivity) const
{
	const DaWorldLL* planet = FindParentWorldInEnv();
	if(!planet)
		return;	// wut?
	const DaSolarSystem* system = planet->FindParentSolarSystem();
	if(!system)
		return;	// wut?
	const DaSector* sector = system->FindParentSector();
	//if(!sector)
		//return;	// no sector during db load

	DaAtom* par = Parent();
	if(!par)
		return;

	DaAtomList bds;
	if(IndustryId() == IID_Capitol)
	{
		report.m_CityType = CITY_Capitol;
		par->FindBdCity(bds, Id());
	}
	else if(IndustryId() == IID_BaseHeadquarters)
	{
		report.m_CityType = CITY_MilitaryBase;
		par->FindBdBase(bds);
	}
	else
	{
		qWarning() << "error: DaBd::ReportCurrent" << Id() << Name() << "is" << IndustryName();
		return;
	}

	// Count total building volume on the world.
	report.m_WorldBuildingCount = 0;
	report.m_WorldBuildingVol = 0;
	quint32 fences = 0;
	quint32 streetLights = 0;
	DaAtomList subs;
	par->ListNormalSubatoms(subs);
	if(report.m_CityType == CITY_MilitaryBase)
	{
		for(DaAtomList::const_iterator ai = subs.cbegin(); ai != subs.cend(); ai++)
		{
			DaBd* bd = dynamic_cast<DaBd*>(*ai);
			if(!bd)
				continue;
			// Street lights don't count against world build count limit.
			if(bd->Structure() == BD_Fence)
				fences++;
			else if(bd->Structure() == BD_StreetLight)
				streetLights++;
			else
				report.m_WorldBuildingCount++;
			if(report.m_WorldBuildingVol < 0xffffffff)
			{
				quint32 obv = report.m_WorldBuildingVol;
				report.m_WorldBuildingVol += bd->HullVolume();
				if(report.m_WorldBuildingVol < obv)
					report.m_WorldBuildingVol = 0xffffffff;	// rolled over
			}
			if(!bd->IsMilitary() && !bd->IsUnderConstruction())
			{
				// Military bases gather count of civilian lounges and retail stores.
				quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
				bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
				report.m_Lounges += lounges;
				if(bd->IndustryId() == IID_Grocery)
					report.m_StoresGrocery += stores;
				else
					report.m_StoresRetail += stores;
			}
		}
	}
	else
	{
		for(DaAtomList::const_iterator ai = subs.cbegin(); ai != subs.cend(); ai++)
		{
			DaBd* bd = dynamic_cast<DaBd*>(*ai);
			if(!bd)
				continue;
			// Street lights don't count against world build count limit.
			if(bd->Structure() == BD_Fence)
				fences++;
			else if(bd->Structure() == BD_StreetLight)
				streetLights++;
			else
				report.m_WorldBuildingCount++;
			if(report.m_WorldBuildingVol < 0xffffffff)
			{
				quint32 obv = report.m_WorldBuildingVol;
				report.m_WorldBuildingVol += bd->HullVolume();
				if(report.m_WorldBuildingVol < obv)
					report.m_WorldBuildingVol = 0xffffffff;	// rolled over
			}
		}
	}
	// The first 20 fences are free.
	if(fences > 20)
		report.m_WorldBuildingCount += fences - 20;
	// The first 20 street lights are free.
	if(streetLights > 20)
		report.m_WorldBuildingCount += streetLights - 20;

	// Abandonment and Neglect
	AuId empireCapitol, galaxyCapitol, sectorCapitol;
	const DgData& gd = g_Au.LockDataForRead();
	if(gd.EmpireCapital(EmpireId(), empireCapitol) && sector)
	{
		const DaGalaxy* galaxy = sector->FindParentGalaxy();
		if(galaxy)
			galaxyCapitol = gd.EmpireGalaxyCapital(EmpireId(), galaxy->Id());
		sectorCapitol = gd.EmpireSectorCapital(EmpireId(), sector->Id());
	}
	FOUNDER_STATUS founderStatus = gd.EmpireCityFounderStatus(EmpireId(), Id());
	g_Au.UnlockData();

	// Collect information from all of the buildings that make up this city, including this one.
	quint32 residents = 0;
	quint32 residentsEmployed = 0;
	quint32 jobsCon = 0;
	quint32 jobsMfg = 0;
	quint32 jobsPro = 0;
	quint32 jobsSvc = 0;
	bool hasSensorsOrObservatory = false;
	for(DaAtomList::const_iterator bi = bds.cbegin(); bi != bds.cend(); bi++)
	{
		if(!(*bi)->IsNormal())
			continue;
		DaBd* bd = (DaBd*)*bi;
		if(bd->IsUnderConstruction())
		{
			jobsCon++;
		}
		else
		{
			// Event Log
			bd->ReportEventLog(*report.m_EventLog);

			if(bd->HasSensors() && bd->CapacitorLevel() > 0)
				hasSensorsOrObservatory = true;
			else if(bd->IndustryId() == IID_Observatory)
				hasSensorsOrObservatory = true;

			if(bd->Residents())
			{
				AuSpecies species(bd->ResidentSpecies());
				report.AddResidentSpecies(species, planet->IsAlienSpecies(species), bd->Residents());
				residents += bd->Residents();
			}
			if(bd->TransientPopulation())
			{
				bd->m_TransientLock.lockForRead();
				for(QMap<AuSpecies, quint32>::const_iterator ti = bd->m_TransientPopulation.cbegin();
						ti != bd->m_TransientPopulation.cend(); ti++)
				{
					report.AddResidentSpecies(ti.key(), planet->IsAlienSpecies(ti.key()), *ti);
					residents += *ti;
				}
				bd->m_TransientLock.unlock();
			}
			residentsEmployed += bd->ResidentsEmployed();

			bd->m_BdLock.lockForRead();
			report.m_PopBirths += bd->m_ReportPopBirths;
			report.m_PopDeaths += bd->m_ReportPopDeaths;
			report.m_PopIndigenousArr += bd->m_ReportPopIndigenousArr;
			report.m_PopIndigenousDep += bd->m_ReportPopIndigenousDep;
			report.m_PopSeafarersArr += bd->m_ReportPopSeafarersArr;
			report.m_PopSeafarersDep += bd->m_ReportPopSeafarersDep;
			report.m_PopTravellersArr += bd->m_ReportPopTravellersArr;
			report.m_PopTravellersDep += bd->m_ReportPopTravellersDep;
			report.m_PopWanderersArr += bd->m_ReportPopWanderersArr;
			report.m_PopWanderersDep += bd->m_ReportPopWanderersDep;
			bd->m_BdLock.unlock();
			if(bd->IsDamagedHeavily())
				report.m_HasDestroyedBuildings |= 0x01;
			if(bd->IsBurning())
				report.m_HasDestroyedBuildings |= 0x02;

			quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, manufacturingJobsEnabled, serviceJobs, stores, lounges,
					proJobs;
			bd->IndustryInfoJobs(homesLarge, homesMedium, homesSmall, manufacturingJobs, manufacturingJobsEnabled, serviceJobs,
					stores, lounges, proJobs);
			report.m_Lounges += lounges;
			if(bd->IndustryId() == IID_Grocery)
				report.m_StoresGrocery += stores;
			else
				report.m_StoresRetail += stores;
			if(homesLarge > 0xffff)
				homesLarge = 0xffff;
			if(homesMedium > 0xffff)
				homesMedium = 0xffff;
			if(homesSmall > 0xffff)
				homesSmall = 0xffff;
			if(manufacturingJobs > 0xffff)
				manufacturingJobs = 0xffff;
			if(manufacturingJobsEnabled > 0xffff)
				manufacturingJobsEnabled = 0xffff;
			if(proJobs > 0xffff)
				proJobs = 0xffff;
			if(serviceJobs > 0xffff)
				serviceJobs = 0xffff;
			report.m_HomesLg += homesLarge;
			report.m_HomesMd += homesMedium;
			report.m_HomesSm += homesSmall;
			jobsMfg += manufacturingJobsEnabled;
			jobsPro += proJobs;
			jobsSvc += serviceJobs;

			if(manufacturingJobs)
				report.m_Industries.Add(bd->IndustryId(), AuCityIndustry(manufacturingJobs, manufacturingJobsEnabled));
			else if(proJobs)
				report.m_Industries.Add(bd->IndustryId(), AuCityIndustry(proJobs, proJobs));
			else
				report.m_Industries.Add(bd->IndustryId(), AuCityIndustry(1, 1));

			bd->LockCargoForRead();
			// Inventory
			for(AuItemHash::const_iterator ci = bd->m_Cargo.cbegin(); ci != bd->m_Cargo.cend(); ci++)
				report.m_Inventory->AddItem(*(*ci).second);
			// Tools
			for(AuItemHash::const_iterator ti = bd->m_Tools.cbegin(); ti != bd->m_Tools.cend(); ti++)
				report.m_Tools->AddItem(*(*ti).second);
			// Vehicles
			for(QList<COMMODITYID>::const_iterator vi = bd->m_Vehicles.cbegin(); vi != bd->m_Vehicles.cend(); vi++)
				if(!report.m_Vehicles.contains(*vi))
					report.m_Vehicles.append(*vi);
			bd->UnlockCargo();

			// Patent RnD
			const DeManufacturingProcessArray& mpa = bd->LockManufacturingProcessesForRead();
			for(DeManufacturingProcessArray::const_iterator mi = mpa.cbegin(); mi != mpa.cend(); mi++)
			{
				if(!DbCommodity::IsPatent((*mi).CommodityId()))
					continue;	// Not a patent development process.
				// We only need to know about Patent processes that are active.
				quint32 shops = (*mi).ShopsEnabled();
				if(!shops)
					continue;	// Not active.
				QMap<QString, quint16>::iterator pi = report.m_PatentRnD.find((*mi).CommodityName());
				if(pi != report.m_PatentRnD.end())
					(*pi) += shops;
				else
					report.m_PatentRnD.insert((*mi).CommodityName(), shops);
			}
			bd->UnlockManufacturingProcesses();

			// Patents
			const AuKnownPatents& bdpat = bd->LockPatentsForRead();
			report.m_Patents.RecordPatents(bdpat);
			bd->UnlockPatents();

			report.m_iCapacitor += bd->CapacitorMax();
			report.m_Power += bd->CapacitorLevel();
			if(resetBankActivity)
			{
				// Accumulate bank activity and balances.
				report.m_Bank += bd->LockBankForWrite();
				bd->ClearBankActivityAccountLocked();
				bd->UnlockBank();
			}
			else
			{
				// Accumulate bank activity and balances.
				report.m_Bank += bd->LockBank();
				bd->UnlockBank();
			}
		}
		report.m_iStorage += bd->CargoCapacityVolume();
	}

	m_BdLock.lockForRead();
	quint32 foodPerMeal = m_FoodPerMeal;
	m_BdLock.unlock();
	if(residents)
	{
		if(!foodPerMeal)
		{
			// Worker's DNA tells us how much food they eat per meal.
			// Citizens eat 1/5 of their hit points per meal.
			//DHH animalia DpBody workerBody(1, 1, report.CitizenDNA());
			//DHH animalia foodPerMeal = workerBody.MaxHitPoints() / 5;
			foodPerMeal = 50 / 5;	//DHH animalia
			if(foodPerMeal < 1)
				foodPerMeal = 1;
			m_BdLock.lockForWrite();
			m_FoodPerMeal = foodPerMeal;
			m_BdLock.unlock();
		}
	}
	else
	{
		// No residents. No food consumption.
		if(foodPerMeal)
		{
			foodPerMeal = 0;
			m_BdLock.lockForWrite();
			m_FoodPerMeal = foodPerMeal;
			m_BdLock.unlock();
		}
	}

	// Spacecraft - All ships in town and in orbit.
	DaAtomList ships;
	QMap<const DaVessel*, AuGlobeLLF> shipsToReport;
	planet->FindVesselsRecursive(ships);
	if(report.BuildingLevels(IID_Hangar))
		planet->FindHangaredSpaceships(ships);
	for(DaAtomList::const_iterator si = ships.begin(); si != ships.end(); si++)
	{
		DaVessel* ship = (DaVessel*)(*si);
		if(ship->IsNormal())
		{
			if(Is(ship->InBdCity()))
			{
				// Found a ship in this city.
				if(ship->IsOnGround())
					shipsToReport.insert(ship, ship->GlobeLL());					// Found a ship in this city on the ground.
			}
			else if(!ship->IsInAtmosphere() && planet->Is(ship->ParentId()))
			{
				// Ships in orbit are detected using sensors or known if they belong to my empire.
				if(hasSensorsOrObservatory || ship->EmpireId() == EmpireId())
					shipsToReport.insert(ship, ship->GlobeLL());					// Found a ship in orbit.
			}
		}
		else if(ship->IsDormant() && ship->IsMoored())
		{
			// Ships in hangars are not "normal". They are dormant and also moored.
			// Check to see if the ship is hangared in this city.
			if(Is(ship->InBdCity()))
				shipsToReport.insert(ship, ship->GlobeLL());						// Found a hangared ship in this city.
		}
	}
	if(!shipsToReport.isEmpty())
	{
		for(QMap<const DaVessel*, AuGlobeLLF>::const_iterator si = shipsToReport.begin(); si != shipsToReport.end(); si++)
		{
			const DaVessel* ship = si.key();

			AuCityReportShip rptship;
			rptship.m_IsSpaceStation = ship->IsSpaceStation();
			rptship.m_IsNew = ship->IsNew();
			if(ship->IsNormal())
				rptship.m_Location = ship->IsOnGround() ? 1 : 0;
			else
				rptship.m_Location = 2;					// Hangar
			rptship.m_ShipLL = *si;
			rptship.m_SpotDesc = ship->SpotDescription(EmpireId());
			report.m_Ships.append(rptship);
		}
	}

	report.m_AirConsumed = -1;			// -1 for intermediate queries so air/suffocation reported differently
	report.m_AirSupply = report.m_Inventory->RawCount(CID_Air);

	// Food consumption result carries over from last city cycle until the next CityCycle updates it.
	m_BdLock.lockForRead();
	if(!m_ReportHistory.IsEmpty())
		report.m_AteEnoughFood = m_ReportHistory.Last().m_AteEnoughFood;
	else
		report.m_AteEnoughFood = true;	// Don't impose hunger penalty when just getting started and no history of reports.
	m_BdLock.unlock();

	if((report.m_Industries.contains(IID_BaseAcademy) || report.m_Industries.contains(IID_School)) &&
			planet->CaptId().IsNull() && !planet->CaptName().isEmpty())
		report.m_CaptName = planet->CaptName();					// Report the parent planet's ship captain available at academy.
	report.m_ConsumedLiquor = report.m_Inventory->HasLiquor();
	AuFlag flag;
	flag.m_DevLL = GlobeLL();
	flag.m_Empire = EmpireId();
	flag.m_IID = IndustryId();
	flag.m_Terrain = planet->Id();
	report.m_Flags.append(flag);				// First one is always town square. A flag is added for each base.
	report.m_FoodPerMeal = foodPerMeal;
	ECOROLE workerEcoRole = report.m_Citizens.empty() ? ECO_Omnivore : report.Citizen().EcoRole();
	report.m_FoodUnits = report.m_Inventory->TotalFoodNutritionValue(workerEcoRole);
	report.m_FoodTypes = report.m_Inventory->AvailableFoodTypes(workerEcoRole);
	report.m_FounderId = FounderId();
	report.m_FounderName = FounderName();
	report.m_FounderStatus = founderStatus;
	report.m_Galaxy = Galaxy();
	report.m_HasBreathableAtmo = planet->HasBreathableAtmosphere();
	report.m_IsCapitalOfEmpire = Is(empireCapitol);
	report.m_IsCapitalOfGalaxy = Is(galaxyCapitol);
	report.m_IsCapitalOfSector = Is(sectorCapitol);
	report.m_IsHabitablePlanet = planet->IsHabitable(HABITABLE_System);
	report.m_IsIsolated = IsIsolated();
	report.m_IsOnRingworld = dynamic_cast<const DaWorldRingSection*>(planet);
	report.m_Jobs = jobsMfg;
	report.m_JobsNonConst = jobsCon;
	report.m_JobsPro = jobsPro;
	report.m_JobsRepair = jobsSvc;
	if(!m_ReportHistory.IsEmpty())
		report.m_LastTribute = m_ReportHistory.Last().m_LastTribute;		// Carry forward last tribute value.
	if(!system->LastPersonVisited().IsNull())
	{
		// Days since system visited by an avatar on line.
		if(system->LastPersonVisited().IsNull())
			report.m_LastVisit = 0xffff;
		else
			report.m_LastVisit = system->LastPersonVisited().ElapsedDay();
	}
	if(!system->LastAvatarAccountActive().IsNull())
	{
		// Days since land systems pinged by avatar on active account. I get the ping if I am in one of those solar systems.
		if(system->LastAvatarAccountActive().IsNull())
			report.m_LastAvatarAccountActive = 0xffff;
		else
			report.m_LastAvatarAccountActive = system->LastAvatarAccountActive().ElapsedDay();
	}
	// Report my site center location. It works better if someone is ordering their crew to hover here.
	AuPoint siteCen = Transform().Project(SiteCenter());					// Site center relative to the world.
	planet->LLOfLoc(report.m_LL, siteCen);
	//report.m_LoyaltyOrig;
	report.m_MaxPop = planet->WorldPopulationMax();

	if(report.m_Decayed[0] != IID_None)
	{
		// The final decay message gets a message type that is not automatically deleted from the mail system.
		QString distressRpt;
		if(IsDormant())
		{
			// City decayed from existence.
			report.m_MessageType = AuMailMsg::MSG_CityFinalDecayReport;
			if(report.m_CityType == CITY_Capitol)
				distressRpt += tr("Abandoned city decayed from existence.");
			else
				distressRpt += tr("Abandoned base decayed from existence.");
		}
		else
		{
			// City is not gone yet.
			report.m_MessageType = AuMailMsg::MSG_CityDistressReport;		// Distress report message.
			if(report.m_CityType == CITY_Capitol)
				distressRpt += tr("City is abandoned and decaying.");
			else
				distressRpt += tr("Base is abandoned and decaying.");
		}
		report.m_DistressRpt = QString("<b style=\"color: rgb(255, 255, 0);\">DISTRESS</b><div style=\"margin-left: 10px;\">"
				"<span style=\"color: rgb(255, 255, 0);\">") +
			distressRpt + "</span></div><br>";
	}
	else if(report.m_EventLog->ContainsAlert(AuTime()))
		report.m_MessageType = AuMailMsg::MSG_CityDistressReport;			// Distress report message.
	else if(!report.m_EventLog->isEmpty())
		report.m_MessageType = AuMailMsg::MSG_CityStatusReportInfo;			// City status report with info.
	report.m_Name = HtmlName(CityOrBuildingName());
	report.m_NativeSpecies = planet->WorkerSpeciesName();
	report.m_NativeSpeciesDesc = planet->WorkerSpeciesDesc();
	report.m_PlanetDesc = planet->Description();
	report.m_PlanetName = planet->HtmlName();
	report.m_PopOrig = residents;
	report.m_SatOrig = Morale();
	if(sector)
	{
		report.m_SectorName = sector->HtmlName();
		report.m_SectorDesc = sector->Description();
	}
	//report.m_Ships;
	report.m_SystemName = system->HtmlNameWithSystem();
	report.m_SystemDesc = system->Description();
	//report.m_TroopsAtCity;
	//report.m_TroopsDrafted;
	unsigned int totalJobs = jobsMfg + jobsCon + jobsPro + jobsSvc;
	if(residents > totalJobs)
		report.m_Unemployed = residents - totalJobs;
	else
		report.m_Unemployed = 0;
	report.m_WhenCompiled.Set();
	report.m_Zone = planet->ResourceZone(report.m_LL.Longitude());
	report.m_ZonePop = planet->WorldPopulation();
}

quint32 DaBd::TradeConnectionsByAir() const
{
	quint32 connections = 0;
	m_TradeConnectionsLock.lockForRead();
	if(m_Airport)
	{
		for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
		{
			if(Is(ci.key()))
				continue;
			if((*ci) & CON_Airport)
				connections++;
		}
	}
	m_TradeConnectionsLock.unlock();
	return connections;
}

quint32 DaBd::TradeConnectionsByLand() const
{
	quint32 connections = 0;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(Is(ci.key()))
			continue;
		if((*ci) & CON_Road)
			connections++;
	}
	m_TradeConnectionsLock.unlock();
	return connections;
}

quint32 DaBd::TradeConnectionsBySea() const
{
	quint32 connections = 0;
	m_TradeConnectionsLock.lockForRead();
	if(m_Wharf)
	{
		for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
		{
			if(Is(ci.key()))
				continue;
			if((*ci) & CON_Wharf)
				connections++;
		}
	}
	m_TradeConnectionsLock.unlock();
	return connections;
}

