// Spacecraft factory.
void DaBd::TryToSpawnShip()
{
	// Spacecraft must be built with an empire id.
	quint32 myEmpireId = EmpireId();
	if(!myEmpireId)
		return;
	DeManufacturingProcessArray& mpa = LockManufacturingProcessesForWrite();
	if(mpa.empty())
	{
		UnlockManufacturingProcesses();
		qDebug() << "DaBd::TryToSpawnShip" << Id() << Name() << "Manufacturing process not found";
		return;
	}
	DeManufacturingProcess& mp = mpa.FindProcess(0);

	// The negative CommodityId of the process is the design id of the ship.
	int idDesign = -mp.CommodityId();

	m_SpacecraftFactoryLock.lockForWrite();

	if(m_MakingShip.DesignId() != (quint32)idDesign)
	{
		if(m_MakingShip.DesignId())
		{
			UnlockManufacturingProcesses();
			qWarning() << "error: DaBd::TryToSpawnShip" << Id() << Name()
				<< "Manufacturing process design" << idDesign << "does not match current ship design" << m_MakingShip.DesignId()
				<< "Abandoning making ship.";
			ClearProcess(mp);
			m_SpacecraftFactoryLock.unlock();
			SetModified();
			return;
		}
	}

	// Insure that the design is valid. It may not be if the database thread hasn't gotten around to loading it yet.
	AuScReport shipDesign;
	const DgData& sdd = g_Au.LockScDesignsForRead();
	bool hasDesign = sdd.ScDesignReport(m_MakingShip.DesignId(), shipDesign);	// Triggers load of design from db if needed.
	g_Au.UnlockScDesigns();
	if(hasDesign)
	{
		// The design record is available locally.
		m_DesignTries = 0;
		quint32 empireId = m_MakingShip.OwnerEmpire();
		if(!empireId)
			empireId = myEmpireId;
		int result = SpawnSc(shipDesign, m_MakingShip.Quality(), m_MakingShip.OwnerId(), m_MakingShip.OwnerName(), empireId);
		if(result == 0)
		{
			// Spawned ok.
			mp.SetLastOutput(1, m_MakingShip.Quality());
			mp.ConsumeComponents();
			ClearProcess(mp);
		}
		else
		{
			// Couldn't spawn or data isn't valid yet.
			// Set up to try again later.
			switch(result)
			{
			default:
				qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						<< "Result" << result << "Trying again later.";
				break;
			case 11:
				//qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						//<< "No slab found. Trying again later.";
				break;
			case 12:
				// This is normal enough that we don't need to see a message.
				//qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						//<< "No unobstruction slab found. Trying again later.";
				break;
			case 13:
				qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						<< "Spawn loc not on the world. Trying again later.";
				break;
			case 21:
				qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						<< "Blocked by unanalyzed ship. Trying again later." << Id() << Name();
				break;
			case 22:
				// This is normal enough that we don't need to see a message.
				//qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						//<< "Cannot spawn another station in orbit or replace an existing station. Trying again later.";
				break;
			case 23:
				// This is normal enough that we don't need to see a message.
				//qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						//<< "Cannot spawn another nu ship in orbit or replace an existing nu ship. Trying again later.";
				break;
			case 24:
				qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						<< "Orbit spawn location could not be found. Trying again later.";
				break;
			case 25:
				//qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						//<< "No station at which to spawn. Trying again later.";
				break;
			case 40:
				qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						<< "Empire 0 cannot own spacecraft. Trying again later." << Id() << Name();
				break;
			case 41:
				qDebug() << "DaBd::TryToSpawnShip - Spawn design id failed" << m_MakingShip.DesignId()
						<< "Empire 0 cannot make spacecraft. Trying again later." << Id() << Name();
				break;
			}
			m_tmLastSpawnTry.restart();
			mp.SetLastOutput(-result, m_MakingShip.Quality());
		}
	}
	else
	{
		// Couldn't spawn or data isn't valid yet.
		// Set up to try again later.
		m_DesignTries++;
		if(m_DesignTries > 10)
			qDebug() << "DaBd::TryToSpawnShip" << Id() << Name()
				<< "Design cache not valid, sc design" << m_MakingShip.DesignId() << "Will try again later. Already tried"
				<< m_DesignTries << "times.";
		m_tmLastSpawnTry.restart();
		mp.SetLastOutput(-5, m_MakingShip.Quality());	// Design not analyzed.
	}
	m_SpacecraftFactoryLock.unlock();
	UnlockManufacturingProcesses();
	SetModified();
}

void DaBd::ClearProcess(DeManufacturingProcess& mp)
{
	// Clear the manufacturing process.
	mp.InitSc(0, 1);											// Stop trying to manufacture any design.
	m_MakingShip = AuMakeDesign();								// Clear information about current ship in process.
}

int DaBd::SpawnSc(const AuScReport& ship, quint8 initQuality, const AuId& ownerId, const QString& ownerName, quint32 ownerEmpire)
{
	if(!ownerEmpire)
		return 40;	// Empire 0 cannot own spacecraft.
	quint32 myEmpireId = EmpireId();
	if(!myEmpireId)
		return 41;	// Empire 0 cannot build spacecraft.

	// Update empire id on ship design to spawn. We wait until now in case the city changes hands.
	DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return 41;	//DHH wrong error code

	int result;
	if(ship.MustBeBuiltInSpace())
	{
		result = llworld->SpawnSc(ship, myEmpireId, initQuality, ownerId, ownerName, ownerEmpire, Id());
		if(result)
			result += 20;				// So result codes don't overlap those of the other version of SpawnSpacecraft.
	}
	else
	{
		result = llworld->SpawnSc(this, ship, initQuality, ownerId, ownerName, ownerEmpire);
		if(result)
			result += 10;				// So result codes don't overlap those of the other version of SpawnSpacecraft.
	}
	return result;
}

void DaBd::NotifyNewSpacecraftOwner(const AuId& ownerId, const QString& ownerName, quint32 ownerEmpire,
		const DaVessel* ship) const
{
	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	const DaSolarSystem* system = world->FindParentSolarSystem();
	if(!system)
		return;
	const DaSector* sector = world->FindParentSector();
	if(!sector)
		return;
	const DaGalaxy* galaxy = sector->FindParentGalaxy();
	if(!galaxy)
		return;
	AuPoint galaxyLoc;
	system->GetLocationRelativeToParent(galaxyLoc, galaxy);

	const DgData& gd = g_Au.LockDataForRead();
	unsigned int idPlayer = gd.PlayerId();	// The local server must be "logged in" as someone to send mail.
	unsigned int confirmNum = gd.ConfirmationNumber();
	QString ownerEmpireName;
	gd.EmpireName(ownerEmpire, ownerEmpireName);
	g_Au.UnlockData();

	QString name(CityOrBuildingName());

	// Build a mail message.
	QString rpt = g_Au.EncodeUTCString() + "<br><br>";
	rpt += "<b>" + name + "</b><div style=\"margin-left: 10px;\">";
	rpt += world->HtmlName() + ", " + world->Description() + "<br>";
	rpt += system->HtmlNameWithSystem() + ' ' + system->Description() + "<br>";
	rpt += sector->HtmlName() + ' ' + sector->Description() + "<br>";
	rpt += galaxy->HtmlName() + "<br>";

	// Longitude and latitude coordinates.
	// My location is the real long lat on my parent world.
	rpt += Description() + "<br></div>";

	if(ship->IsInAtmosphere())
		rpt += QObject::tr("<div style=\"margin-left: 10px;\"><p>Congratulations %1!</p>"
				"<p>"
				"Construction of your new spacecraft was completed. "
				"%5. "
				"She is a beauty. "
				"</p>"
				"<p>"
				"The ship is parked on the tarmac at %4. "
				"The title was registered to %1 <i>%2</i> under the flag of %3. "
				"She's ready for you to pick up, at your convenience. "
				"</p>"
				"<p>"
				"As always, we are happy to serve you. "
				"Please call on our expert facilities to build your next ship. "
				"</p>"
				"<p>"
				"Best regards,<br>"
				"Shipyard Manager"
				"</p>"
			)
			.arg(ownerName)
			.arg(ownerId.StringId())
			.arg(ownerEmpireName)
			.arg(ship->GlobeLL().ToString())
			.arg(ship->SpotDescription(ownerEmpire));
	else
		rpt += QObject::tr("<div style=\"margin-left: 10px;\"><p>Congratulations %1!</p>"
				"<p>"
				"Construction of your new spacecraft was completed. "
				"%5. "
				"She is a beauty. "
				"</p>"
				"<p>"
				"The ship is parked in orbit at %4. "
				"The title was registered to %1 <i>%2</i> under the flag of %3. "
				"She's ready for you to pick up, at your convenience. "
				"</p>"
				"<p>"
				"As always, we are happy to serve you. "
				"Please call on our expert facilities to build your next ship. "
				"</p>"
				"<p>"
				"Best regards,<br>"
				"Shipyard Manager"
				"</p>"
			)
			.arg(ownerName)
			.arg(ownerId.StringId())
			.arg(ownerEmpireName)
			.arg(ship->GlobeLL().ToString())
			.arg(ship->SpotDescription(ownerEmpire));

	QString title = QObject::tr("Spacecraft Manufacture Completed");
	g_Au.SendMail(idPlayer, confirmNum, Id(), name, ownerId, AuMailMsg::MSG_ShipReport, title, rpt, system->Id(), system->Name(),
			world->Id(), world->Name(), galaxy->Galaxy(), galaxyLoc);
}

void DaBd::SpacecraftParkingSpots(QList<AuMatrix4x4>& parkMs) const
{
	const AuBdDesign* scd = LockDesign();
	if(scd)
		scd->SpacecraftParkingSpots(parkMs);
	UnlockDesign();
}

void DaBd::WaterVehicleParkingSpots(QList<AuMatrix4x4>& parkMs) const
{
	const AuBdDesign* scd = LockDesign();
	if(scd)
		scd->WaterVehicleParkingSpots(parkMs);
	UnlockDesign();
}

void DaBd::QueueMakeShip(quint32 designId, const QString& designName, quint8 designQ, const AuId& ownerId,
		const QString& ownerName, quint32 ownerEmpire)
{
	m_SpacecraftFactoryLock.lockForWrite();
	if(m_DesignQueue.size() < 0xff)
		m_DesignQueue.push_back(AuMakeDesign(designId, designName, designQ, ownerId, ownerName, ownerEmpire));
	m_SpacecraftFactoryLock.unlock();
	SetModified();
}

void DaBd::SetDefaultMakeShip(quint32 designId, const QString& designName, quint8 designQ)
{
	m_SpacecraftFactoryLock.lockForWrite();
	m_DefaultDesign = AuMakeDesign(designId, designName, designQ);
	m_SpacecraftFactoryLock.unlock();
	SetModified();
}

void DaBd::DeleteOrder(quint32 designId)
{
	for(QList<AuMakeDesign>::iterator di = m_DesignQueue.begin(); di != m_DesignQueue.end(); di++)
	{
		if((*di).DesignId() == designId && (*di).OwnerId().IsNull())
		{
			// Found the fleet design order.
			m_DesignQueue.erase(di);
			SetModified();
			return;
		}
	}
}

void DaBd::SpacecraftProcessCanceled(AuId& buyerId, QString& buyerName, double& buyerRefund)
{
	DeManufacturingProcessArray& mpa = LockManufacturingProcessesForWrite();
	if(mpa.empty())
	{
		UnlockManufacturingProcesses();
		return;
	}
	DeManufacturingProcess& mp = mpa.FindProcess(0);

	// Return materials that have already been collected by the process to the city inventory.
	for(DeProcessComponentArray::const_iterator ci = mp.Components().cbegin(); ci != mp.Components().cend(); ci++)
	{
		if((*ci).QtyConsumed() && (*ci).QtyApplied())
		{
			// Consumable components have already been applied to the process.
			if((*ci).CommodityId() == CID_Money)
			{
				// Money is returned to the govt and citizen accounts equally. That is where processes pull money from.
				double refund = (*ci).QtyApplied();
				DebitAccount(refund, AuBank::Civ_DebitSalary);	// Take money back from payroll.
				CreditAccount(refund, AuBank::Civ_CreditRnD);
			}
			else if(g_Au.Commodity((*ci).CommodityId()).CanBeCargo())
			{
				// Other commodities are returned to the city's inventory, if they can be stored there. Sunlight and similar things
				// are lost.
				AuItem* returnItem = AuItem::Create((*ci).CommodityId(), (*ci).Quality(), EmpireId(), (*ci).QtyApplied());
				if(returnItem)
				{
					quint32 canFit = TestFitCommodity(*returnItem);
					if(canFit)
					{
						returnItem->SetCount(canFit);
						AddCommodity(*returnItem);				// There was room for at least one of the return items.
					}
					delete returnItem;
				}
			}
		}
	}

	// 0 is the none option on the UI.
	mp.InitSc(0, 1);											// Stop trying to manufacture any design.
	UnlockManufacturingProcesses();

	// Cancel whatever the building was making.
	TerminateProcess(buyerId, buyerName, buyerRefund);
	SetModified();
}

void DaBd::TerminateProcess(AuId& buyerId, QString& buyerName, double& buyerRefund)
{
	m_SpacecraftFactoryLock.lockForWrite();
	buyerId = m_MakingShip.OwnerId();
	buyerName = m_MakingShip.OwnerName();
	if(!m_MakingShip.OwnerId().IsNull())
	{
		// Make a manufacturing process for the design so we can estimate the cost of manufacturing the design.
		DeManufacturingProcess mfgProc;
		mfgProc.InitSc(m_MakingShip.DesignId(), m_MakingShip.Quality());

		// Estimate the cost at the design quality.
		buyerRefund = mfgProc.EstimatedCost(m_MakingShip.Quality());
	}
	m_MakingShip = AuMakeDesign();
	m_SpacecraftFactoryLock.unlock();
	SetModified();
}

bool DaBd::SelectProcess(DeManufacturingProcess& mp)
{
	if(IndustryId() != IID_SpacecraftFactory)
		return false;

	// Select the next process if we are not currently making anything.
	m_SpacecraftFactoryLock.lockForWrite();
	if(!m_MakingShip.IsNull())
	{
		m_SpacecraftFactoryLock.unlock();
		return false;
	}

	// Select the next design to make.
	if(!m_DesignQueue.empty())
	{
		// The design queue gets priority for making designs.
		m_MakingShip = m_DesignQueue.takeFirst();
	}
	else if(!m_DefaultDesign.IsNull())
	{
		// Make the default design. This might not actually be a change.
		m_MakingShip = m_DefaultDesign;
	}
	else
	{
		// No longer manufacturing any ships.
		m_MakingShip = AuMakeDesign();
	}

	// Configure the manufacturing process.
	if(m_MakingShip.IsNull())
		mp.InitSc(0, 1);											// Stop trying to manufacture any design.
	else
	{
		// Configure process to make the design.
		mp.InitSc(m_MakingShip.DesignId(), m_MakingShip.Quality());
		if(m_MakeMinQ > mp.MinimumQRequired())
			mp.SetMinimumQ(m_MakeMinQ);
	}
	m_SpacecraftFactoryLock.unlock();
	SetModified();
	return true;
}

double DaBd::BankLoanFundsAvailable() const
{
	if(IndustryId() != IID_Bank)
		return 0;
	AuId capId = CapitolId();
	if(capId.IsNull())
		return AccountBalance() * .9;	// I am not part of a city so I can only access my own money. Loan up to 90% of my money.

	const DaAtom* parent = Parent();
	if(!parent)
		return 0;
	DaAtomList bds;
	parent->FindBdCity(bds, CapitolId());
	double money = 0;
	for(DaAtomList::const_iterator bi = bds.cbegin(); bi != bds.cend(); bi++)
	{
		const DaBd* bd = (const DaBd*)*bi;
		double bdmoney = bd->AccountBalance();
		bdmoney *= .9;					// Loan up to 90% of all money.
		money += bdmoney;
	}
	return money;
}

