void DaBd::DebitAccountCitizenLoans(double amount)
{
	if(IndustryId() != IID_Bank)
		return;
	AuId capId = CapitolId();
	if(capId.IsNull())
		DebitAccount(amount, AuBank::Civ_DebitLoans);
	else
	{
		const DaAtom* parent = Parent();
		if(!parent)
			return;
		DaAtomList bds;
		parent->FindBdCity(bds, CapitolId());
		for(DaAtomList::const_iterator bi = bds.begin(); bi != bds.end(); bi++)
		{
			DaBd* bd = (DaBd*)*bi;
			double bdmoney = bd->AccountBalance();
			bdmoney *= .9;					// Loan up to 90% of all money.
			if(bdmoney < amount)
			{
				bd->DebitAccount(bdmoney, AuBank::Civ_DebitLoans);
				amount -= bdmoney;
			}
			else
			{
				bd->DebitAccount(amount, AuBank::Civ_DebitLoans);
				break;
			}
		}
	}
}

