void DaBd::RxAuction(const AuCommAuction* msg, DaVessel* ship, const AuId& sectorId, AuCommStdChannel::RANGE range,
		POLITICAL_STANCE stanceToSender, DaPerson* person)
{
	if(!msg)
		return;
	switch(IndustryId())
	{
	case IID_Broker:
		// Brokers support company and fleet ships.
		if(!ship)
			return;
		break;
	case IID_BaseAirTerminal:
		// Military air terminals only communicate with fleet spacecraft.
		if(!ship)
			return;
		if(ship->IsPrivatelyOwned())
			return;
		break;
	case IID_AirportTerminal:
		// Airport terminals support company and fleet ships.
		if(!ship)
			return;
		break;
	default:
		// Other buildings will communicate with a person who is at this building.
		if(!person || !Is(person->BdId()))
			return;
		break;
	}

	// Determine what is for sale.
	const AuItem* item = msg->Item();
	if(!item)
		return;
	if(!item->Count())
		return;

	if(item->StoryInstance())
	{
		AuCommCityMessage mymsg(AuCommCityMessage::UnwantedStoryItem, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	QString empireNameOfOrigin = msg->EmpireOfOrigin();
	AuItem* offer = item->Clone();	// So we can mess with the count.

	// Prevent any ships from selling "freeStuff" that is issued to govt ships of my empire.
	bool freeStuff = ship && !ship->IsPrivatelyOwned() &&
		(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal);
	double myprice;
	if(IndustryId() == IID_BaseAirTerminal || (freeStuff && (offer->IsFreeToFriendlyGovShip() || offer->IsPower())))
		myprice = 0;
	else
	{
		quint32 unitPrice = BuyCost(msg->FromId(), *offer);
		myprice = unitPrice * offer->Count();
		//qDebug() << "RxAuction" << Id() << Name() << "count" << offer.Count() << "unitPrice" << unitPrice
			//<< "myprice" << myprice << "account" << AccountBalance();

		// Limit the count to what I can afford.
		if(myprice > BrokerAccountBalance())
		{
			int affordCount = (int)(BrokerAccountBalance() / unitPrice);
			if(affordCount <= 0)
			{
				AuCommCityMessage mymsg(AuCommCityMessage::WeNoAffordThose, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
						Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
				delete offer;
				return;
			}
			offer->SetCount(affordCount);
			myprice = unitPrice * offer->Count();
		}

		if(myprice > 2000000000)
		{
			// Stay within numerical limits.
			double unitPrice = myprice / offer->Count();
			offer->SetCount((int)(2000000000. / unitPrice));
			myprice = unitPrice * offer->Count();
		}
	}

	quint32 canFit;
	if(IndustryId() == IID_BaseAirTerminal)
		canFit = BaseTestFitCommodity(*offer);							// Modify the offer to fit available space.
	else
		canFit = BrokerTestFitCommodity(*offer);							// Modify the offer to fit available space.
	if(canFit)
	{
		// Respond with a Bid on the senders channel.
		if(canFit != offer->Count())
		{
			// Count changed so modify my offer price based on the unit price offered.
			float unitPrice = myprice / offer->Count();
			offer->SetCount(canFit);
			myprice = unitPrice * offer->Count();
		}

		AuCommBid mymsg(*offer, empireNameOfOrigin, myprice,
				msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
	else
	{
		// Tell the seller why.
		AuCommCityMessage mymsg(AuCommCityMessage::WeNoWantThose, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
	delete offer;
}

void DaBd::CommunityCreditAccount(double amount, AuBank::CATEGORY cat)
{
	if(IsMilitary())
		return;
	return BrokerCreditAccount(amount, cat);
}

void DaBd::CommunityDebitAccount(double amount, AuBank::CATEGORY cat)
{
	if(IsMilitary())
		return;
	return BrokerDebitAccount(amount, cat);
}

quint32 DaBd::CommunityTestFitCommodity(const AuItem& offer) const
{
	if(IsMilitary())
		return BaseTestFitCommodity(offer);
	else
		return BrokerTestFitCommodity(offer);
}

quint32 DaBd::BaseTestFitCommodity(const AuItem& offer) const
{
	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return 0;
	AuItem* offerToFit = offer.Clone();
	quint32 totalFit = 0;
	DaAtomList base;
	world->FindBdBase(base);
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		// Bases fill all their buildings because they don't manufacture anything.
		quint32 amtFit = bd->TestFitCommodity(*offerToFit);
		if(!amtFit)
			continue;
		totalFit += amtFit;
		if(totalFit == offer.Count())
			break;
		offerToFit->Consume(amtFit);
	}
	delete offerToFit;
	return totalFit;
}

void DaBd::AgentAddCommodity(AuItem& offer)
{
	quint32 offerCount = offer.Count();
	if(!offerCount)
		return;
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	quint32 totalFit = 0;
	if(IsMilitary())
	{
		DaAtomList base;
		world->FindBdBase(base);
		for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
		{
			DaBd* bd = (DaBd*)*bi;
			// Bases fill all their buildings because they don't manufacture anything.
			quint32 amtFit = bd->TestFitCommodity(offer);
			if(!amtFit)
				continue;
			AuItem* offerThatFit = offer.Clone();
			offerThatFit->SetCount(amtFit);
			bd->AddCommodity(*offerThatFit);
			delete offerThatFit;
			totalFit += amtFit;
			offer.Consume(amtFit);
			if(totalFit == offerCount)
				break;
		}
	}
	else
	{
		m_TradeConnectionsLock.lockForRead();
		for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
		{
			if(!(*ci & CON_Road))
				continue;					// Only care about buildings connected by road.
			DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
			if(!bd)
				continue;
			if(!bd->InCommunityBroker(EmpireId()))
				continue;
			quint32 amtFit = bd->TestFitCommodity(offer);
			if(!amtFit)
				continue;
			AuItem* offerThatFit = offer.Clone();
			offerThatFit->SetCount(amtFit);
			bd->AddCommodity(*offerThatFit);
			delete offerThatFit;
			totalFit += amtFit;
			offer.Consume(amtFit);
			if(totalFit == offerCount)
				break;
		}
		m_TradeConnectionsLock.unlock();
	}
	// It is possible at this point that the total offer amount could not be stored.
}

void DaBd::CommunityAddCommodity(const AuItem& offer)
{
	if(IsMilitary())
		BaseAddCommodity(offer);
	else
		BrokerAddCommodity(offer);
}

void DaBd::BaseAddCommodity(const AuItem& offer)
{
	if(offer.Count() == 0)
		return;
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	AuItem* offerToFit = offer.Clone();
	quint32 totalFit = 0;
	DaAtomList base;
	world->FindBdBase(base);
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		// Bases fill all their buildings because they don't manufacture anything.
		quint32 amtFit = bd->TestFitCommodity(*offerToFit);
		if(!amtFit)
			continue;
		AuItem* offerThatFit = offerToFit->Clone();
		offerThatFit->SetCount(amtFit);
		bd->AddCommodity(*offerThatFit);
		delete offerThatFit;
		totalFit += amtFit;
		if(totalFit == offer.Count())
			break;
		offerToFit->Consume(amtFit);
	}
	delete offerToFit;
	// It is possible at this point that the total offer amount could not be stored.
}

bool DaBd::BrokerFillsMyStorage(COMMODITYID storeCID) const
{
	if(DbCommodity::IsObsolete(storeCID))
		return false;
	switch(IndustryId())
	{
	case IID_AircraftFactory:
	case IID_AirportRadar:
	case IID_AirportRepairShop:
	case IID_AirportTerminal:
	case IID_Apartment:
	case IID_Arena:
	case IID_Broker:
	case IID_Cantina:
	case IID_Capitol:
	case IID_Casino:
	case IID_Church:
	case IID_DesignStudio:
	case IID_FireDepartment:
	case IID_Grocery:
	case IID_Hangar:
	case IID_Hospital:
	case IID_Hotel:
	case IID_MassMedia:
	case IID_Observatory:
	case IID_PoliceAcademy:
	case IID_PoliceDepartment:
	case IID_RetailStore:
	case IID_School:
	case IID_ShipYard:
	case IID_SpacecraftFactory:
	case IID_VehicleFactory:
	case IID_Zoo:
		// Brokers fill storage at these buildings because they never use the storage themselves.
		return true;
	case IID_Armorer:
	case IID_Bakery:
	case IID_Bank:
	case IID_Brewery:
	case IID_Carpenter:
	case IID_ClothingFactory:
	case IID_ComputerFactory:
	case IID_Dairy:
	case IID_Distillery:
	case IID_DrillingRig:
	case IID_ElectronicsFactory:
	case IID_ExplosivesFactory:
	case IID_Farm:
	case IID_GristMill:
	case IID_GunSmith:
	case IID_Jeweler:
	case IID_LoggingCamp:
	case IID_LumberMill:
	case IID_MachineShop:
	case IID_MeatProcessingPlant:
	case IID_Mine:
	case IID_MunitionsFactory:
	case IID_NuclearFuelPlant:
	case IID_Orchard:
	case IID_PaperMill:
	case IID_PharmaceuticalLab:
	case IID_PlasticsFactory:
	case IID_Refinery:
	case IID_RocketMotorFactory:
	case IID_Smelter:
	case IID_SugarMill:
	case IID_TextileMill:
	case IID_TreatmentPlant:
	case IID_Well:
	case IID_Wharf:
	case IID_Winery:
		// Brokers do not fill storage at buildings that manufacture things. That is where they store their output.
		return false;
	case IID_BaseAcademy:
	case IID_BaseAirTerminal:
	case IID_BaseBarracks:
	case IID_BaseDock:
	case IID_BaseFlag:
	case IID_BaseGuardPost:
	case IID_BaseGuardTower:
	case IID_BaseHeadquarters:
	case IID_BaseMarineBarracks:
	case IID_BaseMotorPool:
	case IID_BaseRadar:
	case IID_BaseShield:
	case IID_BaseWeapon:
		// Brokers do not fill military buildings.
		return false;
	case IID_Biodome:
	case IID_Bridge:
	case IID_Count:
	case IID_Fence:
	case IID_SeaPlatform:
	case IID_AerialPlatform:
	case IID_GroundPlatform:
	case IID_House:
	case IID_Landscape:
	case IID_None:
	case IID_Park:
	case IID_Road:
	case IID_Shed:
	case IID_StreetLight:
	case IID_TownSquare:
	case IID_Tunnel:
		// These buildings do not make any storage available to brokers.
		return false;
	case IID_CoalPowerPlant:
	case IID_GasolinePowerPlant:
	case IID_HydroelectricPowerPlant:
	case IID_HydrogenPowerPlant:
	case IID_NaturalGasPowerPlant:
	case IID_NuclearPowerPlant:
	case IID_SolarPowerPlant:
	case IID_WindPowerPlant:
		// Brokers store fuel at power plants.
		return IsFuel(storeCID);
	case IID_StorageTank:
		// Brokers fill storage tanks with liquid materials.
		return DbCommodity::IsStorageLiquid(storeCID);
	case IID_Warehouse:
		// Brokers fill warehouses with non-liquid materials.
		return !DbCommodity::IsStorageLiquid(storeCID);
	}
	qWarning() << "error: DaBd::BrokerFillsMyStorage unhandled industry id" << IndustryId() << IndustryName();
	return false;
}

quint32 DaBd::BrokerTestFitCommodity(const AuItem& offer) const
{
	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return 0;
	AuItem* offerToFit = offer.Clone();
	quint32 totalFit = 0;
	quint32 myEmpireId = EmpireId();
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;					// Only care about buildings connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;
		if(!bd->InCommunityBroker(myEmpireId))
			continue;
		if(!bd->BrokerFillsMyStorage(offerToFit->CommodityId()))
			continue;
		quint32 amtFit = bd->TestFitCommodity(*offerToFit);
		if(!amtFit)
			continue;
		totalFit += amtFit;
		if(totalFit == offer.Count())
			break;
		offerToFit->Consume(amtFit);
	}
	m_TradeConnectionsLock.unlock();
	delete offerToFit;
	return totalFit;
}

void DaBd::BrokerAddCommodity(const AuItem& offer)
{
	if(offer.Count() == 0)
		return;
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	AuItem* offerToFit = offer.Clone();
	quint32 totalFit = 0;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;					// Only care about buildings connected by road.
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;
		if(!bd->InCommunityBroker(EmpireId()))
			continue;
		if(!bd->BrokerFillsMyStorage(offerToFit->CommodityId()))
			continue;
		quint32 amtFit = bd->TestFitCommodity(*offerToFit);
		if(!amtFit)
			continue;
		AuItem* offerThatFit = offerToFit->Clone();
		offerThatFit->SetCount(amtFit);
		bd->AddCommodity(*offerThatFit);
		delete offerThatFit;
		totalFit += amtFit;
		if(totalFit == offer.Count())
			break;
		offerToFit->Consume(amtFit);
	}
	m_TradeConnectionsLock.unlock();
	delete offerToFit;
	// It is possible at this point that the total offer amount could not be stored.
}

// Calculate sell cost of one unit of the item, which is demand cost modified up with a profit margin for this city as the seller.
// The sell cost is always at least 1 higher than the demand cost, which is always
// at least 1. Therefore the sell cost is always at least 2.
quint32 DaBd::SellCost(const AuId& idToWho, const AuItem& item)
{
	if(IsMilitary())
		return 0;

	quint32 sellCost;
	if(item.HitPoints() >= item.NewHitPoints())
	{
		// Like new items are priced uniformly.
		m_PriceOfferLock.lockForWrite();
		QMap<DeInvItemId, AuPriceOffer>::const_iterator poi = PriceOffer(idToWho, item);
		sellCost = (*poi).m_SellPrice;
		m_PriceOfferLock.unlock();
	}
	else
	{
		// Treat damaged items individually.
		// The demand cost is modified by item damage.
		quint32 demandCost = DemandCost(idToWho, item);

		// 20% sell margin sounds good. This could be modified by whoId's trade skill.
		// 10% was not enough after years of being at 10%; it's just too hard to make a profit.
		sellCost = demandCost * 120 / 100;
		if(sellCost == demandCost)
			sellCost++;												// offer to sell at a price higher than the demand cost.
	}
	return sellCost;
}

// Calculate buy cost of one unit of the item, which is demand cost modified down with a profit margin for this city as the buyer.
// The buy cost is always at least 1.
quint32 DaBd::BuyCost(const AuId& idFromWho, const AuItem& item)
{
	if(IsMilitary())
		return 0;

	quint32 buyCost;
	if(item.HitPoints() >= item.NewHitPoints())
	{
		// Like new items are priced uniformly.
		m_PriceOfferLock.lockForWrite();
		QMap<DeInvItemId, AuPriceOffer>::const_iterator poi = PriceOffer(idFromWho, item);
		buyCost = (*poi).m_BuyPrice;
		m_PriceOfferLock.unlock();
	}
	else
	{
		// Treat damaged items individually.
		// The demand cost is modified by item damage.
		quint32 demandCost = DemandCost(idFromWho, item);

		// 20% buy margin sounds good. This could be modified by whoId's trade skill.
		// 10% was not enough after years of being at 10%; it's just too hard to make a profit.
		// Offer to buy at a price no higher than the demand cost.
		buyCost = demandCost * 80 / 100;
		if(buyCost < 1)
			buyCost = 1;											// Offer at least 1.
	}
	return buyCost;
}

QMap<DeInvItemId, AuPriceOffer>::const_iterator DaBd::PriceOffer(const AuId& whoId, const AuItem& item)
{
	// Determine if I have made a recent price offer for the item.
	DeInvItemId itemId(item.CommodityId(), item.Quality(), item.EmpireOfOrigin());
	QMap<DeInvItemId, AuPriceOffer>::iterator pi = m_PriceOffers.find(itemId);
	if(pi != m_PriceOffers.end() && (*pi).m_When.ElapsedMin() < 20)
	{
		(*pi).m_When.restart();									// Refresh the offer time due to Ikkir exploit.
		return pi;												// The offer is still fresh.
	}

	// The demand cost is our local baseline.
	quint32 demandCost = DemandCost(whoId, item);

	// 20% buy margin sounds good. This could be modified by whoId's trade skill.
	// 10% was not enough after years of being at 10%; it's just too hard to make a profit.
	// Offer to buy at a price no higher than the demand cost.
	quint32 buyCost = demandCost * 80 / 100;
	if(buyCost < 1)
		buyCost = 1;											// Offer at least 1.

	// 20% sell margin sounds good. This could be modified by whoId's trade skill.
	// 10% was not enough after years of being at 10%; it's just too hard to make a profit.
	quint32 sellCost = demandCost * 120 / 100;
	if(sellCost == demandCost)
		sellCost++;												// offer to sell at a price higher than the demand cost.

	// Add sales tax to the sell cost.
	float taxRate = EmpireSalesTax();
	if(taxRate > 0)
	{
		quint32 salesTax = (quint32)ceilf(taxRate * sellCost);
		sellCost += salesTax;
	}

	// Remember that we made this price offer.
	return m_PriceOffers.insert(itemId, AuPriceOffer(buyCost, sellCost));
}

// Calculate demand cost based on which context is appropriate.
// The demand cost is the local cost of a commodity, calculated from the quality 
// cost and modified by quality and local demand. The quality cost 'qualCost' is the base
// cost adjusted for quality.
// 'idToWho' is a unit atom. It will be NULL when called by a retail console in town to
// display prices.
quint32 DaBd::DemandCost(const AuId& idToWho, const AuItem& item) const
{
	// Supply and demand effects are calculated within the context of the buyer's
	// location. When in town the prices are quoted based on this city's local 
	// supply and demand, which will be different from city to city. When at a 
	// station in orbit the prices are based on planet wide supply and demand,
	// producing identical prices at all cities on the planet. If neither of those 
	// cases is true, pricing is based on solar system wide supply and demand, 
	// producing the same prices from all cities in the system. This way, a station out
	// near the wormholes can act as a trade hub for the entire system without being
	// abused. Likewise, a station in orbit around a planet acts as a trade hub for
	// that planet. Finally, in town pricing is the most granular, providing opportunity
	// for hungry star traders. Thanks to Shane for this concept. dhh 1/13/2007
	//
	// Three location contexts are relevant: at this planet (within atmosphere), in
	// orbit around this planet, and beyond orbit of this planet.
	//
	// Within those contexts, four states relative to the existence of stations
	// matter: no stations, station orbiting planet but no station elsewhere in system,
	// station orbiting planet and station elsewhere in system, station elsewhere in
	// system but no station orbiting planet
	//
	// These things relate as shown in the following table to determine which pricing
	// context to use.
	//                                   Person      Person      Person
	//                                  At Planet   In Orbit   Beyond Orbit
	// No Stations in System             Town         Town         Town
	// Planet Station, No Other Stations Town        Planet       Planet
	// Planet Station And Other Station  Town        Planet       System
	// Other Station Only                Town         Town        System

	// The id is NULL when a console requests pricing for its publicly visible display.
	// Respond with in town pricing.
	if(idToWho.IsNull())
		return DemandCost(item);			// Town

	// Locate relevant atoms.
	const DaWorld* cityPlanet = FindParentPlanetInEnv();
	if(!cityPlanet)
		return (int)item.UnitCost();	// City not on a planet? Not likely.
	const DaSolarSystem* system = dynamic_cast<const DaSolarSystem*>(cityPlanet->FindEnvironmentAtom());
	if(!system)
		return (int)item.UnitCost();	// City not in a system? Not likely.
	const DaUnit* toWho = dynamic_cast<const DaUnit*>(system->FindIdRecursive(idToWho));
	if(!toWho)
		return (int)item.UnitCost();	// Not a unit in the same system as this city.

	bool anyStation = false;	// true if a friendly station is anywhere in the system.
	bool inOrbit = false;		// true if in orbit around this planet.
	bool onPlanet = false;		// true if within atmosphere of this planet.
	bool planetStation = false;	// true if a friendly station is orbiting this planet.
	bool systemStation = false;	// true if a friendly station is elsewhere in the system

	const DaWorld* whoPlanet = toWho->FindParentPlanetInEnv();
	if(cityPlanet == whoPlanet)
	{
		// Person is near this planet.
		const DaUnit* unit = (const DaUnit*)toWho;
		if(unit->IsInAtmosphere())
			onPlanet = true;	// Inside atmosphere is "on" this planet.
		else
			inOrbit = true;		// At planet but outside atmosphere is "orbiting".
	}

	if(!onPlanet)
	{
		// Person is not on this planet (within the atmosphere anyway).
		// Determine if there are friendly stations anywhere in this system and/or around this planet.
		DaAtomList atoms;
		((DaSolarSystem*)system)->FindVesselsRecursive(atoms);
		for(DaAtomList::const_iterator it = atoms.begin(); it != atoms.end(); it++)
		{
			DaVessel* ss = dynamic_cast<DaVessel*>(*it);
			if(!ss)
				continue;
			if(!ss->IsSpaceStation())
				continue;
			anyStation = true;			// Found a station in this system.
			const DaWorld* stationPlanet = ss->FindParentPlanetInEnv();
			if(stationPlanet == cityPlanet)
				planetStation = true;	// The station is orbiting this planet.
			else
				systemStation = true;	// The station is not orbiting this planet.
		}
	}

	// Based on the table above, calculate the demand cost within the appropriate
	// location context: Town, Planet, or Solar System.
	quint32 demandCost;
	if(onPlanet || !anyStation || (inOrbit && !planetStation))
		demandCost = DemandCost(item);			// Town
	else if(inOrbit || (planetStation && !systemStation))
		demandCost = cityPlanet->DemandCost(item); // Planet
	else
		demandCost = system->DemandCost(item);	// System
	return demandCost;
}

// Cost of one unit of the item when the transaction occurs in this town.
quint32 DaBd::DemandCost(const AuItem& item) const
{
	// Determine local demand for the commodity.
	unsigned int stock = 0;			// Stock of equal or higher quality of idCommodity.
	unsigned int citizens = 0;		// The system wide call picks up my population too.
	unsigned int needCount = 0;		// Count needed by all running processes, both manufacturing and construction.
	unsigned int produceCount = 0;	// Count produced by all running mfg processes.
	const DaWorld* planet = FindParentPlanetInEnv();
	if(planet)
		planet->ProcessDemandTally(Id(), item, stock, citizens, needCount, produceCount);

	// The commodity calculates the demand.
	float demand = item.Demand(citizens, stock, needCount, produceCount);

	// Modify quality cost by demand.
	float cost = item.UnitCost() * demand;

	/*DHH city
	// Situations can increase the cost of certain items.
	if(item.CommodityId() == CID_Antitoxin)
	{
		const AuSitDisease* disease = dynamic_cast<const AuSitDisease*>(LockFindSituation(AuSitDisease::SituationType()));
		if(disease && item.Quality() >= disease->Quality())
			cost *= 2;									// Antitoxin is needed to treat my local epidemic.
		UnlockSituations();
	}
	else if(item.CommodityId() == CID_Antidote)
	{
		const AuSitPoison* poison = dynamic_cast<const AuSitPoison*>(LockFindSituation(AuSitPoison::SituationType()));
		if(poison && item.Quality() >= poison->Quality())
			cost *= 2;									// Antidote is needed to treat my local food poisoning.
		UnlockSituations();
	}
	else if(item.CommodityId() == CID_Pharmaceuticals)
	{
		const AuSitRats* rats = dynamic_cast<const AuSitRats*>(LockFindSituation(AuSitRats::SituationType()));
		if(rats && item.Quality() >= rats->Quality())
			cost *= 2;									// Pharmaceuticals is needed to treat my local rat infestation.
		UnlockSituations();
	}
	*/

	// Round UP.
	cost = ceilf(cost);
	if(cost < 1)
		cost = 1;

	return (int)cost;
}

void DaBd::RxBid(const AuCommBid* msg, DaVessel* ship, const AuId& sectorId, AuCommStdChannel::RANGE range, DaPerson* person,
		POLITICAL_STANCE stanceToSender, bool hasTransporter, bool inTransporterRange)
{
	if(!msg)
		return;
	if(!ship)
		return;
	// Brokers support company and fleet ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
	case IID_Broker:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	// City in trade range will attempt to accept the bid.
	if(!g_Au.HasPendingBid(msg))
		return;

	// Insure the buyer is physically located where the transaction can be performed.
	// - In a spaceship, and
	//    - On a road slab that belongs to this city, or
	//    - Near a friendly station in this solar system.
	// - Not in a spaceship, and
	//    - In a building that sells the item.
	if(!ship->InChainOfCommand(person))
	{
		AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToBuy, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Person is not an officer of the ship.
	}

	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore bid if the buyer is too far away to accept the transaction.
	if(msg->Item()->IsPower())
	{
		if(!inCity)
		{
			// Tell the buyer to move to town.
			AuCommCityMessage::MESSAGE msgId;
			msgId = AuCommCityMessage::MoveBdToBuyPower;
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
					msg->Scope());
			g_Au.SendAtomChat(mymsg);
			return;
		}
	}
	else
	{
		if(!inCity && !nearStation && !inTransporterRange)
		{
			// Tell the buyer to move closer.
			AuCommCityMessage::MESSAGE msgId;
			if(hasTransporter)
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdTransporterStationToBuy;
				else
					msgId = AuCommCityMessage::MoveBdTransporterToBuy;
			}
			else
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdStationToBuy;
				else
					msgId = AuCommCityMessage::MoveBdToBuy;
			}
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
					msg->Scope());
			g_Au.SendAtomChat(mymsg);
			return;
		}
	}

	const AuItem* item = msg->Item();		// The item I offered for sale.
	if(!item)
		return;
	quint32 offerprice = msg->Price();
	QString empireNameOfOrigin = msg->EmpireOfOrigin();

	// Locate the item for sale.
	AuItemHash inventory;
	if(IndustryId() == IID_BaseAirTerminal)
		BaseInventoryAvailable(inventory, ship->EmpireId());
	else
		BrokerInventoryAvailable(inventory, ship->EmpireId());
	AuItemHash::iterator itemI = inventory.Find(*item);
	if(itemI == inventory.end())
	{
		// The item is no longer in stock.
		// Tell the buyer why.
		QString text = tr("We are out of stock on %1.")
			.arg(item->ListDesc(empireNameOfOrigin));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}
	else if((*itemI).second->Count() < item->Count())
	{
		// We no longer have that many in stock.
		// Tell the buyer why.
		QString text = tr("We only have %1 in stock.")
			.arg((*itemI).second->ListDesc(empireNameOfOrigin));

		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Check my selling price.
	bool freeStuff = !ship->IsPrivatelyOwned() &&
		(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal);
	double myprice;
	if(IndustryId() == IID_BaseAirTerminal || (freeStuff && item->IsFreeToFriendlyGovShip()))
		myprice = 0;
	else
		myprice = SellCost(msg->FromId(), *item) * item->Count();
	if(offerprice < myprice)
	{
		// Tell the buyer why.
		QString text = tr("Your offer of %1 is too low. I won't accept less than %2 for %3.")
			.arg(AuGlobal::FormatMoney(offerprice))
			.arg(AuGlobal::FormatMoney(myprice))
			.arg(item->ListDesc(empireNameOfOrigin));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Ignore the offer; it's too low.
	}

	// Insure the buyer can afford the cost.
	double fAccountBalance = ship->AccountBalance();
	if(offerprice > fAccountBalance)
	{
		// Tell the buyer why.
		QString text(tr("You don't have %1.").arg(AuGlobal::FormatMoney(offerprice)));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Ignore the offer; insufficient funds.
	}
	
	// Insure the buyer can store the merchandise.
	AuItem* iNew = item->Clone();	// So we can mess with the count.
	if(!ship->CanAddCargo(*iNew))
	{
		// Person is aboard a ship but the nu cargo won't fit in the hold.
		// Tell the buyer they don't have room.
		QString text;
		if(iNew->CommodityId() == CID_Hydrogen)
			text = tr("The fuel cells in your spacecraft have insufficient space to add %L1 units").arg(iNew->Count());
		else if(iNew->CommodityId() == CID_Electricity)
			text = tr("The capacitor in your spacecraft has insufficient storage to add %L1 units").arg(iNew->Count());
		else
			text = tr("The hold in your spacecraft has insufficient space to add %L1 units").arg(iNew->Count());
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		delete iNew;
		return;	// Ignore the offer; no space to store the stuff.
	}

	// Perform the transaction.
	// Player Statistics
	person->Stats().ItemBoughtAsCargo(*iNew);
	person->IncreaseSkill(AuSkill::Trade, 1);

	ship->DebitAccount(offerprice);					// Take the money from the ship.
	BrokerCreditAccount(offerprice, AuBank::Civ_CreditSales);

	ship->AddCargo(*iNew);	// Hydrogen gets put into fuel cells.
	CommunityRemoveInventory(*iNew);

	// Revoke the bid so it can't be accepted again.
	g_Au.BidRevoked(msg->FromId(), msg->ChannelName());

	// Send an Accept message so the person knows the deal is done. The count may have changed from the bid when not
	// all of the items fit in the buyer's inventory.
	AuCommAccept mymsg(msg->FromId(), msg->FromName(), *iNew, empireNameOfOrigin, offerprice,
			msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
	delete iNew;
	// Transaction is completed.
}

bool DaBd::CanAccessByGround(const DaVessel* ship) const
{
	if(!ship->IsOnGround())
		return false;					// Ship is not on the ground.
	if(ship->BdId().IsNull())
		return false;					// Ship is not at a bd building site or geo road.
	if(ship->InCityEmpire() != EmpireId())
		return false;					// Ship is on a building site or road location that is not in my empire.
	// When the BdId is the world, the ship is on a geo road or slab.
	if(!HasTradeConnectionByGround(ship->BdId()) && !FindParentPlanetInEnv()->Is(ship->BdId()))
		return false;					// Building site is not connected to me by ground.
	return true;
}

void DaBd::RxBidBarter(const AuCommBidBarter* msg, DaVessel* ship, const AuId& sectorId, AuCommStdChannel::RANGE range,
		DaPerson* person, bool hasTransporter, bool inTransporterRange, POLITICAL_STANCE stanceToSender)
{
	if(!msg)
		return;
	if(!ship)
		return;
	// Brokers support company and fleet ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
	case IID_Broker:
		break;
	case IID_BaseAirTerminal:
		return;	// Base air terminals do not barter.
	default:
		return;
	}

	// City in trade range will attempt to accept the bid.
	if(!g_Au.HasPendingBidBarter(msg))
		return;

	// Insure the buyer is physically located where the transaction can be performed.
	// - In a spaceship, and
	//    - On a road slab that belongs to this city, or
	//    - Near a friendly station in this solar system.
	// - Not in a spaceship, and
	//    - In a building that sells the item.
	// Person is aboard a spacecraft.
	if(!ship->InChainOfCommand(person))
	{
		AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToBuy, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Person is not an officer of the ship.
	}

	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore bid if the buyer is too far away to accept the transaction.
	if(msg->Item()->IsPower() || msg->OfferItem()->IsPower())
	{
		if(!inCity)
		{
			// Tell the buyer to move to town.
			AuCommCityMessage::MESSAGE msgId;
			msgId = AuCommCityMessage::MoveBdToBuyPower;
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
					msg->Scope());
			g_Au.SendAtomChat(mymsg);
			return;
		}
	}
	else
	{
		if(!inCity && !nearStation && !inTransporterRange)
		{
			// Tell the buyer to move closer.
			AuCommCityMessage::MESSAGE msgId;
			if(hasTransporter)
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdTransporterStationToBuy;
				else
					msgId = AuCommCityMessage::MoveBdTransporterToBuy;
			}
			else
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdStationToBuy;
				else
					msgId = AuCommCityMessage::MoveBdToBuy;
			}
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
					msg->Scope());
			g_Au.SendAtomChat(mymsg);
			return;
		}
	}

	// Extract barter offer info.
	const AuItem* item = msg->Item();							// The item I offered for sale.
	if(!item)
		return;
	const AuItem* offerItem = msg->OfferItem();					// The item offered in trade by a buyer.
	if(!offerItem)
		return;
	QString offerEmpireNameOfOrigin = msg->OfferEmpireOfOrigin();
	double offerprice = offerItem->TotalCost();
	QString empireNameOfOrigin = msg->EmpireOfOrigin();

	// Locate the item for sale.
	AuItemHash inventory;
	BrokerInventoryAvailable(inventory, ship->EmpireId());
	AuItemHash::iterator itemI = inventory.Find(*item);
	if(itemI == inventory.end())
	{
		// The item is no longer in stock.
		// Tell the buyer why.
		QString text = tr("We are out of stock on %1.")
			.arg(item->ListDesc(empireNameOfOrigin));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}
	else if((*itemI).second->Count() < item->Count())
	{
		// We no longer have that many in stock.
		// Tell the buyer why.
		QString text = tr("We only have %1 in stock.")
			.arg((*itemI).second->ListDesc(empireNameOfOrigin));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Check my selling price.
	bool freeStuff = !ship->IsPrivatelyOwned() &&
		(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal);
	double myprice;
	if(IndustryId() == IID_BaseAirTerminal || (freeStuff && item->IsFreeToFriendlyGovShip()))
		myprice = 0;
	else
		myprice = SellCost(msg->FromId(), *item) * item->Count();
	if(offerprice < myprice)
	{
		// Tell the buyer why.
		QString text = tr("Your offer is not valuable enough. I won't accept less than %1 for %2.")
			.arg(AuGlobal::FormatMoney(myprice))
			.arg(item->ListDesc(empireNameOfOrigin));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Ignore the offer; it's too low.
	}

	// Insure the buyer has the item they offered.
	const AuItemHash& sinv = ship->LockCargoForRead();
	AuItemHash::const_iterator offerItemI = sinv.Find(*offerItem);
	if(offerItemI == sinv.end())
	{
		// The item is no longer in the hold.
		ship->UnlockCargo();

		// Tell the buyer why.
		QString text = tr("Your hold does not contain %1.")
			.arg(offerItem->ListDesc(offerEmpireNameOfOrigin));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}
	else if((*offerItemI).second->Count() < offerItem->Count())
	{
		// The hold no longer contains that many.
		ship->UnlockCargo();

		// Tell the buyer why.
		QString text = tr("Your hold only contains %1.")
			.arg(offerItem->ListDesc(offerEmpireNameOfOrigin));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}
	ship->UnlockCargo();

	quint32 canFit = BrokerTestFitCommodity(*offerItem);
	if(canFit == 0)
	{
		// City inventory doesn't have room for their offer.
		AuCommCityMessage mymsg(AuCommCityMessage::WeNoWantThose, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Ignore the offer; no room to store the offer in town or it's obsolete.
	}
	else if(canFit < offerItem->Count())
	{
		// City inventory doesn't have room for their entire offer.
		AuCommCityMessage mymsg(AuCommCityMessage::WeNoWantAllOfThose, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Ignore the offer; no room to store the offer in town or it's obsolete.
	}

	// Insure the buyer can store the merchandise.
	AuItem* iNew = item->Clone();	// So we can mess with the count.
	if(!ship->CanAddCargo(*iNew))
	{
		// Person is aboard a ship but the nu cargo won't fit in the hold.
		// Tell the buyer they don't have room.
		QString text;
		if(iNew->CommodityId() == CID_Hydrogen)
			text = tr("The fuel cells in your spacecraft have insufficient space to add %L1 units").arg(iNew->Count());
		else if(iNew->CommodityId() == CID_Electricity)
			text = tr("The capacitor in your spacecraft has insufficient storage to add %L1 units").arg(iNew->Count());
		else
			text = tr("The hold in your spacecraft has insufficient space to add %L1 units").arg(iNew->Count());
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		delete iNew;
		return;	// Ignore the offer; no room to store the stuff on their ship.
	}

	// Perform the transaction.
	// Player Statistics
	person->Stats().ItemBoughtAsCargo(*iNew);
	person->IncreaseSkill(AuSkill::Trade, 1);

	// Take the offer item from the ship.
	ship->RemoveCargo(*offerItem, offerItem->Count());

	// Add the offer item to my inventory.
	BrokerAddCommodity(*offerItem);

	ship->AddCargo(*iNew);	// Hydrogen gets put into fuel cells.
	BrokerRemoveInventory(*iNew);

	// Revoke the bid so it can't be accepted again.
	g_Au.BidRevoked(msg->FromId(), msg->ChannelName());

	// Send an Accept message so the person knows the deal is done. The count may have changed from the bid when not
	// all of the items fit in the buyer's inventory.
	AuCommAcceptBarter mymsg(msg->FromId(), msg->FromName(), *iNew, empireNameOfOrigin, *offerItem, offerEmpireNameOfOrigin,
			msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
	delete iNew;
	// Transaction is completed.
}

void DaBd::RxForSale(const AuCommForSale* msg, DaVessel* ship, const AuId& sectorId, AuCommStdChannel::RANGE range,
		POLITICAL_STANCE stanceToSender, DaPerson* person)
{
	if(!msg)
		return;
	switch(IndustryId())
	{
	case IID_Broker:
		// Brokers support company and fleet ships.
		if(!ship)
			return;
		break;
	case IID_BaseAirTerminal:
		// Military air terminals only communicate with fleet spacecraft.
		if(!ship)
			return;
		if(ship->IsPrivatelyOwned())
			return;
		break;
	case IID_AirportTerminal:
		// Airport terminals support company and fleet ships.
		if(!ship)
			return;
		break;
	default:
		// Other buildings will communicate with a person who is at this building.
		if(!person || !Is(person->BdId()))
			return;
		break;
	}

	// Determine what is for sale.
	const AuItem* item = msg->Item();
	if(!item)
		return;
	if(!item->Count())
		return;

	if(item->StoryInstance())
	{
		AuCommCityMessage mymsg(AuCommCityMessage::UnwantedStoryItem, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	QString empireNameOfOrigin = msg->EmpireOfOrigin();
	AuItem* offer = item->Clone();	// So we can mess with the count.
	quint32 price = msg->Price();
	double totalForSalePrice = price * offer->Count();					// Price at which the commodities are offered for sale.

	// Prevent any ships from selling "freeStuff" that is issued to govt ships of my empire.
	bool freeStuff = ship && !ship->IsPrivatelyOwned() &&
		(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal);
	double myprice;
	if(IndustryId() == IID_BaseAirTerminal || (freeStuff && (offer->IsFreeToFriendlyGovShip() || offer->IsPower())))
		myprice = 0;
	else
	{
		quint32 unitPrice = BuyCost(msg->FromId(), *offer);
		if(unitPrice > price)
			unitPrice = price;									// Limit my price to what they are asking.
		myprice = unitPrice * offer->Count();

		// Limit the count to what I can afford.
		if(myprice > BrokerAccountBalance())
		{
			int affordCount = (int)(BrokerAccountBalance() / unitPrice);
			if(affordCount <= 0)
			{
				AuCommCityMessage mymsg(AuCommCityMessage::WeNoAffordThose, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
						Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
				delete offer;
				return;
			}
			offer->SetCount(affordCount);
			myprice = unitPrice * offer->Count();
		}

		if(myprice > 2000000000)
		{
			// Stay within numerical limits.
			double unitPrice = myprice / offer->Count();
			offer->SetCount((int)(2000000000. / unitPrice));
			myprice = unitPrice * offer->Count();
		}
	}
	if(myprice < totalForSalePrice)
	{
		// Tell the seller why.
		AuCommCityMessage mymsg(AuCommCityMessage::PriceTooHigh, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		delete offer;
		return;													// Ignore; the price is too high.
	}

	quint32 canFit;
	if(IndustryId() == IID_BaseAirTerminal)
		canFit = BaseTestFitCommodity(*offer);				// Modify the offer to fit available space.
	else
		canFit = BrokerTestFitCommodity(*offer);				// Modify the offer to fit available space.
	if(canFit)
	{
		// Respond with a Bid on the senders channel.
		if(canFit != offer->Count())
		{
			// Count changed so modify the sale price based on the unit price offered.
			float unitPrice = totalForSalePrice / offer->Count();
			offer->SetCount(canFit);
			totalForSalePrice = unitPrice * offer->Count();
		}

		AuCommBid mymsg(*offer, empireNameOfOrigin, totalForSalePrice,
				msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
	else
	{
		// Tell the seller why.
		AuCommCityMessage mymsg(AuCommCityMessage::WeNoWantThose, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
	delete offer;
}

double DaBd::BrokerAccountBalance() const
{
	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return 0;
	double brokerAcct = 0;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;					// Only care about buildings connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;
		if(!bd->InCommunityBroker(EmpireId()))
			continue;
		// Tally funds of every kind of building, including banks.
		brokerAcct += bd->AccountBalance();
	}
	m_TradeConnectionsLock.unlock();
	return brokerAcct;
}

void DaBd::BrokerCreditAccount(double amount, AuBank::CATEGORY cat)
{
	if(amount <= 0)
		return;
	if(!CapitolId().IsNull())
	{
		// Put the money in a bank if there is one. That requires a city.
		DaWorld* world = FindParentPlanetInEnv();
		if(!world)
			return;
		m_TradeConnectionsLock.lockForRead();
		for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
		{
			if(!(*ci & CON_Road))
				continue;				// Only care about buildings connected by road.
			DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
			if(!bd)
				continue;
			if(bd->IndustryId() != IID_Bank)
				continue;
			if(!bd->InCommunityBroker(EmpireId()))
				continue;
			bd->CreditAccount(amount, cat);	// Credit bank account.
			m_TradeConnectionsLock.unlock();
			return;
		}
		m_TradeConnectionsLock.unlock();
	}
	// No bank so I am the banker.
	CreditAccount(amount, AuBank::Civ_CreditSales);
}

void DaBd::BrokerDebitAccount(double amount, AuBank::CATEGORY cat)
{
	if(amount <= 0)
		return;
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;					// Only care about buildings connected by road.
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;
		if(!bd->InCommunityBroker(EmpireId()))
			continue;

		// How much money does the building have?
		double bdacct = bd->AccountBalance();
		if(bdacct <= 0)
			continue;

		// Is it more than the amount left to take?
		if(bdacct >= amount)
		{
			bdacct = amount;
			amount = 0;			// Reduce the amount remaining to take.
		}
		else
			amount -= bdacct;	// Reduce the amount remaining to take.

		// Take money from the building.
		bd->DebitAccount(bdacct, cat);
		if(amount <= 0)
			break;
	}
	m_TradeConnectionsLock.unlock();
}

void DaBd::SolicitSales(DaPerson* person, DaVessel* ship, COMMODITYFILTER filter, COMMODITYID cid, const AuCommPacket& msg,
		const AuId& sectorId, POLITICAL_STANCE stanceToSender)
{
	if(!ship)
		return;
	// Brokers support company and fleet ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
	case IID_Broker:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	// Person is in a spacecraft. Are they authorized to trade cargo.
	if(!ship->InChainOfCommand(person))
		return;

	// Person is authorized to trade cargo.
	bool freeStuff = !ship->IsPrivatelyOwned() &&
		(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal);
	TxForSaleChat(msg, sectorId, filter, freeStuff, person->EmpireId(), cid);
}

// 'freeStuff' is true to offer certain items for free, such as fuel. This is for friendly subsidized vessels.
// 'cid' is optional, used when inquiring about a specific commodity
void DaBd::TxForSaleChat(const AuCommPacket& msg, const AuId& sectorId, COMMODITYFILTER filter, bool freeStuff,
		quint32 senderEmpire, COMMODITYID cid)
{
	const DaWorld* planet = FindParentPlanetInEnv();
	if(!planet)
		return;
	const bool planetCanHaveFauna = planet->CanHaveFauna();
	const bool planetCanHaveFlora = planet->CanHaveFlora();

	// Get a list of the commodities that fit into the current filter.
	QList<COMMODITYID> cidFilter;
	if(cid != CID_Invalid)
		cidFilter.append(cid);											// Caller wants a specific commodity.
	else
		g_Au.m_CommodityArray.ListFilterCommodities(cidFilter, filter);	// Caller wants a category of commodities.

	AuItemHash inventory;
	BrokerInventoryAvailable(inventory, senderEmpire);

	// Send the best of each commodity as a For Sale message.
	// We'll accumulate an alphabetically sorted list so they look nice on the clients screen.
	INDUSTRYID myIndustry = IndustryId();
	QString cname;				// only set when cid != CID_Invalid and we find one
	QMultiMap<QString, SellOffer> offers;	// List of offers sorted alphabetically.
	for(AuItemHash::const_iterator it = inventory.begin(); it != inventory.end(); it++)
	{
		if(!(*it).second->Count())
			continue;	// None in stock.
		if(!(*it).second->CanBeCarried() && !(*it).second->IsPower())
			continue;	// Skip BIG things, like airplanes and tanks.

		// Determine if the item is available based on commodity filter.
		if(!cidFilter.contains((*it).second->CommodityId()))
			continue;

		// Prepare a sell offer.
		SellOffer offer(*(*it).second);

		// Limit export of essential supplies in harsh environments.
		quint32 minStock;										// Minimum stock that the exporter wants to hold.
		if((*it).second->CommodityId() == CID_Air || (*it).second->CommodityId() == CID_Water)
		{
			// Air and water, because water can be used to make air at a refinery.
			if(!planetCanHaveFauna)
				minStock = Population()*13;						// Keep enough air for one city report cycle.
			else
				minStock = 0;									// Planet has abundant air.
		}
		else if((*it).second->IsFood() && (*it).second->FoodNutritionValue())
		{
			// Food with real food nutrition value, i.e. not "diet".
			if(!planetCanHaveFlora)
				minStock = Population()*10;						// Planet cannot produce food easily.
			else
				minStock = Population();						// Don't starve the city even in good conditions.
		}
		else
			minStock = 0;
		if(offer.m_Item->Count() > minStock)
			offer.m_Item->SetCount(offer.m_Item->Count() - minStock);
		else
			continue;

		QString name = (*it).second->ListName();
		if(myIndustry == IID_BaseAirTerminal || (freeStuff && (*it).second->IsFreeToFriendlyGovShip()))
			offer.m_Price = 0;
		else
			offer.m_Price = SellCost(msg.FromId(), *(*it).second);

		// Remember commodity name for message text later.
		if(cid != CID_Invalid)
			cname = name;
		else
		{
			// The caller wants the best one of each commodity.
			QMultiMap<QString, SellOffer>::iterator offerI = offers.find(name);
			if(offerI != offers.end())
			{
				// The commodity has already been added to our offer list. Is this one better?
				if(offer.IsBetterProduct(*offerI))
					*offerI = offer;	// Update the product offered in our list to the best available.
				continue;
			}
		}

		// Insert the sell offer into our list in alphabetical order.
		offers.insert(name, offer);
	}

	// Cities normally respond at the same range the message was sent.
	// Cities do not respond beyond solar system range.
	AuCommStdChannel::RANGE range = msg.ReceptionRange();
	if(range > AuCommStdChannel::SolarSystem)
		range = AuCommStdChannel::SolarSystem;

	if(offers.isEmpty())
	{
		// We had nothing to offer them. At least give them a response.
		if(!AuCommStdChannel::IsTradeChannel(msg.ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NothingToSell, msg.ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg.Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Lock atom chat queue mutex so we can access both the open channels queue and the chat messages queue simultaneously.
	AuAtomChatList* chatqueue = g_Au.LockAtomChat();

	// Open a channel to the seller so my output, which could be considerable, will not be mixed with other messages.
	QString channame;
	if(msg.ChannelName() == AuCommStdChannel::TradeChannelName())
	{
		channame = QString("%1 %2-%3").arg(CityBuildingName()).arg(Id().StringId()).arg(msg.FromId().StringId());

		// Notify the person on the current channel that we have
		// sent a response on a different channel.
		AuCommCityMessage mymsg(AuCommCityMessage::ItemsOnPrivateChannel, msg.ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg.Scope());
		chatqueue->append(AuAtomChat(mymsg));
	}
	else
		channame = msg.ChannelName();
	g_Au.m_OpenChannels.append(AuOpenChannel(channame, AuCommStdChannel::Everyone, Id(), CityBuildingName(), sectorId,
				Galaxy(), msg.FromId(), false));

	// Construct a chat message to send on the nu channel.
	QString text;
	if(cid != CID_Invalid)
		text = tr("%1 for sale.").arg(cname);
	else
		text = QString(tr("For sale. Inquire about a specific item to see more choices."));
	AuCommCityChat mymsg(text, channame, Id(), CityBuildingName(), sectorId, Galaxy(), range,
			AuCommStdChannel::Everyone);
	chatqueue->append(AuAtomChat(mymsg));

	// Now transmit the sorted list of offers as ForSale messages.
	for(QMultiMap<QString, SellOffer>::const_iterator it = offers.cbegin(); it != offers.cend(); it++)
	{
		// Format the ForSale message text.
		AuCommForSale mymsg(*(*it).m_Item, (*it).m_EmpireOfOrigin, (*it).m_Price,
				channame, Id(), CityBuildingName(), sectorId, Galaxy(), range, AuCommStdChannel::Everyone);
		chatqueue->append(AuAtomChat(mymsg));
	}
	g_Au.UnlockAtomChat();
}

void DaBd::RxRequestRefit(const AuCommRequestRefit* msg, DaVessel* ship, const AuId& sectorId, AuCommStdChannel::RANGE range,
		DaPerson* person, POLITICAL_STANCE stanceToSender)
{
	if(!msg)
		return;
	if(!ship || !ship->Is(msg->ShipId()))
		return;
	// Airports support company and military ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;

	if(!ship->InChainOfCommand(person))
	{
		// The message sender is not an officer of the ship.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToRefit, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	if(ship->RepairSecondsRemaining())
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoRefitShipGettingRepairs, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;	// Ignore; ship is already getting repairs.
	}

	// Find quality of highest available repair shop.
	if(!CommunityHasRepairShop())
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShop, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Ignore the request if my empire restricts export of repairs to the ship's empire.
	quint32 empireId = EmpireId();
	const DgData& gd = g_Au.LockDataForRead();
	bool isRestricted = gd.EmpireCommerceRestricted(empireId, CID_Sunlight, stanceToSender);	// CID_Sunlight = Repairs
	g_Au.UnlockData();
	if(isRestricted)
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::RepairProhibited, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Estimate the time, cost and TL to perform the refit.
	double estCost;
	quint32 estSeconds;
	quint8 estQ = msg->Refit().m_MinQ;
	AuRefitMaterials estMat;
	int result = ship->EstimateRefit(msg->Refit(), estCost, estSeconds, estMat);	// estCost is only the labor.
	if(result == 3)
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::RefitNoChange, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Insure we have the required materials.
	AuItemHash inventory;
	BrokerInventoryAvailable(inventory, ship->EmpireId());

	// Add the cost of those materials to the labor estimate.
	bool hadEnough = true;
	for(QHash<COMMODITYID, quint32>::const_iterator mi = estMat.m_Materials.cbegin(); mi != estMat.m_Materials.cend(); mi++)
	{
		quint32 count = inventory.RawCount(mi.key(), estQ);
		if(count)
		{
			// We have some of them. Add the price based on the best of them.
			AuItemHash::const_iterator bi = inventory.FindBest(mi.key());
			if(bi != inventory.cend())
				estCost += SellCost(msg->FromId(), *(*bi).second) * *mi;
		}
		if(count < *mi)
		{
			QString text;
			if(count)
			{
				if(estQ)
					text = tr("We do not have enough Q%4 %1 in stock to refit your ship. "
							"%L2 units are needed but we have only %L3 that will work.")
						.arg(g_Au.CommodityName(mi.key()))
						.arg(*mi)
						.arg(count)
						.arg(estQ);
				else
					text = tr("We do not have enough %1 in stock to refit your ship. "
							"%L2 units are needed but we have only %L3 that will work.")
						.arg(g_Au.CommodityName(mi.key()))
						.arg(*mi)
						.arg(count);
			}
			else
			{
				if(estQ)
					text = tr("We do not have enough Q%4 %1 in stock to refit your ship. "
							"%L2 units are needed but we do not have any that will work.")
						.arg(g_Au.CommodityName(mi.key()))
						.arg(*mi)
						.arg(estQ);
				else
					text = tr("We do not have enough %1 in stock to refit your ship. "
							"%L2 units are needed but we do not have any that will work.")
						.arg(g_Au.CommodityName(mi.key()))
						.arg(*mi);
			}
			AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
					range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
			hadEnough = false;
		}
	}
	if(!hadEnough)
		return;

	if(result == 1)
	{
		bool freeStuff = IndustryId() == IID_BaseAirTerminal || (!ship->IsPrivatelyOwned() &&
			(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal));
		if(freeStuff)
			estCost = 0;

		// Split repair time between workers at shops.
		quint16 workers = 0;
		if(estSeconds)
		{
			quint32 workersWanted = (estSeconds + 9) / 10;
			workers = CommunityRepairShopWorkers((quint16)workersWanted);
		}
		else
			workers = 0;
		if(!workers)
		{
			if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
			{
				AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShopWorkers, msg->ChannelName(), Id(), CityBuildingName(),
						sectorId, Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
			}
		}
		else
		{
			AuCommOfferRefit mymsg(ship->Id(), msg->Refit(), estCost, estSeconds, estMat, workers, msg->ChannelName(), Id(),
					CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
	}
	else if(result == 2)
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::InvalidRefit, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
	}
	else
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::CannotRefit, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
	}
}

void DaBd::RxAcceptRefit(const AuCommAcceptRefit* msg, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, POLITICAL_STANCE stanceToSender)
{
	if(!msg)
		return;
	if(!ship || !ship->Is(msg->ShipId()))
		return;
	// Airports support company and military ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;

	if(!Is(msg->CityId()))
		return;							// I am not the building who offered the refit.

	if(!ship->InChainOfCommand(person))
		return;

	if(ship->RepairSecondsRemaining())
	{
		AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShipGettingRepairs, msg->ChannelName(), Id(), CityBuildingName(),
				sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Ignore; ship is already getting repairs.
	}

	// Validate the transaction based on the buyer.
	// Insure physical locations permit acceptance of the offer.
	// - Ship must be on a road slab that belongs to the city, or
	// - Ship must be near a friendly station in this solar system.
	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore AcceptRefit if the ship is too far away.
	if(!inCity && !nearStation)
	{
		AuCommCityMessage::MESSAGE msgId;
		if(hasStation)
			msgId = AuCommCityMessage::MoveBdStationToRepair;
		else
			msgId = AuCommCityMessage::MoveBdToRepair;
		AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), msg->FromSectorId(), msg->FromGalaxy(),
				msg->ReceptionRange(), msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Verify ship is motionless with key systems off for repairs.
	AuCommCityMessage::MESSAGE msgId = AuCommCityMessage::MessageCount;
	if(ship->IsMoving())
		msgId = AuCommCityMessage::NoRepairMoving;
	else if(ship->SensorsWorking())
		msgId = AuCommCityMessage::NoRepairSensors;
	else if(ship->ShieldsWorkingAndOn())
		msgId = AuCommCityMessage::NoRepairShields;
	else if(ship->IsAnyFTLDriveWorking())
		msgId = AuCommCityMessage::NoRepairFTL;
	else if(ship->GravityDriveWorking())
		msgId = AuCommCityMessage::NoRepairManeuver;
	else if(ship->PowerPlantWorking())
		msgId = AuCommCityMessage::NoRepairPowerPlant;
	if(msgId != AuCommCityMessage::MessageCount)
	{
		AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), msg->FromSectorId(), msg->FromGalaxy(),
				msg->ReceptionRange(), msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Estimate the materials. Time, cost and Q are taken from the message.
	double estCost;
	quint32 estSeconds;
	quint8 estQ = msg->Refit().m_MinQ;
	AuRefitMaterials estMat;
	int result = ship->EstimateRefit(msg->Refit(), estCost, estSeconds, estMat);
	if(result != 1)
		return;

	bool freeStuff = IndustryId() == IID_BaseAirTerminal || (!ship->IsPrivatelyOwned() &&
		(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal));
	if(freeStuff)
		estCost = 0;

	if(ship->AccountBalance() < msg->EstCost())
	{
		QString text(tr("Your ship's fund does not have %1 to pay for the refit.").arg(AuGlobal::FormatMoney(msg->EstCost())));
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Insure we still have the required materials.
	bool hadEnough = true;
	AuItemHash inv;
	BrokerInventoryAvailable(inv, ship->EmpireId());
	for(QHash<COMMODITYID, quint32>::const_iterator mi = estMat.m_Materials.cbegin(); mi != estMat.m_Materials.cend(); mi++)
	{
		quint32 count = inv.RawCount(mi.key(), estQ);
		if(count < *mi)
		{
			QString text;
			if(estQ)
				text = tr("We no longer have enough Q%4 %1 in stock to refit your ship. "
						"%L2 units are needed but we have only %L3 that will work.")
					.arg(g_Au.CommodityName(mi.key()))
					.arg(*mi)
					.arg(count)
					.arg(estQ);
			else
				text = tr("We no longer have enough %1 in stock to refit your ship. "
						"%L2 units are needed but we have only %L3 that will work.")
					.arg(g_Au.CommodityName(mi.key()))
					.arg(*mi)
					.arg(count);
			AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
					range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
			hadEnough = false;
		}
	}
	if(!hadEnough)
		return;

	// Take the materials. If they aren't there this time around, oh well.
	for(QHash<COMMODITYID, quint32>::const_iterator mi = estMat.m_Materials.cbegin(); mi != estMat.m_Materials.cend(); mi++)
		BrokerRawRemove(mi.key(), estQ, *mi);

	// Take the money from the ship's account.
	ship->DebitAccount(msg->EstCost());								// Take the money from the ship.
	BrokerCreditAccount(msg->EstCost(), AuBank::Civ_CreditSales);

	// Refit the ship.
	ship->Refit(msg->Refit(), msg->EstSeconds());

	// Player Statistics
	person->Stats().SpacecraftRepairsBought(ship);
	person->IncreaseSkill(AuSkill::Command, 1);

	// Notify the person that the work is begun.
	QString text = tr("Spacecraft refit started. %1 will remain moored in dry dock until the refit is complete.").arg(ship->Name());
	AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
}

void DaBd::RxRequestRepairAll(const AuCommRequestRepairAll* msg, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, POLITICAL_STANCE stanceToSender)
{
	if(!msg)
		return;
	if(!ship)
		return;
	// Airports support company and military ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	if(!ship->InChainOfCommand(person))
	{
		// The message sender is not an officer of the ship.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToRepair, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	if(ship->RepairSecondsRemaining())
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShipGettingRepairs, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;	// Ignore; ship is already getting repairs.
	}

	// Find quality of highest available repair shop.
	if(!CommunityHasRepairShop())
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShop, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Ignore the request if my empire restricts export of repairs to the ship's empire.
	quint32 empireId = EmpireId();
	const DgData& gd = g_Au.LockDataForRead();
	bool isRestricted = gd.EmpireCommerceRestricted(empireId, CID_Sunlight, stanceToSender);	// CID_Sunlight = Repairs
	g_Au.UnlockData();
	if(isRestricted)
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::RepairProhibited, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	quint8 repairQ = msg->MinQ();

	// Determine what is needed to repair all the systems of the ship.
	QList<COMMODITYID> noQ, shortQ, noSupply, enough;			// parts that cannot be completely repaired
	quint16 repairSecs = 0;
	quint16 workers = 0;
	EstimateRepairCost(ship, noQ, shortQ, noSupply, enough, repairSecs, repairQ, workers);	// Estimate tells availability of parts.
	unsigned int repairCost = EstimateRepairCostPossible(ship, repairSecs, repairQ);		// Estimate counts all usable parts.
	if(!workers)
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShopWorkers, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
	}
	else if(repairCost)
	{
		// Subsidized spacecraft of friends get free repairs.
		bool freeStuff = IndustryId() == IID_BaseAirTerminal || (!ship->IsPrivatelyOwned() &&
			(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal));
		if(freeStuff)
			repairCost = 0;

		// Make an offer to repair for the repairCost. The client can Accept the offer.
		AuCommOfferRepairAll mymsg(noQ, shortQ, noSupply, enough, ship->Id(), ship->NameWithEmpire(), repairCost, repairSecs,
				repairQ, workers, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
	else if(!noQ.empty() || !shortQ.empty() || !noSupply.empty() || !enough.empty())
	{
		AuCommRepairPartsMissing mymsg(noQ, shortQ, noSupply, enough, repairQ, msg->ChannelName(), Id(), CityBuildingName(),
				sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
	else
	{
		AuCommCityMessage mymsg(AuCommCityMessage::ShipNotDamaged, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
				range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
}

unsigned int DaBd::EstimateRepairCost(const DaVessel* ship,
		QList<COMMODITYID>& noQ, QList<COMMODITYID>& shortQ, QList<COMMODITYID>& noSupply, QList<COMMODITYID>& enough,
		quint16& repairSecs, quint8 repairQ, quint16& workers) const
{
	// Determine what is needed to repair all the systems of the ship.
	quint32 hitsNeeded;
	AuRepairParts partsNeeded;
	ship->ListRepairsNeeded(hitsNeeded, partsNeeded);

	// Init the return values.
	unsigned int repairCost = hitsNeeded;
	unsigned int totalRepairSecs = (hitsNeeded + REPAIR_PER_SEC - 1) / REPAIR_PER_SEC;
	if(!partsNeeded.empty())
	{
		AuItemHash parts;
		BrokerInventoryAvailable(parts, ship->EmpireId());
		for(AuRepairParts::const_iterator pni = partsNeeded.cbegin(); pni != partsNeeded.cend(); pni++)
		{
			quint16 itemRepairSecs = 0;
			repairCost += RepairCost(parts, pni.key(), repairQ, *pni, noQ, shortQ, noSupply, enough, itemRepairSecs);
			totalRepairSecs += itemRepairSecs;
		}
	}
	if(totalRepairSecs > 0xffff)
		totalRepairSecs = 0xffff;

	// Split repair time between workers at shops.
	if(totalRepairSecs)
	{
		quint32 workersWanted = (totalRepairSecs + 9) / 10;
		workers = CommunityRepairShopWorkers((quint16)workersWanted);
		if(workers > 1)
		{
			totalRepairSecs /= workers;
			if(totalRepairSecs < 10)
				totalRepairSecs = 10;
		}
	}
	else
		workers = 0;

	//qDebug() << "Total repair seconds" << totalRepairSecs << "Repair Secs" << repairSecs << "repairCost" << repairCost;
	repairSecs = (quint16)totalRepairSecs;
	return repairCost;
}

// Returns the estimated cost of repairing the ship at this city.
// 'repairSecs' is the amount of time needed to conduct the repairs.
unsigned int DaBd::EstimateRepairCostPossible(const DaVessel* ship, quint16& repairSecs, quint8 repairQ) const
{
	// Determine what is needed to repair all the systems of the ship.
	quint32 hitsNeeded;
	AuRepairParts partsNeeded;
	ship->ListRepairsNeeded(hitsNeeded, partsNeeded);

	// Init the return values.
	unsigned int repairCost = hitsNeeded;
	unsigned int totalRepairSecs = (hitsNeeded + REPAIR_PER_SEC - 1) / REPAIR_PER_SEC;
	if(!partsNeeded.empty())
	{
		AuItemHash parts;
		BrokerInventoryAvailable(parts, ship->EmpireId());
		for(AuRepairParts::const_iterator pni = partsNeeded.cbegin(); pni != partsNeeded.cend(); pni++)
		{
			quint16 itemRepairSecs = 0;
			repairCost += RepairCostPossible(parts, pni.key(), repairQ, *pni, itemRepairSecs);
			totalRepairSecs += itemRepairSecs;
		}
	}
	if(totalRepairSecs > 0xffff)
		repairSecs = 0xffff;
	else
		repairSecs = (quint16)totalRepairSecs;
	//qDebug() << "Total repair seconds" << totalRepairSecs << "Repair Secs" << repairSecs << "repairCost" << repairCost;
	return repairCost;
}

unsigned int DaBd::EstimateRepairCostPossible(const DaVessel* ship, SYSTEM system, quint16 which, quint16& repairSecs,
		quint8 repairQ) const
{
	// Determine what is needed to repair all the systems of the ship.
	quint32 hitsNeeded;
	AuRepairParts partsNeeded;
	ship->ListRepairsNeeded(AuSysId(system, which), hitsNeeded, partsNeeded);

	// Init the return values.
	unsigned int repairCost = hitsNeeded;
	unsigned int totalRepairSecs = (hitsNeeded + REPAIR_PER_SEC - 1) / REPAIR_PER_SEC;
	if(!partsNeeded.empty())
	{
		AuItemHash parts;
		BrokerInventoryAvailable(parts, ship->EmpireId());
		for(AuRepairParts::const_iterator pni = partsNeeded.cbegin(); pni != partsNeeded.cend(); pni++)
		{
			quint16 itemRepairSecs = 0;
			repairCost += RepairCostPossible(parts, pni.key(), repairQ, *pni, itemRepairSecs);
			totalRepairSecs += itemRepairSecs;
		}
	}
	if(totalRepairSecs > 0xffff)
		repairSecs = 0xffff;
	else
		repairSecs = (quint16)totalRepairSecs;
	//qDebug() << "Total repair seconds" << totalRepairSecs << "Repair Secs" << repairSecs << "repairCost" << repairCost;
	return repairCost;
}

unsigned int DaBd::RepairCost(const AuItemHash& parts, COMMODITYID cid, unsigned int minQ, unsigned int count,
		QList<COMMODITYID>& noQ, QList<COMMODITYID>& shortQ, QList<COMMODITYID>& noSupply, QList<COMMODITYID>& enough,
		quint16& repairSecs) const
{
	repairSecs = 0;
	if(!count)
		return 0;

	quint32 itemC = parts.RawCount(cid, minQ);	// Count of minimum quality parts.
	if(itemC < count)
	{
		// The total count of raw materials at minQ and above is below the count needed.
		quint32 rawC = parts.RawCount(cid);		// Count of any parts ignoring quality.
		if(rawC == 0)
		{
			// No parts are available at any Q.
			if(!noSupply.contains(cid))
				noSupply.append(cid);
		}
		else
		{
			if(rawC >= count)
			{
				// Enough parts are available at lower Q.
				if(!enough.contains(cid))
					enough.append(cid);
			}

			if(itemC == 0)
			{
				// No parts are available at the min Q.
				if(!noQ.contains(cid))
					noQ.append(cid);
			}
			else
			{
				// Some parts are available at the min Q.
				if(!shortQ.contains(cid))
					shortQ.append(cid);
			}
		}
		return 0;
	}

	// This city has the spare part commodity.
	AuItemHash::const_iterator itemI = parts.FindBest(cid);
	if(itemI == parts.cend())
	{
		qDebug() << "DaBd::RepairCost ERROR" << Id() << Name() << g_Au.CommodityName(cid) << "not in inventory";
		return 0;	// Safe but should never happen; already checked to see if the inventory contains the commodity.
	}

	unsigned int repairCost = (unsigned int)(g_Au.CommodityQualityCost(cid, (*itemI).second->Quality()) * count);

	repairCost += (count * LABOR_RATE);							// Add labor cost to remove/replace the broken components.

	// Calculate seconds needed for the repairs using the same formula as manufacture.
	unsigned int totalRepairSecs = (count + REPAIR_PER_SEC - 1)/REPAIR_PER_SEC;

	// Reduce repair time by quality of building.
	const float tlBoost = QualityBoostF(QualityMade());
	totalRepairSecs = (unsigned int)((float)totalRepairSecs / tlBoost);
	if(!totalRepairSecs)
		totalRepairSecs = 1;

	if(totalRepairSecs > 0xffff)
		repairSecs = 0xffff;
	else
		repairSecs = (quint16)totalRepairSecs;
	if(repairSecs < 5)
		repairSecs = 5;

	return repairCost;
}

unsigned int DaBd::RepairCostPossible(const AuItemHash& parts, COMMODITYID cid, unsigned int repairQ, unsigned int count,
		quint16& repairSecs) const
{
	repairSecs = 0;
	if(!count)
		return 0;

	quint32 itemC = parts.RawCount(cid, repairQ);
	if(!itemC)
		return 0;
	if(itemC < count)
		count = itemC;

	// This city has the spare part commodity.
	AuItemHash::const_iterator itemI = parts.FindBest(cid);
	if(itemI == parts.cend())
	{
		qDebug() << "DaBd::RepairCostPossible ERROR" << Id() << Name() << g_Au.CommodityName(cid) << "not in inventory";
		return 0;	// Safe but should never happen; already checked to see if the inventory contains the commodity.
	}

	unsigned int repairCost = (unsigned int)(g_Au.CommodityQualityCost(cid, (*itemI).second->Quality()) * count);

	repairCost += (count * LABOR_RATE);							// Add labor cost to remove/replace the broken components.

	// Calculate seconds needed for the repairs using the same formula as manufacture.
	unsigned int totalRepairSecs = (count + REPAIR_PER_SEC - 1)/REPAIR_PER_SEC;

	// Reduce repair time by quality of building.
	const float tlBoost = QualityBoostF(QualityMade());
	totalRepairSecs = (unsigned int)((float)totalRepairSecs / tlBoost);
	if(!totalRepairSecs)
		totalRepairSecs = 1;

	if(totalRepairSecs > 0xffff)
		repairSecs = 0xffff;
	else
		repairSecs = (quint16)totalRepairSecs;
	if(repairSecs < 5)
		repairSecs = 5;

	return repairCost;
}

void DaBd::RxRequestRepairSystem(const AuCommRequestRepairSystem* msg, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, POLITICAL_STANCE stanceToSender)
{
	if(!msg)
		return;
	if(!ship)
		return;
	// Airports support company and military ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	if(!ship->InChainOfCommand(person))
	{
		// The message sender is not an officer of the ship.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToRepair, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	if(ship->RepairSecondsRemaining())
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShipGettingRepairs, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;	// Ignore; ship is already getting repairs.
	}

	// Find quality of highest available repair shop.
	if(!CommunityHasRepairShop())
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShop, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Ignore the request if my empire restricts export of repairs to the ship's empire.
	quint32 empireId = EmpireId();
	const DgData& gd = g_Au.LockDataForRead();
	bool isRestricted = gd.EmpireCommerceRestricted(empireId, CID_Sunlight, stanceToSender);	// CID_Sunlight = Repairs
	g_Au.UnlockData();
	if(isRestricted)
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::RepairProhibited, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	quint8 repairQ = msg->MinQ();

	// Determine what is needed to repair all the systems of the ship.
	quint32 hitsNeeded;
	AuRepairParts partsNeeded;
	ship->ListRepairsNeeded(AuSysId(msg->System(), msg->SystemWhich()), hitsNeeded, partsNeeded);
	if(hitsNeeded || !partsNeeded.empty())
	{
		unsigned int repairCost = hitsNeeded;
		unsigned int totalRepairSecs = (hitsNeeded + REPAIR_PER_SEC - 1) / REPAIR_PER_SEC;
		QList<COMMODITYID> noQ, shortQ, noSupply, enough;						// parts that cannot be repaired
		if(!partsNeeded.empty())
		{
			AuItemHash parts;
			BrokerInventoryAvailable(parts, ship->EmpireId());
			for(AuRepairParts::const_iterator pni = partsNeeded.cbegin(); pni != partsNeeded.cend(); pni++)
			{
				quint16 itemRepairSecs = 0;
				repairCost += RepairCost(parts, pni.key(), repairQ, *pni, noQ, shortQ, noSupply, enough, itemRepairSecs);
				totalRepairSecs += itemRepairSecs;
			}
		}

		// Make an offer to perform the repairs.
		if(repairCost)
		{
			if(totalRepairSecs > 0xffff)
				totalRepairSecs = 0xffff;

			// Split repair time between workers at shops.
			quint16 workers = 0;
			if(totalRepairSecs)
			{
				quint32 workersWanted = (totalRepairSecs + 9) / 10;
				workers = CommunityRepairShopWorkers((quint16)workersWanted);
				if(workers > 1)
				{
					totalRepairSecs /= workers;
					if(totalRepairSecs < 10)
						totalRepairSecs = 10;
				}
			}
			else
				workers = 0;

			if(workers)
			{
				// Subsidized spacecraft of friends get free repairs.
				bool freeStuff = IndustryId() == IID_BaseAirTerminal || (!ship->IsPrivatelyOwned() &&
					(stanceToSender == POL_Friend || stanceToSender == POL_Empire || stanceToSender == POL_Vassal));
				if(freeStuff)
					repairCost = 0;
				quint16 repairSecs = (quint16)totalRepairSecs;

				// Make an offer to repair for the repairCost. The client can Accept the offer.
				AuCommOfferRepairSystem mymsg(msg->System(), msg->SystemWhich(), msg->SystemDesc(), noQ, shortQ, noSupply, enough,
						ship->Id(), ship->NameWithEmpire(), repairCost, repairSecs, repairQ, workers, msg->ChannelName(), Id(),
						CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
			}
			else if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
			{
				AuCommCityMessage mymsg(AuCommCityMessage::NoRepairShopWorkers, msg->ChannelName(), Id(), CityBuildingName(),
						sectorId, Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
			}
		}
		else if(!noQ.empty() || !shortQ.empty() || !noSupply.empty() || !enough.empty())
		{
			AuCommRepairPartsMissing mymsg(noQ, shortQ, noSupply, enough, repairQ, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
	}
	else
	{
		AuCommCityMessage mymsg(AuCommCityMessage::ShipNotDamaged, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
				range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
	}
}

void DaBd::RxDebarkCryo(const AuCommDebarkCryo* msg, quint32& countSupplied, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, bool hasTransporter, bool inTransporterRange)
{
	if(!msg)
		return;
	if(!ship)
		return;
	if(IndustryId() != IID_AirportTerminal && IndustryId() != IID_BaseAirTerminal)
		return;
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;

	// Message text is the count of colonists debarked.
	// Do nothing if the requested number has already been supplied.
	if(countSupplied >= msg->Count())
		return;
	unsigned int count = msg->Count() - countSupplied;

	// City in trade range will add the colonists to its population.
	if(!g_Au.HasPendingCryo(msg))
		return;

	// Insure the colonists are physically located where the
	// transaction can be performed.
	if(!ship->InChainOfCommand(person))
	{
		// On a private channel, give a reason why not.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToUnloadCryo, msg->ChannelName(), Id(), CityBuildingName(),
					sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;	// Person is not an officer of the ship.
	}

	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore colonists if the buyer is too far away to accept the transaction.
	if(!inCity && !nearStation && !inTransporterRange)
	{
		// Tell the buyer to move closer.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage::MESSAGE msgId;
			if(hasTransporter)
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdTransporterStationToDebarkCryo;
				else
					msgId = AuCommCityMessage::MoveBdTransporterToDebarkCryo;
			}
			else
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdStationToDebarkCryo;
				else
					msgId = AuCommCityMessage::MoveBdToDebarkCryo;
			}
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
					range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	if(IsMilitary())
	{
		quint32 homes = BaseTransientHomes(world);
		if(!homes)
		{
			if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
			{
				AuCommCityMessage mymsg(AuCommCityMessage::NoHomesForRecruits, msg->ChannelName(), Id(), CityBuildingName(),
						sectorId, Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
			}
			return;
		}
		if(count > homes)
			count = homes;
	}
	else
	{
		quint32 homes = AirportTransientHomes(world);
		if(!homes)
		{
			if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
			{
				AuCommCityMessage mymsg(AuCommCityMessage::NoHomesForTravellers, msg->ChannelName(), Id(), CityBuildingName(),
						sectorId, Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
			}
			return;
		}
		if(count > homes)
			count = homes;
	}

	// Take them from cryo berths on the ship.
	unsigned int debarked = 0;
	QStringList speciesDebarked;
	for(unsigned int icol = 0; icol < count; icol++)
	{
		AuSpecies species = ship->RemoveAnyCryoBerthOccupant();
		if(species.IsNull())
			break;	// Nobody left to take.

		TransientIncreasePopulation(species);				// Transfer dna,population to this city.
		debarked++;

		QString speciesName = species.NameOrDesc();
		if(!speciesDebarked.contains(speciesName))
			speciesDebarked.append(speciesName);
	}

	// Player Statistics
	person->Stats().DebarkedCryo(debarked);
	person->IncreaseSkill(AuSkill::Command, 1);

	person->CryoDelivered(Id(), debarked);

	// Tally cryo travellers supplied by this city so other cities may supply the remainder.
	countSupplied += debarked;

	// Send a CryoDebarked message so the person knows the transfer is complete. The count may have
	// changed from the request.
	AuCommCryoDebarked mymsg(msg->FromId(), debarked, hasTransporter && inTransporterRange, speciesDebarked,
			msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
}

quint32 DaBd::TransientPopulation() const
{
	quint32 tpop = 0;
	m_TransientLock.lockForRead();
	for(QMap<AuSpecies, quint32>::const_iterator ti = m_TransientPopulation.cbegin(); ti != m_TransientPopulation.cend(); ti++)
		tpop += *ti;
	m_TransientLock.unlock();
	return tpop;
}

quint32 DaBd::AirportEmptyHomes(const DaWorld* world) const
{
	// Local facilities.
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	quint32 emptyHomes = 0;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about airport repair shop connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		if(bd->IndustryId() == IID_School || bd->IndustryId() == IID_PoliceAcademy)
			continue;
		emptyHomes += bd->EmptyHomes();
	}
	m_TradeConnectionsLock.unlock();
	return emptyHomes;
}

quint32 DaBd::AirportTransientHomes(const DaWorld* world) const
{
	// Determine how many airport departures we can take based on current population and transient capacity.
	// Determine how many transients we can handle.
	quint32 maxTransient = (quint32)ceil(LastReportedHomes() * .15);	// Max transients we want.
	quint32 curTransient = 0;
	quint32 emptyHomes = 0;
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about airport repair shop connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		if(bd->IndustryId() != IID_School && bd->IndustryId() != IID_PoliceAcademy)
			emptyHomes += bd->EmptyHomes();
		if(bd->IndustryId() == IID_AirportTerminal)
			curTransient += bd->TransientPopulation();
	}
	m_TradeConnectionsLock.unlock();

	// Determine how many new transients we can accept.
	quint32 acceptTransient;
	if(maxTransient > curTransient)
		acceptTransient = maxTransient - curTransient;
	else
		acceptTransient = 0;

	// Airport arrivals can go directly to empty homes too.
	return acceptTransient + emptyHomes;
}

quint32 DaBd::BaseEmptyHomes(const DaWorld* world) const
{
	// Local facilities.
	quint32 emptyHomes = 0;
	DaAtomList base;
	world->FindBdBase(base);
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		if(bd->IndustryId() == IID_BaseAcademy || bd->IndustryId() == IID_BaseMarineBarracks)
			continue;
		emptyHomes += bd->EmptyHomes();
	}
	return emptyHomes;
}

quint32 DaBd::BaseTransientHomes(const DaWorld* world) const
{
	// Determine how many air base departures we can take based on current population and transient capacity.
	// Determine how many transients we can handle.
	quint32 maxTransient = (quint32)ceil(LastReportedHomes() * .30);	// Max transients we want.
	quint32 curTransient = 0;
	quint32 emptyHomes = 0;
	DaAtomList base;
	world->FindBdBase(base);
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		if(bd->IndustryId() != IID_BaseAcademy && bd->IndustryId() != IID_BaseMarineBarracks)
			emptyHomes += bd->EmptyHomes();
		if(bd->IndustryId() == IID_BaseAirTerminal)
			curTransient += bd->TransientPopulation();
	}

	// Determine how many new transients we can accept.
	quint32 acceptTransient;
	if(maxTransient > curTransient)
		acceptTransient = maxTransient - curTransient;
	else
		acceptTransient = 0;

	// Air base arrivals can go directly to empty homes too.
	return acceptTransient + emptyHomes;
}

quint32 DaBd::AirportPassengers(const DaWorld* world, bool requestorInCoC) const
{
	// Local facilities.
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	quint32 citizens = 0;
	quint32 homes = 0;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about airport repair shop connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		if(bd->IndustryId() == IID_School || bd->IndustryId() == IID_PoliceAcademy)
			continue;
		if(bd->IsUnderConstruction())
			continue;
		citizens += bd->Population();	// Include transients
		quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
		bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
		if(homesLarge + homesMedium + homesSmall > 0xffff)
			homes += 0xffff;
		else
			homes += homesLarge + homesMedium + homesSmall;
	}
	m_TradeConnectionsLock.unlock();

	// Up to 15% of the homes may be emptied.
	quint32 minPop;
	if(requestorInCoC)
		minPop = 2;
	else
		minPop = homes * 85 / 100;
	if(citizens <= minPop)
		return 0;
	return citizens - minPop;
}

quint16 DaBd::EmptyHomes() const
{
	if(IsUnderConstruction())
		return 0;
	// Determine my number of resident citizens and my total number of homes.
	quint16 citizens = Residents();
	quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
	IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
	quint32 homes = homesLarge + homesMedium + homesSmall;
	if(homes > 0xffff)
		homes = 0xffff;
	if(homes <= citizens)
		return 0;
	return (quint16)(homes - citizens);
}

quint16 DaBd::ResidentsReadyToDepart(bool requestorInCoC) const
{
	if(IsUnderConstruction())
		return 0;
	// Determine my number of resident citizens and my total number of homes.
	quint16 citizens = Population();	// include transients
	quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
	IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
	quint32 homes = homesLarge + homesMedium + homesSmall;
	if(homes > 0xffff)
		homes = 0xffff;

	// Up to 15% of the homes may be emptied.
	quint32 minPop;
	if(requestorInCoC)
		minPop = 2;
	else
		minPop = homes * 85 / 100;
	if(citizens <= minPop)
		return 0;
	return (quint16)(citizens - minPop);
}

quint32 DaBd::AirportCryoPassengers(const DaWorld* world, bool requestorInCoC) const
{
	// Local facilities.
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	quint32 citizens = 0;
	quint32 homes = 0;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about airport repair shop connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		if(bd->IndustryId() == IID_School || bd->IndustryId() == IID_PoliceAcademy)
			continue;
		if(bd->IsUnderConstruction())
			continue;
		citizens += bd->Population();	// include transients
		quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
		bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
		if(homes > 0xffff)
			homes += 0xffff;
		else
			homes += homesLarge + homesMedium + homesSmall;
	}
	m_TradeConnectionsLock.unlock();

	// Up to 15% of the homes may be emptied.
	quint32 minPop;
	if(requestorInCoC)
		minPop = 2;
	else
		minPop = homes * 85 / 100;
	if(citizens <= minPop)
		return 0;
	return citizens - minPop;
}

quint32 DaBd::BaseCryoPassengers(const DaWorld* world, bool requestorInCoC) const
{
	// Local facilities.
	quint32 citizens = 0;
	quint32 homes = 0;
	DaAtomList base;
	world->FindBdBase(base);
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		if(bd->IndustryId() == IID_BaseAcademy || bd->IndustryId() == IID_BaseMarineBarracks)
			continue;
		if(bd->IsUnderConstruction())
			continue;
		citizens += bd->Population();	// include transients
		quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
		bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
		if(homes > 0xffff)
			homes += 0xffff;
		else
			homes += homesLarge + homesMedium + homesSmall;
	}

	// Up to 15% of the homes may be emptied.
	quint32 minPop;
	if(requestorInCoC)
		minPop = 2;
	else
		minPop = homes * 85 / 100;
	if(citizens <= minPop)
		return 0;
	return citizens - minPop;
}

quint16 DaBd::CommunityRepairShopWorkers(const quint16 workersWanted) const
{
	if(IsMilitary())
		return BaseRepairShopWorkers(workersWanted);
	else
		return AirportRepairShopWorkers(workersWanted);
}

quint16 DaBd::AirportRepairShopWorkers(const quint16 workersWanted) const
{
	quint32 workers = 0;
	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return (quint16)workers;
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about buildings connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;
		if(bd->IndustryId() != IID_AirportRepairShop)
			continue;
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		workers += bd->Workers();
		if(workers >= workersWanted)
		{
			workers = workersWanted;
			break;
		}
	}
	m_TradeConnectionsLock.unlock();
	return (quint16)workers;
}

quint16 DaBd::BaseRepairShopWorkers(const quint16 workersWanted) const
{
	quint32 workers = 0;
	const DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return workers;
	DaAtomList base;
	world->FindBds(base);	// Bases use all airport repair shops on the planet.
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		if(bd->IndustryId() != IID_AirportRepairShop)
			continue;
		workers += bd->Workers();
		if(workers >= workersWanted)
		{
			workers = workersWanted;
			break;
		}
	}
	return workers;
}

