bool DaBd::CommunityIncreasePopulation(const AuSpecies& species)
{
	if(IsMilitary())
		return BaseIncreasePopulation(species);
	else
		return AirportIncreasePopulation(species);
}

void DaBd::TransientIncreasePopulation(const AuSpecies& species)
{
	if(CommunityIncreasePopulation(species))
		return;
	m_TransientLock.lockForWrite();
	QMap<AuSpecies, quint32>::iterator ti = m_TransientPopulation.find(species);
	if(ti != m_TransientPopulation.end())
		(*ti)++;
	else
		m_TransientPopulation.insert(species, 1);
	m_TransientLock.unlock();
	SetModified(NOTIFY_Database);
}

bool DaBd::AirportIncreasePopulation(const AuSpecies& species)
{
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return false;
	// Local facilities.
	bool movedIn = false;
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about airport repair shop connected by road.
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		if(bd->IndustryId() == IID_School || bd->IndustryId() == IID_PoliceAcademy)
			continue;
		if(bd->IsUnderConstruction())
			continue;
		quint32 citizens = bd->Residents();
		quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
		bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
		quint32 homes = homesLarge + homesMedium + homesSmall;
		if(homes > 0xffff)
			homes = 0xffff;
		if(homes > citizens)
		{
			bd->TravellerMovedIn(species);
			movedIn = true;
			break;
		}
	}
	m_TradeConnectionsLock.unlock();
	return movedIn;
}

