bool DaBd::CommunityIncreasePopulation(const DaCreature* creature, const QString& sourceName)
{
	if(IsMilitary())
		return BaseIncreasePopulation(creature, sourceName);
	else
		return AirportIncreasePopulation(creature, sourceName);
}

void DaBd::TransientIncreasePopulation(const DaCreature* creature, const QString& sourceName)
{
	if(CommunityIncreasePopulation(creature, sourceName))
		return;
	AuSpecies species = creature->Species();
	if(species.IsNull())
		return;

	m_TransientLock.lockForWrite();

	// See if we already have that exact DNA in our transient population.
	QMap<AuSpecies, quint32>::iterator ti = m_TransientPopulation.find(species);
	if(ti != m_TransientPopulation.end())
		(*ti)++;									// Increase existing population.
	else
		m_TransientPopulation.insert(species, 1);	// Add new species of transient population.

	m_TransientLock.unlock();
	SpreadDisease(creature, sourceName);	// The arriving creature may have something to share. Do it right away.
	SetModified(NOTIFY_Database);
}

