void DaBd::CommunityIncreaseCrew(const DaCreature* creature, const QString& sourceName)
{
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	// Local facilities.
	bool crewPlaced = false;
	AuId myCapitolId = CapitolId();		// Null if I am not part of a city.
	DaAtomList base;
	world->FindBds(base);
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		switch(bd->IndustryId())
		{
		case IID_School:
			if(!HasTradeConnectionByGround(bd->Id()))
				continue;				// Only care about university connected by road.
			if(!bd->InCommunityCity(myCapitolId))
				continue;
			break;
		case IID_BaseAcademy:
			break;
		default:
			continue;
		}
		if(bd->IsUnderConstruction())
			continue;
		quint32 citizens = bd->Residents();
		quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
		bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
		quint32 homes = homesLarge + homesMedium + homesSmall;
		if(homes > 0xffff)
			homes = 0xffff;
		if(homes > citizens)
		{
			bd->TravellerMovedIn(creature, sourceName);
			crewPlaced = true;
			break;
		}
	}
	if(!crewPlaced)
		CommunityIncreasePopulation(creature, sourceName);
}

