void DaBd::RxDebarkPassengers(const AuCommDebarkPassengers* msg, quint32& countSupplied, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, bool hasTransporter, bool inTransporterRange)
{
	if(!msg)
		return;
	if(!ship)
		return;
	if(IndustryId() != IID_AirportTerminal && IndustryId() != IID_BaseAirTerminal)
		return;
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;

	// Message text is the count of colonists debarked.
	// Do nothing if the requested number has already been supplied.
	if(countSupplied >= msg->Count())
		return;
	unsigned int count = msg->Count() - countSupplied;

	// City in trade range will add the colonists to its population.
	if(!g_Au.HasPendingColonists(msg))
		return;

	// Insure the colonists are physically located where the
	// transaction can be performed.
	if(!ship->InChainOfCommand(person))
	{
		// On a private channel, give a reason why not.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToUnloadPassengers, msg->ChannelName(), Id(),
					CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;	// Person is not an officer of the ship.
	}

	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore colonists if the buyer is too far away to accept the transaction.
	if(!inCity && !nearStation && !inTransporterRange)
	{
		// Tell the buyer to move closer.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage::MESSAGE msgId;
			if(hasTransporter)
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdTransporterStationToDebarkPassengers;
				else
					msgId = AuCommCityMessage::MoveBdTransporterToDebarkPassengers;
			}
			else
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdStationToDebarkPassengers;
				else
					msgId = AuCommCityMessage::MoveBdToDebarkPassengers;
			}
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
					range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	if(IsMilitary())
	{
		quint32 homes = BaseTransientHomes(world);
		if(!homes)
		{
			if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
			{
				AuCommCityMessage mymsg(AuCommCityMessage::NoHomesForRecruits, msg->ChannelName(), Id(), CityBuildingName(),
						sectorId, Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
			}
			return;
		}
		if(count > homes)
			count = homes;
	}
	else
	{
		quint32 homes = AirportTransientHomes(world);
		if(!homes)
		{
			if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
			{
				AuCommCityMessage mymsg(AuCommCityMessage::NoHomesForTravellers, msg->ChannelName(), Id(), CityBuildingName(),
						sectorId, Galaxy(), range, msg->Scope());
				g_Au.SendAtomChat(mymsg);
			}
			return;
		}
		if(count > homes)
			count = homes;
	}

	// Take them from colonist berths on the ship.
	// Calculate payment due for delivering the colonists.
	// Determine transport rates based on trip length.
	quint8 lsQ = ship->SystemQuality(SYS_LifeSupport);	// Life support quality affects fare rate.
	double lsQBoost = QualityBoostF(lsQ);
	double longTripRate = 300 * lsQBoost;				// Travel to another solar system.
	double medTripRate = 30 * lsQBoost;					// Travel to another world.
	double shortTripRate = 3 * lsQBoost;				// Travel to another city.
	if(ship->IsFirstClass())
	{
		// First class accomodations earn triple fees.
		longTripRate *= 3;
		medTripRate *= 3;
		shortTripRate *= 3;
	}
	else if(ship->IsSecondClass())
	{
		// Second class accomodations earn double fees.
		longTripRate *= 2;
		medTripRate *= 2;
		shortTripRate *= 2;
	}

	QString sourceName = ship->NameWithEmpire();	// For disease outbreak event message.
	double transportFee = 0;	// accumulated
	unsigned int debarked = 0;
	for(unsigned int icol = 0; icol < count; icol++)
	{
		DaNpc* npc = ship->FindColonist();
		if(!npc)
			break;
		AuId originCity(npc->PortBd());	// Get the passenger's building of origin.
		ship->RemoveBerthOccupant(npc->Id());	// Release the colonist's berth.
		TransientIncreasePopulation(npc, sourceName);	// Transfer disease,dna,population to this city.
		ship->KillColonist();					// Remove a colonist atom from the ship.
		debarked++;

		// Transport fees
		if(!Is(originCity))
		{
			// Colonist was dropped off in a city that is not their city of origin. A fee is due.
			if(world->FindSubatomId(originCity))
			{
				// The city of origin is on this planet.
				transportFee += shortTripRate;

				// Passengers take 1000c with them when they leave their city of origin.
				// Put their remaining money into their nu city's citizen fund.
				CommunityCreditAccount(1000 - shortTripRate, AuBank::Civ_CreditImmigration);
			}
			else if(FindEnvironmentAtom()->FindIdRecursive(originCity))
			{
				// The city of origin is in this solar system.
				// City could be up to five levels below the
				// solar system.
				// 0 - Solar System
				//   1 - Primary Star
				//     2 - Secondary or Tertiary Star
				//       3 - Planet
				//         4 - Moon
				//           5 - City
				transportFee += medTripRate;

				// Passengers take 1000c with them when they leave their city of origin.
				// Put their remaining money into their nu city's citizen fund.
				CommunityCreditAccount(1000 - medTripRate, AuBank::Civ_CreditImmigration);
			}
			else
			{
				// The city of origin is NOT in this system.
				transportFee += longTripRate;

				// Passengers take 1000c with them when they leave their city of origin.
				// Put their remaining money into their nu city's citizen fund.
				CommunityCreditAccount(1000 - longTripRate, AuBank::Civ_CreditImmigration);
			}
		}
		else
		{
			// This is the origin city.
			// Put their money back into their origin city's citizen fund.
			CommunityCreditAccount(1000, AuBank::Civ_CreditImmigration);
		}
	}

	// Pay the ship for debarking the passengers.
	ship->CreditAccountSales(transportFee);

	// Player Statistics
	person->Stats().DebarkedPassengers(debarked);
	person->IncreaseSkill(AuSkill::Command, 1);

	person->PassengersDelivered(Id(), debarked);

	// Tally officer supplied by this city so other cities may supply the remainder.
	countSupplied += debarked;

	// Send a PassengersDebarked message so the person knows the transfer is complete. The count may have
	// changed from the request.
	AuCommPassengersDebarked mymsg(msg->FromId(), debarked, (quint32)transportFee, hasTransporter && inTransporterRange,
			msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
}

void DaBd::RxBoardPassengers(const AuCommBoardPassengers* msg, quint32& countSupplied, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, POLITICAL_STANCE stanceToSender, bool hasTransporter,
		bool inTransporterRange)
{
	if(!msg)
		return;
	if(!ship)
		return;
	if(IsMilitary())
		return;
	DaWorldLL* world = FindParentWorldInEnv();
	if(!world)
		return;

	if(ship->InDesignEnvironment())
	{
		AuCommCityMessage mymsg(AuCommCityMessage::NoPassengersInStudio, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Message text is the count of colonists debarked.
	// Do nothing if the requested number has already been supplied.
	if(countSupplied >= msg->Count())
		return;
	unsigned int count = msg->Count() - countSupplied;

	// City in trade range will attempt to board some of its citizens.
	if(!g_Au.HasPendingColonists(msg))
		return;

	if(!ship->InChainOfCommand(person))
	{
		AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToLoadPassengers, msg->ChannelName(), Id(), CityBuildingName(),
				sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Person is not an officer of the ship.
	}

	// Calculate number of colonists willing to leave.
	quint32 colonists = AirportPassengers(world, InChainOfCommand(person));
	if(!colonists)
	{
		AuCommCityMessage mymsg(AuCommCityMessage::NoPassengersToLeave, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// This city has too few citizens to give up any.
	}

	// Ignore the request if my empire restricts export of citizens to the ship's empire.
	quint32 empire = EmpireId();
	const DgData& gd = g_Au.LockDataForRead();
	bool isRestricted = gd.EmpireCommerceRestricted(empire, CID_Invalid, stanceToSender);	// Invalid = Citizens
	g_Au.UnlockData();
	if(isRestricted)
	{
		AuCommCityMessage mymsg(AuCommCityMessage::CitizensRestricted, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Calculate how many citizens can afford to leave, if they used all the money in town.
	// Each citizen will only leave if they have at least 1000c in their pocket, to pay the ticket and have some
	// spending money. They are leaving their home after all. They might never be back.
	double brokerAccount = BrokerAccountBalance();
	if(brokerAccount < 1000)
	{
		// This city doesn't have enough money for even one citizen to leave.
		AuCommCityMessage::MESSAGE msgId = AuCommCityMessage::NobodyCanAffordToLeave;
		AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}
	double canAffordToLeave = brokerAccount / 1000.;
	if(colonists > (unsigned int)canAffordToLeave)
		colonists = (unsigned int)canAffordToLeave;

	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore bid if the buyer is too far away to accept the transaction.
	if(!inCity && !nearStation && !inTransporterRange)
	{
		// Tell the buyer to move closer.
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage::MESSAGE msgId;
			if(hasTransporter)
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdTransporterStationToBoardPassengers;
				else
					msgId = AuCommCityMessage::MoveBdTransporterToBoardPassengers;
			}
			else
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdStationToBoardPassengers;
				else
					msgId = AuCommCityMessage::MoveBdToBoardPassengers;
			}
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
					range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Message knows the count of berths offered.
	unsigned int berthsOpen = ship->PassengerBerthsAvailable();
	if(count > berthsOpen)
		count = berthsOpen;	// Limit count to berths available.
	if(count > colonists)
		count = colonists;
	if(!count)
		return;

	// Player Statistics
	person->Stats().BoardedPassengers(count);
	person->IncreaseSkill(AuSkill::Command, 1);

	person->PassengersPickedUp(Id(), world->Id(), count);

	// People take their bank account with them. 1000c per person.
	BrokerDebitAccount(count * 1000, AuBank::Civ_DebitEmigration);

	// Transfer population from the city to the ship's roster.
	// Remove citizens from this city.
	QList<AuSpecies> speciesRemoved;
	AirportDecreasePassengers(world, count, speciesRemoved);

	AuItemHash inventory;
	BrokerInventoryAvailable(inventory, ship->EmpireId());

	// Put them in colonist berths on the ship.
	if(!speciesRemoved.empty())
	{
		int resourceZone = world->ResourceZone(GlobeLL().Longitude());
		quint8 bodyQ = world->NaturalResourceQuality(CID_Animal, resourceZone);
		for(unsigned int icol = 0; icol < count; icol++)
			ship->BoardColonist(Id(), world, EmpireId(), speciesRemoved, inventory, bodyQ);
	}

	// Tally officer supplied by this city so other cities may supply the remainder.
	countSupplied += count;

	// Send a PassengersBoarded message so the loader knows the transfer is complete. The count may have changed from
	// the request.
	AuCommPassengersBoarded mymsg(msg->FromId(), count, hasTransporter && inTransporterRange,
			msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
}

void DaBd::CommunityPersonDied(quint32 howMany)
{
	if(IsMilitary())
		TroopDied(howMany);
	else
		CitizenDied(howMany);
}

void DaBd::CitizenDied(quint32 howMany)
{
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	// Local facilities.
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about buildings connected by road.
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		howMany -= bd->ResidentDied(howMany);
		if(!howMany)
			break;
	}
	m_TradeConnectionsLock.unlock();
}

void DaBd::WorkerDied(DaWorld* world, quint32 howMany)
{
	// Local facilities.
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about buildings connected by road.
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		if(bd->IndustryId() == IID_School || bd->IndustryId() == IID_PoliceAcademy)
			continue;
		howMany -= bd->ResidentDied(howMany);
		if(!howMany)
			break;
	}
	m_TradeConnectionsLock.unlock();
	world->WorldPopulationChanged();	// Dirty the world's population cache.
}

void DaBd::TroopDied(quint32 howMany)
{
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return;
	// Local facilities.
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->IsMilitary())
			continue;
		howMany -= bd->ResidentDied(howMany);
		if(!howMany)
			break;
	}
	m_TradeConnectionsLock.unlock();
}

void DaBd::AirportDecreasePassengers(DaWorld* world, quint32 howMany, QList<AuSpecies>& speciesRemoved)
{
	// Local facilities.
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	m_TradeConnectionsLock.lockForRead();
	// Take transients before regular residents.
	DaAtomList bds;
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about airport repair shop connected by road.
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(!bd->InCommunityCity(myCapitolId))
			continue;

		// Transients could inhabit any building.
		if(bd->TransientPopulation())
		{
			while(howMany)
			{
				AuSpecies species = TakeTransient();
				if(species.IsNull())
					break;	// out of transients at this air base
				if(!speciesRemoved.contains(species))
					speciesRemoved.append(species);
				howMany--;
			}
			if(!howMany)
				break;	// stop checking trade connections for transients
		}
		bds.append(bd);
	}
	m_TradeConnectionsLock.unlock();
	if(!howMany)
		return;

	// Take building residents.
	for(DaAtomList::const_iterator bi = bds.cbegin(); bi != bds.cend(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		if(bd->IndustryId() == IID_School || bd->IndustryId() == IID_PoliceAcademy)
			continue;
		if(!bd->Residents())
			continue;
		AuSpecies species(bd->ResidentSpecies());
		if(species.IsNull())
			continue;
		if(!speciesRemoved.contains(species))
			speciesRemoved.append(species);
		howMany -= bd->RemoveTravellers(howMany);
		if(!howMany)
			break;	// stop taking residents
	}
}

void DaBd::BaseDecreasePassengers(DaWorld* world, quint32 howMany, QList<AuSpecies>& speciesRemoved)
{
	// Local facilities.
	DaAtomList base;
	world->FindBdBase(base);
	// Take transients before regular residents.
	DaAtomList bds;
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		// Transients could inhabit any building.
		DaBd* bd = (DaBd*)*bi;
		if(bd->TransientPopulation())
		{
			while(howMany)
			{
				AuSpecies species = TakeTransient();
				if(species.IsNull())
					break;	// out of transients at this air base
				if(!speciesRemoved.contains(species))
					speciesRemoved.append(species);
				howMany--;
			}
			if(!howMany)
				break;	// stop checking trade connections for transients
		}
		bds.append(bd);
	}
	if(!howMany)
		return;

	// Take building residents.
	for(DaAtomList::const_iterator bi = bds.cbegin(); bi != bds.cend(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		if(bd->IndustryId() == IID_BaseAcademy || bd->IndustryId() == IID_BaseMarineBarracks)
			continue;
		if(!bd->Residents())
			continue;
		AuSpecies species(bd->ResidentSpecies());
		if(species.IsNull())
			continue;
		if(!speciesRemoved.contains(species))
			speciesRemoved.append(species);
		howMany -= bd->RemoveTravellers(howMany);
		if(!howMany)
			break;	// stop taking residents
	}
}

