void DaBd::RxBoardCrew(const AuCommBoardCrew* msg, quint32& countSupplied, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, POLITICAL_STANCE stanceToSender, bool hasTransporter,
		bool inTransporterRange)
{
	if(!msg)
		return;
	if(!ship)
		return;
	// Airports provide personnel to company ships. Fleet personnel come from bases.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
		// The fleet can draft anybody.
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}
	DaWorldLL* world = FindParentWorldInEnv();
	if(!world)
		return;

	if(ship->InDesignEnvironment())
	{
		AuCommCityMessage mymsg(AuCommCityMessage::NoCrewInStudio, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Message text is the count of colonists debarked.
	// Do nothing if the requested number has already been supplied.
	if(countSupplied >= msg->Count())
		return;
	unsigned int count = msg->Count() - countSupplied;

	// City in trade range will attempt to board some of its citizens.
	if(!g_Au.HasPendingCrew(msg))
		return;

	if(!ship->InChainOfCommand(person))
	{
		AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToLoadCrew, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Person is not an officer of the ship.
	}

	// Calculate number of crew willing to leave.
	quint32 crew;
	if(IsMilitary())
		crew = BaseCrew(world);
	else
		crew = AirportCrew(world);
	if(!crew)
	{
		AuCommCityMessage mymsg(AuCommCityMessage::NoCrewToLeave, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// This city has too few citizens to give up any.
	}

	// Ignore the request if my empire restricts export of citizens to the ship's empire.
	quint32 empire = EmpireId();
	const DgData& gd = g_Au.LockDataForRead();
	bool isRestricted = gd.EmpireCommerceRestricted(empire, CID_Invalid, stanceToSender);	// Invalid = Citizens
	g_Au.UnlockData();
	if(isRestricted || empire == 0)
	{
		AuCommCityMessage mymsg(AuCommCityMessage::CitizensRestricted, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore bid if the buyer is too far away to accept the transaction.
	if(!inCity && !nearStation && !inTransporterRange)
	{
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			// Tell the buyer to move closer.
			AuCommCityMessage::MESSAGE msgId;
			if(hasTransporter)
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdTransporterStationToBoardCrew;
				else
					msgId = AuCommCityMessage::MoveBdTransporterToBoardCrew;
			}
			else
			{
				if(hasStation)
					msgId = AuCommCityMessage::MoveBdStationToBoardCrew;
				else
					msgId = AuCommCityMessage::MoveBdToBoardCrew;
			}
			AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(),
					range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Message knows the count of berths offered.
	unsigned int berthsOpen = ship->CrewBerthsAvailable();
	if(count > berthsOpen)
		count = berthsOpen;	// Limit count to berths available.
	if(count > crew)
		count = crew;
	if(!count)
		return;

	// Player Statistics
	person->Stats().BoardedCrew(count);
	person->IncreaseSkill(AuSkill::Command, 1);

	// Transfer population from the city to the ship's roster.
	// Remove citizens from this city.
	QList<AuSpecies> speciesRemoved;
	if(IsMilitary())
		BaseDecreaseCrew(world, count, speciesRemoved);
	else
		AirportDecreaseCrew(world, count, speciesRemoved);

	AuItemHash inventory;
	BrokerInventoryAvailable(inventory, ship->EmpireId());

	// Put them in crew berths on the ship.
	if(!speciesRemoved.empty())
	{
		int resourceZone = world->ResourceZone(GlobeLL().Longitude());
		quint8 bodyQ = world->NaturalResourceQuality(CID_Animal, resourceZone);
		for(unsigned int icol = 0; icol < count; icol++)
			ship->BoardCrew(EmpireId(), speciesRemoved, inventory, bodyQ);
	}

	// Tally crew supplied by this city so other cities may supply the remainder.
	countSupplied += count;

	// Send a CrewBoarded message so the loader knows the transfer is complete. The count may have changed from the request.
	AuCommCrewBoarded mymsg(msg->FromId(), count, hasTransporter && inTransporterRange,
			msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
}

quint32 DaBd::AirportCrew(const DaWorld* world) const
{
	// Local facilities.
	AuId myCapitolId = CapitolId();	// Null if I am not part of a city.
	quint32 citizens = 0;
	quint32 homes = 0;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;				// Only care about airport repair shop connected by road.
		const DaBd* bd = dynamic_cast<const DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;				// Don't care about cities.
		if(bd->IndustryId() != IID_School)
			continue;
		if(!bd->InCommunityCity(myCapitolId))
			continue;
		if(bd->IsUnderConstruction())
			continue;
		citizens += bd->Residents();
		quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
		bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
		if(homesLarge + homesMedium + homesSmall > 0xffff)
			homes += 0xffff;
		else
			homes += homesLarge + homesMedium + homesSmall;
	}
	m_TradeConnectionsLock.unlock();
	return citizens;
}

quint32 DaBd::BaseCrew(const DaWorld* world) const
{
	// Local facilities.
	quint32 citizens = 0;
	quint32 homes = 0;
	DaAtomList base;
	world->FindBdBase(base);
	for(DaAtomList::const_iterator bi = base.begin(); bi != base.end(); bi++)
	{
		DaBd* bd = (DaBd*)*bi;
		if(bd->IndustryId() != IID_BaseAcademy)
			continue;
		if(bd->IsUnderConstruction())
			continue;
		citizens += bd->Residents();
		quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
		bd->IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
		if(homesLarge + homesMedium + homesSmall > 0xffff)
			homes += 0xffff;
		else
			homes += homesLarge + homesMedium + homesSmall;
	}
	return citizens;
}

