DaVehicle* DaBd::FindNewVehicle(COMMODITYID vehicleCID)
{
	// Buildings and spacecraft only fetch vehicles from certain buildings.
	VEHICLE_SPOT_TYPE spotType = DaVehicle::ParkingSpotType(vehicleCID);
	switch(spotType)
	{
	case SPOT_Invalid:
	case SPOT_Count:
	default:
		return 0;
	case SPOT_GroundVehicle:
		// Ground vehicles are fetched from vehicle factories.
		if(IndustryId() != IID_VehicleFactory)
			return 0;
		break;
	case SPOT_Rocket:
	case SPOT_SpaceVehicle:
		// Space vehicles are fetched from aircraft factories.
		if(IndustryId() != IID_AircraftFactory)
			return 0;
		break;
	case SPOT_WaterVehicle:
		// Water vehicles are fetched from ship yards.
		if(IndustryId() != IID_ShipYard)
			return 0;
		break;
	}

	// Search for nu vehicles in this building.
	DaAtomList subs;
	ListNormalSubatoms(subs);
	for(DaAtomList::const_iterator it = subs.cbegin(); it != subs.cend(); it++)
	{
		DaVehicle* vehicle = dynamic_cast<DaVehicle*>(*it);
		if(!vehicle)
			continue;
		if(vehicle->CommodityId() != vehicleCID)
			continue;
		if(!vehicle->CanFetch(spotType))
			continue;
		return vehicle;
	}
	return 0;
}

DaVehicle* DaBd::FindNewVehicleType(VEHICLE_SPOT_TYPE spotType, const DaBd* fetcher)
{
	// Buildings and spacecraft only fetch vehicles from certain buildings.
	switch(spotType)
	{
	case SPOT_Invalid:
	case SPOT_Count:
	default:
		return 0;
	case SPOT_GroundVehicle:
		// Ground vehicles are fetched from vehicle factories.
		if(IndustryId() != IID_VehicleFactory)
			return 0;
		break;
	case SPOT_Rocket:
	case SPOT_SpaceVehicle:
		// Space vehicles are fetched from aircraft factories.
		if(IndustryId() != IID_AircraftFactory)
			return 0;
		break;
	case SPOT_WaterVehicle:
		// Water vehicles are fetched from ship yards.
		if(IndustryId() != IID_ShipYard)
			return 0;
		break;
	}

	// Search for nu vehicles in this building.
	DaAtomList subs;
	ListNormalSubatoms(subs);
	for(DaAtomList::const_iterator it = subs.cbegin(); it != subs.cend(); it++)
	{
		DaVehicle* vehicle = dynamic_cast<DaVehicle*>(*it);
		if(vehicle)
		{
			if(fetcher)
			{
				// Fetcher is a building.
				if(!vehicle->CanBdFetch(spotType, fetcher))
					continue;
			}
			else
			{
				// Fetcher is a spacecraft.
				if(!vehicle->CanFetch(spotType))
					continue;
			}
			return vehicle;
		}
	}
	return 0;
}

void DaBd::ListDesignsRecursive(QSet<quint32>& bdDesigns, QSet<quint32>& scDesigns) const
{
	// Building design.
	quint32 designId = DesignId();
	if(designId)
		bdDesigns.insert(designId);

	// Designs I am making.
	quint32 makingDesignId = MakingDesignId();
	if(makingDesignId)
		scDesigns.insert(makingDesignId);
	DaCapsule::ListDesignsRecursive(bdDesigns, scDesigns);
}

bool DaBd::IsDamaged() const
{
	m_DamageLock.lockForRead();
	bool v = m_Damage.IsDamaged();
	m_DamageLock.unlock();
	return v;
}

bool DaBd::IsDamagedHeavily() const
{
	quint32 curHits = HitsDamageStructural();
	if(!curHits)
		return false;	// No damage.
	quint32 maxHits = DesignHitsStructural();
	if(!maxHits)
		return false;	// No health?
	return curHits >= maxHits * 9 / 10;	// 90% damage shows red health text; let's use that threshold.
}

void DaBd::RepairDamage()
{
	if(!IsDamaged())
		return;	// Not damaged.
	if(Morale() < 0)
		return;	// Nobody fixes anything when morale is negative.

	// Calculate the number of people who are available to perform repairs on this building.
	unsigned int repairWorkers = Workers() / 3;
	if(!repairWorkers)
		repairWorkers = 1;

	// Locate construction material.
	// The damage object does not record broken parts for buildings, only hit points. We will take building materials now to
	// do the repairs so parts are always required.
	COMMODITYID hullModule = SystemModule(SYS_Hull);
	COMMODITYID hullMaterial = HullModuleMaterial(hullModule);
	quint32 countAvail = CommunityRawCount(hullMaterial, 0);
	if(!countAvail)
		return;	// No repair material available.
	if(repairWorkers > countAvail)
		repairWorkers = countAvail;	// Limit workers to the amount of materials available, one per worker.

	// Repair a hit point of damage.
	m_DamageLock.lockForWrite();
	m_Damage.Repair(repairWorkers * AuDamage::HitsPerPart());	// Each workers installs one new part.
	bool v = m_Damage.IsDamaged();
	m_DamageLock.unlock();

	// When no longer damaged, my fire goes out.
	if(!v)
		RepairConditions();
	DamageStateChanged();

	// Remove the repair materials.
	CommunityRawRemove(hullMaterial, 0, repairWorkers);
}

int DaBd::FireProbability() const
{
	quint32 maxHits = DesignHitsStructural();
	if(!maxHits)
		return 0;
	quint32 dmgHits = HitsDamageStructural();
	switch(SystemModule(SYS_Hull))
	{
	case CID_WoodHullModule:
		return 16 + 84 * dmgHits / maxHits;	// 16 to 100% probability as damage increases from 0 to 100%.
	case CID_LumberHullModule:
		return 8 + 72 * dmgHits / maxHits;	// 8 to 90% probability as damage increases from 0 to 100%.
	case CID_StoneHullModule:
		return 4 + 76 * dmgHits / maxHits;	// 4 to 80% probability as damage increases from 0 to 100%.
	case CID_MetalHullModule:
		return 2 + 68 * dmgHits / maxHits;	// 2 to 70% probability as damage increases from 0 to 100%.
	case CID_MagmiumHullModule:
		return 1 + 59 * dmgHits / maxHits;	// 1 to 60% probability as damage increases from 0 to 100%.
	case CID_VulciumHullModule:
		return 50 * dmgHits / maxHits;		// 0 to 50% probability as damage increases from 0 to 100%.
	case CID_AdamantineHullModule:
		return 40 * dmgHits / maxHits;		// 0 to 40% probability as damage increases from 0 to 100%.
	default:
		return 0;
	}
}

void DaBd::CallFireStation()
{
	int fireFighters;
	if(IsMilitary())
	{
		// Military buildings fight their own fires.
		fireFighters = Residents() + Workers() + 1;
	}
	else
	{
		// Civilians benefit from a fire station.
		fireFighters = 0;
		DaWorld* world = FindParentPlanetInEnv();
		if(world)
		{
			m_TradeConnectionsLock.lockForRead();
			for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
			{
				if(!(*ci & CON_Road))
					continue;					// Only care about buildings connected by road.
				DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
				if(!bd)
					continue;
				if(!bd->InCommunityBroker(EmpireId()))
					continue;
				fireFighters = bd->FireFighterResponse();
				if(fireFighters)
					break;
			}
			m_TradeConnectionsLock.unlock();
		}
		fireFighters++;	// A good samaritan.
		if(Residents())
			fireFighters++;	// A brave resident.
		if(Workers())
			fireFighters++;	// A heroic worker.
	}
	if(g_Au.Dice().Roll(1,100) <= fireFighters)
		RepairConditions();
}

quint32 DaBd::FireFighterResponse()
{
	if(IndustryId() != IID_FireDepartment)
		return 0;
	quint16 workers = Workers();
	if(!workers)
		return 0;
	m_FireStationLock.lockForRead();
	int lastCall = m_FireStationCalled.ElapsedMin();
	m_FireStationLock.unlock();
	if(lastCall < 4)
		return 0;
	m_FireStationLock.lockForWrite();
	m_FireStationCalled.Set();
	m_FireStationLock.unlock();
	return workers;
}

void DaBd::RenderScGlobe(AuAtomRenderInfo& ari, AuModelMatrixHash& rmod, const DaPerson* sceneAtom, RENDERPASS pass)
{
	// Globe over the horizon effect is desirable when at a globe.
	// Globe position in eye space is needed to calculate sun over-the-horizon effect.
	AuPoint globeP = rmod.Matrix(ParentId()).Translation();
	ari.re->GLSL().ScGlobeShader().SetGlobeLocation(globeP);

	// Suns
	if(m_AV->m_SunsBlocked)
		for(int sunIndex=0; sunIndex<MAX_SUNS; sunIndex++)
			ari.re->GLSL().ScGlobeShader().SetSunEnabled(sunIndex, false);

	const AuMatrix4x4& model = rmod.Matrix(Id());
	if(pass == PASS_Far || pass == PASS_Near)
		RenderScShader(&ari.re->GLSL().ScGlobeShader(), ari, model, sceneAtom);
	else
		RenderScShaderBlend(&ari.re->GLSL().ScGlobeShader(), ari, model, sceneAtom);

	// Restore shader states.
	if(m_AV->m_SunsBlocked)
		for(int sunIndex=0; sunIndex<MAX_SUNS; sunIndex++)
		{
			const AuGLSun& sun = ari.re->Sun(sunIndex);
			ari.re->GLSL().ScGlobeShader().SetSunEnabled(sunIndex, sun.m_Enabled);
		}
}

void DaBd::RenderScGlobeFog(AuAtomRenderInfo& ari, AuModelMatrixHash& rmod, const DaPerson* sceneAtom, RENDERPASS pass)
{
	// Globe over the horizon effect is desirable when at a globe.
	// Globe position in eye space is needed to calculate sun over-the-horizon effect.
	//qDebug() << "DaBd::RenderScGlobeFog" << Id() << Name() << "fog" << m_FogR << m_FogG << m_FogB;
	AuPoint globeP = rmod.Matrix(ParentId()).Translation();
	ari.re->GLSL().ScGlobeFogShader().SetFog(m_AV->m_FogDensity, m_AV->m_FogR, m_AV->m_FogG, m_AV->m_FogB);
	ari.re->GLSL().ScGlobeFogShader().SetGlobeLocation(globeP);

	// Suns
	if(m_AV->m_SunsBlocked)
		for(int sunIndex=0; sunIndex<MAX_SUNS; sunIndex++)
			ari.re->GLSL().ScGlobeFogShader().SetSunEnabled(sunIndex, false);

	const AuMatrix4x4& model = rmod.Matrix(Id());
	if(pass == PASS_Far || pass == PASS_Near)
		RenderScShader(&ari.re->GLSL().ScGlobeFogShader(), ari, model, sceneAtom);
	else
		RenderScShaderBlend(&ari.re->GLSL().ScGlobeFogShader(), ari, model, sceneAtom);

	// Restore shader states.
	if(m_AV->m_SunsBlocked)
		for(int sunIndex=0; sunIndex<MAX_SUNS; sunIndex++)
		{
			const AuGLSun& sun = ari.re->Sun(sunIndex);
			ari.re->GLSL().ScGlobeFogShader().SetSunEnabled(sunIndex, sun.m_Enabled);
		}
}

void DaBd::RenderScRingworld(AuAtomRenderInfo& ari, AuModelMatrixHash& rmod, const DaPerson* sceneAtom, RENDERPASS pass)
{
	const DaWorldRingSection* rsworld = dynamic_cast<const DaWorldRingSection*>(Parent());
	if(!rsworld)
		return;

	// Ringworld shadow panel shadow is desirable when at a ringworld.
	// Eye location is needed by ringworld shaders.
	const AuMatrix4x4& model = rmod.Matrix(Id());
	ari.re->GLSL().ScRingworldShader().SetEyeLocation(model.UnProject(ari.re->EyeLocation()));

	// Suns
	for(int sunIndex=0; sunIndex<MAX_SUNS; sunIndex++)
	{
		const AuGLSun& sun = ari.re->Sun(sunIndex);
		ari.re->GLSL().ScRingworldShader().SetSunEnabled(sunIndex, sun.m_Enabled && !m_AV->m_SunsBlocked);
		ari.re->GLSL().ScRingworldShader().SetSunShadowAngle(sunIndex, rsworld->ShadowPanelSunAngle(sun.m_ShadowAngle));
	}

	if(pass == PASS_Far || pass == PASS_Near)
		RenderScShader(&ari.re->GLSL().ScRingworldShader(), ari, model, sceneAtom);
	else
		RenderScShaderBlend(&ari.re->GLSL().ScRingworldShader(), ari, model, sceneAtom);

	// Restore shader states.
	if(m_AV->m_SunsBlocked)
		for(int sunIndex=0; sunIndex<MAX_SUNS; sunIndex++)
		{
			const AuGLSun& sun = ari.re->Sun(sunIndex);
			ari.re->GLSL().ScRingworldShader().SetSunEnabled(sunIndex, sun.m_Enabled);
		}
}

