void DaBd::RenderScShader(AuGLSLScBase* shader, AuAtomRenderInfo& ari, const AuMatrix4x4& model, const DaPerson* sceneAtom)
{
	shader->SetModelView(model);
	shader->SetSurfaceTextures(m_AV->m_SurfaceTex);
	shader->SetGlowDiscard(0,0,0, .01f);
	shader->SetVertAlpha(1);
	shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
	shader->SetAmbientLightUp(m_AV->m_AmbientUp);
	if((IsUnderConstruction() && IndustryId() != IID_Fence) || IsDestroyed())
	{
		if(m_AV->m_BoardsVAO.VAO())
			m_AV->m_BoardsVAO.DrawSc(*shader, EffectTextures(), m_AV->m_HullEffectAppl);
		return;
	}

	if(m_AV->m_InsideVisible)
	{
		// Disable my own external light when rendering interior rooms.
		// Render lifts at their current stops.
		if(!m_AV->m_LiftOpaqueVAOs.empty())
			RenderLiftVAOs(m_AV->m_LiftOpaqueVAOs, model, ari, *shader);

		// Render rooms according to their interior lighting.
		if(!m_AV->m_RoomOpaqueVAOs.empty())
			RenderRoomVAOs(m_AV->m_RoomOpaqueVAOs, *shader);
		if(!m_AV->m_IntRoomOpaqueVAOs.empty())
			RenderInteriorRoomVAOs(m_AV->m_IntRoomOpaqueVAOs, ari, *shader);

		if(m_AV->m_IsAboard)
		{
			// Viewer is aboard so exterior light remains disabled while rendering my own windows and doors.
			// Render translucent windows; they use the texture palette that we have already configured.
			if(!m_AV->m_WindowTranslucentVAOs.empty())
				RenderWindowVAOs(m_AV->m_WindowTranslucentVAOs, *shader);

			// Render current states of doors.
			if(!m_AV->m_DoorOpaqueVAOs.empty())
				RenderDoorVAOs(m_AV->m_DoorOpaqueVAOs, *shader, sceneAtom->BdRoomId(), m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
			if(!m_AV->m_IntDoorOpaqueVAOs.empty())
				RenderInteriorDoorVAOs(m_AV->m_IntDoorOpaqueVAOs, ari, *shader, sceneAtom->BdRoomId(), m_AV->m_AmbientR, m_AV->m_AmbientG,
						m_AV->m_AmbientB);
			else
				shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB); // Restore ambient lighting for exterior.
		}
		else
		{
			// Viewer is not aboard so restore exterior light before rendering doors and windows.
			// Render translucent windows; they use the texture palette that we have already configured.
			if(!m_AV->m_WindowTranslucentVAOs.empty())
				RenderWindowVAOs(m_AV->m_WindowTranslucentVAOs, *shader);

			// Render current states of doors.
			if(!m_AV->m_DoorOpaqueVAOs.empty())
				RenderDoorVAOs(m_AV->m_DoorOpaqueVAOs, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
			if(!m_AV->m_IntDoorOpaqueVAOs.empty())
				RenderInteriorDoorVAOs(m_AV->m_IntDoorOpaqueVAOs, ari, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
			else
				shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB); // Restore ambient lighting for exterior.
		}
	}
	else
	{
		// Inside is not visible.
		// Render translucent windows; they use the texture palette that we have already configured.
		if(!m_AV->m_WindowTranslucentVAOs.empty())
			RenderWindowVAOs(m_AV->m_WindowTranslucentVAOs, *shader);

		// Render current states of doors.
		if(!m_AV->m_DoorOpaqueVAOs.empty())
			RenderDoorVAOs(m_AV->m_DoorOpaqueVAOs, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
		if(!m_AV->m_IntDoorOpaqueVAOs.empty())
			RenderInteriorDoorVAOs(m_AV->m_IntDoorOpaqueVAOs, ari, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
		else
			shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB); // Restore ambient lighting for exterior.
	}

	// Render non-window parts that use the texture palette that we have configured.
	if(!m_AV->m_OpaqueVAOs.empty())
		RenderDesignVAOs(m_AV->m_OpaqueVAOs, *shader);

	// Render light lenses.
	if(!m_AV->m_LensBeaconOpaqueVAOs.empty())
		RenderLensVAOs(m_AV->m_LensBeaconOpaqueVAOs, m_AV->m_LensBeaconGlows, *shader, true);
	if(!m_AV->m_LensHeadlightOpaqueVAOs.empty())
	{
		if(HasPower())
			RenderLensVAOs(m_AV->m_LensHeadlightOpaqueVAOs, m_AV->m_LensHeadlightGlows, *shader, IsStreetLightOn());
		else
			RenderLensVAOs(m_AV->m_LensHeadlightOpaqueVAOs, m_AV->m_LensDimLightGlows, *shader, IsStreetLightOn());
	}
	if(!m_AV->m_LensNavOpaqueVAOs.empty())
		RenderLensVAOs(m_AV->m_LensNavOpaqueVAOs, m_AV->m_LensNavGlows, *shader, m_AV->m_IsDark);
	if(!m_AV->m_LensStrobeOpaqueVAOs.empty())
		RenderLensVAOs(m_AV->m_LensStrobeOpaqueVAOs, m_AV->m_LensStrobeGlows, *shader, m_AV->m_StrobesLit);

	// Render current states of turrets.
	if(!m_AV->m_TurBaseOpaqueVAOs.empty())
		RenderTurretBaseVAOs(m_AV->m_TurBaseOpaqueVAOs, model, *shader);
	if(!m_AV->m_TurGunOpaqueVAOs.empty())
		RenderTurretGunVAOs(m_AV->m_TurGunOpaqueVAOs, model, *shader);

	if(!m_AV->m_DecalOpaqueVAOs.empty() ||
			!m_AV->m_OwnOpaqueVAOs.empty() ||
			!m_AV->m_OwnDecalOpaqueVAOs.empty())
	{
		// Depth test and polygon offset are changed to enable coplanar render of decals.
		// This includes own texture things, such as icons, screens and sketches.
		// glPolygonOffset(0.0f,1.0f); will unconditionally offset all polygons by one.
		// glPolygonOffset(1.0f,0.0f); will offset polys with a depth slope of one (rotated 45? into the screen) by one, polys
		// parallel to the eye plane it won't offset at all.
		ari.re->glEnable(GL_POLYGON_OFFSET_FILL);
		ari.re->glPolygonOffset(-1.f, 0);
		ari.re->glDepthFunc(GL_LEQUAL);

		// Render decals that use the texture palette that we have configured.
		if(!m_AV->m_DecalOpaqueVAOs.empty() ||
				!m_AV->m_OwnDecalOpaqueVAOs.empty())
		{
			// Decals are always blended.
			ari.re->glEnable(GL_BLEND);
			ari.re->glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
			// Render decals that use the texture palette that we have configured.
			if(!m_AV->m_DecalOpaqueVAOs.empty())
				RenderDesignVAOs(m_AV->m_DecalOpaqueVAOs, *shader);
			// Render decals that have their own textures.
			if(!m_AV->m_OwnDecalOpaqueVAOs.empty())
				RenderOwnTextureVAOs(m_AV->m_OwnDecalOpaqueVAOs, *shader);
			ari.re->glDisable(GL_BLEND);
		}

		// Render parts that have their own textures.
		// So far, own texture things are icons, screens and sketches. We like to see them from the back too, mainly the
		// sketches.
		if(!m_AV->m_OwnOpaqueVAOs.empty())
		{
			ari.re->glDisable(GL_CULL_FACE);
			RenderOwnTextureVAOs(m_AV->m_OwnOpaqueVAOs, *shader);
			ari.re->glEnable(GL_CULL_FACE);
		}

		ari.re->glDepthFunc(GL_LESS);
		ari.re->glDisable(GL_POLYGON_OFFSET_FILL);
	}

	for(QHash<quint32, AuScVAO>::iterator vi = m_AV->m_FenceCustomOpaqueVAO.begin(); vi != m_AV->m_FenceCustomOpaqueVAO.end(); vi++)
	{
		// Configure texture palette for custom fences and walls.
		QHash<quint32, AuTexturePalette>::iterator ti = m_AV->m_FenceCustomTex.find(vi.key());
		if(ti != m_AV->m_FenceCustomTex.end())
			shader->SetSurfaceTextures(*ti);
		(*vi).DrawSc(*shader, EffectTextures(), m_AV->m_HullEffectAppl);
	}

	if(m_AV->m_FenceStyleOpaqueVAO.VAO())
	{
		// Configure texture palette for fences and walls that use default styles.
		AuTexturePalette surfaceTex;
		AuDesign::FenceTexturePalette(*ari.re, surfaceTex);
		shader->SetSurfaceTextures(surfaceTex);
		m_AV->m_FenceStyleOpaqueVAO.DrawSc(*shader, EffectTextures(), m_AV->m_HullEffectAppl);
	}
}

void DaBd::RenderScShaderBlend(AuGLSLScBase* shader, AuAtomRenderInfo& ari, const AuMatrix4x4& model,
		const DaPerson* sceneAtom)
{
	shader->SetModelView(model);
	shader->SetSurfaceTextures(m_AV->m_SurfaceTex);
	shader->SetGlowDiscard(0,0,0, .01f);
	shader->SetVertAlpha(1);
	shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
	shader->SetAmbientLightUp(m_AV->m_AmbientUp);
	if((IsUnderConstruction() && IndustryId() != IID_Fence) || IsDestroyed())
		return;

	if(m_AV->m_InsideVisible)
	{
		// Turn on blending for transparency.
		ari.re->glEnable(GL_BLEND);
		ari.re->glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);

		// Render lifts at their current stops.
		if(!m_AV->m_LiftTransparentVAOs.empty())
			RenderLiftVAOs(m_AV->m_LiftTransparentVAOs, model, ari, *shader);

		// Render rooms according to their interior lighting.
		if(!m_AV->m_RoomTransparentVAOs.empty())
			RenderRoomVAOs(m_AV->m_RoomTransparentVAOs, *shader);
		if(!m_AV->m_IntRoomTransparentVAOs.empty())
			RenderInteriorRoomVAOs(m_AV->m_IntRoomTransparentVAOs, ari, *shader);

		if(m_AV->m_IsAboard)
		{
			// Viewer is aboard so exterior light remains disabled while rendering my own windows and doors.
			// Render transparent windows; they use the texture palette that we have already configured.
			if(!m_AV->m_WindowTransparentVAOs.empty())
				RenderWindowVAOs(m_AV->m_WindowTransparentVAOs, *shader);

			// Render current states of doors.
			if(!m_AV->m_DoorTransparentVAOs.empty())
				RenderDoorVAOs(m_AV->m_DoorTransparentVAOs, *shader, sceneAtom->BdRoomId(), m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
			if(!m_AV->m_IntDoorTransparentVAOs.empty())
				RenderInteriorDoorVAOs(m_AV->m_IntDoorTransparentVAOs, ari, *shader, sceneAtom->BdRoomId(), m_AV->m_AmbientR, m_AV->m_AmbientG,
						m_AV->m_AmbientB);
			else
				shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB); // Restore ambient lighting for exterior.
		}
		else
		{
			// Viewer is not aboard so restore exterior light before rendering doors and windows.
			// Restore exterior light before rendering doors and windows.
			// Render transparent windows; they use the texture palette that we have already configured.
			if(!m_AV->m_WindowTransparentVAOs.empty())
				RenderWindowVAOs(m_AV->m_WindowTransparentVAOs, *shader);

			// Render current states of doors.
			if(!m_AV->m_DoorTransparentVAOs.empty())
				RenderDoorVAOs(m_AV->m_DoorTransparentVAOs, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
			if(!m_AV->m_IntDoorTransparentVAOs.empty())
				RenderInteriorDoorVAOs(m_AV->m_IntDoorTransparentVAOs, ari, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
			else
				shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB); // Restore ambient lighting for exterior.
		}
	}
	else
	{
		// Inside is not visible.
		// Inside is not visible so render windows opaque; they use the texture palette that we have already configured.
		if(!m_AV->m_WindowTransparentVAOs.empty())
			RenderWindowVAOs(m_AV->m_WindowTransparentVAOs, *shader);

		// Turn on blending for transparency.
		ari.re->glEnable(GL_BLEND);
		ari.re->glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);

		// Render current states of doors.
		if(!m_AV->m_DoorTransparentVAOs.empty())
			RenderDoorVAOs(m_AV->m_DoorTransparentVAOs, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
		if(!m_AV->m_IntDoorTransparentVAOs.empty())
			RenderInteriorDoorVAOs(m_AV->m_IntDoorTransparentVAOs, ari, *shader, 0, m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB);
		else
			shader->SetAmbientLight(m_AV->m_AmbientR, m_AV->m_AmbientG, m_AV->m_AmbientB); // Restore ambient lighting for exterior.
	}

	// Render non-window parts that use the texture palette that we have configured.
	if(!m_AV->m_TransparentVAOs.empty())
		RenderDesignVAOs(m_AV->m_TransparentVAOs, *shader);

	// Render light lenses.
	if(!m_AV->m_LensBeaconTransparentVAOs.empty())
		RenderLensVAOs(m_AV->m_LensBeaconTransparentVAOs, m_AV->m_LensBeaconGlows, *shader, true);
	if(!m_AV->m_LensHeadlightTransparentVAOs.empty())
	{
		if(HasPower())
			RenderLensVAOs(m_AV->m_LensHeadlightTransparentVAOs, m_AV->m_LensHeadlightGlows, *shader, IsStreetLightOn());
		else
			RenderLensVAOs(m_AV->m_LensHeadlightTransparentVAOs, m_AV->m_LensDimLightGlows, *shader, IsStreetLightOn());
	}
	if(!m_AV->m_LensNavTransparentVAOs.empty())
		RenderLensVAOs(m_AV->m_LensNavTransparentVAOs, m_AV->m_LensNavGlows, *shader, m_AV->m_IsDark);
	if(!m_AV->m_LensStrobeTransparentVAOs.empty())
		RenderLensVAOs(m_AV->m_LensStrobeTransparentVAOs, m_AV->m_LensStrobeGlows, *shader, m_AV->m_StrobesLit);

	// Render current states of turrets.
	if(!m_AV->m_TurBaseTransparentVAOs.empty())
		RenderTurretBaseVAOs(m_AV->m_TurBaseTransparentVAOs, model, *shader);
	if(!m_AV->m_TurGunTransparentVAOs.empty())
		RenderTurretGunVAOs(m_AV->m_TurGunTransparentVAOs, model, *shader);

	if(!m_AV->m_DecalTransparentVAOs.empty() ||
			!m_AV->m_OwnTransparentVAOs.empty() ||
			!m_AV->m_OwnDecalTransparentVAOs.empty())
	{
		// Depth test and polygon offset are changed to enable coplanar render of decals.
		// This includes own texture things, such as icons, screens and sketches.
		ari.re->glEnable(GL_POLYGON_OFFSET_FILL);
		ari.re->glPolygonOffset(-1.f, 0);
		ari.re->glDepthFunc(GL_LEQUAL);

		// Render decals that use the texture palette that we have configured.
		// Decals are always blended; it's already enabled in transparent pass.
		if(!m_AV->m_DecalTransparentVAOs.empty())
			RenderDesignVAOs(m_AV->m_DecalTransparentVAOs, *shader);

		// Render decals that have their own textures.
		if(!m_AV->m_OwnDecalTransparentVAOs.empty())
			RenderOwnTextureVAOs(m_AV->m_OwnDecalTransparentVAOs, *shader);

		// Render parts that have their own textures.
		// So far, own texture things are icons, screens and sketches. We like to see them from the back too, mainly the
		// sketches.
		if(!m_AV->m_OwnTransparentVAOs.empty())
		{
			ari.re->glDisable(GL_CULL_FACE);
			RenderOwnTextureVAOs(m_AV->m_OwnTransparentVAOs, *shader);
			ari.re->glEnable(GL_CULL_FACE);
		}

		ari.re->glDepthFunc(GL_LESS);
		ari.re->glDisable(GL_POLYGON_OFFSET_FILL);
	}

	for(QHash<quint32, AuScVAO>::iterator vi = m_AV->m_FenceCustomTransparentVAO.begin(); vi != m_AV->m_FenceCustomTransparentVAO.end(); vi++)
	{
		// Configure texture palette for custom fences and walls.
		QHash<quint32, AuTexturePalette>::iterator ti = m_AV->m_FenceCustomTex.find(vi.key());
		if(ti != m_AV->m_FenceCustomTex.end())
			shader->SetSurfaceTextures(*ti);
		(*vi).DrawSc(*shader, EffectTextures(), m_AV->m_HullEffectAppl);
	}

	if(m_AV->m_FenceStyleTransparentVAO.VAO())
	{
		// Configure texture palette for fences and walls that use default styles.
		AuTexturePalette surfaceTex;
		AuDesign::FenceTexturePalette(*ari.re, surfaceTex);
		shader->SetSurfaceTextures(surfaceTex);
		m_AV->m_FenceStyleTransparentVAO.DrawSc(*shader, EffectTextures(), m_AV->m_HullEffectAppl);
	}

	ari.re->glDisable(GL_BLEND);
}

