double DaBd::JurisdictionRadius() const
{
	if(IndustryId() != IID_PoliceDepartment && IndustryId() != IID_Capitol)
		return 0;
	m_DesignLock.lockForRead();
	double jr;
	if(IndustryId() == IID_PoliceDepartment)
		jr = m_Design.PoliceJurisdictionRadius();
	else
		jr = m_Design.CapitolJurisdictionRadius();
	m_DesignLock.unlock();
	return jr;
}

void DaBd::LockLiftContents(quint16 liftId, DaAtomList& atomsInLift)
{
	AuIdList subIds;
	ListSubatomIds(subIds);
	for(AuIdList::const_iterator ii = subIds.cbegin(); ii != subIds.cend(); ii++)
	{
		DaAtom* atom = FindSubatomId(*ii);
		if(!atom)
			continue;
		if(!atom->DoesQueryEnvironment())
			continue;						// Designer?
		quint16 roomId = atom->BdRoomId();
		if(roomId != liftId)
			continue;
		atomsInLift.append(atom);			// The atom will be moved in the lift.
	}
}

bool DaBd::CommunityEatFood(ECOROLE workerEcoRole, quint32 foodToEat, bool& consumedLiquor)
{
	consumedLiquor = false;
	if(!foodToEat)
		return true;	// Satisfied if no food wanted, I guess.
	DaWorld* world = FindParentPlanetInEnv();
	if(!world)
		return false;
	quint32 liquorToDrink = foodToEat;
	m_TradeConnectionsLock.lockForRead();
	for(QHash<AuId, int>::const_iterator ci = m_TradeConnections.cbegin(); ci != m_TradeConnections.cend(); ci++)
	{
		if(!(*ci & CON_Road))
			continue;					// Only care about buildings connected by road.
		DaBd* bd = dynamic_cast<DaBd*>(world->FindIdRecursive(ci.key()));
		if(!bd)
			continue;
		if(!InCommunity(*bd))
			continue;
		// Eat from the output stockpile of every building in my community.
		quint32 liquorDrank;
		quint32 foodEaten = bd->EatMeal(foodToEat, workerEcoRole, liquorToDrink, liquorDrank);
		if(foodEaten)
			foodToEat -= foodEaten;
		if(liquorDrank)
		{
			liquorToDrink -= liquorDrank;
			consumedLiquor = true;
		}
		if(!foodToEat && !liquorToDrink)
			break;
	}
	m_TradeConnectionsLock.unlock();
	return(foodToEat > 0 ? false : true);	// Supply inadequate if food still needed.
}

quint32 DaBd::EatMeal(quint32 foodToEat, ECOROLE workerEcoRole, quint32 liquorToDrink, quint32& liquorDrank)
{
	AuItemHash& stock = LockCargoForWrite();
	quint32 foodEaten = stock.EatMeal(foodToEat, workerEcoRole, liquorToDrink, liquorDrank);
	if(foodEaten || liquorDrank)
		m_tmCargoChange.Set();
	UnlockCargo();
	if(foodEaten || liquorDrank)
		SetModified();	// Trigger update due to inventory change.
	return foodEaten;
}

quint32 DaBd::Generators() const
{
	m_DesignLock.lockForRead();
	quint32 lounges = m_Design.GeneratorJobs();
	m_DesignLock.unlock();
	return lounges;
}

