void DaBd::DetectWarpSignatureRecursive(const AuId& systemId, quint32 warpFactors, const AuPoint& galaxyLoc)
{
	// Ignore emissions of I have no sensors.
	if(!HasSensors() || !HasPower())
		return;													// This building has no sensors.

	// Empire without warp drive cannot detect warp signatures.
	quint32 empireId = EmpireId();
	const DgData& gd = g_Au.LockDataForRead();
	bool hasWarp = gd.EmpireHasWarpTechnology(empireId);
	g_Au.UnlockData();
	if(!hasWarp)
		return;

	// Calculate vector to the location that emitted the signal.
	// I only receive signals emitted from within my own galaxy.
	const DaGalaxy* galaxy = FindParentGalaxy();
	if(!galaxy)
		return;
	AuPoint myGalaxyLoc;
	GetLocationRelativeToParent(myGalaxyLoc, galaxy);
	AuPoint vecToSystem = galaxyLoc - myGalaxyLoc;				// Vector to system, in parsecs.

	// Crossing zones dampens the signal.
	quint32 warpSignal = warpFactors * 10;	// Lets work with 10 units of signal for every warp factor engaged.
	int myZone;
	if(myGalaxyLoc.z > 10)
		myZone = 1;												// I am in the upper veil.
	else if(myGalaxyLoc.z < 0)
		myZone = -1;											// I am in the lower veil.
	else
		myZone = 0;												// I am in the neutral zone.
	int signalZone;
	if(galaxyLoc.z > 10)
		signalZone = 1;											// Signal emanated from the upper veil.
	else if(galaxyLoc.z < 0)
		signalZone = -1;										// Signal emanated from the lower veil.
	else
		signalZone = 0;											// Signal emanated from the neutral zone.
	int relZone = abs(myZone - signalZone);						// 0, 1 or 2
	if(relZone)
	{
		warpSignal /= (relZone * 2);							// 1/2 signal lost per zone
		if(!warpSignal)
			return;
	}

	// Calculate emitter detection range based on warp signal and the capability of my sensors.
	// A spaceport in an empire with warp technology will engage a warp drive at factor 1 once per hour.
	// A system emits its warp signature signal every hour.
	// At 10pc per warp factor, a drive engaged at warp 9 can be detected 90pc away, or 9 sectors.
	quint32 emissionRange = warpSignal;							// Range the emission can be detected in pc.
	quint32 sensorRange = SensorRangeDeepSpace();				// Range my sensors can detect warp signatures, in parsecs.
	quint32 effectiveRange;
	if(emissionRange < sensorRange)
		effectiveRange = emissionRange;							// Effective range is limited by the emitter's weak signal.
	else
		effectiveRange = sensorRange;							// Effective range is limited by my sensor range.

	//qDebug() << "DaBd::DetectCityRecursive" << Id() << Name() << "warpSignal" << warpSignal << "emitRange"
		//<< cityEmissionRange << "sensorRange" << sensorRange << "effRange" << effectiveRange << "vecToSystem" << vecToSystem;

	// Quickly rule out cities that are way too far away.
	if(fabs(vecToSystem.x) > effectiveRange || fabs(vecToSystem.y) > effectiveRange || fabs(vecToSystem.z) > effectiveRange)
		return;							// Way out of range.

	// Do some math.
	double dist2 = vecToSystem.Length2();
	if(dist2 > effectiveRange*effectiveRange)
		return;							// Out of range.

	// The emitter is in range to detect.
	//qDebug() << "DaBd::DetectCityRecursive" << Id() << Name() << "power use detected, system" << citySystemId << "my empire"
		//<< empireId;
	emit WarpSignatureDetected(systemId, warpSignal, empireId);
}

float DaBd::RelativeAudioGain(const DaPerson* sceneAtom) const
{
	if(sceneAtom->IsInBd() && Is(sceneAtom->BdId()))
	{
		if(sceneAtom->HelmetClosed())
			return .5f;
		return 1;
	}
	return DaCapsule::RelativeAudioGain(sceneAtom);
}

void DaBd::FindClosestShipThreatRecursive(const AuId& shipId, int shipDomain, const AuId& shipWorldId, quint32 shipEmpire,
		SHIELD_POLICY shieldPolicy, const AuPoint& shipSysLoc, float sensorRange, const DaAtom*& targetAtom,
		double& targetRange) const
{
	// Civilian buildings are not a threat to spacecraft.
	//if(!IsMilitary())
		//return;
	if(IndustryId() != IID_BaseWeapon && IndustryId() != IID_BaseGuardTower)
		return;
	DaCapsule::FindClosestShipThreatRecursive(shipId, shipDomain, shipWorldId, shipEmpire, shieldPolicy, shipSysLoc, sensorRange,
			targetAtom, targetRange);
}

void DaBd::EmpireDeleted(quint32 empireId)
{
	if(EmpireId() != empireId)
		return;
	// Empire is not supposed to be deleted while it has cities.
	switch(IndustryId())
	{
	case IID_Capitol:
	case IID_PoliceDepartment:
	case IID_Bank:
	case IID_BaseAcademy:
	case IID_BaseAirTerminal:
	case IID_BaseBarracks:
	case IID_BaseDock:
	case IID_BaseGuardPost:
	case IID_BaseGuardTower:
	case IID_BaseHeadquarters:
	case IID_BaseMarineBarracks:
	case IID_BaseMotorPool:
	case IID_BaseRadar:
	case IID_BaseShield:
	case IID_BaseWeapon:
		DamageAndDestroy(tr("empire deleted"));
		break;
	default:
		{
			quint32 nuEmpire = 0;
			const DaWorldLL* llworld = FindParentWorldInEnv();
			if(llworld)
			{
				quint32 claimEmpire = llworld->ClaimedByEmpire();
				if(claimEmpire && claimEmpire != empireId)
					nuEmpire = claimEmpire;
			}
			SetEmpireId(nuEmpire);
		}
		break;
	}
}

AuSpecies DaBd::TakeTransient()
{
	AuSpecies species;
	m_TransientLock.lockForWrite();
	QMap<AuSpecies, quint32>::iterator ti = m_TransientPopulation.begin();
	if(ti != m_TransientPopulation.end())
	{
		species = ti.key();
		(*ti)--;
		if(!(*ti))
			m_TransientPopulation.erase(ti);
	}
	m_TransientLock.unlock();
	SetModified(NOTIFY_Database);
	return species;
}

void DaBd::LogEvent(const AuEventLogEntry& le)
{
	m_EventLogLock.lock();
	m_EventLog->AddEventTrim(le);
	if(m_EventLog->size() > 20)
		qWarning() << "warning: DaBd::LogEvent" << Id() << Name() << le.Text() << "lots of events in queue" << m_EventLog->size();
	m_EventLogLock.unlock();
}

void DaBd::LogEvent(AuEventLogEntry::TYPE type, const QString& text, const AuId& atomId)
{
	LogEvent(AuEventLogEntry(type, text, atomId));
}

void DaBd::KilledByUnit(const DaUnit* killer)
{
	if(!killer->EmpireId())
		return;							// Killer is probably a wild animal.

	if(InArena())
		return;
	if(InDesignEnvironment())
		return;

	if(EmpireId() == killer->EmpireId())
		return;
	// Victim is from a different empire as the killer.

	// Victim's empire logs this as a diplomatic incident.
	const DaSolarSystem* system = dynamic_cast<const DaSolarSystem*>(FindEnvironmentAtom());
	if(!system)
		return;	// No parent solar system?

	GALAXY galaxy = Galaxy();
	const DaSector* sector = system->FindParentSector();
	const DaWorld* world = FindParentPlanetInEnv();
	QString sectorName = sector ? sector->Name() : "";
	QString systemName = system ? system->Name() : "";
	QString worldName = world ? world->Name() : "";

	AuId empireCapitol, galaxyCapitol, sectorCapitol;
	const DgData& gd = g_Au.LockDataForRead();
	if(gd.EmpireCapital(EmpireId(), empireCapitol))
	{
		const DaGalaxy* galaxy = FindParentGalaxy();
		if(galaxy)
			galaxyCapitol = gd.EmpireGalaxyCapital(EmpireId(), galaxy->Id());
		const DaSector* sector = FindParentSector();
		if(sector)
			sectorCapitol = gd.EmpireSectorCapital(EmpireId(), sector->Id());
	}
	g_Au.UnlockData();

	if(IndustryId() == IID_BaseHeadquarters)
	{
		AuDocBdMilitaryHQDestroyed doc(Name(), killer->Name(), galaxy, sectorName, systemName, worldName,
				CityName());
		emit GovDossierAddDocument(EmpireId(), killer->EmpireId(), doc.Pack());
	}
	else if(IsMilitary())
	{
		AuDocBdMilitaryDestroyed doc(Name(), killer->Name(), galaxy, sectorName, systemName, worldName,
				CityName());
		emit GovDossierAddDocument(EmpireId(), killer->EmpireId(), doc.Pack());
	}
	else if(Is(empireCapitol))
	{
		AuDocBdEmpireCapitolDestroyed doc(Name(), killer->Name(), galaxy, sectorName, systemName, worldName,
				CityName());
		emit GovDossierAddDocument(EmpireId(), killer->EmpireId(), doc.Pack());
	}
	else if(Is(galaxyCapitol))
	{
		AuDocBdGalaxyCapitolDestroyed doc(Name(), killer->Name(), galaxy, sectorName, systemName, worldName,
				CityName());
		emit GovDossierAddDocument(EmpireId(), killer->EmpireId(), doc.Pack());
	}
	else if(Is(sectorCapitol))
	{
		AuDocBdSectorCapitolDestroyed doc(Name(), killer->Name(), galaxy, sectorName, systemName, worldName,
				CityName());
		emit GovDossierAddDocument(EmpireId(), killer->EmpireId(), doc.Pack());
	}
	else if(IndustryId() == IID_Capitol)
	{
		AuDocBdCityCapitolDestroyed doc(Name(), killer->Name(), galaxy, sectorName, systemName, worldName, CityName());
		emit GovDossierAddDocument(EmpireId(), killer->EmpireId(), doc.Pack());
	}
	else
	{
		AuDocBdDestroyed doc(Name(), killer->Name(), galaxy, sectorName, systemName, worldName, CityName());
		emit GovDossierAddDocument(EmpireId(), killer->EmpireId(), doc.Pack());
	}
}

void DaBd::ReportAttacked(const QString& attackerName, quint32 attackerEmpire, const DaSolarSystem* system)
{
	if(InArena())
		return;
	if(InDesignEnvironment())
		return;
	if(EmpireId() == attackerEmpire)
		return;
	// Victim is from a different empire as the attacker.
	// Victim's empire logs this as a diplomatic incident.
	GALAXY galaxy = Galaxy();
	const DaSector* sector = system->FindParentSector();
	const DaWorld* world = FindParentPlanetInEnv();
	QString sectorName = sector ? sector->Name() : "";
	QString systemName = system ? system->Name() : "";
	QString worldName = world ? world->Name() : "";

	AuId empireCapitol, galaxyCapitol, sectorCapitol;
	const DgData& gd = g_Au.LockDataForRead();
	if(gd.EmpireCapital(EmpireId(), empireCapitol))
	{
		const DaGalaxy* galaxy = FindParentGalaxy();
		if(galaxy)
			galaxyCapitol = gd.EmpireGalaxyCapital(EmpireId(), galaxy->Id());
		const DaSector* sector = FindParentSector();
		if(sector)
			sectorCapitol = gd.EmpireSectorCapital(EmpireId(), sector->Id());
	}
	g_Au.UnlockData();

	if(IsMilitary())
	{
		AuDocBdMilitaryDamaged doc(Id(), Name(), attackerName, galaxy, sectorName, systemName, worldName, CityName());
		emit GovDossierAddDocument(EmpireId(), attackerEmpire, doc.Pack());
	}
	else
	{
		AuDocBdDamaged doc(Id(), Name(), attackerName, galaxy, sectorName, systemName, worldName, CityName());
		emit GovDossierAddDocument(EmpireId(), attackerEmpire, doc.Pack());
	}

	// Remember when we last tattled.
	m_CommLock.lockForWrite();
	m_tmSOS.restart();
	m_CommLock.unlock();
}

