void DaBd::SetEmpireId(quint32 idEmpire)
{
	if(Allegiance() != idEmpire)
	{
		DaCapsule::SetEmpireId(idEmpire);
		m_NameWithEmpireLock.lockForWrite();
		m_NameWithEmpire = "";
		m_NameWithEmpireLock.unlock();

		// Trim patents down to only those actually in use at this building.
		m_CargoLock.lockForRead();
		AuKnownPatents patents(m_Patents);
		m_CargoLock.unlock();
		AuKnownPatents patentsInUse;
		if(!IsDestroyed())
		{
			// Destroyed buildings do not surrender patents.
			for(QHash<COMMODITYID, quint8>::const_iterator pi = patents.cbegin(); pi != patents.cend(); pi++)
			{
				// Check my mfg processes to see which patents I am not using.
				m_MfgProcLock.lockForRead();
				for(DeManufacturingProcessArray::const_iterator it = m_MfgProc.begin(); it != m_MfgProc.end(); it++)
				{
					// If the process has not been run and has no shops assigned, we don't consider it to be using any patents yet.
					// That logic does not apply at spacecraft factories because they cycle through a lot of manufacturing processes
					// and they are often run manually.
					if(!(*it).ShopsEnabled() && !(*it).LastOutputQuality() && IndustryId() != IID_SpacecraftFactory)
						continue;	// No shops; no previous output; and this is not a spacecraft factory.
					if(!(*it).Components().IsComponent(pi.key()))
						continue;	// Process does not use the patent.
					patentsInUse.RecordPatent(pi.key(), *pi);
					break;
				}
				m_MfgProcLock.unlock();
			}
		}
		if(patents.size() != patentsInUse.size())
		{
			m_CargoLock.lockForWrite();
			m_Patents = patentsInUse;
			m_CargoLock.unlock();
		}

		ExploreWorld();
	}
}

