QString DaBd::TransporterTargetName() const
{
	QString placeName;
	bool isUndersea = SeaDepth() > FeetPerMeter();	// +/- 1 is the margin for sea surface construction, i.e. drilling rigs.
	if(IsInsideEnclosure())
	{
		if(isUndersea)
			placeName = tr("Undersea %1 at %2 inside enclosure").arg(CityBuildingName()).arg(GlobeLL().ToString());
		else
			placeName = tr("%1 at %2 inside enclosure").arg(CityBuildingName()).arg(GlobeLL().ToString());
	}
	else
	{
		if(isUndersea)
			placeName = tr("Undersea %1 at %2").arg(CityBuildingName()).arg(GlobeLL().ToString());
		else
			placeName = tr("%1 at %2").arg(CityBuildingName()).arg(GlobeLL().ToString());
	}
	return placeName;
}

