void DaBd::ExpandPirateBase()
{
	if(IsInAnyScene())
		return;		// Do not build buildings when someone is watching.
	if(IndustryId() != IID_BaseHeadquarters)
		return;		// Only base HQ builds buildings.
	if(!IsPirate())
		return;		// Only pirates build pirate bases.
	DaWorldLL* world = FindParentWorldInEnv();
	if(!world)
		return;		// wut?
	// Find all buildings, to pick up civilians like cantinas.
	DaAtomList base;
	world->FindBds(base);
	if(base.empty())
		return;		// wut? What about this building?

	// Ask my empire record for the list of buildings I want to build.
	QList<INDUSTRYID> baseBuildings;
	quint32 empireId = EmpireId();
	const DgData& gd = g_Au.LockDataForRead();
	gd.PirateBaseBuildings(empireId, baseBuildings);
	g_Au.UnlockData();
	if(baseBuildings.empty())
		return;		// wut?

	// Decide what kind of building to build next.
	INDUSTRYID buildIndustry = IID_None;
	QHash<INDUSTRYID, int> countedBuildings;
	for(QList<INDUSTRYID>::const_iterator bi = baseBuildings.cbegin(); bi != baseBuildings.cend(); bi++)
	{
		// Keep track of how many of the industry buildings we want in total.
		int buildingsWanted;
		QHash<INDUSTRYID, int>::iterator ci = countedBuildings.find(*bi);
		if(ci == countedBuildings.end())
		{
			countedBuildings.insert(*bi, 1);	// This is the first building of the type wanted.
			buildingsWanted = 1;
		}
		else
		{
			(*ci)++;							// Add one to the number of the building type that is wanted.
			buildingsWanted = *ci;
		}

		// Check to see if I have the desired number of the buildings on my base.
		for(DaAtomList::const_iterator ai = base.cbegin(); ai != base.cend(); ai++)
		{
			const DaBd* bd = dynamic_cast<const DaBd*>(*ai);
			if(!bd)
				continue;	// Shouldn't really happen.
			if(bd->IndustryId() != *bi)
				continue;	// Not the kind of building I want.
			// Found the kind of building I want.
			buildingsWanted--;
			if(!buildingsWanted)
				break;		// We found all of those kind of buildings we want.
		}
		if(buildingsWanted)
		{
			// We did not find all of the buildings we wanted of the industry. Build another one.
			buildIndustry = *bi;
			break;
		}
	}
	if(buildIndustry != IID_None)
	{
		// Our base is not complete.
		const DgData& gd = g_Au.LockDataForRead();
		int rank = gd.PirateEmpireRank(empireId);
		g_Au.UnlockData();

		// Building construction details.
		COMMODITYID material = CID_Stone;
		double minDist = RoughSiteRadius();
		double maxDist = minDist + rank * 30*FeetPerMeter();
		AuGlobeLLF buildLL = world->RandomLandLLNear(g_Au.Dice(), GlobeLL(), 1, minDist, maxDist);
		float zRotation = g_Au.Dice().Roll(1,360,-1) * DEG2RADf;

		// Build the building. This will test the build location and quitly fail if it does not work. We'll try again next time.
		AuSpecies species(ResidentSpecies());
		if(!species.IsNull())
			world->PirateBaseBuilding(buildIndustry, material, buildLL, zRotation, empireId, species);
	}
}

void DaBd::SetupPirate(quint32 empireId, quint8 quality, DaWorldLL* llworld)
{
	// Residents
	PirateFillResidents(empireId, llworld);

	// Fuel
	PirateFillCommodity(empireId, Fuel(), quality);

	// Air
	if(!IsAirBreathable())
		PirateFillCommodity(empireId, CID_Air, quality);

	// Food
	if(IndustryId() == IID_BaseHeadquarters || IndustryId() == IID_Cantina)
	{
		ECOROLE ecoRole = ResidentEcoRole();
		int foodToGet = 5 + Residents();
		for(int f=0; f<foodToGet; f++)
		{
			COMMODITYID cid = DbCommodity::RandomFood(ecoRole);
			if(cid != CID_Invalid)
			{
				AuItem* item = AuItem::Create(cid, quality, empireId, 100);
				if(item)
				{
					AddCargo(*item);
					delete item;
				}
			}
		}
	}

	// Medical supplies
	{
		m_DesignLock.lockForRead();
		int meds = m_Design.SurgeryUnitCount() + 1;
		m_DesignLock.unlock();
		QSet<COMMODITYID> medcids;
		medcids << CID_MedicalKit;
		medcids << CID_Antidote;
		medcids << CID_Antitoxin;
		medcids << CID_Water;

		// Load all the kinds of meds I need into the hold.
		for(QSet<COMMODITYID>::const_iterator ai = medcids.cbegin(); ai != medcids.cend(); ai++)
		{
			AuItem* item = AuItem::Create(*ai, quality, empireId, meds);
			if(item)
			{
				AddCargo(*item);
				delete item;
			}
		}
	}

	// Tally all my ammo-using weapons.

	// Bay weapons.
	int bcannons = 0;
	int blaunchers = 0;
	int bprojectors = 0;
	int bracks = 0;
	m_DesignLock.lockForRead();
	for(AuScReportSysVolHash::const_iterator bi = m_Design.WeaponBays().cbegin(); bi != m_Design.WeaponBays().cend(); bi++)
	{
		COMMODITYID bayMod = (*bi).Module();
		quint32 wpns = (*bi).Volume();
		double wpnsCuFt = wpns * CubicFeetPerCubicMeter();
		switch(bayMod)
		{
		default:
			continue;
		case CID_BallisticWeaponBayModule:
			bcannons += AuScDesign::BayWeaponCannons(wpnsCuFt);
			break;
		case CID_EnergyWeaponBayModule:
			bprojectors += AuScDesign::BayWeaponProjectors(wpnsCuFt);
			break;
		case CID_WeaponDeploymentBayModule:
			bracks += AuScDesign::BayWeaponEjectorRacks(wpnsCuFt);
			break;
		case CID_WeaponLauncherBayModule:
			blaunchers += AuScDesign::BayWeaponLaunchers(wpnsCuFt);
			break;
		}
	}

	// Turrets
	int tcannons = 0;
	int tlaunchers = 0;
	int tprojectors = 0;
	for(AuScReportTurretHash::const_iterator ti = m_Design.Turrets().begin(); ti != m_Design.Turrets().end(); ti++)
	{
		COMMODITYID turretMod = (*ti).Module();
		switch(turretMod)
		{
		case CID_WeaponLauncherTurretModule:
			tlaunchers++;
			break;
		case CID_BallisticWeaponTurretModule:
			tcannons++;
			break;
		case CID_EnergyWeaponTurretModule:
			tprojectors++;
			break;
		default:
			break;
		}
	}

	// Ammo for vehicles. Only get ammo that is already needed by ship weapons, so we don't grab projectors for Seledon and Ogar.
	int parkingSpots = m_Design.ParkingSpotsTotal();
	if(tlaunchers)
		tlaunchers += parkingSpots;
	if(tcannons)
		tcannons += parkingSpots;
	if(tprojectors)
		tprojectors += parkingSpots;
	if(bracks)
		bracks += parkingSpots;
	m_DesignLock.unlock();

	QHash<COMMODITYID, int> ammoNeeded;	// Key is ammo CID, value is count wanted.
	if(bcannons || tcannons)
	{
		int cannons = bcannons + tcannons;
		if(g_Au.Dice().Roll(1,3) == 1)
			ammoNeeded.insert(CID_HeavyArmsAmmoPiRa, cannons*10);
		if(g_Au.Dice().Roll(1,3) == 1)
			ammoNeeded.insert(CID_HeavyArmsAmmoPiAc, cannons*10);
		if(g_Au.Dice().Roll(1,3) == 1)
			ammoNeeded.insert(CID_HeavyArmsAmmoPiBl, cannons*10);
		ammoNeeded.insert(CID_HeavyArmsAmmoPi, cannons*10);
	}

	if(bracks)
	{
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_BombBlRa, bracks*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_BombBlPi, bracks*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_BombElSt, bracks*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_BombSuPo, bracks*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_BombSlCr, bracks*10);
		ammoNeeded.insert(CID_BombBl, bracks*10);
	}

	if(bprojectors || tprojectors)
	{
		int projectors = bprojectors + tprojectors;
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_CompressorBeam, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_DisintegratorRay, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_ProtonBeam, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_StasisBeam, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_DisruptorBeam, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_ErgRay, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_HeatRay, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_FreezeRay, projectors);
		if(g_Au.Dice().Roll(1,9) == 1)
			ammoNeeded.insert(CID_NeutronBeam, projectors);
		ammoNeeded.insert(CID_ElectronBeam, projectors);
	}

	if(blaunchers)
	{
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_LargeRocketBuDi, blaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_LargeRocketBlBu, blaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_LargeMissileSlPo, blaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_LargeMissileBlBu, blaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_LargeMissileBl, blaunchers*10);
		ammoNeeded.insert(CID_LargeRocketBl, blaunchers*10);
	}

	if(tlaunchers)
	{
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_SmallMissileCrFr, tlaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_SmallMissileBlBu, tlaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_SmallRocketSlPi, tlaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_SmallRocketBlBu, tlaunchers*10);
		if(g_Au.Dice().Roll(1,5) == 1)
			ammoNeeded.insert(CID_SmallMissileBl, tlaunchers*10);
		ammoNeeded.insert(CID_SmallRocketBl, tlaunchers*10);
	}

	if(!ammoNeeded.isEmpty())
	{
		int totalAmmoWanted = 0;
		for(QHash<COMMODITYID, int>::const_iterator ai = ammoNeeded.cbegin(); ai != ammoNeeded.cend(); ai++)
			totalAmmoWanted += *ai;

		// Load all the kinds of ammo I need into the hold, up to half full.
		for(QHash<COMMODITYID, int>::const_iterator ai = ammoNeeded.cbegin(); ai != ammoNeeded.cend(); ai++)
		{
			int roundsToLoad = (CargoCapacityVolume()/2) * *ai / totalAmmoWanted;
			if(!roundsToLoad)
				roundsToLoad = 1;

			// We only need one energy weapon per turret, unless we have bay weapons.
			AuItem* item = AuItem::Create(ai.key(), quality, empireId, roundsToLoad);
			if(item)
			{
				AddCargo(*item);
				delete item;
			}
		}
	}
}

void DaBd::PirateFillCommodity(quint32 empireId, COMMODITYID cid, quint8 quality)
{
	if(cid == CID_Invalid)
		return;
	quint32 storage = CargoCapacityVolume();
	if(!storage)
		return;

	AuItem* item = AuItem::Create(cid, quality, empireId, 1);
	if(!item)
		return;

	// Count the total number of the fuel commodity on hand that is equal or better
	// than the nu item. We will replace lower quality stuff.
	m_CargoLock.lockForRead();
	quint32 count = m_Cargo.EqualOrBetterCount(*item);
	m_CargoLock.unlock();
	if(count < storage)
	{
		// There is room to store some of the commodity.
		quint32 spaceAvailable = storage - count;
		item->SetCount(spaceAvailable);
		AddCommodity(*item);
	}
	delete item;
}

void DaBd::PirateFillResidents(quint32 empireId, DaWorldLL* llworld)
{
	quint32 homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs;
	IndustryInfo(homesLarge, homesMedium, homesSmall, manufacturingJobs, serviceJobs, stores, lounges, proJobs);
	int homes = homesLarge + homesMedium + homesSmall;
	if(!homes)
		return;
	if(homes > 0xffff)
		homes = 0xffff;

	bool worldPopChange = false;
	while(homes--)
	{
		NewResident(1);	// space traveller
		worldPopChange = true;
	}

	if(worldPopChange)
		llworld->WorldPopulationChanged();	// Dirty the world's population cache.

	// University, academy, marine barracks, and private security contractors do not make their citizens available as
	// workers. Their citizens are waiting for assignment aboard a ship.
	if(IndustryId() == IID_School ||
			IndustryId() == IID_BaseAcademy ||
			IndustryId() == IID_BaseMarineBarracks ||
			IndustryId() == IID_PoliceAcademy)
		return;

	// Advertise workers available to other buildings.
	if(ResidentsUnemployed())
	{
		if(IsMilitary())
			llworld->TroopAvailable(Id(), empireId);
		else
			llworld->CitizenAvailable(Id(), empireId);
	}
	else
	{
		if(IsMilitary())
			llworld->TroopNotAvailable(Id());
		else
			llworld->CitizenNotAvailable(Id());
	}
}

bool DaBd::IsProtectedFromDestruction() const
{
	if(IndustryId() == IID_Fence)
		return false;
	if(!IsMilitary())
	{
		// Civilian buildings are not destroyed while the world has a military base.
		const DaWorldLL* llworld = FindParentWorldInEnv();
		if(!llworld)
			return false;	// wtf?
		if(llworld->HQHere())
			return true;
		else if(IndustryId() == IID_Capitol)
		{
			// Capitol building is not destroyed while it has any police in its city.
			return llworld->HasCityPolice(CapitolId());
		}
	}
	else if(IndustryId() == IID_BaseHeadquarters)
	{
		// HQ buildings are not destroyed while the world has any other military buildings.
		const DaWorldLL* llworld = FindParentWorldInEnv();
		if(!llworld)
			return false;	// wtf?
		return llworld->BaseHere();
	}
	return false;
}

bool DaBd::IsOnLadderTo(const AuPoint& fromLoc, const AuPoint& ladderPathLoc) const
{
	// Find a room with that exact name.
	bool foundIt;
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	if(scd)
		foundIt = scd->IsOnLadderTo(fromLoc, ladderPathLoc, m_DoorStates);
	else
		foundIt = false;
	UnlockDesign();
	m_DesignLock.unlock();
	return foundIt;
}

bool DaBd::CanGrabLadderAt(const DaAtom& who, const AuPoint& ladderPathLoc, AuMatrix4x4& mLadder)
{
	// Find closest ladder path to 'who' with an end point at 'ladderPathLoc'.
	bool foundLadder;
	m_DesignLock.lockForRead();
	const AuBdDesign* scd = LockDesign();
	if(scd)
		foundLadder = scd->FindLadderToGrabAt(who.Location(), ladderPathLoc, mLadder, m_DoorStates, m_Lifts);
	else
		foundLadder = false;
	UnlockDesign();
	m_DesignLock.unlock();
	return foundLadder;
}

int DaBd::GunnerDomain(AuId& worldId) const
{
	const DaWorldLL* w = FindParentWorldInEnv();
	if(!w)
		return 3;	// wut?
	// Inside atmosphere range of a world.
	worldId = w->Id();
	if(IsCGUnderWater())
		return 1;	// Under water
	return 2;		// In atmosphere
}

void DaBd::ClaimTitleRecursive(const AuId& propertyId, const QString& propertyName, const AuId& ownerId,
		const QString& ownerName, quint32 ownerEmpire)
{
	DaCapsule::ClaimTitleRecursive(propertyId, propertyName, ownerId, ownerName, ownerEmpire);
	if(IsDead())
		return;

	bool anyChange = false;
	m_CargoLock.lockForWrite();
	if(m_Cargo.VoidOwnershipTitle(propertyId, ownerId, ownerName))
		anyChange = true;
	if(m_Tools.VoidOwnershipTitle(propertyId, ownerId, ownerName))
		anyChange = true;
	if(anyChange)
		m_tmCargoChange.Set();
	m_CargoLock.unlock();
	if(anyChange)
		SetModified();
}

void DaBd::SolicitShipments(DaPerson* person, DaVessel* ship, const AuCommPacket& msg, const AuId& sectorId)
{
	if(!ship)
		return;
	// Brokers support company and fleet ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
	case IID_Broker:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	// Person is in a spacecraft. Are they authorized to trade cargo.
	if(!ship->InChainOfCommand(person))
		return;

	// Cities normally respond at the same range the message was sent.
	// Cities do not respond beyond solar system range.
	AuCommStdChannel::RANGE range = msg.ReceptionRange();
	if(range > AuCommStdChannel::SolarSystem)
		range = AuCommStdChannel::SolarSystem;

	if(person->IsBlackListedByInsurer())
	{
		// Nyet!
		if(!AuCommStdChannel::IsTradeChannel(msg.ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::RejectBadShipper, msg.ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg.Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	const DaWorld* planet = FindParentPlanetInEnv();
	if(!planet)
		return;

	// Shipments
	AuShipmentList shipments;
	m_CargoLock.lockForRead();
	m_Shipments.ReadyToShip(shipments);
	m_CargoLock.unlock();

	if(shipments.isEmpty())
	{
		// We have no shiments ready for pickup.
		if(!AuCommStdChannel::IsTradeChannel(msg.ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::NoShipments, msg.ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg.Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	// Lock atom chat queue mutex so we can access both the open channels queue and the chat messages queue simultaneously.
	AuAtomChatList* chatqueue = g_Au.LockAtomChat();

	// Open a channel to the seller so my output, which could be considerable, will not be mixed with other messages.
	QString channame;
	if(msg.ChannelName() == AuCommStdChannel::TradeChannelName())
	{
		channame = QString("%1 %2-%3").arg(CityBuildingName()).arg(Id().StringId()).arg(msg.FromId().StringId());

		// Notify the person on the current channel that we have
		// sent a response on a different channel.
		AuCommCityMessage mymsg(AuCommCityMessage::ShipmentsOnPrivateChannel, msg.ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg.Scope());
		chatqueue->append(AuAtomChat(mymsg));
	}
	else
		channame = msg.ChannelName();
	g_Au.m_OpenChannels.append(AuOpenChannel(channame, AuCommStdChannel::Everyone, Id(), CityBuildingName(), sectorId,
				Galaxy(), msg.FromId(), false));

	// Construct a chat message to send on the nu channel.
	QString text;
	if(shipments.size() > 1)
		text = tr("The loading dock has %L1 shipments ready for pickup.").arg(shipments.size());
	else
		text = tr("The loading dock has one shipment ready for pickup.");
	AuCommCityChat mymsg(text, channame, Id(), CityBuildingName(), sectorId, Galaxy(), range,
			AuCommStdChannel::Everyone);
	chatqueue->append(AuAtomChat(mymsg));

	// Now transmit the list of shipments.
	for(AuShipmentList::const_iterator si = shipments.cbegin(); si != shipments.cend(); si++)
	{
		AuCommShipmentItem mymsg(*si, channame, Id(), CityBuildingName(), sectorId, Galaxy(), range, AuCommStdChannel::Everyone);
		chatqueue->append(AuAtomChat(mymsg));
	}
	g_Au.UnlockAtomChat();
}

void DaBd::RxBidPickupShipment(const AuCommBidPickupShipment* msg, DaVessel* ship, const AuId& sectorId,
		AuCommStdChannel::RANGE range, DaPerson* person, bool hasTransporter, bool inTransporterRange)
{
	if(!msg)
		return;
	if(!ship)
		return;
	// Brokers support company and fleet ships. Military air terminals only communicate with fleet spacecraft.
	switch(IndustryId())
	{
	case IID_AirportTerminal:
	case IID_Broker:
		break;
	case IID_BaseAirTerminal:
		if(ship->IsPrivatelyOwned())
			return;
		break;
	default:
		return;
	}

	// City in trade range will attempt to accept the bid.
	if(!g_Au.HasPendingBidShipment(msg))
		return;

	// Insure the buyer is physically located where the transaction can be performed.
	// - In a spaceship, and
	//    - On a road slab that belongs to this city, or
	//    - Near a friendly station in this solar system.
	// - Not in a spaceship, and
	//    - In a building that sells the item.
	if(!ship->InChainOfCommand(person))
	{
		AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToBuy, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Person is not an officer of the ship.
	}

	if(person->IsBlackListedByInsurer())
	{
		// Nyet!
		if(!AuCommStdChannel::IsTradeChannel(msg->ChannelName()))
		{
			AuCommCityMessage mymsg(AuCommCityMessage::RejectBadShipper, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
		}
		return;
	}

	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore bid if the buyer is too far away to accept the transaction.
	if(!inCity && !nearStation && !inTransporterRange)
	{
		// Tell the buyer to move closer.
		AuCommCityMessage::MESSAGE msgId;
		if(hasTransporter)
		{
			if(hasStation)
				msgId = AuCommCityMessage::MoveBdTransporterStationToBuy;
			else
				msgId = AuCommCityMessage::MoveBdTransporterToBuy;
		}
		else
		{
			if(hasStation)
				msgId = AuCommCityMessage::MoveBdStationToBuy;
			else
				msgId = AuCommCityMessage::MoveBdToBuy;
		}
		AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range,
				msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Insure the buyer can store the merchandise.
	if(!ship->CanAddCargo(msg->Shipment()->Container()))
	{
		// Person is aboard a ship but the nu cargo won't fit in the hold.
		// Tell the buyer they don't have room.
		QString text = tr("The hold in your spacecraft has insufficient space to add the shipment.");
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Ignore the offer; no space to store the stuff.
	}

	// Perform the transaction.
	// Locate the shipment.
	m_CargoLock.lockForWrite();
	bool pickedUp = m_Shipments.PickUp(*msg->Shipment());
	m_CargoLock.unlock();
	if(!pickedUp)
	{
		QString text = tr("That shipment is gone. It was already picked up.");
		AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Player Statistics
	person->Stats().ShipmentLoaded();
	person->IncreaseSkill(AuSkill::Trade, 1);

	AuItemTEUContainer* teu = (AuItemTEUContainer*)msg->Shipment()->Container().Clone();
	teu->SetPickedUp(person->Id(), person->Name(), AuTime::Now());
	ship->AddCargo(*teu);
	delete teu;

	// Revoke the bid so it can't be accepted again.
	g_Au.BidRevoked(msg->FromId(), msg->ChannelName());

	// Send an Accept message so the person knows the deal is done. The count may have changed from the bid when not
	// all of the items fit in the buyer's inventory.
	AuCommAcceptPickupShipment mymsg(msg->FromId(), msg->FromName(), *msg->Shipment(), msg->ChannelName(), Id(), CityBuildingName(),
			sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
	// Transaction is completed.
}

void DaBd::RxOfferTEU(const AuCommOfferTEU* msg, DaVessel* ship, const AuId& sectorId, AuCommStdChannel::RANGE range,
		DaPerson* person, bool hasTransporter, bool inTransporterRange)
{
	if(!msg)
		return;
	switch(IndustryId())
	{
	case IID_Broker:
		// Brokers support company and fleet ships.
		if(!ship)
			return;
		break;
	case IID_BaseAirTerminal:
		// Military air terminals only communicate with fleet spacecraft.
		if(!ship)
			return;
		if(ship->IsPrivatelyOwned())
			return;
		break;
	case IID_AirportTerminal:
		// Airport terminals support company and fleet ships.
		if(!ship)
			return;
		break;
	default:
		return;
	}

	// Determine what is for sale.
	const AuItemTEUContainer* teuItem = dynamic_cast<const AuItemTEUContainer*>(msg->Item());
	if(!teuItem)
		return;
	if(!teuItem->Cargo())
		return;

	if(!ship->InChainOfCommand(person))
	{
		AuCommCityMessage mymsg(AuCommCityMessage::MustBeOfficerToDeliverTEU, msg->ChannelName(), Id(), CityBuildingName(),
				sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;	// Person is not an officer of the ship.
	}

	// Insure the buyer is physically located where the transaction can be performed.
	bool inCity = CanAccessByGround(ship);	// True if I can access the ship by ground.
	bool hasStation = false;
	bool nearStation = false;
	if(!inCity && ship->StationInTradeRange(ship->RoughRadius(), hasStation))
		nearStation = true;	// Found a station in trade range.

	// Ignore bid if the buyer is too far away to accept the transaction.
	if(!inCity && !nearStation && !inTransporterRange)
	{
		// Tell the buyer to move closer.
		AuCommCityMessage::MESSAGE msgId;
		if(hasTransporter)
		{
			if(hasStation)
				msgId = AuCommCityMessage::MoveBdTransporterStationToDeliverTEU;
			else
				msgId = AuCommCityMessage::MoveBdTransporterToDeliverTEU;
		}
		else
		{
			if(hasStation)
				msgId = AuCommCityMessage::MoveBdStationToDeliverTEU;
			else
				msgId = AuCommCityMessage::MoveBdToDeliverTEU;
		}
		AuCommCityMessage mymsg(msgId, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	if(teuItem->StoryInstance())
	{
		AuCommCityMessage mymsg(AuCommCityMessage::UnwantedStoryItem, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	if(!teuItem->IsInsured())
	{
		// The shipment belongs to the person.
		AuCommCityMessage mymsg(AuCommCityMessage::UninsuredTEU, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Am I the destination of the container?
	AuId destId = teuItem->DestinationCity();
	if(!Is(destId) && CapitolId() != destId)
	{
		// I am not the destination of the TEU.
		AuCommCityMessage mymsg(AuCommCityMessage::UnwantedTEU, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Can I afford the delivery fee?
	double fee = teuItem->PaymentNow();
	bool payDebt = false;
	if(fee > CommunityAccountBalance())
	{
		// I can't afford to pay for the delivery. This is a default.
		if(EmpireId() == person->EmpireId())
			payDebt = true;	// Their own empire can go into debt to pay the delivery fee.
		else
		{
			// Foreign governments must default on the debt.
			AuCommCityMessage mymsg(AuCommCityMessage::DeliveryDefault, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
					Galaxy(), range, msg->Scope());
			g_Au.SendAtomChat(mymsg);
			ship->ShipmentDefaulted(*teuItem);
			return;
		}
	}

	// Take the container from the ship.
	if(!ship->RemoveCargo(*teuItem, 1))
	{
		AuCommCityMessage mymsg(AuCommCityMessage::ShipNoCargoToSell, msg->ChannelName(), Id(), CityBuildingName(), sectorId,
				Galaxy(), range, msg->Scope());
		g_Au.SendAtomChat(mymsg);
		return;
	}

	// Add the contents of the container to my inventory.
	for(AuItemHash::const_iterator ci = teuItem->Cargo()->cbegin(); ci != teuItem->Cargo()->cend(); ci++)
		CommunityAddCommodity(*(*ci).second);

	// Transfer the money.
	QString text;
	if(payDebt)
	{
		person->Reward(fee, REW_DeliverTEU);
		text = tr("%1 was offloaded from your ship. "
				"We cannot pay the delivery fee. "
				"%L2%3 was credited to you as a debt; "
				"redeem it at any bank of the empire. ")
			.arg(teuItem->ListName())
			.arg(fee, 0,'f',0)
			.arg(AuGlobal::CurrencySymbol());
	}
	else
	{
		ship->CreditAccountSales(fee);
		CommunityDebitAccount(fee, AuBank::Civ_DebitWholesale);
		text = tr("%1 was offloaded from your ship. "
				"%L2%3 was deposited into your ship's account as payment. ")
			.arg(teuItem->ListName())
			.arg(fee, 0,'f',0)
			.arg(AuGlobal::CurrencySymbol());
	}

	// Player Statistics
	if(person->Is(teuItem->CarrierId()))
		person->Stats().ShipmentMineDelivered();
	else
		person->Stats().ShipmentDelivered();
	person->IncreaseSkill(AuSkill::Trade, 1);

	AuTime deliverTime = teuItem->EstimatedDeliveryTime();
	AuTime now = AuTime::Now();
	float onTimeMinutes = teuItem->DestinationDistancePc()/4;	// Minutes to estimated time to consider it "on time".
	if(llabs(now.MinsTo(deliverTime)) < onTimeMinutes)
	{
		// Delivery is close to the estimated time, accounting for distance.
		text += tr("Thank you for the shipment. "
				"We really appreciate you space truckers. ");
	}
	else if(now > deliverTime)
	{
		// Delivery is late.
		if(fee == 1000)
			text += tr("That shipment is way late; the stuff was supposed to be here a long time ago. "
					"You got crumbs to help cover your costs, that's all, space trucker.");
		else
			text += tr("The shipment is late. "
					"That cost you big money, space trucker. ");
	}
	else
	{
		if(fee > teuItem->EstimatePayment(teuItem->TEUCount()) * 2)
			text += tr("That was fast; your ship is awesome! "
					"You earned more than double the standard fee. "
					"Space truckers are the best.");
		else
			text += tr("The shipment is early; good job. "
					"Enjoy the bonus pay. "
					"We appreciate the work you space truckers do out there.");
	}

	// Report the result.
	AuCommCityChat mymsg(text, msg->ChannelName(), Id(), CityBuildingName(), sectorId, Galaxy(), range, msg->Scope());
	g_Au.SendAtomChat(mymsg);
	SetModified();
}

QString DaBd::IndigenousDescription() const
{
	if(IndustryId() != IID_Capitol && IndustryId() != IID_BaseHeadquarters)
		return Name();
	QString desc;

	int buildings = LastReportedBuildingLevels();
	if(buildings > 100)
		desc = tr("There are many buildings.");
	else if(buildings > 10)
		desc = tr("There are few buildings.");
	else
		desc = tr("There are no buildings.");

	int people = LastReportedPopulation();
	if(people > 500)
	{
		int truncpop = people / 100 * 100;
		desc += tr(" It is a huge metropolis of more than %1 citizens.").arg(truncpop);
	}
	else if(people > 200)
	{
		int truncpop = people / 100 * 100;
		desc += tr(" It is a large city with more than %1 citizens.").arg(truncpop);
	}
	else if(people > 100)
	{
		int truncpop = people / 10 * 10;
		desc += tr(" It is a small city with over %1 citizens.").arg(truncpop);
	}
	else if(people > 10)
	{
		int truncpop = people / 10 * 10;
		desc += tr(" It is a small town of about %1 citizens.").arg(truncpop);
	}
	else if(people > 1)
		desc += tr(" Few people live there.");
	else if(people == 1)
		desc += tr(" Only one person lives there.");
	else
		desc += tr(" Nobody lives there.");

	desc += tr(" The town hall was built there %1.").arg(CreatedTime().UTC().toString("MMMM d yyyy"));

	return desc;
}

void DaBd::ReportEnemySensorContact(const DaSolarSystem* system, const AuSensorBlipList& sensorBlips, float sensorRange)
{
	const DaGalaxy* galaxy = system->FindParentGalaxy();
	if(!galaxy)
		return;
	AuPoint mySysLoc = EnvLocation();
	float sensorRange2 = sensorRange*sensorRange;
	for(AuSensorBlipList::const_iterator bi = sensorBlips.begin(); bi != sensorBlips.end(); bi++)
	{
		if(!(*bi)->IsSensorConsoleBlip())
			continue;
		if((*bi)->Range2(mySysLoc) > sensorRange2)
			continue;

		AuEventLogEntry::TYPE eventType = (*bi)->OfficerEventLogType();
		switch(eventType)
		{
		case AuEventLogEntry::AsteroidDetected:
		case AuEventLogEntry::AsteroidObserved:
		case AuEventLogEntry::AsteroidObservedCollide:
		case AuEventLogEntry::EnemyCapital:
			{
				AuEventLogEntry cle(eventType, (*bi)->HtmlDesc(system));
				m_EventLogLock.lock();
				m_EventLog->AddEventTrim(cle);
				m_EventLogLock.unlock();
			}
			break;
		case AuEventLogEntry::EnemySpaceship:
		case AuEventLogEntry::EnemySpaceshipS:
		case AuEventLogEntry::EnemyStarship:
		case AuEventLogEntry::EnemyStarshipS:
			// Ignore "nu" enemy spacecraft.
			if(!(*bi)->IsNewSpacecraft())
			{
				AuEventLogEntry cle(eventType, (*bi)->HtmlDesc(system));
				m_EventLogLock.lock();
				m_EventLog->AddEventTrim(cle);
				m_EventLogLock.unlock();

				{
					// Create a job posting to interdict the enemy spacecraft.
					const DaSector* sector = system->FindParentSector();
					m_JobInterdict = AuJobInterdictSystem((*bi)->EmpireId(), system->Id(), system->Name(),
							sector->Name() + " " + sector->Description() + ", " + galaxy->Name());
				}
			}
			break;
		case AuEventLogEntry::EnemyStation:
		case AuEventLogEntry::EnemyStationS:
			// Ignore "nu" enemy spacecraft.
			if(!(*bi)->IsNewSpacecraft())
			{
				AuEventLogEntry cle(eventType, (*bi)->HtmlDesc(system));
				m_EventLogLock.lock();
				m_EventLog->AddEventTrim(cle);
				m_EventLogLock.unlock();

				{
					// Create a job posting for the enemy station.
					const DaSector* sector = system->FindParentSector();
					AuJobDestroyEnemyStation job((*bi)->AtomId(), (*bi)->ScreenName(), system->Id(), system->Name(),
							sector->Name() + " " + sector->Description() + ", " + galaxy->Name());
					m_JobsLock.lockForWrite();
					m_JobsEnemyStations.insert(pair<AuId, AuJobDestroyEnemyStation>((*bi)->AtomId(), job));
					m_JobsLock.unlock();
				}
			}
			break;
		case AuEventLogEntry::EnemyAircraft:
		case AuEventLogEntry::EnemyBoat:
		case AuEventLogEntry::EnemyVehicle:
			// Ignore "nu" enemy vehicles.
			if(!(*bi)->IsNewVehicle())
			{
				AuEventLogEntry cle(eventType, (*bi)->HtmlDesc(system));
				m_EventLogLock.lock();
				m_EventLog->AddEventTrim(cle);
				m_EventLogLock.unlock();
			}
			break;
		default:
			break;
		}
	}
}

