void DaBd::ObserveAsteroids()
{
	const DaSolarSystem* system = FindParentSolarSystemInEnv();
	DaAtomList asteroids;
	system->FindAsteroidsRecursive(asteroids);
	for(DaAtomList::const_iterator ai = asteroids.cbegin(); ai != asteroids.cend(); ai++)
	{
		const DaAsteroid* roid = dynamic_cast<const DaAsteroid*>(*ai);
		if(!roid)
			continue;
		if(!roid->IsNormal())
			continue;
		if(roid->IsAwaitingRelease())
			continue;
		float dia = roid->ObstacleRadius() * 2 / FeetPerMeter();	// Diameter in meters.
		float speed = roid->Speed() / FeetPerMeter();				// Speed in meters per second
		AuId targetId(roid->TargetId());
		const DaAtom* target;
		if(!targetId.IsNull())
			target = system->FindIdRecursive(targetId);
		else
			target = 0;

		AuPoint sysLoc = roid->EnvLocation();						// Asteroid location relative to the solar system.
		double distM = round(sysLoc.Length() / FeetPerMeter());
		double angle = round(sysLoc.ArcTangent_2D() * RAD2DEG);
		angle = 90. - angle;
		if(angle >= 360)
			angle -= 360;
		if(angle < 0)
			angle += 360;
		int angidx = (int)((angle + 11.25) / 22.5);
		QString dirNames[17] =
		{
			tr("N"),
			tr("NNE"),
			tr("NE"),
			tr("ENE"),
			tr("E"),
			tr("ESE"),
			tr("SE"),
			tr("SSE"),
			tr("S"),
			tr("SSW"),
			tr("SW"),
			tr("WSW"),
			tr("W"),
			tr("WNW"),
			tr("NW"),
			tr("N"),
			tr("ENE"),
		};
		QString sdir = dirNames[angidx];
		double polar = round(sysLoc.PolarIncline() * RAD2DEG);
		QString spotted = tr("Spotted %1 at %2%3, azimuth %4%3, %L5m away relative to the solar system plane of ecliptic.")
			.arg(sdir)
			.arg(angle)
			.arg(AuGlobal::DegreeSymbol())
			.arg(polar)
			.arg(distM, 0,'f',0);

		if(!target)
		{
			// Untargeted asteroid.
			QString roidInfo = tr("%L1m diameter. %L2m/s velocity. %3")
				.arg(dia, 0,'f',1)
				.arg(speed, 0,'f',1)
				.arg(spotted);
			LogEvent(AuEventLogEntry::AsteroidObserved, roidInfo, roid->Id());
		}
		else
		{
			AuTime targetTime = roid->TargetTime();
			QString roidInfo = tr("Orbit collides with %4 %5. %L1m diameter. %L2m/s velocity. %3")
				.arg(dia, 0,'f',1)
				.arg(speed, 0,'f',1)
				.arg(spotted)
				.arg(target->Name())
				.arg(targetTime.UTC().toString());
			LogEvent(AuEventLogEntry::AsteroidObservedCollide, roidInfo, roid->Id());
		}
	}
}

void DaBd::SurveySite(const DaWorldLL& world, QHash<COMMODITYID, quint32>& rocks)
{
	rocks.clear();
	INDUSTRYID iid = IndustryId();
	if(iid != IID_DrillingRig && iid != IID_Mine && iid != IID_Well)
		return;

	QMap<AuResKey, AuGlobeRock> renderRocks;
	world.CreateRocks(renderRocks, Transform().Project(SiteCenter()), world.GenSeed(), RoughSiteRadius(), false);
	for(QMap<AuResKey, AuGlobeRock>::const_iterator di = renderRocks.cbegin(); di != renderRocks.cend(); di++)
	{
		// Skip resources that cannot be harvested by the industry.
		switch((*di).CommodityId())
		{
		default:
			continue;
		case CID_Adamantite:
		case CID_Bolite:
		case CID_Coal:
		case CID_Crystals:
		case CID_Eludium:
		case CID_Gems:
		case CID_GoldOre:
		case CID_Ice:
		case CID_Lumenite:
		case CID_Minerals:
		case CID_Ore:
		case CID_Radioactives:
		case CID_Stone:
		case CID_Vulcanite:
			if(iid != IID_Mine)
				continue;
			break;
		case CID_CrudeOil:
		case CID_Phlogiston:
		case CID_Polytaride:
		case CID_Viathol:
			if(iid != IID_DrillingRig && iid != IID_Well)
				continue;
			break;
		}

		// Skip rocks that are not on the building site.
		if(!SiteContains((*di).Location()))
			continue;

		// Tally rocks by type.
		QHash<COMMODITYID, quint32>::iterator ri = rocks.find((*di).CommodityId());
		if(ri == rocks.end())
			rocks.insert((*di).CommodityId(), 1);
		else
			(*ri)++;

		if((*di).CommodityId() != CID_CrudeOil)
			continue;

		// Oil rocks also produce natural gas.
		ri = rocks.find(CID_NaturalGas);
		if(ri == rocks.end())
			rocks.insert(CID_NaturalGas, 1);
		else
			(*ri)++;
	}

	// Historically, we allowed mining of rock wherever there were other mineral resources. So keep that going somewhat, we will
	// insure the list contains at least one stone if it contains any rocks at all.
	if(!rocks.empty() && !rocks.contains(CID_Stone))
		rocks.insert(CID_Stone, 1);
}

void DaBd::SurveySiteUpdate()
{
	const DaWorldLL* llworld = FindParentWorldInEnv();
	if(!llworld)
		return;

	// Only some industries care about the site survey information.
	INDUSTRYID iid = IndustryId();
	if(iid != IID_DrillingRig && iid != IID_Mine && iid != IID_Well)
		return;	// Industry doesn't need site survey.

	// If we already have site survey results, keep them. We don't want them to change later.
	m_BdLock.lockForRead();
	bool hasRocks = !m_RocksOnSite.empty();
	m_BdLock.unlock();
	if(hasRocks)
		return;	// Keep previous results.

	// Mines, drilling rigs, and wells must survey their site to know how many shops can be enabled.
	QHash<COMMODITYID, quint32> rocks;
	SurveySite(*llworld, rocks);
	m_BdLock.lockForWrite();
	m_RocksOnSite = rocks;
	m_BdLock.unlock();
	m_DesignLock.lockForWrite();
	m_DesignChg.Set();			// Time of last state change
	m_DesignLock.unlock();
	SetModified();
}

quint32 DaBd::SiteContainsResource(COMMODITYID cid) const
{
	quint32 v;
	m_BdLock.lockForRead();
	QHash<COMMODITYID, quint32>::const_iterator ri = m_RocksOnSite.find(cid);
	if(ri != m_RocksOnSite.cend())
		v = *ri;
	else
		v = 0;
	m_BdLock.unlock();
	return v;
}

