int DaBd::DaysAbandoned() const
{
	const DaSolarSystem* system = FindParentSolarSystemInEnv();
	if(!system)
		return d_AbandonDaysBegin+1;				// wut?

	AuTime lastVisit(system->LastPersonVisited());
	AuTime lastAvatarAccountActive(system->LastAvatarAccountActive());
	if(lastAvatarAccountActive.IsNull() && lastVisit.IsNull())
		return d_AbandonDaysBegin+1;				// Nobody has ever visited or been active here? Not likely.

	// How many days since last visited or pinged by an avatar who calls my system their land.
	int days;
	if(lastVisit.IsNull())
		days = lastAvatarAccountActive.ElapsedDay(); // Nobody has ever visited my system? Not likely.
	else if(lastAvatarAccountActive.IsNull())
		days = lastVisit.ElapsedDay();				// No active avatar has ever had a home in my supersector? That is possible.
	else if(lastVisit > lastAvatarAccountActive)
		days = lastVisit.ElapsedDay();				// Last solar system visit was more recent than last active avatar sector ping.
	else
		days = lastAvatarAccountActive.ElapsedDay(); // Last active avatar sector ping was more recent than last solar system visit.

	// Calculate number of days since abandonment began.
	int abandoned = days - d_AbandonDaysBegin;
	if(abandoned < 0)
		abandoned = 0;
	return abandoned;
}

bool DaBd::TestAbandonmentDecay() const
{
	int daysAbandoned = DaysAbandoned();
	if(!daysAbandoned)
		return false;					// This building does not consider itself to be abandoned.
	if(IsProtectedFromDestruction())
		return false;					// Game rules prevent destruction of this building at this time.
	int result = g_Au.Dice().Roll(1,500,-daysAbandoned);
	if(result > 1)
		return false;					// The dice did not decay me.
	/*
#if !defined(QT_NO_DEBUG)
	QString cityName(CityName());
	if(cityName.isEmpty())
		cityName = "unincorporated";
	qDebug() << "DaBd::TestAbandonmentDecay" << *this << "crumbled away. daysAbandoned" << daysAbandoned
		<< "rollResult" << result << cityName << (IsMilitary() ? "base" : "city");
#endif
*/
	return true;						// I am ready to decay from existence.
}

int DaBd::CanSpawnHere(quint32 empireId) const
{
	if(!IsNormal())
		return 2;
	quint32 myEmpire = EmpireId();
	if(myEmpire == empireId)
		return 0;
	POLITICAL_STANCE stance = PoliticalStance(EmpireId(), empireId);
	return (stance == POL_Friend || stance == POL_Empire || stance == POL_Vassal) ? 0 : 1;
}

// Called by stations and cities.
// Searches recursively for any trespassing cities or stations.
const DaAtom* DaBd::FindTrespasserRecursive(quint32 empireId, const AuPoint& systemLoc, float sensorRange) const
{
    if(IndustryId() != IID_Capitol && IndustryId() != IID_BaseHeadquarters)
		return 0;	// I am not a city or a base.

	POLITICAL_STANCE stance = PoliticalStance(empireId, EmpireId());
	if(stance != POL_Neutral)
		return 0;	// I am not a neutral city to the scanner.

	if(EnvLocation().Distance2(systemLoc) > sensorRange*sensorRange)
		return 0;	// I am not in sensor range.

	// The scanning empire considers any city or base in sensor range to be a trespasser.
	return this;
}

void DaBd::CheckTrespass(const DaSolarSystem* system, float sensorRange)
{
    quint32 empireId = EmpireId();
    if(!system->IsNeutralEmpirePresent(empireId))
        return; // No neutral empire unit or city present.

    // Search the system for a trespasser.
    const DaAtom* trespasser = system->FindTrespasserRecursive(empireId, EnvLocation(), sensorRange);
    if(!trespasser)
        return;

    GALAXY galaxy = Galaxy();
    const DaSector* sector = system->FindParentSector();
	const DaWorld* world = trespasser->FindParentPlanetInEnv();
    QString sectorName = sector ? sector->Name() : "";
    QString systemName = system ? system->Name() : "";
	QString worldName = world ? world->Name() : "";

    // A trespassing station or city was detected. Declare them to be enemy.
    if(dynamic_cast<const DaBd*>(trespasser))
    {
        AuDocCityTrespassCity doc(Name(), trespasser->Name(), galaxy, sectorName, systemName, worldName);
        emit GovDossierAddDocument(empireId, trespasser->EmpireId(), doc.Pack());
    }
    else
    {
        AuDocCityTrespassStation doc(Name(), trespasser->Name(), galaxy, sectorName, systemName, worldName);
        emit GovDossierAddDocument(empireId, trespasser->EmpireId(), doc.Pack());
    }
}

