AuSysId DaBd::SelectNonstructuralSystemToDamage() const
{
	// Create a list of systems that can be damaged.
	quint32 hitsTotal = 0;	// Total hits remaining between my systems.
	QSet<AuSysId> sysIds;
	SystemIds(sysIds, false);
	QHash<AuSysId, quint32> canDamage;
	m_DamageLock.lockForRead();
	for(QSet<AuSysId>::const_iterator si = sysIds.cbegin(); si != sysIds.cend(); si++)
	{
		quint32 dmg = m_Damage.HitsDamageAddParts(*si);
		quint32 maxhp = SystemHits(*si);
		if(dmg >= maxhp)
			continue;		// System is destroyed.
		quint32 hitsLeft = maxhp - dmg;
		canDamage.insert(*si, hitsLeft);
		hitsTotal += hitsLeft;
	}
	m_DamageLock.unlock();
	if(!hitsTotal)
		return SYS_Count;

	// Choose a system at random to damage, based on hit points distribution.
	quint32 canIdx = g_Au.Dice().Roll(1, hitsTotal, -1);
	quint32 curTotal = 0;
	for(QHash<AuSysId, quint32>::const_iterator di = canDamage.cbegin(); di != canDamage.cend(); di++)
	{
		curTotal += *di;
		if(canIdx < curTotal)
			return di.key();
	}
	return SYS_Count;	// This should never happen.
}

AuSysId DaBd::SelectStructuralSystemToDamage() const
{
	// Create a list of systems that can be damaged.
	quint32 hitsTotal = 0;	// Total hits remaining between my systems.
	QSet<AuSysId> sysIds;
	SystemIds(sysIds, true);
	QHash<AuSysId, quint32> canDamage;
	m_DamageLock.lockForRead();
	for(QSet<AuSysId>::const_iterator si = sysIds.cbegin(); si != sysIds.cend(); si++)
	{
		quint32 dmg = m_Damage.HitsDamageAddParts(*si);
		quint32 maxhp = SystemHits(*si);
		if(dmg >= maxhp)
			continue;		// System is destroyed.
		quint32 hitsLeft = maxhp - dmg;
		canDamage.insert(*si, hitsLeft);
		hitsTotal += hitsLeft;
	}
	m_DamageLock.unlock();
	if(!hitsTotal)
		return SYS_Count;

	// Choose a system at random to damage, based on hit points distribution.
	quint32 canIdx = g_Au.Dice().Roll(1, hitsTotal, -1);
	quint32 curTotal = 0;
	for(QHash<AuSysId, quint32>::const_iterator di = canDamage.cbegin(); di != canDamage.cend(); di++)
	{
		curTotal += *di;
		if(canIdx < curTotal)
			return di.key();
	}
	return SYS_Count;	// This should never happen.
}

void DaBd::DamageReportHp(AuDamage& damage) const
{
	// Create a list of all systems.
	QSet<AuSysId> sysIds;
	SystemIds(sysIds, true);
	SystemIds(sysIds, false);
	for(QSet<AuSysId>::const_iterator si = sysIds.cbegin(); si != sysIds.cend(); si++)
	{
		AuRepairParts parts;
		m_DamageLock.lockForRead();
		quint32 hitsDmg = m_Damage.HitsDamageNoParts(*si);
		m_Damage.PartsDamage(*si, parts);
		m_DamageLock.unlock();
		if(!hitsDmg && parts.empty())
			damage.AddHitsDamage(*si, 0);	// System is undamaged.
		else
		{
			damage.AddHitsDamage(*si, hitsDmg);
			damage.AddPartsDamage(*si, parts);
		}
	}
}

void DaBd::DamageReportPercent(AuDamage& damage, int structEquip) const
{
	// Create a list of all systems.
	QSet<AuSysId> sysIds;
	if(structEquip & 0x01)
		SystemIds(sysIds, true);
	if(structEquip & 0x02)
		SystemIds(sysIds, false);
	for(QSet<AuSysId>::const_iterator si = sysIds.cbegin(); si != sysIds.cend(); si++)
	{
		m_DamageLock.lockForRead();
		quint32 hitsDmg = m_Damage.HitsDamageAddParts(*si);
		m_DamageLock.unlock();
		if(!hitsDmg)
		{
			if((structEquip & 0x04) == 0)
				damage.AddHitsDamage(*si, 0);	// System is undamaged.
		}
		else
		{
			// Calculate percentage of damage.
			unsigned int percDmg;
			quint32 syshp = SystemHits(*si);
			if(hitsDmg >= syshp || syshp == 0)
				percDmg = 100;
			else
			{
				percDmg = Percent(hitsDmg, syshp);
				if(!percDmg && hitsDmg)
					percDmg = 1;	// Slightly more than zero percent remaining.
				else if(percDmg == 100)
					percDmg = 99;	// Slightly less than 100 percent remaining.
			}
			damage.AddHitsDamage(*si, percDmg);
		}
	}
}

bool DaBd::IsConsoleOperational(const AuSysId& sysId) const
{
	return SystemHitsRemaining(sysId) ? true : false;
}

int DaBd::TradeAgreementCreate(const AuTradeAgreement& ta)
{
	if(IndustryId() != IID_Broker)
		return 1;
	if(FindParentSolarSystem()->Is(ta.DestinationSystem()))
		return 6;

	int brokerLevels = Offices();
	if(!brokerLevels)
		return 3;

	// Check limit on existing offices.
	m_CargoLock.lockForWrite();
	int offices = m_Shipments.CountOffices() + m_TradeAgreements.CountOffices();
	if(offices >= brokerLevels)
	{
		m_CargoLock.unlock();
		return 4;
	}

	// Add the new trade agreement.
	bool added = m_TradeAgreements.AddTradeAgreement(ta);
	m_CargoLock.unlock();
	if(!added)
		return 5;

	SetModified(NOTIFY_Database);
	return 0;
}

int DaBd::TradeAgreementDelete(const AuTradeAgreement& ta)
{
	if(IndustryId() != IID_Broker)
		return 2;

	// Delete the trade agreement.
	m_CargoLock.lockForWrite();
	bool deleted = m_TradeAgreements.Remove(ta);
	if(deleted)
		m_Shipments.Reconcile(m_TradeAgreements);	// Clean up all orphans, not just mine.
	m_CargoLock.unlock();
	if(!deleted)
		return 3;

	SetModified(NOTIFY_Database);
	if(CapitolId() == ta.OriginCity())
		return 0;	// I am the origin of the trade agreement.
	else
		return 1;	// I am the destination of the trade agreement.
}

int DaBd::TradeAgreementDeliver(const AuTradeAgreement& ta)
{
	// When the sender is in my chain of command, they send a final agreement, not a proposal.
	if(!ta.IsProposal() && !ta.IsAgreement())
		return 5;

	if(IndustryId() == IID_Broker)
	{
		// I am a broker. Accept the proposal if I have a free slot.
		int brokerLevels = Offices();
		if(!brokerLevels)
			return 2;

		// Add the new proposal if we have an office available.
		m_CargoLock.lockForWrite();
		int offices = m_Shipments.CountOffices() + m_TradeAgreements.CountOffices();
		if(offices >= brokerLevels)
		{
			m_CargoLock.unlock();
			return 3;	// No office available.
		}
		bool added = m_TradeAgreements.AddTradeAgreement(ta);
		if(added && ta.IsAgreement())
		{
			// Create a corresponding shipment that is associated with the trade agreement.
			AuShipment shipment(CapitolId(), EmpireId(), ta);
			m_Shipments.AddShipment(shipment);
		}
		m_CargoLock.unlock();
		if(!added)
			return 4;	// 64K proposals? Not likely.
		SetModified(NOTIFY_Database);
		return 0;
	}
	else if(IndustryId() == IID_Capitol)
	{
		DaWorld* world = FindParentPlanetInEnv();
		if(!world)
			return 1;
		DaAtomList bds;
		world->FindBdCity(bds, Id());
		bool anybroker = false;
		bool delivered = false;
		for(DaAtomList::const_iterator bi = bds.begin(); bi != bds.end(); bi++)
		{
			DaBd* bd = dynamic_cast<DaBd*>(*bi);
			if(!bd)
				continue;
			if(bd->IndustryId() != IID_Broker)
				continue;
			anybroker = true;
			int result = bd->TradeAgreementDeliver(ta);
			if(result == 0)
			{
				delivered = true;
				break;
			}
		}
		if(delivered)
			return 0;
		else if(!anybroker)
			return 2;
		else
			return 3;
	}
	return 2;
}

bool DaBd::TradeAgreementDeactivate(const AuTradeAgreement& ta, AuTradeAgreement::STATE nuState)
{
	bool deactivated = false;
	if(IndustryId() == IID_Broker)
	{
		// Delete the trade agreement.
		m_CargoLock.lockForWrite();
		deactivated = m_TradeAgreements.Deactivate(ta, nuState);
		if(deactivated)
			m_Shipments.Reconcile(m_TradeAgreements);	// Clean up all orphans, not just mine.
		m_CargoLock.unlock();
		if(deactivated)
			SetModified(NOTIFY_Database);
	}
	else if(IndustryId() == IID_Capitol)
	{
		DaWorld* world = FindParentPlanetInEnv();
		if(!world)
			return false;
		DaAtomList bds;
		world->FindBdCity(bds, Id());
		for(DaAtomList::const_iterator bi = bds.begin(); bi != bds.end(); bi++)
		{
			DaBd* bd = dynamic_cast<DaBd*>(*bi);
			if(!bd)
				continue;
			if(bd->IndustryId() != IID_Broker)
				continue;
			if(bd->TradeAgreementDeactivate(ta, nuState))
			{
				deactivated = true;
				break;
			}
		}
	}
	return deactivated;
}

bool DaBd::TradeAgreementAccept(const AuTradeAgreement& ta, bool atDest)
{
	bool accepted = false;
	if(IndustryId() == IID_Broker)
	{
		// Accept the trade agreement.
		if(atDest)
		{
			if(CapitolId() != ta.DestinationCity())
				return false;	// I am not at the destination city.
		}
		else
		{
			if(CapitolId() != ta.OriginCity())
				return false;	// I am not at the origin city.
		}
		m_CargoLock.lockForWrite();
		AuTradeAgreement tad(ta);
		accepted = m_TradeAgreements.Accept(tad);	// Changes state of trade agreement, result in tad.
		if(accepted)
		{
			// Create a corresponding shipment that is associated with the trade agreement.
			AuShipment shipment(CapitolId(), EmpireId(), tad);
			m_Shipments.AddShipment(shipment);
			m_CargoLock.unlock();
			SetModified(NOTIFY_Database);
		}
		else
			m_CargoLock.unlock();
	}
	else if(IndustryId() == IID_Capitol)
	{
		if(atDest)
		{
			if(!Is(ta.DestinationCity()))
				return false;	// I am not the destination city.
		}
		else
		{
			if(!Is(ta.OriginCity()))
				return false;	// I am not the origin city.
		}
		DaWorld* world = FindParentPlanetInEnv();
		if(!world)
			return false;
		DaAtomList bds;
		world->FindBdCity(bds, Id());
		for(DaAtomList::const_iterator bi = bds.begin(); bi != bds.end(); bi++)
		{
			DaBd* bd = dynamic_cast<DaBd*>(*bi);
			if(!bd)
				continue;
			if(bd->IndustryId() != IID_Broker)
				continue;
			if(bd->TradeAgreementAccept(ta, atDest))
			{
				accepted = true;
				break;
			}
		}
	}
	return accepted;
}

int DaBd::TradeAgreementCounter(const AuTradeAgreement& proposal, const AuTradeAgreement& counter)
{
	if(IndustryId() != IID_Broker)
		return 1;
	if(!proposal.IsProposal())
		return 4;
	if(!counter.IsProposal())
		return 5;
	if(proposal.OriginCity() == CapitolId())
		return 6;

	m_CargoLock.lockForWrite();
	bool deleted = m_TradeAgreements.Remove(proposal);			// Delete the old proposal.
	bool added = false;
	if(deleted)
		added = m_TradeAgreements.AddTradeAgreement(counter);	// Add the counter proposal.
	m_CargoLock.unlock();
	if(!deleted)
		return 2;
	SetModified(NOTIFY_Database);
	if(!added)
		return 3;
	return 0;
}

bool DaBd::TradeReadyToShipNow(AuTradeAgreement ta)
{
	if(IndustryId() == IID_Broker)
	{
		// Deliver my shipment that is associated with ta, if it is ready to go.
		AuShipment delivery;
		m_CargoLock.lockForWrite();
		int deliveryResult = m_Shipments.DeliverTrade(delivery, ta);
		if(deliveryResult)
		{
			// Shipment is not ready or its not mine.
			m_CargoLock.unlock();
			return deliveryResult == 1;	// True if its my shipment.
		}
		AuTradeAgreement tad(ta);					// Trade agreement modified by delivery.
		m_TradeAgreements.DeliveryComplete(tad);	// This can modify my current trade agreement. tad is the modified result.
		if(tad.IsAgreement())
		{
			// Agreement remains in effect, with potentially different terms if the repeat count was decremented.
			// Create a new shipment to replace the one that was delivered.
			AuShipment shipment(CapitolId(), EmpireId(), tad);
			m_Shipments.AddShipment(shipment);
		}
		m_CargoLock.unlock();

		// Emit a signal to the remote broker to release their shipment, using the original matching trade agreement.
		emit TradeShipped(CapitolId(), ta);

		// Emit delivery.
		emit ShipIt(delivery.Container());

		SetModified(NOTIFY_Database);
		return true;
	}
	else if(IndustryId() == IID_Capitol)
	{
		DaWorld* world = FindParentPlanetInEnv();
		if(!world)
			return false;
		DaAtomList bds;
		world->FindBdCity(bds, Id());
		for(DaAtomList::const_iterator bi = bds.begin(); bi != bds.end(); bi++)
		{
			DaBd* bd = dynamic_cast<DaBd*>(*bi);
			if(!bd)
				continue;
			if(bd->IndustryId() != IID_Broker)
				continue;
			if(bd->TradeReadyToShipNow(ta))
				break;	// The trade agreement belonged to the broker, whether or not it was shipped.
		}
	}
	return false;
}

bool DaBd::TradeShippedNow(AuTradeAgreement ta)
{
	if(IndustryId() == IID_Broker)
	{
		// Deliver my shipment that is associated with ta, if it is ready to go.
		AuShipment delivery;
		m_CargoLock.lockForWrite();
		int deliveryResult = m_Shipments.DeliverTrade(delivery, ta);
		if(deliveryResult)
		{
			// Shipment is not ready or its not mine.
			m_CargoLock.unlock();
			return deliveryResult == 1;	// True if its my shipment.
		}
		AuTradeAgreement tad(ta);					// Trade agreement modified by delivery.
		m_TradeAgreements.DeliveryComplete(tad);	// This can modify my current trade agreement. tad is the modified result.
		if(tad.IsAgreement())
		{
			// Agreement remains in effect, with potentially different terms if the repeat count was decremented.
			// Create a new shipment to replace the one that was delivered.
			AuShipment shipment(CapitolId(), EmpireId(), tad);
			m_Shipments.AddShipment(shipment);
		}
		m_CargoLock.unlock();

		// Emit delivery.
		emit ShipIt(delivery.Container());

		SetModified(NOTIFY_Database);
		return true;
	}
	else if(IndustryId() == IID_Capitol)
	{
		DaWorld* world = FindParentPlanetInEnv();
		if(!world)
			return false;
		DaAtomList bds;
		world->FindBdCity(bds, Id());
		for(DaAtomList::const_iterator bi = bds.begin(); bi != bds.end(); bi++)
		{
			DaBd* bd = dynamic_cast<DaBd*>(*bi);
			if(!bd)
				continue;
			if(bd->IndustryId() != IID_Broker)
				continue;
			if(bd->TradeShippedNow(ta))
				break;	// The trade agreement belonged to the broker, whether or not it was shipped.
		}
	}
	return false;
}

void DaBd::ReportEventLog(AuEventLog& events) const
{
	m_EventLogLock.lock();
	if(!m_EventLog->isEmpty())
		events.AddLogTrim(*m_EventLog);
	m_EventLogLock.unlock();

	if(IndustryId() == IID_Broker)
	{
		// Broker reports info about trade agreements.
		m_CargoLock.lockForRead();
		m_TradeAgreements.Report(events);
		m_CargoLock.unlock();
	}
}

void DaBd::SetModified(SET_MODIFIED_BITS notifyBits)
{
	if((notifyBits & NOTIFY_Database) && IsNormal())
	{
		// Buildings get modified a LOT. Lets ignore the database update if I've been modified recently.
		m_ModDbLock.lockForRead();
		AuElapsedTimer tmMod(m_tmModDb);
		m_ModDbLock.unlock();
		// Database saves every 5 minutes, unless there is a critical update. Only permit db updates hourly per building.
		if(tmMod.ElapsedMin() < 60)
			notifyBits = (SET_MODIFIED_BITS)(notifyBits & ~NOTIFY_Database);	// Turn off the database notify bit.
		else
		{
			// We will notify the database. Reset the time until we allow it to happen again.
			m_ModDbLock.lockForWrite();
			m_tmModDb.restart();
			m_ModDbLock.unlock();
		}
	}
	DaCapsule::SetModified(notifyBits);
}

void DaBd::SetTroopsPresent(int troops)
{
	// Its ok if this exceeds the number of jobs. Excess gets pared off in EmployWorkers.
	m_BdLock.lockForWrite();
	m_Workers = troops;
	m_BdLock.unlock();
}

void DaBd::ToggleDoorState(const DaSentient& who, unsigned int doorIndex)
{
	// Determine if the person can open the door due to locking, access policy, etc. Ignores jamming.
	if(CanOpenDoor(who, doorIndex))
	{
		// First attempt at a jammed door unjams it.
		if(IsDoorJammed(doorIndex))
		{
			UnjamDoor(doorIndex);

			QString text(tr("Door unjammed."));
			who.Thought(text);
		}
		else if(IsDoorOpen(doorIndex))
			CloseDoor(doorIndex);
		else
		{
			m_DesignLock.lockForRead();
			bool isLiftDoor = m_DoorStates.IsTurboLiftDoor(doorIndex);
			quint16 liftId = 0;
			QString liftStop;
			if(isLiftDoor)
			{
				liftId = m_DoorStates.DoorAssociatedPart(doorIndex);
				AuScReportLiftHash::const_iterator liftStops = m_Design.TurboLifts().find(liftId);
				if(liftStops != m_Design.TurboLifts().cend())
					liftStop = (*liftStops).DoorStopName(doorIndex);
			}
			m_DesignLock.unlock();
			// Turbo lift.
			if(isLiftDoor && liftId)
			{
				int result = CallTurboLift(liftId, liftStop);
				AuCommThoughtMessage::MESSAGE tm = AuCommThoughtMessage::MessageCount;
				switch(result)
				{
				case 0:	//  0=lift already at stop, door already open
				case 1:	//  1=no door at turbo lift stop
				case 4:	//  4=broken turbo lift data
				case 5:	//  5=turbo lift moved to stop and door opened
				case 6:	//  6=lift already at stop, door opened
					break;
				case 2:	//  2=not ready to move
					tm = AuCommThoughtMessage::LiftCalled;
					break;
				case 3:	//  3=a door is stuck open,
					tm = AuCommThoughtMessage::LiftCalledDoorStuck;
					break;
				case 7:	//  7=a door is blocked open
					tm = AuCommThoughtMessage::LiftCalledDoorBlocked;
					break;
				}
				if(tm != AuCommThoughtMessage::MessageCount)
				{
					AuCommThoughtMessage msg(tm, liftStop, who.Id(), who.Name());
					g_Au.SendAtomChat(msg);
				}
			}
			else
				OpenDoor(doorIndex);
		}
	}
	else if(IsDoorLocked(doorIndex))
	{
		QString text(tr("The door is locked."));
		who.Thought(text);
	}
	else if(IsDoorOpen(doorIndex))
	{
		QString text(tr("The door will not close."));
		who.Thought(text);
	}
	else
	{
		QString text(tr("The door will not open."));
		who.Thought(text);
	}
}

void DaBd::operator>>(QDataStream& out) const
{
	DaCapsule::operator>>(out);

	out << m_bTaxSubmit;
	out << m_DesignCacheValid;
	out << m_HasAir;
	out << (quint8)m_IndustryId;
	out << m_Morale;
	out << m_QMade;

	m_BdLock.lockForRead();
	out << m_CapitolId;
	out << m_CityName;
	out << m_FoodPerMeal;
	out << m_FounderId;
	out << m_FounderName;
	out << m_PlatformId;
	out << m_ReportHistory;
	out << (quint8)m_ResidentEcoRole;
	out << m_Residents;
	out << m_ResidentsEmployed;
	out << m_ResidentSpecies;

	out << (quint16)m_RocksOnSite.size();
	for(QHash<COMMODITYID, quint32>::const_iterator ri = m_RocksOnSite.cbegin(); ri != m_RocksOnSite.cend(); ri++)
	{
		out << (quint16)ri.key();
		out << *ri;
	}

	out << AuTime();	//m_tmCapitolChange;
	out << AuTime();	//m_tmCitizenChange;
	out << m_tmReport;
	out << AuTime();	//m_tmResidentChange;
	out << m_Workers;

	out << m_ReportPopBirths;
	out << m_ReportPopDeaths;
	out << m_ReportPopIndigenousArr;
	out << m_ReportPopIndigenousDep;
	out << m_ReportPopSeafarersArr;
	out << m_ReportPopSeafarersDep;
	out << m_ReportPopTravellersArr;
	out << m_ReportPopTravellersDep;
	out << m_ReportPopWanderersArr;
	out << m_ReportPopWanderersDep;
	m_BdLock.unlock();

	//m_ModDbLock.lockForRead();
	AuTime tmModDb;
	out << tmModDb;
	//m_ModDbLock.unlock();

	m_VesselLock.lockForRead();
	out << m_CapacitorLevel;
	m_VesselLock.unlock();

	m_AccountLock.lockForRead();
	out << m_Bank;
	out << AuTime();	//m_tmLastBank;
	m_AccountLock.unlock();

	m_BayLock.lockForRead();
	out << (quint16)m_BayFired.size();
	for(unordered_map<quint16, AuBayFired>::const_iterator bi = m_BayFired.cbegin(); bi != m_BayFired.cend(); bi++)
	{
		out << (*bi).first;
		out << (*bi).second;
	}

	out << m_BayRadarRange;
	out << AuTime();	//m_tmBayFired;
	AuTime tmBayRanged;
	out << tmBayRanged;

	out << (quint16)m_BaySetting.size();
	for(unordered_map<quint16, AuBaySetting>::const_iterator si = m_BaySetting.cbegin(); si != m_BaySetting.cend(); si++)
	{
		out << (*si).first;
		out << (*si).second;
	}
	m_BayLock.unlock();

	m_CargoLock.lockForRead();
	out << m_Cargo;
	out << m_LivestockSpecies;
	out << m_Patents;
	out << AuTime();	//m_PatentsChanged;
	out << m_StoreCommodity;
	out << AuTime();	//m_tmCargoChange;
	out << m_Tools;

	out << (quint16)m_Vehicles.size();
	for(QList<COMMODITYID>::const_iterator vi = m_Vehicles.cbegin(); vi != m_Vehicles.cend(); vi++)
		out << (quint16)*vi;

	AuTime vehiclesTallied;
	out << vehiclesTallied;
	out << m_Shipments;
	out << m_TradeAgreements;
	m_CargoLock.unlock();

	m_CommLock.lockForRead();
	AuTime tmAlert;
	out << tmAlert;
	AuTime tmDiplomaticMessage;
	out << tmDiplomaticMessage;
	AuTime tmSOS;
	out << tmSOS;
	m_CommLock.unlock();

	m_ConstructionLock.lockForRead();
	if(m_pConstruct)
	{
		out << (quint8)1;
		out << *m_pConstruct;
	}
	else
		out << (quint8)0;
	m_ConstructionLock.unlock();

	m_MfgProcLock.lockForRead();
	out << m_MfgProc;
	out << AuTime();	//m_tmMfgProcChange;
	m_MfgProcLock.unlock();

	m_DamageLock.lockForRead();
	out << m_Damage;
	out << m_tmDamageChange;
	m_DamageLock.unlock();

	m_GamesLock.lockForRead();
	out << (quint16)m_Games.size();
	for(unordered_map<quint16, AuGame*>::const_iterator gi = m_Games.cbegin(); gi != m_Games.cend(); gi++)
	{
		out << (*gi).first;
		out << (*gi).second->Type();
		out << *(*gi).second;
	}
	out << AuTime();	//m_GamesChanged;
	m_GamesLock.unlock();

	m_LastInRangeLock.lockForRead();
	QTime lastInEnemyRange;
	out << lastInEnemyRange;
	m_LastInRangeLock.unlock();

	m_NameWithEmpireLock.lockForRead();
	out << m_NameWithEmpire;
	m_NameWithEmpireLock.unlock();

	m_ShieldsLock.lockForRead();
	out << m_ShieldCap;
	out << m_ShieldCenter;
	out << m_ShieldScram;
	m_ShieldsLock.unlock();

	m_SystemsLock.lockForRead();
	out << m_ssaShipSystems;
	out << AuTime();	//m_tmSystemsUpg;
	m_SystemsLock.unlock();

	m_TurretLock.lockForRead();
	out << (quint16)m_Turrets.size();
	for(unordered_map<quint16, AuOrdnance>::const_iterator ti = m_Turrets.cbegin(); ti != m_Turrets.cend(); ti++)
	{
		out << (*ti).first;
		out << (*ti).second;
	}
	m_TurretLock.unlock();

	m_DesignLock.lockForRead();
	out << AuTime();	//m_DesignChg;
	out << m_Design;
	out << AuTime();	//m_DoorChg;
	out << m_DoorOpenTimes;
	out << m_DoorStates;
	out << m_HullDoorRooms;
	out << m_HullDoorRoomsValid;
	out << AuTime();	//m_LiftChg;
	out << m_Lifts;
	out << m_TargetLoc;
	out << m_TargetLocValid;
	m_DesignLock.unlock();

	m_AirLock.lockForRead();
	out << AuTime();	//m_AirChg;
	out << m_AirPressures;
	m_AirLock.unlock();

	m_EventLogLock.lock();
	if(m_EventLog)
	{
		out << (quint8)1;
		out << *m_EventLog;
	}
	else
		out << (quint8)0;
	m_EventLogLock.unlock();

	m_LandingSystemLock.lockForRead();
	out << AuTime();	//m_LandingSystemChg;
	out << m_LandingSystemStates;
	m_LandingSystemLock.unlock();

	m_LauncherLock.lockForRead();
	out << AuTime();	//m_LauncherChg;
	out << m_LauncherStates;
	m_LauncherLock.unlock();

	m_RoomLightLock.lockForRead();
	out << AuTime();	//m_RoomLightChg;
	out << m_RoomLightStates;
	m_RoomLightLock.unlock();

	m_TRoomLock.lockForRead();
	out << AuTime();	//m_TRoomChg;
	out << m_TRoomStates;
	m_TRoomLock.unlock();

	m_TurretPosLock.lockForRead();
	out << AuTime();	//m_TurretPosChg;
	out << m_TurretPos;
	m_TurretPosLock.unlock();

	m_TradeConnectionsLock.lockForRead();
	out << m_TradeConnections;
	out << AuTime();	//m_TradeConnectionsChg;
	out << m_Airport;
	out << m_Wharf;
	m_TradeConnectionsLock.unlock();

	m_SpacecraftFactoryLock.lockForRead();
	out << m_CompanyMaxQ;
	out << m_CompanyOk;
	out << m_DefaultDesign;
	out << m_DesignQueue;
	out << m_DesignTries;
	out << m_MakeMinQ;
	out << m_MakingShip;
	AuTime tmLastSpawnTry;
	out << tmLastSpawnTry;
	m_SpacecraftFactoryLock.unlock();

	m_FireStationLock.lockForRead();
	out << m_FireStationCalled;
	m_FireStationLock.unlock();

	m_FenceLock.lockForRead();
	out << AuTime();	//m_FenceChangeTime;
	out << m_FenceExtentsValid;
	out << m_FenceMax;
	out << m_FenceMin;
	out << m_FenceSegs;
	out << m_FenceSegsCache;
	out << m_FenceSegsCacheValid;
	out << m_FenceStyle;
	m_FenceLock.unlock();

	m_JobsLock.lockForRead();
	out << m_JobInterdict;			// Will become valid if we detect enemy ship transmissions.
	out << (quint16)m_JobsEnemyStations.size();
	for(unordered_map<AuId, AuJobDestroyEnemyStation, AuIdHash>::const_iterator ji = m_JobsEnemyStations.cbegin();
			ji != m_JobsEnemyStations.cend(); ji++)
	{
		out << (*ji).first;
		out << (*ji).second;
	}
	m_JobsLock.unlock();

	m_PriceOfferLock.lockForRead();
	out << m_PriceOffers;
	m_PriceOfferLock.unlock();

	m_TransientLock.lockForRead();
	out << m_TransientPopulation;
	m_TransientLock.unlock();
}

void DaBd::operator<<(QDataStream& in)
{
	DaCapsule::operator<<(in);

	in >> m_bTaxSubmit;
	in >> m_DesignCacheValid;
	in >> m_HasAir;
	quint8 ui8;
	in >> ui8;
	m_IndustryId = (INDUSTRYID)ui8;
	in >> m_Morale;
	in >> m_QMade;

	m_BdLock.lockForWrite();
	in >> m_CapitolId;
	in >> m_CityName;
	in >> m_FoodPerMeal;
	in >> m_FounderId;
	in >> m_FounderName;
	in >> m_PlatformId;
	in >> m_ReportHistory;
	in >> ui8;
	m_ResidentEcoRole = (ECOROLE)ui8;
	in >> m_Residents;
	in >> m_ResidentsEmployed;
	in >> m_ResidentSpecies;

	m_RocksOnSite.clear();
	quint16 ui16;
	in >> ui16;
	while(ui16--)
	{
		quint16 cid;
		quint32 amt;
		in >> cid;
		in >> amt;
		m_RocksOnSite.insert((COMMODITYID)cid, amt);
	}

	AuTime tmCapitolChange;
	in >> tmCapitolChange;
	AuTime tmCitizenChange;
	in >> tmCitizenChange;
	in >> m_tmReport;
	AuTime tmResidentChange;
	in >> tmResidentChange;
	in >> m_Workers;

	in >> m_ReportPopBirths;
	in >> m_ReportPopDeaths;
	in >> m_ReportPopIndigenousArr;
	in >> m_ReportPopIndigenousDep;
	in >> m_ReportPopSeafarersArr;
	in >> m_ReportPopSeafarersDep;
	in >> m_ReportPopTravellersArr;
	in >> m_ReportPopTravellersDep;
	in >> m_ReportPopWanderersArr;
	in >> m_ReportPopWanderersDep;
	m_BdLock.unlock();

	//m_ModDbLock.lockForWrite();
	AuTime tmModDb;
	in >> tmModDb;
	//m_ModDbLock.unlock();

	m_VesselLock.lockForWrite();
	in >> m_CapacitorLevel;
	m_VesselLock.unlock();

	m_AccountLock.lockForWrite();
	in >> m_Bank;
	AuTime lastBank;
	in >> lastBank;
	m_AccountLock.unlock();

	m_BayLock.lockForWrite();

	m_BayFired.clear();
	quint16 cnt;
	in >> cnt;
	while(cnt--)
	{
		quint16 id;
		AuBayFired bf;
		in >> id;
		in >> bf;
		m_BayFired.insert(pair<quint16, AuBayFired>(id,bf));
	}

	in >> m_BayRadarRange;
	AuTime tmBayFired;
	in >> tmBayFired;
	AuTime tmBayRanged;
	in >> tmBayRanged;

	m_BaySetting.clear();
	in >> cnt;
	while(cnt--)
	{
		quint16 id;
		AuBaySetting bs;
		in >> id;
		in >> bs;
		m_BaySetting.insert(pair<quint16, AuBaySetting>(id,bs));
	}
	m_BayLock.unlock();

	m_CargoLock.lockForWrite();
	in >> m_Cargo;
	in >> m_LivestockSpecies;
	in >> m_Patents;
	AuTime patentsChanged;
	in >> patentsChanged;
	in >> m_StoreCommodity;
	AuTime tmCargoChange;
	in >> tmCargoChange;
	in >> m_Tools;

	m_Vehicles.clear();
	in >> ui16;
	while(ui16--)
	{
		quint16 cid;
		in >> cid;
		m_Vehicles.append((COMMODITYID)cid);
	}

	AuTime vehiclesTallied;
	in >> vehiclesTallied;
	in >> m_Shipments;
	in >> m_TradeAgreements;
	m_CargoLock.unlock();

	m_CommLock.lockForWrite();
	AuTime tmAlert;
	in >> tmAlert;
	AuTime tmDiplomaticMessage;
	in >> tmDiplomaticMessage;
	AuTime tmSOS;
	in >> tmSOS;
	m_CommLock.unlock();

	m_ConstructionLock.lockForWrite();
	if(m_pConstruct)
		delete m_pConstruct;
	in >> ui8;
	if(ui8)
	{
		m_pConstruct = new DeConstructionProcess();
		in >> *m_pConstruct;
	}
	else
		m_pConstruct = 0;
	m_ConstructionLock.unlock();

	m_MfgProcLock.lockForWrite();
	in >> m_MfgProc;
	AuTime tmMfgProcChange;
	in >> tmMfgProcChange;
	m_MfgProcLock.unlock();

	m_DamageLock.lockForWrite();
	in >> m_Damage;
	in >> m_tmDamageChange;
	m_DamageLock.unlock();

	m_GamesLock.lockForWrite();
	in >> ui16;
	while(ui16--)
	{
		quint16 whichTable;
		quint8 gameType;
		AuGame* game;

		in >> whichTable;
		in >> gameType;
		game = AuGame::CreateGame(gameType);
		if(game)
		{
			// The game object was created.
			in >> *game;
			m_Games.insert(pair<quint16, AuGame*>(whichTable, game));
		}
	}
	AuTime gamesChanged;
	in >> gamesChanged;
	m_GamesLock.unlock();

	m_LastInRangeLock.lockForWrite();
	QTime lastInEnemyRange;
	in >> lastInEnemyRange;
	m_LastInRangeLock.unlock();

	m_NameWithEmpireLock.lockForWrite();
	in >> m_NameWithEmpire;
	m_NameWithEmpireLock.unlock();

	m_ShieldsLock.lockForWrite();
	in >> m_ShieldCap;
	in >> m_ShieldCenter;
	in >> m_ShieldScram;
	m_ShieldsLock.unlock();

	m_SystemsLock.lockForWrite();
	in >> m_ssaShipSystems;
	AuTime tmSystemsUpg;
	in >> tmSystemsUpg;
	m_SystemsLock.unlock();

	m_TurretLock.lockForWrite();
	m_Turrets.clear();
	in >> ui16;
	while(ui16--)
	{
		quint16 id;
		AuOrdnance ord;
		in >> id;
		in >> ord;
		m_Turrets.insert(pair<quint16, AuOrdnance>(id, ord));
	}
	m_TurretLock.unlock();

	m_DesignLock.lockForWrite();
	AuTime designChg;
	in >> designChg;
	in >> m_Design;
	AuTime doorChg;
	in >> doorChg;
	in >> m_DoorOpenTimes;
	in >> m_DoorStates;
	in >> m_HullDoorRooms;
	in >> m_HullDoorRoomsValid;
	AuTime liftChg;
	in >> liftChg;
	in >> m_Lifts;
	in >> m_TargetLoc;
	in >> m_TargetLocValid;
	m_DesignLock.unlock();

	m_AirLock.lockForWrite();
	AuTime airChg;
	in >> airChg;
	in >> m_AirPressures;
	m_AirLock.unlock();

	m_EventLogLock.lock();
	if(m_EventLog)
		delete m_EventLog;
	in >> ui8;
	if(ui8)
	{
		m_EventLog = new AuEventLog;
		in >> *m_EventLog;
	}
	else
		m_EventLog = 0;
	m_EventLogLock.unlock();

	m_LandingSystemLock.lockForWrite();
	AuTime landingSystemChg;
	in >> landingSystemChg;
	in >> m_LandingSystemStates;
	m_LandingSystemLock.unlock();

	m_LauncherLock.lockForWrite();
	AuTime launcherChg;
	in >> launcherChg;
	in >> m_LauncherStates;
	m_LauncherLock.unlock();

	m_RoomLightLock.lockForWrite();
	AuTime roomLightChg;
	in >> roomLightChg;
	in >> m_RoomLightStates;
	m_RoomLightLock.unlock();

	m_TRoomLock.lockForWrite();
	AuTime tRoomChg;
	in >> tRoomChg;
	in >> m_TRoomStates;
	m_TRoomLock.unlock();

	m_TurretPosLock.lockForWrite();
	AuTime turretPosChg;
	in >> turretPosChg;
	in >> m_TurretPos;
	m_TurretPosLock.unlock();

	m_TradeConnectionsLock.lockForWrite();
	in >> m_TradeConnections;
	AuTime tradeConnectionsChg;
	in >> tradeConnectionsChg;
	in >> m_Airport;
	in >> m_Wharf;
	m_TradeConnectionsLock.unlock();

	m_SpacecraftFactoryLock.lockForWrite();
	in >> m_CompanyMaxQ;
	in >> m_CompanyOk;
	in >> m_DefaultDesign;
	in >> m_DesignQueue;
	in >> m_DesignTries;
	in >> m_MakeMinQ;
	in >> m_MakingShip;
	AuTime tmLastSpawnTry;
	in >> tmLastSpawnTry;
	m_SpacecraftFactoryLock.unlock();

	m_FireStationLock.lockForWrite();
	in >> m_FireStationCalled;
	m_FireStationLock.unlock();

	m_FenceLock.lockForWrite();
	AuTime fenceChangeTime;
	in >> fenceChangeTime;
	in >> m_FenceExtentsValid;
	in >> m_FenceMax;
	in >> m_FenceMin;
	in >> m_FenceSegs;
	in >> m_FenceSegsCache;
	in >> m_FenceSegsCacheValid;
	in >> m_FenceStyle;
	m_FenceLock.unlock();

	m_JobsLock.lockForWrite();
	in >> m_JobInterdict;
	m_JobsEnemyStations.clear();
	in >> ui16;
	while(ui16--)
	{
		AuId id;
		AuJobDestroyEnemyStation job;
		in >> id;
		in >> job;
		m_JobsEnemyStations.insert(pair<AuId, AuJobDestroyEnemyStation>(id, job));
	}
	m_JobsLock.unlock();

	m_PriceOfferLock.lockForWrite();
	in >> m_PriceOffers;
	m_PriceOfferLock.unlock();

	m_TransientLock.lockForWrite();
	in >> m_TransientPopulation;
	m_TransientLock.unlock();
}

void DaBd::ExploreWorld()
{
	quint32 empireId(EmpireId());
	if(!empireId)
		return;		// Empire zero does not store fog of war.
	DaWorldLL* world = FindParentWorldInEnv();
	if(!world)
		return;

	// Mark the building's area as explored by the new empire.
	AuPoint seaLevelSiteCen(SiteCenter());
	world->ElevateLocMSL(seaLevelSiteCen, 0);
	world->Explore(AuId(), empireId, seaLevelSiteCen, RoughSiteRadius()); 
}

